// Generated by tools/lore-gallery/build.py from Legends of Runeterra card art, the League of Legends Universe
// galleries and champion splash arts (Riot Games). Do not edit by hand: change tools/lore-gallery/groups.py and run the script again.
window.LORE_GALLERY = {"demacia":{"groups":[{"id":"vanguard","name":"Vanguarda Destemida","desc":"A elite do exército demaciano, liderada por Garen. Soldados escolhidos a dedo que marcham na frente de cada batalha.","items":[{"s":"03DE004","n":"Capitã Arrika","f":"Na infância, Arrika viu com os próprios olhos a devastação de que Noxus era capaz com a destruição de seu próprio lar. Ao se alistar no serviço militar, ela jurou nunca mais permitir que a flâmula noxiana fosse fincada em solo demaciano nem deixar que outras crianças ficassem órfãs."},{"s":"01DE028","n":"Cavalaria da Vanguarda","f":"A Vanguarda não precisa de tambores ou música para manter a sincronia na investida. Apenas o som firme e constante de cascos contra o chão."},{"s":"04DE009","n":"Cavaleiro Galante","f":"Ao darem o comando, todos os soldados demacianos foram convocados para ajudar nas buscas pelo príncipe. A situação exigia, acima de tudo, eficácia."},{"s":"01DE039","n":"Cithria de Campinuvem","f":"\"Todas as noites, antes de dormir, minha mãe contava histórias dos maiores heróis de Demacia enquanto afiava sua espada. Meus sonhos eram repletos de grandes aventuras... e hoje começa a minha própria história.\""},{"s":"01DE051","n":"Cithria, a Audaciosa","f":"\"Contos, lendas… Nunca vi essas coisas como mera ficção, mas sim aventuras clamando por mim. Deixei Campinuvem em busca da minha própria aventura... acabei encontrando várias. E isso é só o começo.\""},{"s":"04DE005","n":"Cithria, Dama das Nuvens","f":"\"Quem mais Demacia poderia enviar para salvar seu príncipe se não a própria Dama das Nuvens?\" – Rei Jarvan III"},{"s":"01DE020","n":"Defensora da Vanguarda","f":"\"Não sabíamos o que eram aquelas criaturas. Mas conhecíamos bem os rostos de nossos companheiros, e somente isso importava.\""},{"s":"01DE036","n":"Escudeira da Vanguarda","f":"\"Todos que conheci e as aventuras que vivi me ensinaram algo novo. Porém, quanto mais eu aprendia e ficava forte, mais percebia que ainda tinha um longo caminho...\" – Cithria, Escudeira da Vanguarda"},{"s":"01DE052","n":"Formação Aciária","f":"\"Esta formação é a base da nossa estratégia. Cada soldado deve confiar em seu escudo e nos de seus companheiros. Enquanto eles estiverem de pé, nosso reino também estará.\"\n– Garen"},{"s":"01DE012T1","n":"Garen","f":"\"Você me acha estoico. Obstinado. Previsível. Sou estoico, pois nada me abala. Sou obstinado, pois confio em Demacia. E sou previsível, pois vou te derrotar sem sombra de dúvida.\""},{"s":"01DE015","n":"Guardiã Radiante","f":"\"Hordas de frias mãos moribundas levaram seus companheiros. Apenas ela permaneceu, um brilho de justiça cuja lâmina parecia entoar a cada golpe os nomes dos que partiram.\" – Alferes demaciano"},{"s":"01DE001","n":"Porta-Estandarte da Vanguarda","f":"\"É preciso entender o peso que nosso estandarte carrega. Ele representa nosso rei, nossas casas, nossos cidadãos; nossa crença inabalável em Demacia. Erga-o e mostre a eles nosso orgulho.\" – Tianna Stemmaguarda"},{"s":"01DE056","n":"Primeira-Espada da Vanguarda","f":"O grito de guerra ecoa. Já estou pronto para avançar. Só preciso das ordens de minha senhora para aceitar meu destino e cumprir sua vontade."},{"s":"01DE009","n":"Protetora Aciária","f":"\"Somos uma nação próspera porque o destino de cada guerreiro tem um valor inestimável.\" – Rei Jarvan III"},{"s":"06DE025","n":"Recruta Benevolente","f":"\"Esse garoto é um risco. Insisti para que não o trouxessem na nossa caçada, já que ele ainda chama aquela criatura vil de 'irmã'. É de uma ingenuidade tão grande que, francamente, me revolta. Ainda assim, acho que tenho pena dele. Na pior das hipóteses, essa será uma lição importante para ele.\" – Do diário pessoal de Sirius Rowill, Cavaleiro-Patrulheiro Zeloso"},{"s":"01DE054","n":"Redentora da Vanguarda","f":"\"Os que já se foram serão lembrados em cada grito de guerra, cada golpe de nossas espadas e cada colisão de nossos escudos! Hoje, seremos vitoriosos!\""},{"s":"01DE006","n":"Sargento da Vanguarda","f":"\"Ele lidera nossos treinos do nascer ao pôr do sol e é o primeiro a adentrar a linha de combate. Resistente como o aço, firme como uma rocha – não poderia haver um líder melhor.\" – Alferes demaciano"},{"s":"01DE016","n":"Vanguarda Destemida","f":"A Vanguarda Destemida é formada pelos melhores guerreiros de Demacia, que já são lendas em suas vilas ou condados, mas almejam ver seus nomes difundidos por todo o reino."},{"s":"01DE046","n":"Vigia da Vanguarda","f":"Um lugar silencioso não é necessariamente seguro."},{"s":"ubfb25f2319","n":"Armas Demacianas","f":"O ethos do design de Demacia é elegante, mas também minimalista e austero. Suas armas e armaduras não são ornamentadas em excesso.","u":1},{"s":"uaa64a8150c","n":"Aço de Demacia","f":"Às vezes chamado de aço de prata ou aço rúnico, esta liga metálica é altamente reconhecida por toda Runeterra. Dizem que os ferreiros demacianos resfriam o metal em águas abençoadas, para oferecer proteção mágica em batalhas.","u":1},{"s":"ua0aca5fa3d","n":"Elite Militar","f":"Demacia ostenta um pequeno, porém de elite, exército permanente. Seus capitães e generais lideram das linhas de frente e seus guerreiros seguem com disciplina inabalável.","u":1},{"s":"u4ccf8e559b","n":"Equipamentos","u":1},{"s":"u8608583fb5","n":"Guarda de Elite de Demacia","u":1},{"s":"u389665de5e","n":"Linha Guerreira e Guarda do Palácio","u":1},{"s":"lxinzhao","n":"Xin Zhao","f":"O Senescal de Demacia.\nXin Zhao é um guerreiro determinado e leal à família real de Demacia. Outrora confinado às arenas de combate noxianas, ele sobreviveu a inúmeros Desafiadores, mas, depois que enfrentou as forças do Rei Jarvan III em batalha, ele decidiu renunciar à sua vida passada para servir ao que considerava uma causa mais nobre.","l":1},{"s":"w0b9ab4914f","n":"Vanguarda de Demacia (arte conceitual)","w":1}]},{"id":"crown","name":"A Coroa e a Casa Lightshield","desc":"A família real de Demacia. O rei Jarvan III morreu, e a sucessão do jovem Jarvan IV ainda divide as casas nobres.","items":[{"s":"04DE008T1","n":"Jarvan IV","f":"Entretanto, os noxianos não levaram em consideração a incontestável força e a incansável determinação do príncipe – um erro que acabou sendo pago em sangue."},{"s":"04DE001","n":"Lorde Honroso","f":"Após saber do desaparecimento do filho, o rei Jarvan III deixou Lorde Barrett Buvelle, seu amigo de confiança, encarregado de organizar um grupo de buscas. O príncipe voltou são e salvo, mas, para o eterno arrependimento do rei, o mesmo não pôde ser dito do Lorde."},{"s":"01DE031","n":"Oradores da Alvorada","f":"\"Cidadãos, o mal venceu por ora, mas não prevalecerá no fim. Lembrem-se daqueles que já se foram e usem a lembrança deles como escudo!\""},{"s":"04DE010","n":"Rei Jarvan III","f":"\"O que um pai sacrificaria para salvar o filho? Ou melhor, que tipo de sacrifício um rei faria?\" – LeBlanc"},{"s":"u61ca27e858","n":"Príncipe Jarvan IV","u":1}]},{"id":"laurent","name":"Casa Laurent","desc":"Família nobre de duelistas, famosa pela esgrima. Fiora governa a casa com a ponta da espada.","items":[{"s":"01DE053","n":"Cavaleiro dos Laurent","f":"\"Santa paciência...\" – Fiora"},{"s":"01DE055","n":"Duelista dos Laurent","f":"\"Parecia um idiota engomadinho com uma espada cara... mas ele sabia mesmo usá-la! Eu pediria uma revanche, mas não entendi seu nome por causa daquele sotaque ridículo.\" –\nAlferes demaciano"},{"s":"01DE003","n":"Espadeiro dos Laurent","f":"\"Sim, elas são lindas. Mas como qualquer instrumento delicado, elas só revelam sua verdadeira beleza nas mãos de um mestre.\""},{"s":"01DE045T1","n":"Fiora","f":"\"... e agora eu sei.\""},{"s":"01DE011","n":"Protegido dos Laurent","f":"\"Ele fez O QUÊ? Confiei a ele o inestimável sabre de Pierre de Guillard! Ele disse que só o usaria nos treinos!\" – Espadeiro dos Laurent"}]},{"id":"durand","name":"Escultores Durand","desc":"Herdeiros do escultor que criou Galio. Moldam a petricita que protege Demacia da magia.","items":[{"s":"05DE019","n":"Arquiteto de Durand","f":"\"O Guarda Cordielmo trouxe más notícias\", anunciou calmamente o arquiteto, focando em enrolar de novo o pergaminho para esconder o tremor nas mãos. Ele se virou para os escultores, que estavam à espera, e deu um aceno rígido com a cabeça. \"Parece que chegou a hora de os defensores secretos de Demacia saírem das sombras.\""},{"s":"05DE012","n":"Asalonga de Petricita","f":"Quando a Asalonga cruzou o céu, os soldados desalentados de Demacia comemoraram no chão, inspirados por sua forma resistente."},{"s":"07DE016","n":"Balen, o Benevolente","f":"O grande porte de Balen, companheiro de longa data da família Durand, esconde sua precisão gentil. Embora tenha começado como assistente, Balen é muito talentoso e excepcionalmente criativo em seu ofício. Os Durand têm orgulho de chamá-lo de amigo."},{"s":"05DE013","n":"Cervo de Petricita","f":"Atrás do Guarda montado no cervo, o Guardião de petricita ofuscava a criatura que havia inspirado sua figura elegante."},{"s":"05DE018","n":"Cão de Petricita","f":"\"É sempre uma alegria vê-los ganhando vida. Você esquece que cada um é único e que sua personalidade é um reflexo do artista que os criou.\" – Escultora de Durand"},{"s":"05DE010","n":"Escultora de Durand","f":"\"Pode não ser óbvio para leigos, mas a obra de um grande artista está entre um talhar e outro do cinzel.\""},{"s":"05DE009T1","n":"Galio","f":"Quando acordou, Galio ficou radiante ao descobrir que uma família inteira havia sido criada para ele, uma cópia da mesma família que continuaria o legado do criador dele por muitos anos. Ela era igual a ele: indestrutível."},{"s":"05DE014","n":"Pupila de Durand","f":"Shireen tirou os olhos de seu trabalho ao ouvir o som de cascos velozes. A pressa do guarda deixou-a inquieta, mas curiosa. Ela incitou seu pássaro de petricita a voar no encalço do homem."},{"s":"06DE044","n":"Touro de Petricita","f":"\"Nada é mais forte que petricita.\" – Arquiteto de Durand"}]},{"id":"mageseekers","name":"Caça-Magos e os magos perseguidos","desc":"A ordem que persegue, prende e \"protege\" os magos de Demacia, odiada por quem tem magia no sangue. Do outro lado estão os perseguidos: Sylas, que escapou da prisão e lidera a rebelião dos magos, e Morgana, nascida em Demacia e marcada pela magia.","items":[{"s":"09DE040","n":"Caçador de Magos Estrambólico","f":"''Lady Stemmaguarda.'' O Caçador de Magos se materializou das sombras, estendendo a mão na direção dela. O sorriso suplicante dele parecia grande demais no rosto parcialmente coberto. \"Por que você não me segue?\""},{"s":"07DE011","n":"Caçador de Magos Novato","f":"\"Silêncio! Isso não é um mero jogo, como ousas alegar, mas o encanto de uma intervenção arcana traiçoeira. Vou desmascarar tua natureza mágica e trapaceira, canalha! Mesmo que precise queimar este lugar inteiro!\""},{"s":"08MT045","n":"Conjurador Acorrentado","f":"Os Caçadores de Magos são peritos em quebrar pessoas. Eles acorrentaram suas mãos e sua magia. Eles roubaram sua voz. Mas ele sobreviveu a isso antes... e, dessa vez, a Redentora Velada estava ao seu lado."},{"s":"08MT024","n":"Conjurador do Olho-Rubi","f":"\"Não tenha medo! Vá e não olhe para trás! Nós já realizamos essa jornada. Agora é nosso dever proteger a sua. Vá agora ao santuário dela, e a Redentora Velada concederá a proteção que você procura.\""},{"s":"01DE040","n":"Doutrinador dos Caçadores de Magos","f":"\"Cidadãos de Demacia, é uma honra mantê-los seguros. Mas precisamos exigir seu apoio incondicional, pois mesmo dentro de nossas muralhas, os magos ainda caminham entre nós!\""},{"s":"04DE007","n":"Escudeira Penitente","f":"Aproximando-se dos muros da cidade, suas pernas finalmente cederam. A Vanguarda Destemida levaria sua mensagem até o rei que, por sua vez, resgataria o príncipe. Assim, o erro que ela cometera seria corrigido e a honra dela seria mantida."},{"s":"08DE017","n":"Inquisidor dos Caçadores de Magos","f":"\"Não podemos permitir que eles cheguem ao santuário da irmã caída. A magia dela é ancestral e perversa, e minhas habilidades não são capazes de suprimi-la. Rápido, levem essas aberrações de volta para o navio e depois subam a montanha em busca dos outros!\""},{"s":"01DE048","n":"Instigador dos Caçadores de Magos","f":"\"Há muito tempo, a magia selvagem das Guerras Rúnicas devastou Runeterra. Nossa Ordem foi criada para proteger o reino, livrando-o de toda a magia, venha de dentro ou de fora.\" – Manual dos Caçadores de Magos"},{"s":"01DE023","n":"Investigadora dos Caçadores de Magos","f":"\"Perdoe a intromissão, mas precisaremos da sua cooperação total. Ficamos sabendo de alguns... 'acontecimentos estranhos'...\""},{"s":"06DE038","n":"Lorde Eldred, Líder dos Caçadores de Magos","f":"\"Não pude deixar de ouvir seus sussurros fervorosos, querida esposa. Aconselho que tenha mais cautela ao discutir assuntos de família em público. Nunca se sabe quem pode estar ouvindo.\""},{"s":"08MT003","n":"Morgana","f":"\"Você chegou a mim ferida e sangrando e, no entanto, nunca vi uma expressão tão jubilante. Você é mesmo estranha, mas está segura aqui. Descanse, e, quando se sentir melhor, eu gostaria muito de ouvir a sua história.\""},{"s":"08MT003T4","n":"Morgana","f":"\"Você se arrependerá dessa transgressão! Tenha certeza de uma coisa: você sentirá o sofrimento que infligiu aos outros como um torniquete comprimindo a sua alma. Você reconhecerá seus pecados ou será sufocado por eles.\""},{"s":"03DE015","n":"Supressor Pétreo","f":"O que antes era um bloco disforme e bruto de petricita logo vira algo valioso nas mãos habilidosas da escultora. É assim que uma obra realmente ganha vida."},{"s":"01DE024","n":"Tutor dos Caçadores de Magos","f":"\"Itens arcanos afloram uma curiosidade inegável. Mas é melhor deixá-los nas mãos competentes de nossos especialistas e longe da ignorância bem-intencionada dos cidadãos.\"\n– Manual dos Caçadores de Magos"},{"s":"lsylas","n":"Sylas","f":"O Abjugado.\nCriado em um dos bairros mais pobres de Demacia, Sylas de Dregbourne se tornou o símbolo do lado mais sombrio da Grande Cidade. Quando criança, sua habilidade de identificar magia chamou a atenção de importantes caçadores de magos, que depois o aprisionaram por ter se virado contra eles.","l":1},{"s":"w1013d4337b","n":"Magos de Demacia (arte conceitual)","w":1}]},{"id":"rangers","name":"Patrulheiros e Asa-Prateada","desc":"Batedores e cavaleiros de rapina que vigiam as fronteiras. Quinn e sua águia Valor são os mais famosos.","items":[{"s":"06DE027","n":"Cavaleiro-Patrulheiro Zeloso","f":"\"Janan, certo? O que você sabe sobre o Sirius?\"\n\"Ah, o Cavaleiro-Patrulheiro Rowill? Revogaram o título dele alguns anos atrás. Aparentemente, ele ignorou de propósito todas as ordens que tinha recebido. Parece que ele faz o que quer e não aceita 'não' como resposta.\"\n\"Ah.\"\n\"Enfim... por que deixou ele participar da caçada?\"\n\"Não deixei.\"\n\"Então por que... ah, certo. Fantástico.\"\n– Vayne e Janan, a Caçadora Viúva"},{"s":"02DE008","n":"Companheiro Chifrídeo","f":"Ao serem recrutados, os guardas passam meses na floresta com seus companheiros, aprendendo a prever cada movimento de seu animal. É preciso ter paciência, mas depois que o laço é formado, nada pode desfazê-lo."},{"s":"04DE015","n":"Esquadrilha de Rapina","f":"Só de olharem para a Esquadrilha de Rapina lá no alto, os soldados demacianos já se enchem de coragem em meio aos campos de batalha. Ao vê-los perfurando as nuvens, quem está no solo se sente revigorado e pronto para continuar lutando."},{"s":"02DE010","n":"Genevieve Cordielmo","f":"Ver os guardas-florestais de Demacia em batalha é inspirador. Eles lutam como um só. Humano e animal, lado a lado, ferozmente determinados e completamente inseparáveis."},{"s":"02DE004","n":"Guardião da Presa Verde","f":"\"Eu jurei proteger esta floresta e todos que buscam abrigo nela.\""},{"s":"01DE010","n":"Lanceiro de Rapina","f":"\"É preciso ter coragem para confiar a própria vida a uma Rapina Prateada engajada em combate e bem longe do chão. Coragem e vigor.\" – Garen"},{"s":"01DE029","n":"Plumageiro Rastreador","f":"Esses parentes das Rapinas Prateadas têm os instintos predatórios de seus semelhantes, mas não percebem que são muito menores."},{"s":"01DE030","n":"Precursora de Rapina","f":"Lançaram uma chuva de flechas das paredes da fortaleza, mas nada conseguia atingir o feixe prateado disparando pelos céus."},{"s":"02DE006T1","n":"Quinn","f":"\"É você no comando, Valor!\""},{"s":"04DE004","n":"Rastreadora Fervente","f":"Embora os noxianos tenham montado uma bela armadilha, ninguém conhecia a floresta melhor do que os patrulheiros de Demacia. Cada galho, cada pegada era uma pista que os levava ao seu príncipe."},{"s":"02DE006T2","n":"Valor","f":"Quem o encontra pessoalmente jura ver um brilho diferente em seu olhar profundo, uma sagacidade que supera qualquer ave de rapina comum."},{"s":"01DE004","n":"Vanguarda de Rapinas Prateadas","f":"Elas surgiram nos céus como relâmpagos prateados: velozes e precisas mergulhando em direção ao alvo. E desapareceram tão subitamente quanto surgiram."},{"s":"u51a62d7c74","n":"Cavaleiro de Rapina","u":1}]},{"id":"dragonguard","name":"Guarda dos Dragões","desc":"Os que servem ao lado de Shyvana e protegem (ou caçam) os dragões que ainda voam sobre Demacia.","items":[{"s":"08DE013","n":"Aliado dos Dragões","f":"\"Detesto ter que admitir isso, parceiro, mas não podemos domá-lo sozinhos. Já fizemos o que podíamos. Avisarei ao general e, com o poder de Demacia ao nosso lado, com certeza derrubaremos essa fera.\""},{"s":"04DE014","n":"Lanchinho de Dragão","f":"\"Está ouvindo esse som vindo lá do alto? Não é um pássaro, meu garoto. É o chamado de caça de um dragão.\"\n– Fazendeiro demaciano"},{"s":"03DE005","n":"Pesquisador Acadêmico","f":"Ovo de dragão (Dragão Furioso, Draco murmurationis)\nLocal: encontrado pelo pesquisador Anden Mayne em uma expedição.\nNotas: período de gestação desconhecido. Incubação em andamento. Movimento recente dentro da casca. O ovo responde ao calor, à luz e ao martelo. Estudos atuais inconclusivos.\n– Notas de Anden Mayne, Pesquisador Acadêmico"},{"s":"08DE006","n":"Pioneiro Erudito","f":"\"Tá frio. Eu tô com frio. Tudo é tão frio o tempo todo. Tem lugares que não são feitos para os seres humanos. Me mandem pra um lugar quente na próxima.'' – Registros de expedição da Divisão de Grandes Distâncias da Guilda dos Exploradores, alocação: Freljord"},{"s":"03DE011T1","n":"Shyvana Dragoa","f":"\"Na primeira vez que testemunhei a transformação dela, olhei-a com repulsa. Ali estava Yvva, ardendo em fogo e fúria! Se eu ao menos soubesse o que sei agora... que ela se tornaria nossa companheira de luta, uma soldada exemplar... e uma amiga muito querida.\"\n– Página do relato do Tenente Jerik sobre Wrenwall"},{"s":"03DE008","n":"Tenente da Dracoguarda","f":"\"Quando perdi meus companheiros de luta em Wrenwall, pensei que meu propósito também estivesse perdido... mas, na verdade, a batalha pode reacender qualquer coisa em um velho soldado.\""},{"s":"03DE003","n":"Vigia da Dracoguarda","f":"\"Olha, lá longe! Aquilo é...?\"\n\"Parece que sim.\"\n\"Como pode ter certeza?\"\n\"Ah, não tem como errar. Tape os ouvidos. Vai ser alto.\"\n– Anden e Yessenia"}]},{"id":"illuminators","name":"Iluminadores e devotos da Luz","desc":"Clérigos e guerreiros que pregam a fé na luz e na ordem. Alguns caçam as trevas pelo mundo.","items":[{"s":"06MT008","n":"Kayle","f":"\"Os demacianos a conhecem como a Protetora Alada, mas aqueles de nós que vivem sob o abrigo das estrelas em Targon a conhecem como a filha da Justiça, portadora de um propósito divino e de uma espada de fogo estelar.\"\n– Guardião Mitológico Skai'en"},{"s":"06MT008T2","n":"Kayle","f":"\"Nós certamente a reconheceríamos caso ela retornasse... mas, infelizmente, acredito que haja poucos motivos para tal além de uma ameaça tão terrível que exija sua interferência.\" – Guardião Mitológico Skai'en"}]},{"id":"houses","name":"Casas Nobres","desc":"As casas que juraram lealdade à coroa e servem de exemplo ao povo. A Casa Crownguard, uma das famílias mais tradicionais de Demacia e guardiã do trono, da qual vêm Garen e Lux, que esconde sua magia. E as outras casas: Vayne, a caçadora de monstros, e Buvelle, de Sona, virtuose do etwahl, querida pela nobreza apesar da suspeita de que suas melodias sejam magia.","items":[{"s":"01DE042","n":"Lux","f":"\"Eu sempre soube que havia algo diferente em mim... uma luz que vem de dentro. Não sei bem o que é, mas tenho que descobrir!\""},{"s":"01DE042T2","n":"Lux","f":"\"Chega de me conter!\""},{"s":"09DE034","n":"Lux: Iluminada","f":"Luzes rodopiavam ao redor de Luxanna, e as pessoas da cidade observavam maravilhadas. Aqui, ela era a Dama do Resplendor de Demacia, jovem Stemmaguarda exemplar e maga talentosa. Ali, Demacia era tudo que ela sempre quis."},{"s":"09DE034T1","n":"Lux: Iluminada","f":"''Sou Luxanna, Dama do Resplendor, e não tenho medo! Você pode até tentar transformar Demacia em um pesadelo e mergulhá-la em escuridão, mas não existe sombra que eu não possa ofuscar!''"},{"s":"01DE002","n":"Tianna Stemmaguarda","f":"\"Nossa Casa já sangrou por este reino. Você não destruirá a honra da família por uns truquezinhos de luz baratos.\""},{"s":"06DE021T1","n":"Vayne","f":"\"... atirem para matar.\""},{"s":"lsona","n":"Sona","f":"A Mestra das Cordas.\nSona é um prodígio do etwahl , expressando-se apenas por meio de seus acordes graciosos e árias vibrantes. Seus modos gentis e refinados conquistaram a nobreza demaciana, embora alguns especulem que suas melodias cativantes, na verdade, exalem magia – uma possibilidade perigosa no reino.","l":1}]},{"id":"outros","name":null,"desc":null,"items":[{"s":"09DE045","n":"Alina Sonhaluz","f":"''Quando tinha sua idade, eu tinha tanto medo da luz. Não havia ninguém para me dizer que minha magia era uma bênção, que eu era assim por um motivo. Mas agora você tem a mim para te dizer isso. Não tenha medo, Alina. Deixe sua luz brilhar!'' – Lux: Iluminada"},{"s":"06DE019","n":"Caçadora Viúva","f":"\"Apesar de parecer uma lutadora competente, o luto dessa mulher é recente e ameaça consumi-la. O desespero é, sem dúvida, uma motivação atraente (eu que o diga), mas desmedido assim? Talvez ela queira morrer...\" – Do diário pessoal de Sirius Rowill, Cavaleiro-Patrulheiro Zeloso"},{"s":"01DE043","n":"Chefs de Guerra","f":"Não se deve subestimar ninguém do exército demaciano."},{"s":"06DE006","n":"Cozinheiro de Combate","f":"Depois de servir no exército demaciano, Breshi achou que ia se aposentar e cozinhar em uma taverna de algum vilarejo tranquilo. Mas esse sonho foi arruinado por Jax após uma briga de bar e uma opinião bem ruim sobre ovos com gema dura. Desde então, Breshi abraçou um novo objetivo de vida: ensinar Jax a ter um pouco de bom gosto."},{"s":"01DE034","n":"Ferreiro de Batalha","f":"Guerras são vencidas na forja."},{"s":"05DE003","n":"Gorlith, o Inescalável","f":"\"Um tributo honroso para aqueles que se foram, mas ficaram na memória: Quando as pessoas de Demacia virem os raios de sol refletindo na figura dele, saberão o que é esperança, e o espírito indomável que inspirou a construção viverá através dele.\"\n– Placa da oficina Durand"},{"s":"09DE031","n":"Jarro Plumaluz","f":"Um jovem com uma máscara de baile aparece diante dela com um floreio de pétalas de rosas e criaturas luminescentes. ''Meu nome é Plumaluz. Jarro Plumaluz'', ele disse. ''Fiquei sabendo que talvez você estivesse precisando de ajuda, senhorita.''"},{"s":"08DE022","n":"O Martim-Pescador","f":"''Lembre-se, meu filho: buscar qualquer horizonte deve ser em serviço do lar que deixamos para trás.'' – Rei Jarvan III"},{"s":"05BC041T1","n":"Poppy","f":"O poder é uma força que corrompe muitos, mas Poppy é a prova viva de que essa corrupção não é páreo para um bom coração e uma inocência teimosa e inabalável."},{"s":"llocke","n":"Locke","f":"O Exorcista das Cinzas.\nCorvin Locke, um exorcista versado em ritos proibidos e na arte de atirar pregos, é a prole dos ocultistas demacianos. Nascido em meio a mentiras e hipocrisia, ele aprendeu desde cedo que demônios não são a causa das trevas da humanidade, mas sim a consequência. Agora, Locke rasga cada alma e expõe sua escuridão, determinado a tornar o mundo um lugar mais honesto... um exorcismo de cada vez.","l":1}]}],"places":[{"s":"07DE008","n":"Altar à União","f":"A primeira vez que viu o Altar, Cithria ficou sem palavras. Por um tempo, ela ficou imóvel e maravilhada com a magnanimidade daqueles nobres heróis. Seria ela ousada o suficiente para estar ao lado deles?"},{"s":"06DE035","n":"Pilar de Petricita","f":"Os Caçadores de Magos colocam enormes obeliscos de petricita em seus complexos, garantindo que até os magos mais fortes fiquem completamente impotentes."},{"s":"ufa5b79ce1e","n":"A Cidadela do Alvorecer, palácio de Jarvan III","u":1},{"s":"ub7b522569e","n":"A Grande Praça de Demacia, onde seus regentes são apresentados para a aclamação do povo","u":1},{"s":"u7657508ba5","n":"Alta Pratânia, uma cidade nos planaltos rochosos no nordeste de Demacia","u":1},{"s":"uc8d4b4194d","n":"O Templo dos Arautos da Luz","u":1},{"s":"wdb4797e7c0","n":"Demacia (arte conceitual 1)","w":1},{"s":"wf39e53d7fa","n":"Demacia (arte conceitual 10)","w":1},{"s":"wd339fef587","n":"Demacia (arte conceitual 11)","w":1},{"s":"w41041c3c0c","n":"Demacia (arte conceitual 12)","w":1},{"s":"w1af19d08e5","n":"Demacia (arte conceitual 13)","w":1},{"s":"w35fdb792db","n":"Demacia (arte conceitual 14)","w":1},{"s":"w11b8e14078","n":"Demacia (arte conceitual 15)","w":1},{"s":"w0cc7d76798","n":"Demacia (arte conceitual 16)","w":1},{"s":"wd03faf17fb","n":"Demacia (arte conceitual 17)","w":1},{"s":"w9fb63d1e9c","n":"Demacia (arte conceitual 2)","w":1},{"s":"w8b62ba9a10","n":"Demacia (arte conceitual 3)","w":1},{"s":"wddca137582","n":"Demacia (arte conceitual 4)","w":1},{"s":"w6065788ec3","n":"Demacia (arte conceitual 5)","w":1},{"s":"wafdfb5265c","n":"Demacia (arte conceitual 6)","w":1},{"s":"wa6ead98ae7","n":"Demacia (arte conceitual 7)","w":1},{"s":"w61f90debc0","n":"Demacia (arte conceitual 8)","w":1},{"s":"waf1c1d00ad","n":"Demacia (arte conceitual 9)","w":1}],"creatures":[{"s":"08DE026","n":"Alatis, o Imponente","f":"\"A bem da verdade, eu nem sempre fui aliado dos dragões. Mas Alatis aqui me convenceu quando salvou a minha vida pela primeira vez. Ele me ensinou muito, mas sabe o que é mais importante? Não há nada melhor que servir a Demacia montado em um dragão.\" – Aliado dos Dragões"},{"s":"06DE043","n":"Capricão de Confiança","f":"\"Ela não é tão rápida quanto uma rapina prateada, mas a rapidez das suas perninhas surpreende qualquer um.\"\n– Cithria, Dama das Nuvens"},{"s":"05DE015","n":"Dragão da Montanha","f":"Apesar de sua aparência, os serenos dragões da montanha não se irritam facilmente, e seu estoicismo ao redor de outras criaturas montanhesas faz com que sejam defensores natos de rebanhos vulneráveis."},{"s":"08DE025","n":"Dragão das Nuvens","f":"Com uma espessa pelagem que o protege do frio, este dragão pode atingir altitudes muito mais elevadas do que a maioria dos outros. Enérgicos, porém esquivos, os dragões geralmente são avistados lá no alto, com suas asas cortando as nuvens enquanto saltam entre rajadas de vento."},{"s":"03DE006","n":"Dragão Furioso","f":"Todas as criaturas protegem seus filhotes com unhas e dentes, mas poucas são tão bem equipadas para lidar com possíveis ameaças quanto um dragão."},{"s":"06DE029","n":"Elkin Inabalável","f":"\"Para trás, criatura vil! Se arrancar um único fio do pelo imaculado da Pureza, vou garantir que você sofra uma AGONIA ETERNA!\" – Sirius Rowill, Cavaleiro-Patrulheiro Zeloso"},{"s":"07DE015","n":"Falcoleão Cristado","f":"\"Os registros confirmam o primeiro avistamento do falcoleão em quase cinquenta anos. Linda crista azul, olhos inteligentes. O corpo é blindado, mas os ossos são leves o suficiente para escalar árvores e até planar com alcance limitado. Estruturas de asas quase reminiscentes de rapinas demacianas. Retornarei com mais detalhes.\" – Do diário de campo de Anura, dia 12"},{"s":"06DE028","n":"Harpia Maldissangue","f":"\"Kian, se você estiver lendo isso... espero que eu já tenha morrido. Não consigo controlar o que está acontecendo comigo. O sangue sob as minhas unhas não sai. E sinto tanta coceira. Coço e coço, mas não adianta. Dói. Só quero que isso acabe. Se eu tiver sobrevivido, prometa que vai parar de tentar me encontrar.\n\nEu pediria perdão, mas não mereço."},{"s":"03DE007","n":"Kadregrin, o Infernal","f":"Quando Demacia sofreu uma súbita onda de ataques de dragão, Shyvana sabia que a culpa era de Kadregrin, o Infernal. Outros dragões, inspirados pela natureza ousada e pela poderosa chama de Kadregrin, levaram terror aos demacianos."},{"s":"06DE034","n":"Loba Leal","f":"\"A Maggie está comigo desde que era filhote. Pode até já estar velha, mas ainda é mordaz feito uma lâmina recém-afiada. Eu daria a minha vida por ela — e sei que ela daria a dela por mim.\" – Janan, a Caçadora Viúva"},{"s":"03DE013","n":"Matriarca Vigilante","f":"\"Cuidado, soldados! Se tivermos cautela e não perturbarmos o ninho, podemos manter a mãe na defensiva. Se a importunarmos mais... Bom, é melhor estarmos prontos para correr.\" – Anden Mayne, Pesquisador Acadêmico"},{"s":"06DE036","n":"Patriarca Protetor","f":"\"Felizmente, minha pesquisa sugere que os patriarcas da ninhada passam a maior parte do tempo caçando a uma boa distância das crias. Podemos concluir que, se o macho voltar, viraremos todos comida de dragão! Haha!\" – Anden Mayne, Pesquisador Acadêmico"},{"s":"04DE013","n":"Petricórnio Imponente","f":"Dizem que os majestosos petricórnios vêm da época em que a floresta de petricita ainda era jovem, e que os chifres são feitos de um material similar ao que dá forma a essas árvores anciãs."},{"s":"02DE003","n":"Texurso Leal","f":"É verdade o que dizem. Os animais realmente se parecem com seus donos."},{"s":"06DE048","n":"Texurso Segurança","f":"''Se veio pra ser amigo, seja muito bem-vindo, viu? Mas, se alguém com coração ardiloso botar um pezinho aqui, vai provar a vingança do poderoso protetor!''"},{"s":"u5f90cfc71d","n":"Ascensão do Ninho de Rapina","u":1},{"s":"u44fb87b42e","n":"Envergadura da Rapina","u":1},{"s":"u247289e559","n":"Rapinas Demacianas","f":"Nativas de altos penhascos, as rapinas são predadoras vorazes. Ainda assim, sabe-se de indivíduos raros que conseguiram forjar um vínculo tão poderoso com essas criaturas ao ponto da rapina permitir ser montada. Esses cavaleiros de rapina servem ao exército demaciano, patrulhando e importunando as linhas inimigas.","u":1},{"s":"u0d3b5bd503","n":"Rapinas Demacianas","u":1},{"s":"weda6b785f2","n":"Fera de Demacia (arte conceitual 1)","w":1},{"s":"w5939c5d710","n":"Fera de Demacia (arte conceitual 2)","w":1},{"s":"w3d55e29d0a","n":"Fera de Demacia (arte conceitual 3)","w":1},{"s":"wab9e09f425","n":"Fera de Demacia (arte conceitual 4)","w":1}]},"shadow-isles":{"groups":[{"id":"sentinels","name":"Sentinelas da Luz","desc":"Uma antiga ordem que combate a Névoa Negra e os mortos. Senna, Lucian e Akshan levam sua luz pelo mundo.","items":[{"s":"04SH130","n":"Akshan","f":"''O código dos Sentinelas tem muitas restrições complicadas. Coisas como 'Nunca tire uma vida em nome da vingança' e 'Lute pelo mundo, não por si mesmo'. Já eu...''"},{"s":"04SH130T2","n":"Akshan","f":"''Meu código é bem mais simples: eu simplesmente ignoro qualquer regra que me impeça de fazer o que quero.''"},{"s":"05SI010","n":"Dess e Ada","f":"\"Outro pesadelo?\"\n\"Dessa vez não foi tão ruim. Você não estava lá.\"\n\"Besta. E qual foi a parte ruim?\"\n\"Você não estar lá.\""},{"s":"05SI009T1","n":"Senna","f":"\"Estávamos errados. A Névoa Negra não é desprovida de sentimento nem acontece por acaso. Ela tem um propósito, portanto podemos rastreá-la. E fazê-la sangrar.\""},{"s":"01DE038","n":"Senna, Sentinela da Luz","f":"\"Sentinelas são a primeira linha de defesa entre os incansáveis mortos-vivos e os reinos humanos. Atacamos primeiro e com tudo o que temos, e NUNCA recuamos quando a vida de nossos companheiros está em jogo.\""},{"s":"05SI015","n":"Sentinela Buhru","f":"As filosofias dos Buhru e dos Sentinelas compartilham de um único ponto crucial: todas as coisas devem ter um fim, e algumas precisam ser obrigadas a chegar lá."},{"s":"05SI008","n":"Sentinela Ixtalense","f":"\"Senna, você me perguntou o que me trouxe até aqui. É verdade que não perdi nada para a Névoa, já que ela não ameaça minha terra natal. Mas ela existe, mesmo quando não deveria. Estou aqui para saber por quê. Preciso mesmo de um passado triste para me juntar à causa?\""},{"s":"05SI011","n":"Sentinela Prodígio","f":"O que será que a Névoa vê ao se deparar com Maeve? Exuberância, confiança... otimismo inabalável? Seja o que for, mal deve ver a hora de apagar essa chama insolente. Afinal, o que a morte teme se não o ardor da vida?"},{"s":"05SI012","n":"Sentinela Solari","f":"\"Não sinto mais a energia do sol. Mesmo assim, mantenho-a em minhas lembranças — isso já é suficiente.\""}]},{"id":"spider","name":"Culto da Aranha","desc":"Elise e seus devotos, que oferecem vidas a Vilemaw, a aranha gigante das Ilhas.","items":[{"s":"01NX023","n":"Anfitriã Aracnídea","f":"Com um único olhar, você pertence a ela. E com uma única mordida, você pertence a elas."},{"s":"07SI010","n":"Aracnídeo Necrótico","f":"Encontradas apenas nas regiões mais tenebrosas das Ilhas das Sombras, essas aranhas secretam um necroveneno letal que anestesia a pele enquanto apodrece a carne."},{"s":"01NX055","n":"Aranha Doméstica","f":"\"Minhas aranhas adoram companhia. Pena que a recíproca não é verdadeira.\" – Elise"},{"s":"07SI012","n":"Caranguejeira Fiandeira","f":"Caranguejeiras fiandeiras tomam muito cuidado ao criar seus ninhos. Elas são especialmente afetuosas com suas crias aracnídeas... mas igualmente cruéis quando se trata de ameaças em potencial."},{"s":"01SI002","n":"Cria Aracnídea","f":"\"Eu, hein? Tá com medo de quê? É só UMA aranhazinha.\"\n– Lorde Sassen, Aristocrata Azarado"},{"s":"01NX015","n":"Cria Preciosa","f":"Ela ama todas elas, mas ama esta aqui um pouquinho mais."},{"s":"01SI053T2","n":"Elise, a Aranha Rainha","f":"A beleza está nos vários olhos de quem vê."},{"s":"04NX016","n":"Fiandeira Estridente","f":"\"Vamos, meu bem. Deixe que as outras ouçam o seu chamado. Você sabe como isso as atiça... e sabe como me agrada.\" – Elise"},{"s":"01SI027T1","n":"Maldíbula","f":"\"Quem é seu deus? O que ele pode fazer? Seu deus te deixaria morrer e definhar por ele? Ou ofereceria mais vida do que qualquer mortal jamais teve? Para que servir a um deus que não te serve?\" – Elise"},{"s":"01SI056","n":"Predadora Desenfreada","f":"\"Elas fazem uma teia do tamanho de um homem em menos de um minuto... Quer uma demonstração?\" – Elise"},{"s":"01SI039","n":"Terror Aracnídeo","f":"Alguns espíritos maléficos se inspiram na fauna local, transformando o familiar em algo apavorante."},{"s":"06NX044","n":"Urdidora Sorrateira","f":"''Uma boa mãe ensina os filhos a caçar, mas uma grande mãe... caça por eles.'' – Elise"},{"s":"01NX046","n":"Vigia Aracnídea","f":"\"Ah, como ela me cativa! Suas pernas longas, sua voz que me paralisa de tanta doçura e seus olhos vermelhos como as rosas. E pensar que ela escolheu jantar comigo!\"\n– Aristocrata Azarado"}]},{"id":"helia","name":"Os Heliatas","desc":"Os sábios, escrivães e guardiões de Hélia, a cidade das Ilhas Abençoadas antes da Ruína, e os que sobreviveram a ela: Karthus, o cantor da morte, Yorick, o pastor de almas, Gwen, a costureira, Maokai, o treant, e Thresh, o carcereiro que coleciona almas numa lanterna, junto de quem ele guia ou caça.","items":[{"s":"01SI032","n":"Cronista da Ruína","f":"Ela costumava se sentar ao lado do pai – um lorde que trabalhava como curador – enquanto ele estudava os tomos empoeirados. Ele desejava que a filha continuasse seu trabalho... mas não assim."},{"s":"02SI004","n":"Defensora Arruinada","f":"\"Cada coração é um jardim onde raízes podem se fixar!\""},{"s":"01SI018","n":"Escriba das Lamentações","f":"\"E nosso autor mal sabia que logo a Ruína... a Ruína... não, não, não, droga, a tinta vazou de novo! E nosso autor... não, não, não!\""},{"s":"01SI048","n":"Guardião Amaldiçoado","f":"Loucura e tempo. Não há dupla mais impiedosa."},{"s":"06SI012","n":"Gwen","f":"Gwen retalhou a Névoa Negra, achando estranho como toda aquela área já tinha sido completamente envolvida por ela. Depois do seu corte e recorte, a mansão encantada apareceu entre as árvores sombrias como um farol e, como era de se esperar, Gwen se sentiu atraída por ela. Era tão intrigante, tão... grandiosa!"},{"s":"06SI012T1","n":"Gwen","f":"Ela sabia que a Névoa Negra tinha que ser removida de onde havia se infiltrado, e toda a luz e a alegria que os espíritos tinham dado a ela tornaram a empreitada mais fácil. Se ela pudesse contribuir para a celebração deles, melhor ainda!"},{"s":"02SI008T2","n":"Maokai","f":"Ele destruiria a praga que aflige essas ilhas e restauraria a vida perdida."},{"s":"01SI023","n":"Pastora de Almas","f":"Apenas os caídos sabiam que ela não andava só. Apenas eles conseguiam enxergar os inúmeros companheiros que ela guiava para terras longínquas."},{"s":"01SI026","n":"Presa do Guardião","f":"Ele prendeu a respiração o máximo que pôde, rezando para que o Guardião fosse embora. Mal sabia ele que a perseguição era só o começo do tormento que fazia Thresh se deleitar..."},{"s":"01SI051","n":"Prodígio Atormentado","f":"Trabalhava noite e dia aperfeiçoando sua composição. Então, em um piscar de olhos, um silêncio sombrio passou por ele. Outros gritaram e fugiram para se salvar. Mas ele não percebeu nada."},{"s":"01SI052","n":"Thresh","f":"\"Clink, clenk, lá vêm as correntes trazendo a sua sina...\nClink, clenk, com suas correntes, o Guardião se aproxima...\""},{"s":"01SI052T1","n":"Thresh","f":"\"Você pertence a mim. Para sempre.\" Clink, clenk, com suas correntes, o Guardião se aproxima..."},{"s":"u16d5911288","n":"Cidadãos das Ilhas das Bênçãos","u":1},{"s":"ued7ff4acd4","n":"Escrivão Eterno","f":"Muitos dos humildes escrivães e arquivistas das Ilhas das Bênçãos morreram nos seus púlpitos, sem notar o desastre que recém caíra sobre eles. Essa alma perdida agora escreve fervorosamente descrições do seu tormento em um pergaminho infinito.","u":1},{"s":"u9b0c6033a8","n":"Pastor de Almas","f":"O Pastor de Almas procura proteger espíritos mais fracos de espectros predatórios.","u":1},{"s":"ua1295d0f5d","n":"Thresh","u":1},{"s":"lkarthus","n":"Karthus","f":"A Voz Mortal.\nKarthus, o presságio do fim, é uma aparição imortal cujas canções perturbadoras são um prelúdio para o terror de sua aparência horripilante. Os vivos temem a eternidade da morte em vida, mas Karthus vê apenas beleza e pureza em seu abraço, uma união perfeita de vida e morte. Quando Karthus emerge das Ilhas das Sombras, ele traz a alegria da morte aos mortais, como um apóstolo dos mortos-vivos.","l":1},{"s":"lyorick","n":"Yorick","f":"O Pastor de Almas.\nÚltimo sobrevivente de uma ordem religiosa há muito esquecida, Yorick é ao mesmo tempo abençoado e amaldiçoado pelo poder que tem sobre os mortos. Preso nas Ilhas das Sombras, suas únicas companhias são os defuntos e os espectros atormentados que ele atrai para si. As ações monstruosas de Yorick mascaram seu nobre propósito: libertar sua terra da maldição da Ruína.","l":1}]},{"id":"revelry","name":"Festa da Meia-Noite","desc":"Espíritos que ainda dançam, tocam e brindam nos salões assombrados das Ilhas das Sombras, repetindo as festas de uma vida que já acabou, e o poeta sombrio Grimm.","items":[{"s":"06SI022","n":"Amante Espectral","f":"Não sei se ele era um fantasma, uma lembrança ou um sonho, mas algo nele não me era estranho..."},{"s":"06SI016","n":"Anfitrião Animado","f":"\"Você está CORDIALMENTE CONVIDADO para uma festa memorável no FESTIVAL DA MEIA-NOITE. Venha beber, dançar e celebrar conosco na MANSÃO DE PORCELANA! (A festa acabará exatamente ao raiar do dia)\"\n– Convite escrito à mão com uma caligrafia sofisticada"},{"s":"06SI009","n":"Banda Assombrosa","f":"O repertório era impressionante. Minuetos, valsas, baladas e músicas populares. Mas a verdade é que os convidados estavam loucos por algo novo."},{"s":"06SI013","n":"Eternas Dançarinas","f":"É sempre mais fácil juntar-se a alguém na pista de dança do que ser a primeira pessoa lá. As gêmeas, porém, estão sempre dispostas a mostrar aos outros como se faz."},{"s":"06SI028","n":"Mordomo Espectral","f":"O que seria de uma festa chique sem bebidas chiques?"},{"s":"06SI038","n":"Prodígio Redimido","f":"Tentar alcançar a perfeição era limitador, rígido. A perfeição não tinha vida; não podia respirar. Agora, a imperfeição perfeita, ela sim era algo pelo qual valia a pena lutar."},{"s":"06SI026","n":"Regente das Névoas","f":"\"Podem tocar, amigos! Este será o concerto mais animado de todos os tempos!\""}]},{"id":"specters","name":"Espectros e almas penadas","desc":"Os mortos das Ilhas das Sombras: almas presas à Névoa que perderam o corpo, mas guardam fragmentos de memória, personalidade e desejos, dos espectros mais fracos aos que ainda lembram quem foram, e a Névoa Negra que os prende.","items":[{"s":"01SI048T1","n":"Aberração Liberta","f":"O tempo pode parar, mas a loucura continua."},{"s":"01SI011","n":"Açougueiro Voraz","f":"Você é o que você come."},{"s":"04NX022","n":"Desafiadora Destruída","f":"Ao final de sua sentença, Thea sabia que nunca voltaria para casa. A guerra – e Noxus – tinham feito dela uma assassina. Ela nunca teria paz. Sendo assim, ela resolveu tirar proveito de suas novas habilidades na arena."},{"s":"04DE020","n":"Dracoguarda Destruído","f":"A Névoa se apossou da mente de Gregem, fazendo-o reviver Wrenwall incessantemente. Tomado pela fúria e amargura que guardava dentro de si, ele se voltou contra seus antigos companheiros."},{"s":"07SI013","n":"Espectreva Proliferante","f":"''A Névoa me ensinou muitas coisas. De todas as lições, a mais importante foi saber quando correr.'' – Sentinela Ixtalense"},{"s":"01SI014","n":"Espectro da Névoa","f":"Esses espectros das Ilhas perderam a identidade, transformando-se em um amálgama de fome pura e insaciável."},{"s":"06SI034","n":"Espectro dos Ecos","f":"\"Eu não sei que tipo de magia perversa praticam e nem QUERO saber. Tudo o que preciso saber é que, caso se ergam, vão morrer. De novo.\" – Vigilante das Ilhas"},{"s":"08SI018","n":"Espectrógrafo","f":"\"O terreno é inescrutável. A visibilidade, próxima de zero. Eu encontrei inimigos em cada curva... mas, estranhamente, aliados inesperados também.\" – Registros de expedição da Divisão de Grandes Distâncias da Guilda dos Exploradores, alocação: Ilhas das Sombras"},{"s":"01SI007T1","n":"Espírito Libertado","f":"... a cada espírito, uma nova vítima fascinada pela relíquia. Eles vagam em silêncio enquanto aguardam o próximo idiota ganancioso."},{"s":"01SI009","n":"Espíritos Agitados","f":"Diante da Ruína, alguns enxergam apenas destruição e sofrimento. Outros veem uma oportunidade."},{"s":"01SI016","n":"Evocadora de Espectros","f":"Ela aparece sem fazer som algum, mas os horrores que traz consigo são bem menos sutis."},{"s":"01SI038","n":"Fantasma Travessa","f":"Massacrar os soldados que acreditaram no choro de uma garotinha não foi sua travessura mais cruel: foi plantar a dúvida nos sobreviventes para que ignorassem o choro das próprias filhas..."},{"s":"05SI013","n":"Guardiões da Névoa","f":"A Névoa Negra aprisiona suas vítimas em ciclos de tormento sem fim infligidos por si mesmas. E é através dos Apanhadores da Névoa que Tek e Kana dão a essas almas uma chance de quebrar esses ciclos."},{"s":"04DE016","n":"Kadregrin, o Destruído","f":"Kadregrin já semeava o caos antes da chegada da Névoa Negra a Demacia. Porém, sob o comando de Viego, suas habilidades passaram a servir às forças do Rei Destruído."},{"s":"09SI017","n":"Kharox","f":"Dizem que Kharox, o remador solitário de um barco espectral que muitos marinheiros chamam de Última Barca, comunga com os espíritos de todos os marujos que pereceram tentando chegar às Ilhas."},{"s":"01SI044","n":"Matrona Espectral","f":"A Ruína corrompeu todos em seu caminho. Os gentis se tornaram cruéis. Os corajosos se tornaram violentos. A razão deu lugar ao ressentimento."},{"s":"01SI058","n":"Mensageiro Etéreo","f":"Espíritos, emprestem suas vozes a mim! Juntos, invocaremos uma escuridão sem fim!"},{"s":"04SI045","n":"Névoa Invasora","f":"Cada ser vivo que se vê diante da Névoa Negra enxerga algo diferente, seus próprios medos manifestados e representados em formas vagas e turvas."},{"s":"01SI041","n":"O Imortal","f":"O velho mártir se lembrava de ter levado seus companheiros diretamente para a morte. Porém, há muitos anos não consegue lembrar o por quê..."},{"s":"01SI020","n":"O Reacendedor","f":"Qual é o propósito de uma vela prestes a se apagar senão o de acender sua sucessora?"},{"s":"03SI015","n":"Observador Inoportuno","f":"Muitos dos espíritos das Ilhas das Sombras são criaturas absolutamente aterrorizantes e mórbidas. Mas alguns são só... hã... beeeem irritantes."},{"s":"01SI031","n":"Precursor de Ferro","f":"Na morte, assim como em vida, ele grita seus comandos deturpados e malignos. Na morte, assim como em vida, os cavaleiros leais de Hecarim respondem, avançando para iniciar o massacre."},{"s":"04BW016","n":"Rex Destruído","f":"''...Rex?'' – Suboficial"},{"s":"01SI035","n":"Rhasa, o Ruptor","f":"\"Disseram que... seria a jornada de uma lenda. Deveríamos proteger... o futuro de Demacia. Velejamos com tanta esperança. Mas tudo... todas aquelas vidas... para quê?\"\n– Arie Wrence, soldado demaciano"},{"s":"06SI019","n":"Sultur","f":"\"Cuidado com as pessoas que sorriem nestas ilhas assombradas. Talvez sejam recém-chegadas e não compreendam a brutalidade do lugar. Talvez sejam loucas. Talvez não sejam nada disso. Mas cuidado.\"\n– Anotações de Jens Tommen"},{"s":"05SI004","n":"Vigilante das Ilhas","f":"\"O cachorrinho é o cachorrinho.\" – Sabedoria rabiscada na alma"},{"s":"06SI046","n":"Vigilante Determinado","f":"''... e, assim, eu continuo vigilante, por toda eternidade, além da vida e da morte. Esse é meu dever.''"},{"s":"06SI041","n":"Vigilante do Vale Enluarado","f":"Longe das margens das Ilhas das Sombras, há bosques de árvores consideradas mortas há muito tempo, tortas e imóveis para todos, exceto para um excelente observador, que notará que, no solo encharcado pelo luar, surge nova vida."},{"s":"u7e433b8800","n":"Além das Ilhas","f":"Apesar de espíritos mais fracos só conseguirem se manifestar durante um Tormento, entidades mais poderosas podem fazê-lo sempre, às vezes até se aventurando para além das Ilhas das Sombras.","u":1},{"s":"u66e1d9c42d","n":"Igual Atrai Igual","f":"Qualquer mortal que pisar nas Ilhas das Sombras atrairá os espíritos dos caídos.","u":1},{"s":"u49f535288e","n":"Morte Eterna","u":1},{"s":"u335e87cf52","n":"Obstinados","f":"Os espectros mais poderosos conservaram muito de sua personalidade e desejos mesmo depois da Ruína, tornando-se espíritos predatórios que podem caçar os mais fracos e vulneráveis por toda a eternidade.","u":1},{"s":"uf31b723fcc","n":"Viúva dos Cantos Esquecidos","f":"A Viúva das Canções Esquecidas era uma colecionadora de pássaros que tentou libertá-los quando o desastre chegou. Ela agora anda sem rumo, procurando por canções das quais ela não consegue mais lembrar.","u":1}]},{"id":"outros","name":null,"desc":null,"items":[{"s":"01SI043","n":"Aristocrata Azarado","f":"\"S-Senhora Elise? A-Aonde você foi?\""},{"s":"02SI001","n":"Colecionador da Nunclareira","f":"\"Encontrei com Niven esta... o novo barqueiro! Ele remou... até... ele até canta bem! Antes... convidá-lo para jantar um dia.\" – Diário recuperado"},{"s":"01SI012","n":"Pescador Distraído","f":"Ah, pobre rapaz..."},{"s":"06SI018","n":"Vora","f":"Ao contrário de outros demônios, que atraem as vítimas com mentiras, Vora é muito objetiva em seus desígnios, muito dominada pelo desejo. Em vez de uma predadora em busca de comida, ela é uma fera selvagem que precisa ser alimentada."}]}],"places":[{"s":"05SI014","n":"Catálogo de Arrependimentos","f":"Do que Ilhas das Bênçãos esquecem, as Ilhas das Sombras se lembram. Do que as Ilhas das Sombras se esquecem, as Ilhas das Bênçãos se lembram."},{"s":"08SI036","n":"Limiar Cinzento","f":"\"Estas almas, nós oferecemos a ti. Este caminho, nós pavimentamos com ossos diante de ti. Estes reinos, nós rasgamos ao meio para abrir caminho para o teu eterno exército de ferro.\" – Cultista do Aperto Mortal"},{"s":"04SI018","n":"O Arvoredo Retorcido","f":"Um altar já esquecido\nEm uma trilha abandonada\nQue na escuridão ainda abriga\nA fera que ali fora deixada"},{"s":"09SI015","n":"O Belo Desastre","f":"Ele subiu os degraus do palco segurando o poema na mão. Ele não colocou nenhum cartaz para anunciar a declamação, pois já tinha a única plateia que desejava."},{"s":"06SI014","n":"Saguão Opulento","f":"\"Os participantes estão prontos, o palco está montado, nosso público aguarda. Maestro, por gentileza!\" – Anfitrião Animado"},{"s":"06SI033","n":"Tumba Assombrada","f":"O som da espada no escudo foi como uma sentença de morte, e atraiu espíritos cujos laços com o mundo não tinham sido totalmente cortados, cujos desejos não tinham sido saciados nem mesmo na morte."},{"s":"u43ed4eca99","n":"A Biblioteca","u":1},{"s":"ud25c8c8d5b","n":"A cratera que costumava ser uma grande galeria de antigos artefatos no coração das Ilhas das Sombras","u":1},{"s":"ud52b39ecad","n":"As Ilhas das Bênçãos","u":1},{"s":"u4656f926c8","n":"Campos Férteis","u":1},{"s":"u1c764cbb9a","n":"Cidades Inundadas","f":"Helia, a capital das Ilhas das Bênçãos, está localizada na costa. Como resultado, muitas partes da cidade foram alagadas depois da Ruína.","u":1},{"s":"uebe7e40b23","n":"Escondida dos Forasteiros","u":1},{"s":"u504f5e8065","n":"Fortaleza da Biblioteca","u":1},{"s":"ubb2cf6b965","n":"Interior da biblioteca","u":1},{"s":"ud7779248f4","n":"O Ateneu da Luz, onde as preces dos Vigias estão marcadas no chão e nas paredes","u":1},{"s":"u51640b20e1","n":"O Cofre Celestial, aberto pelas revelações do Hemisfério Lunatrópico","u":1},{"s":"uad9a79aa43","n":"O Resplendor de Alinhamentos dá início à jornada pela iluminação","u":1},{"s":"ufc677ad7a6","n":"O Salão da Conjunção, por onde todos os exploradores devem passar","u":1},{"s":"u2a7a19c44b","n":"Os Cofres de Arcana, a união da magia das trevas","u":1},{"s":"ub0a8947d6b","n":"Ponte das Ilhas das Bênçãos","u":1},{"s":"u85959f700c","n":"Quebra-cabeças Arquitetônicos","u":1},{"s":"w2cb85341f7","n":"Ilhas das Sombras (arte conceitual 1)","w":1},{"s":"wb61d20e1ea","n":"Ilhas das Sombras (arte conceitual 10)","w":1},{"s":"wb88f849b9b","n":"Ilhas das Sombras (arte conceitual 2)","w":1},{"s":"w9a367a1efb","n":"Ilhas das Sombras (arte conceitual 3)","w":1},{"s":"w23fc80052d","n":"Ilhas das Sombras (arte conceitual 4)","w":1},{"s":"we894708325","n":"Ilhas das Sombras (arte conceitual 5)","w":1},{"s":"w1aa7934a63","n":"Ilhas das Sombras (arte conceitual 6)","w":1},{"s":"w9b71fec021","n":"Ilhas das Sombras (arte conceitual 7)","w":1},{"s":"wd6348c98d1","n":"Ilhas das Sombras (arte conceitual 8)","w":1},{"s":"w4ff93d9e9c","n":"Ilhas das Sombras (arte conceitual 9)","w":1}],"creatures":[{"s":"03SI006","n":"Assombrofera","f":"Os viajantes ficavam mais cansados a cada noite. O sono deles era agitado e os sonhos, vívidos demais. Dormir não trazia descanso, apenas exaustão, como se as vidas fossem sugadas pouco a pouco."},{"s":"08SI037","n":"Caniferrus Espectral","f":"Essas feras nunca se esquecem do cheiro de alguém que tentou fugir... e, quando os canis cercam a presa, um ocasoquilador nunca está longe."},{"s":"01SI021","n":"Carruagem de Tubarões","f":"\"Ela viu O QUÊ? Entendi. A loucura é uma companheira cruel, boticário. Pelo menos os outros ainda demonstram um resquício de lucidez.\" – Cirurgião demaciano"},{"s":"07SI007","n":"Companheiro Sepulcral","f":"\"Acabei de ensinar um truque novo pra ele! Quer ver?\"\n– Fantasma Travessa"},{"s":"01SI057","n":"Crocólito Ancestral","f":"\"Coloque-os na gaiola, tum-ta-dum...\nArranque as almas deles, um por um...\nNão os deixe ir, não, senhor!\nE os outros espíritos tremem de pavor...\""},{"s":"01SI005","n":"Crustageist","f":"Este monstro já foi a calamidade de um reino há muito tempo esquecido. Agora, ele vasculha campos de batalha abandonados, adicionando restos à sua carapaça e almas ao seu âmago."},{"s":"01SI055","n":"Devora-Almas","f":"\"Enquanto nossa frota se aproximava das terras amaldiçoadas, eu pensei: aquelas criaturas terríveis surgiram desse lugar nefasto? Ou será que algum dia viveram de verdade?\" – Arie Wrence, soldado demaciano"},{"s":"04SI021","n":"Dracovíbora Rastejante","f":"A princípio, soldados demacianos ouviram o som de garras contra o chão da praça. Foi só quando elas invadiram a torre do relógio que eles finalmente perceberam que todos aqueles membros pertenciam a uma só criatura."},{"s":"04SI015","n":"Escaravelho Marinho","f":"\"Vamos, seus imprestáveis, preparem as armadilhas! E vale lembrar: se aparecer um escaravelho marinho, é pra cortar a corda e seguir viagem. Não vou expor minha quilha à carniça que sobrar do rango deles, entenderam?\" – Capitão de Águas de Sentina"},{"s":"03SI001","n":"Espreitador Eternebroso","f":"\"No começo, era só um par de olhos e uma voz solitária gorjeando nas sombras. Cada vez que eu olhava para trás, havia mais. Vozes cada vez mais altas, mais irritadas. Mas, assim que avistei o Dente, saí correndo.\" – Saqueador do Dente de Baleia"},{"s":"02SI006","n":"Fera da Casca","f":"As criaturas das Ilhas das Sombras abriram mão do sentimentalismo há muito tempo. Elas precisam comer."},{"s":"02SI010","n":"Florimorta Errante","f":"\"O grande ente continuou mostrando... criaturas. Esta... para espalhar a vida por onde passasse... notável como... aqui. Realmente são as Ilhas das Bênçãos!\" – Diário recuperado"},{"s":"04SI053","n":"Hidravinha Intrusa","f":"Maokai trabalhou incansavelmente para cultivar a vida nas Ilhas das Sombras. A ambivalência da Névoa não a torna menos cruel."},{"s":"02SI008T3","n":"Muda","f":"\"A vida aqui… nenhum esforço. Florestas verdejantes... brotam da noite pro dia… deslumbrante. Esta terra é um verdadeiro tesouro. Deve ser preservada… gerações.\"\n– Diário recuperado"},{"s":"03SI003","n":"Observadora Estígia","f":"À medida que o sol dá lugar à escuridão, os terrores deste lugar acordam, observam e esperam."},{"s":"04SI016","n":"Parasita Espiritual ","f":"Eles se escondem nas sombras, esperando um sinal de cansaço ou uma distração. Depois vêm as garras, a boca escancarada e, finalmente, a escuridão."},{"s":"01SI004","n":"Perdição das Águas Sombrias","f":"Alguns dos que fugiam da Ruína tentaram se jogar ao mar, acreditando que a corrupção não chegaria até as profundezas. Mas estavam enganados."},{"s":"01SI037","n":"Poro Sinistro","f":"Bom, existem jeitos piores de morrer."},{"s":"02SI007","n":"Sapo Espinhoso","f":"\"... espécie extraordinária... mesma criatura que encontrei na infância... não envelheceu nada! Será que... próxima cidade. Talvez esses incríveis camaradas vivam para sempre!\"\n– Diário recuperado"},{"s":"08SI021","n":"Sinuoso Solitário","f":"Não ligue para esse barulho sinistro, é só o velho Sinuoso fazendo a ronda. Ele sempre fica feliz em ver os recém-chegados... mas o sentimento certamente não é mútuo."},{"s":"02SI003","n":"Terror das Marés","f":"Eles perceberam o perigo tarde demais. A fera titânica abriu a bocarra e avançou na direção deles. Os caçadores só puderam esperar a morte chegar enquanto os dentes enormes destruíam o navio."},{"s":"02SI002","n":"Videira Vigorosa","f":"\"Hoje... mais uma extraordinária... veio à tona... crianças muito assustadas. Mas... nenhuma ameaça. Aproximou-se... criatura muito dócil. Vou procurar mais frutinhas para ela!\"\n– Diário recuperado"},{"s":"we208934c9c","n":"Criatura das Ilhas das Sombras (arte conceitual 1)","w":1},{"s":"w34841989c8","n":"Criatura das Ilhas das Sombras (arte conceitual 2)","w":1},{"s":"wa50d9c3251","n":"Criatura das Ilhas das Sombras (arte conceitual 3)","w":1},{"s":"we75c8eeee0","n":"Criatura das Ilhas das Sombras (arte conceitual 4)","w":1},{"s":"we4cf4e23eb","n":"Criatura das Ilhas das Sombras (arte conceitual 5)","w":1},{"s":"w99866f3238","n":"Criatura das Ilhas das Sombras (arte conceitual 6)","w":1},{"s":"wa6c361f273","n":"Criatura das Ilhas das Sombras (arte conceitual 7)","w":1},{"s":"w96178bddc3","n":"Criatura das Ilhas das Sombras (arte conceitual 8)","w":1}]},"freljord":{"groups":[{"id":"avarosan","name":"Avarosanos","desc":"A tribo de Ashe, que sonha unir o Freljord em paz. Arqueiros, guardas e caçadores das terras geladas.","items":[{"s":"01FR048","n":"Armadilheiro Avarosiano","f":"\"Não peguei nada a semana inteira! Ou as feras ficaram mais espertas, ou tem alguma coisa afugentando tudo...\""},{"s":"01FR011","n":"Arqueiro do Vale de Gelo","f":"Avarosianos têm orgulho de suas estações rigorosas e terras geladas. Seus perspicazes defensores demonstram isso."},{"s":"01FR038","n":"Ashe","f":"\"Quando olho para minha terra, eu vejo o que ela é, mas vejo também o que poderia ser. Próspera e abundante, não apenas para o meu povo, mas para todos que buscam a paz. Uma Freljord unida.\""},{"s":"01FR038T2","n":"Ashe","f":"\"Vocês não são nossos inimigos. O verdadeiro inimigo é um longo inverno sem lei. Somos todos freljordanos e esta terra pertence a todos nós!\""},{"s":"01FR036","n":"Atirador Avarosiano","f":"Em Freljord, ou você caça ou morre de fome."},{"s":"01FR037","n":"Batedores Avarosianos","f":"Quando as fileiras de reforços apareceram no cume, os Batedores se curvaram perante a mãe de guerra, pois a rainha Ashe, sua Avarosa encarnada, trazia a promessa de paz."},{"s":"01FR009T1","n":"Braum","f":"\"Preste bem atenção, pois vou contar a história de Braum e seu poro mais poderoso!\" – Ingvar, a Anciã"},{"s":"01FR041","n":"Guarda Termestre Avarosiano ","f":"\"Muitas tribos sob uma só bandeira! Talvez um dia Freljord inteira lute lado a lado.\""},{"s":"06FR028","n":"Revna, a Guardiã Mitológica","f":"Os guardiões mitológicos avarosianos costumam ser os anciãos mais experientes da tribo, protetores das pessoas e ótimos contadores de histórias. Eles mantêm viva a tradição da caça e da luta com histórias e canções."},{"s":"01FR050","n":"Taverneiro Gentil","f":"\"Este simpático estabelecimento é o Coruja Embriagada! Temos ensopados e bebidas para espantar o frio. Pode entrar!\""},{"s":"01FR039","n":"Tryndamere","f":"\"Não morra pela causa. Viva por ela...\""},{"s":"01FR039T2","n":"Tryndamere","f":"\"... e faça com que ELES morram por ela.\""},{"s":"06FR040","n":"Vigia das Tribos","f":"\"... e tinha uma criatura GRANDONA que cuidava de tooooodas as criaturas PEQUENAS...\" – Ingvar, a Jovem"},{"s":"01FR003","n":"Vigilante Avarosiano","f":"\"Já procurei meu lugar em campos de batalha distantes. Agora, encontrei-o em minha terra natal. Meus olhos servem ao povo, e a segurança de todos está em minhas mãos.\""}]},{"id":"winters-claw","name":"Garra do Inverno","desc":"A tribo guerreira de Sejuani. Saqueadores que acreditam que só os fortes merecem viver.","items":[{"s":"02FR008","n":"A Colmilhadora","f":"\"Quando a primavera traz um clima ameno o bastante para plantar, traz também as embarcações... e os grãos, antes abundantes, tornam-se escassos.\" – Guarda Termestre Avarosiano"},{"s":"02FR006","n":"Guerreira Impiedosa","f":"A Garra do Inverno domina Freljord, e todos conhecem a ferocidade de seus guerreiros implacáveis. Quando partem em busca de sangue, só resta torcer por uma morte rápida."},{"s":"02FR001","n":"Guerreira Incandescente","f":"\"Eles cultivam campos férteis,\nSemeiam o que vão comer.\nColocamos tudo em chamas,\nPra Garra do Inverno recolher!\" – Cantiga das crianças da Garra do Inverno"},{"s":"02FR009","n":"Guerreira Lupina","f":"Os jovens da Garra do Inverno ganham um filhote de lobo assim que conseguem segurar uma arma. Sua criação é totalmente dedicada à batalha. O lobo é treinado para massacrar e devorar, e o guerreiro para saquear e roubar."},{"s":"01FR054","n":"Rapinadora Cicatrizela","f":"\"Os fracos fazem a colheita, os fortes levam os frutos. Esses vermes avarosianos descobrirão o seu papel!\""},{"s":"01FR035","n":"Rapinadora Incólume","f":"\"Os avarosianos criam seus filhos de forma que envelhecem despreparados para o calor da batalha. Os nossos já nascem no fogo da própria guerra.\" – Vrynna, Mãe das Cicatrizes"},{"s":"02FR002T3","n":"Sejuani","f":"\"Botem todos pra correr! Mostrem que Freljord pertence à Garra do Inverno!\""},{"s":"01FR045","n":"Steffen, Tano das Cicatrizes","f":"\"Selei meu juramento à Garra do Inverno quando Sejuani me deu minha primeira cicatriz. Desde então, todas as minhas cicatrizes foram conquistadas a serviço dela.\""},{"s":"01FR013","n":"Vrynna, Mãe das Cicatrizes","f":"\"Prefiro morrer tremendo de frio a dividir uma lareira com os seguidores fracotes da Ashe. Mas se é calor que eles querem, é isso que terão.\""},{"s":"u7df5864a6b","n":"Assentamentos sazonais","f":"Durante as pilhagens feitas nos meses de verão, os guerreiros da tribo se espalham por uma vasta parte das terras nortenhas, tomando e reaproveitando tudo o que precisarem. À medida que o inverno chega, eles atracam os navios, criam assentamentos temporários e se preparam para esperar as noites mais longas e gélidas passarem, até que o clima mais ameno apareça outra vez.","u":1},{"s":"u39a9457552","n":"Caçando nas profundezas","f":"Sempre que as condições climáticas que cercam os mares congelados se tornam mais permissivas, os mergulhadores mais talentosos são enviados para se aventurar sob as ondas em busca de caça. Para garantir um pouco mais calor, eles espalham gordura de foca por todo o corpo e pelas roupas.","u":1},{"s":"ud5b94d25d0","n":"Montadores de feras","f":"Apesar do clima rígido e implacável, Freljord é lar de uma grande variedade de fauna fantástica que se adaptara especialmente para viver na região. Os Garra do Inverno não domesticam nem paparicam suas montarias. Em vez disso, encorajam o cultivo dos instintos mais selvagens e agressivos desses animais, até mesmo enquanto carregam os guerreiros.","u":1},{"s":"u866f8dcdac","n":"Saqueadores e rapinadores","f":"A morte percorre as terras de Freljord tomando inúmeras formas – presas, lâminas, queimaduras gélidas paralisantes e inanição extrema. Neste lugar, sobreviver significa lutar contra todas as faces da morte, esmagar qualquer ameaça e aproveitar qualquer vantagem. Cada aurora traz um novo dilema: faça o que tiver que fazer para sobreviver, ou morra. Para os Garra do Inverno, a escolha é muito óbvia.","u":1},{"s":"u1b9a11e5c1","n":"Tome o que precisar","f":"Os Garra do Inverno raramente permitem que algo seja desperdiçado. Suas armas, quando não passam de pedaços de madeira afiados e pedras esculpidas para o combate, são forjadas do aço de inimigos caídos. Tecidos grossos e peles de animais oferecem proteção contra o frio, acompanhados de adornos feitos de ossos, presas e chifres retirados dos troféus de maior destaque.","u":1},{"s":"u0ea7b00a18","n":"Uma tribo em marcha","f":"Às vezes, as rotas marítimas congeladas demoram mais que o esperado para se abrirem novamente. Alguns saqueadores mais impacientes preferem sacrificar um navio ou outro com o intuito de criar arreios para suas bestas de carga, levando o resto da frota para o mar aberto em uma tentativa de obter vantagem sobre os rivais menos engenhosos.","u":1},{"s":"lolaf","n":"Olaf","f":"O Berserker.\nUma força desenfreada de destruição, Olaf e seus machados não querem nada além de morrer em um combate glorioso. Vindo da brutal península de Freljord, Lokfar, ele recebeu uma profecia que dizia que ele teria uma morte pacífica: o destino de um covarde e um grande insulto entre seu povo.","l":1}]},{"id":"frostguard","name":"Guarda Gélida e os Observadores","desc":"Lissandra e seus seguidores guardam o Abismo Uivante. Em segredo, servem às entidades antigas presas sob o gelo.","items":[{"s":"03FR003","n":"Aquele que Encara","f":"\"Nem tivemos tempo de pegar nossas coisas ou avisar os outros. Só conseguimos correr para a floresta e assistir enquanto nossos lares eram destruídos.\" – Guarda Termestre Avarosiano"},{"s":"07FR005","n":"Bastião de Servos","f":"\"Depois que começa, a avalanche não pode mais ser detida.\" – Lissandra"},{"s":"06FR017","n":"Cultista do Vale de Gelo","f":"A Garra do Inverno tinha razão. Os avarosianos estavam sendo gentis DEMAIS. Estava na hora de uma nova pessoa tomar a liderança, alguém que não tentaria unificar Freljord através da paz, e sim governá-la."},{"s":"04FR006","n":"Inquisidor Draklorn","f":"\"Minha soberana se comunica comigo em sonhos, a voz jamais excedendo um sussurro. 'Siga-me', diz ela. Esse é um comando que não posso desobedecer.\""},{"s":"04FR005","n":"Lissandra","f":"\"Além desses muros, espreitam os Observadores, suspensos nas camadas de gelo, congelados no tempo... Enquanto aguardam, preciso dar início aos meus planos...\""},{"s":"04FR005T1","n":"Lissandra","f":"Poucos sabem o que Lissandra sacrificou para conquistar poder. Suas ambições eram grandes demais para serem impedidas por inconveniências mortais."},{"s":"04FR005T4","n":"Observador","f":"\"Este é o fim, como foi profetizado... e prometido por mim. Irmãs... me perdoem.\" – Lissandra"},{"s":"04FR001T1","n":"Servo Praeglacius","f":"Finalmente livre da tumba gélida, o troll corrompido só tinha certeza de uma coisa: ele precisava seguir os comandos de sua soberana sombria."},{"s":"uc79ba28b71","n":"Contendo a escuridão","f":"At key points throughout the Howling Abyss, gigantic spiked barricades of stone and iron were set into the walls by the Frostguard, many thousands of years ago. One day, when the Watchers reawaken, these meager defenses may buy some precious time for those above to prepare for the final battle.","u":1},{"s":"u5f58453419","n":"O domínio da Bruxa Gélida","f":"In the deepest halls of the Frostguard Citadel, Lissandra spends most of her waking hours in this grand, vaulted audience chamber. It is from here that she delivers her chilling sermons, hears the reports of her priests... and passes judgment on the fate of heretics among the tribes they serve.","u":1},{"s":"u3d28c70ca7","n":"Olhos no Abismo","f":"Warriors of the Keeper’s Lodge diligently patrol the locations of some of the largest known Watchers, or at least those closest to the icy surface. This particular beast is known as “the Pierce-Eye”, ever since it was skewered with titanic Mortis Stones dropped from the fortress high above.","u":1},{"s":"u1ec29de661","n":"Os Draklorn","f":"As the highest tier of the priesthood—answering only to the Ice Witch herself—Draklorn are among the most zealous and learned of all Frostguard. Some of them rarely set foot outside the Citadel’s walls, and they are no doubt privy to secrets that would never be entrusted to the lower ranks.","u":1},{"s":"u1973c52d61","n":"Pedras Mortis","f":"These sleek daggers of frozen granite, over a hundred feet in length, are weapons of last resort when a Watcher stirs from its slumber. The Frostguard have not needed to drop even a single stone in many centuries... but they stand ready to do so, whenever the alarm is raised.","u":1}]},{"id":"ursine","name":"Ursine (seguidores de Volibear)","desc":"Guerreiros ursinos devotos do semideus da tempestade. Selvagens, livres e ferozes.","items":[{"s":"09FR014","n":"Brynhir Cantotrovejante","f":"''Sou fruto da tempestade da montanha e da canção de meu povo!''"},{"s":"08FR011","n":"Caprina Chamabrasas","f":"\"O Senhor da Forja prometeu mudanças e, em vez disso, martelou as correntes da inação. Aqueles que adoram um deus fraco também são fracos. Somente pelo poder de Valhir alcançaremos a glória do passado!\""},{"s":"01FR047","n":"Místico Selvagem","f":"\"Aqueles que aprendem a rugir feito animais acabam esquecendo sua língua nativa.\" – Anivia"},{"s":"08FR002","n":"Profetisa de Valhir","f":"\"Eu vejo o que os outros não podem ver: a tempestade que aniquilará a montanha, os ossos da terra se quebrarão. A antiga Freljord será forjada novamente com sangue... é apenas uma questão de tempo.\""},{"s":"08FR003","n":"Ursine Berserker","f":"Às vezes, os seguidores de Volibear mergulham tão profundamente no fanatismo que começam a assumir aspectos do urso. Nada ficará no caminho da vontade de Valhir, nem mesmo aqueles que os Ursine outrora chamavam de conterrâneos."},{"s":"02FR005","n":"Ursine Caminhalma","f":"Os Ursine eram humanos, mas abriram mão das comodidades da vida mortal pelo poder feroz e selvagem concedido pelo grande espírito de Volibear."},{"s":"02FR005T1","n":"Ursine Tempesgarra","f":"Sem qualquer amarra, os Ursine deixaram de ser humanos e conquistaram o poder da tempestade. Eles percorrem as estepes geladas, e seus rugidos ecoam como estrondos de trovões."},{"s":"08FR001T1","n":"Volibear","f":"\"Como ousa me insultar com um desafio? Garota insignificante de terras distantes. Eu sou o coração da tundra! Eu sou a tempestade e prometo a você uma morte comum!\""}]},{"id":"hearthblood","name":"Ferreiros de Ornn","desc":"Os que honram Ornn, o semideus da forja: ferreiros, artesãos e os fogos-vivos do Freljord.","items":[{"s":"06FR012","n":"Artesã Aprimorada","f":"''Minha mãe me contou histórias sobre Ornn assim como a mãe dela o fez, e a mãe da mãe dela também. Hoje, eu farei o mesmo, então preste atenção. Nada de interrupções. Muito tempo atrás, do outro lado de um agitado e fumegante mar...''"},{"s":"06FR023","n":"Colosso Forjado","f":"Apesar de não admitir, Ornn ficou muito satisfeito com os colossos. Eles serviam ao propósito atribuído... e o melhor de tudo: não falavam."},{"s":"06FR004","n":"Ferreira Aprendiz","f":"Ornn construiu a forja viva muitos, muitos anos atrás, mas só foi procurar por ela recentemente. Ele jamais pensou que ela sairia por aí em busca de um novo dono."},{"s":"07FR009","n":"Ferreira Inovadora","f":"\"A bolinha de pelo pode até não me ajudar a trabalhar mais rápido, mas me deixa com um sorriso no rosto. Isso já é ajuda suficiente.\" – Ferreira Inovadora"},{"s":"06FR011","n":"Ornn","f":"Se alguém perguntasse por que Ornn tem tão pouca paciência, ele responderia que, na verdade, tem muita paciência. Paciência até de sobra, por isso seu trabalho é incomparável. O que ele não tem paciência é com PESSOAS. Mas ninguém nunca perguntou isso, então ele nunca deu essa resposta."},{"s":"06FR011T1","n":"Ornn","f":"Alguns acreditam que os escolhidos de Ornn finalmente encontrarão seu deus quando o mundo realmente precisar dele. Bem típico de deuses retraídos e teimosos, não é? Ser encontrado no último lugar imaginável?"},{"s":"06FR008","n":"Reparador Sangue da Fornalha","f":"Os Sangue da Fornalha já não existiam mais quando Ornn decidiu deixar o mundo. Gerações se passaram desde então, e o nome desse grupo quase foi esquecido. Porém, os contos sobre Ornn ressurgiram nos últimos tempos, e dizem que alguns voltaram a adotar o estilo de vida deles."}]},{"id":"old-gods","name":"Os Deuses Antigos e seus profetas","desc":"Semideuses como Anivia, Volibear e Ornn, e os xamãs que ainda falam com eles e com os espíritos.","items":[{"s":"01FR024","n":"Anivia","f":"\"Como filha desta terra hostil, meu dever é protegê-la. Nem o tempo, nem a guerra, nem mesmo a morte impedirá minha vigília.\""},{"s":"01FR024T3","n":"Anivia","f":"\"Cessem sua marcha e dispersem seus exércitos. O olho do inverno espreitou sua conquista, e as garras geladas sufocarão cada coração traidor.\""},{"s":"01FR052","n":"Aquela que Vaga","f":"\"Eu saí dos escombros e vi uma grande cauterização na terra ao meu redor. Em vez dos meus companheiros, havia cinzas fumegantes, e um vulto assombroso se movia ao longe...\"\n– Bjerg, o Andarilho"},{"s":"01FR034","n":"Aqueles que Perduram","f":"\"Ah, o velho Bjerg já viu de tudo um pouco. Perdeu sua tripulação no norte, voltou completamente desorientado meses depois. Agora só fala em feras gigantes e garras enormes. Coitado...\" – Taverneiro Gentil"},{"s":"08FR033","n":"Berserker Vinculâmina","f":"''Você acha que um punhado de flechas vai me impedir? Rá! Tudo que você joga contra mim se torna uma arma no meu arsenal. Tudo que for perdido será reforjado em gelo!''"},{"s":"05FR001T1","n":"Combatente Trevoguari","f":"Os xamãs do Trevoguari nunca morrem sozinhos. Na morte, juntam-se aos espíritos de outros xamãs e começam uma jornada pelo Grande Além como uma nova alcateia."},{"s":"05FR004","n":"Errante Vulpina","f":"\"Ambiciosa e cautelosa. Rápida e silenciosa. O estilo da raposa é a alegria de ver e não ser vista. Em viagens ou guerras, um líder sábio honra quem segue o espírito dela, pois não se vence batalha alguma sem desbravadores e batedores.\" – Vrynna, Mãe das Cicatrizes"},{"s":"06FR011T4","n":"Espírito do Carneiro","f":"''Depois do fogo, o que restar ou está forjado ou derretido. Melhor que seja algo de aço que tomará forma do que... algo que queimará até virar pó!'' – Ornn"},{"s":"05FR014","n":"Ira de Freljord","f":"\"Eu estive lá anos atrás... primeiro, veio o frio, penetrante e implacável. depois, a tempestade, colérica e indiferente. Por último, um rugido tão forte que abalou meus ossos. Caí de joelhos e orei para que não tivéssemos cometido um grave erro. Invocar um grande espírito é pedir por sua vingança... e misericórdia.\" – Vidente Hyara"},{"s":"05FR006","n":"Orador das Presas","f":"Poucas famílias xamânicas servem à tribo Garra do Inverno há tanto tempo quanto a de Chuluun. Sendo um xamã da grande morsa, ele pressagia e anuncia a fartura do mar... e os perigos dele."},{"s":"05FR005","n":"Ossividente","f":"Poucos preveem o futuro tão bem quanto os xamãs a serviço do Alce dos Ossos. Pouquíssimos aguentam ver a morte iminente de quem busca sua clarividência."},{"s":"01FR024T4","n":"Ovonivia","f":"Nas profundezas do abraço congelante do inverno, a guardiã de Freljord aguarda o momento de retornar."},{"s":"01FR033","n":"Pedras Destinadas","f":"\"Esses pilares de pedras ancestrais são lembretes de que somos os filhos de uma longa linhagem de tribos a enfrentar essas terras indomáveis\" – Ashe"},{"s":"03FR017","n":"Presságio dos Ancestrais","f":"Dizem que pouquíssimos trolls sabem os cânticos dos Ancestrais, mas que aqueles que os conhecem podem invocar seus antepassados para conceder força e resistência excepcionais a todos os companheiros."},{"s":"08FR015","n":"Rhond, a Serpente de Magma","f":"Embora poucos ainda o adorem, todos os freljordanos conhecem a história da grande batalha de Volibear contra Rhond. Muito antes de qualquer mortal pisar no norte congelado, esse confronto cindiu a terra e formou as cordilheiras e os rios da tundra."},{"s":"03FR010","n":"Rostos dos Ancestrais","f":"\"Venham, Ancestrais, venham,\nRompam os céus com mãos de gelo.\nVenham, Ancestrais, venham,\nTragam-nos força, e a eles, desespero.\"\n– Cântico dos Trolls"},{"s":"05FR013T4","n":"Udyr","f":"\"Estamos unidos como um só, coração e Espírito! Juntos, vamos despachar nossos inimigos para a noite fria e eterna!\""},{"s":"01FR032","n":"Vidente Constelado","f":"\"Que eles tenham ouvidos apurados para escutar a chegada do vento, pés leves para atravessar as nevascas iminentes e olhos penetrantes para enxergar além do véu do inverno.\""},{"s":"05FR012","n":"Vidente Hyara","f":"Respeitada por todos, a grande xamã, Vidente Hyara, perdeu a visão há muito tempo e enxerga através dos olhos dos falcões e águias que se aninham em sua casa no cume da montanha. Agora, notícias preocupantes levaram-na a descer a montanha... ela espera que os presságios não passem de meras visões."},{"s":"01FR040","n":"Xamã das Glacipresas","f":"\"Para entrar em comunhão com a natureza, o segredo é não se esconder do frio, mas sim apreciar sua brutalidade.\""},{"s":"05FR002","n":"Xamã Mamute","f":"Quando enfrentam predadores, as manadas de mamutes cercam os filhotes jovens e as fêmeas prenhas. Então, os xamãs do grande espírito do mamute invocam não apenas a força física do espírito, mas também a força da união, com a qual protegem sua família."},{"s":"05FR001","n":"Xamã Trevoguari","f":"\"Nós não morremos feito covardes! Morremos com garras e dentes à mostra, assim, honramos o Lobo.\" – Vidente Hyara"}]},{"id":"trolls","name":"Trolls do Gelo","desc":"Tribos de trolls reunidas em torno do Rei Trundle e de seu porrete de Gelo Verdadeiro.","items":[{"s":"03FR007","n":"Troll Catador","f":"O patrulheiro se ajoelhou junto a um trapo de pano enterrado na neve. Apesar do ar gelado, o cheiro de suor humano e de fumaça persistia.\nEle soltou o tecido e viu, em uma das extremidades, um talismã pendurado, opaco sob o céu nublado. Avarosiano."},{"s":"03FR006T2","n":"Trundle","f":"Os avarosianos não se renderam. Trundle gesticulou e, como uma avalanche, os trolls avançaram com tanto ímpeto que continuaram por quilômetros, adentrando as tribos avarosianas, golpeando e devastando tudo pelo caminho."},{"s":"03FR011","n":"Uzgar, o Ancião","f":"Antes que pudessem ouvir, eles sentiram o chão tremer. Tudo logo se tornou audível, como um trovão distante se aproximando.\nMeyrick levantou a cabeça e arregalou os olhos, ouvindo atentamente.\n\"O que é isso?\", sussurrou Anya, sacando seu arco. Mas Meyrick já estava correndo em direção à trilha.\n\"FUJAM!\""}]},{"id":"wanderers-fr","name":"Sem tribo: andarilhos do gelo","desc":"Quem vive no Freljord sem jurar a nenhuma tribo: Gnar, o yordle que passou milênios congelado em Gelo Verdadeiro, Gragas, o cervejeiro, o menino Nunu e seu amigo yeti Willump, e Aurora, a vastaya que anda entre o mundo material e o espiritual.","items":[{"s":"01FR007","n":"Bjerg Balbuciador","f":"\"V-Você tem que acreditar em mim! Era enorme! Sério mesmo, ENOOORME!\""},{"s":"05BC161","n":"Gnar","f":"Há muito tempo, Gnar e sua espécie prosperavam no Vale Nakotak. Era um lugar inocente, intocado pelas comodidades modernas. É uma pena que o passar do tempo tirou-o de Gnar, mas que bom que o tempo não funciona como o esperado em Bandópolis."},{"s":"07FR015","n":"Ingvar, a Jovem","f":"Autonomeada supervisora de Poros e exploradora de Freljord, Ingvar tem certeza de que a aventura aguarda por ela em algum lugar... E ela vai encontrá-la."},{"s":"05BC161T1","n":"Mega Gnar","f":"Sentados num galho de árvore, os yordles torciam por Gnar enquanto ele enfrentava outro monstro que estava ali de passagem. Era um acontecimento raro, mas sempre incrível de se ver!"},{"s":"01FR025","n":"Pastor de Poros","f":"Um rebanho só precisa de duas coisas: amor e companhia. O resto vem sozinho."},{"s":"01FR021","n":"Tarkaz, o Desgarrado","f":"\"Tarkaz lutou mais e melhor do que a maioria. Acho que ele aceitou bem a derrota. Bom, mais ou menos...\"\n– Tryndamere"},{"s":"laurora","n":"Aurora","f":"A Bruxa Entre Mundos.\nDesde que nasceu, Aurora vive com uma habilidade inigualável de viajar entre os reinos dos mortais e dos espíritos. Determinada a aprender mais sobre os habitantes do reino espiritual, ela deixou seu lar para trás com o objetivo de conduzir mais pesquisas e acabou encontrando um semideus corrompido, perdido e deformado.","l":1},{"s":"lgragas","n":"Gragas","f":"O Badernista.\nIgualmente alegre e imponente, Gragas é um gigante e arruaceiro mestre-cervejeiro em uma busca pessoal pelo mais perfeito caneco de cerveja. Vindo de partes desconhecidas, ele busca por ingredientes raros entre a vastidão intocada de Freljord, testando cada receita enquanto segue seu caminho.","l":1},{"s":"lnunu","n":"Nunu e Willump","f":"O Garoto e seu Yeti.\nEra uma vez um garoto que queria provar a todos que poderia ser um herói indo matar uma fera horripilante... mas que no fim descobriu que esse monstro era um solitário yeti mágico que só queria um amigo. Unidos por um antigo poder e compartilhando um amor por bolas de neve, Nunu e Willump agora vagavam ferozmente através de toda Freljord, dando um sopro de vida em aventuras imaginárias.","l":1}]},{"id":"outros","name":null,"desc":null,"items":[{"s":"u8c97c9b422","n":"Armas Tribais","f":"Os arcos e espadas usados pelas tribos são criados com madeira, aço e osso, e, nos casos mais raros, também podem incorporar Gelo Verdadeiro.","u":1},{"s":"u3b0f5593de","n":"Gelo Verdadeiro","f":"Gelo Verdadeiro ocorre naturalmente e nunca derrete, apesar de ser extremamente raro. Somente guerreiros Glacinatas podem aguentar seu toque congelante e podem empunhá-lo em batalha.","u":1},{"s":"u89cfacdeeb","n":"Povos das tribos","u":1}]}],"places":[{"s":"09FR009","n":"Desfile de Poros","f":"Ingvar criou laços ainda mais fortes com os súditos do Rei Poro desde que visitou o reino dele. Marchar por Freljord em busca de aventuras é uma das melhores táticas para melhorar relações diplomáticas."},{"s":"06FR005","n":"Forja de Ornn","f":"Sozinho na forja de Pedra-Lar, ouvindo nada além dos sons do rio fundido logo abaixo e o soar do martelo na bigorna... Ah, como ele adorava isso."},{"s":"08FR002T1","n":"Insígnia da Tempestade","f":"Em uma passagem traiçoeira na montanha, uma insígnia paira no ar, brilhando contra o céu noturno. Muito sangue foi derramado como oferenda até chegar a esse ponto, e nessas horas Volibear oferece tanto sua aprovação quanto seu desejo por mais..."},{"s":"03FR020","n":"O Lar das Cicatrizes","f":"Há muitos locais honrosos no território da Garra do Inverno, mas um dos mais importantes é o Lar das Cicatrizes, onde barcos de guerra danificados que retornaram de invasões são rearranjados como salas comunais para guerreiros, familiares e amigos. Esses barcos simbolizam a tribo que os construiu\n– resistentes e adaptáveis."},{"s":"09FR014T1","n":"Pináculo Tempescavado","f":"''Desafiar a natureza é imprudência. Canalizá-la, no entanto... é fonte de um poder imensurável.'' – Brynhir Cantotrovejante"},{"s":"04FR014","n":"Ravina Arruinada","f":"Formas bizarras feitas de gelo sombrio surgem por toda a ravina, e seus espinhos externos afugentam qualquer intruso em potencial."},{"s":"04FR001","n":"Servo Congelado","f":"Sem sombra de dúvidas, havia muitos guerreiros imbecis no exército desordenado de Trundle que poderiam ser usados como escudos descartáveis na linha de frente, mas Lissandra queria algo mais leal, algo que servisse a ela e somente a ela..."},{"s":"04FR007T1","n":"Túmulo Congelado","f":"\"Nossa soberana enterrará este mundo e tudo o que há nele em gelo.\" – Inquisidor Draklorn"},{"s":"ub8e00964e7","n":"As cavernas congeladas de Howling Abyss","u":1},{"s":"u3cd6f3e125","n":"As ruínas da Fortaleza dos Glacinatas","u":1},{"s":"u79281d7f1c","n":"Casa Freljordana","u":1},{"s":"ucf172e1c11","n":"Casa Freljordana","u":1},{"s":"u5662474c91","n":"Cidadela Praeglacius","u":1},{"s":"u33d32f5007","n":"Mausoléus dos Glacinatas sob o Pico Chifregélido","u":1},{"s":"u0a8323cd33","n":"O conglomerado de peregrinos de Rakelstake","u":1},{"s":"u99c2b03fa0","n":"O porto congelado de Glaciporto, com suas galés-lobo acorrentadas","u":1},{"s":"u38b1ea8a72","n":"Passagem vigiada para Howling Abyss","u":1},{"s":"wb9276d55f0","n":"Freljord (arte conceitual 1)","w":1},{"s":"wd3cb7a503a","n":"Freljord (arte conceitual 10)","w":1},{"s":"w9622e854a7","n":"Freljord (arte conceitual 11)","w":1},{"s":"wd7f44bf9e9","n":"Freljord (arte conceitual 12)","w":1},{"s":"wb90e219ce4","n":"Freljord (arte conceitual 13)","w":1},{"s":"w37bd7d993f","n":"Freljord (arte conceitual 2)","w":1},{"s":"w931740e70f","n":"Freljord (arte conceitual 3)","w":1},{"s":"wd50e78493c","n":"Freljord (arte conceitual 4)","w":1},{"s":"w7dbdd40057","n":"Freljord (arte conceitual 5)","w":1},{"s":"wd228e0ce81","n":"Freljord (arte conceitual 6)","w":1},{"s":"w6bf054a733","n":"Freljord (arte conceitual 7)","w":1},{"s":"w732722891f","n":"Freljord (arte conceitual 8)","w":1},{"s":"w826503eb9c","n":"Freljord (arte conceitual 9)","w":1}],"creatures":[{"s":"04FR018","n":"Abominável Guardião das Neves","f":"\"... e, além de tudo, são sorrateiros! Da última vez em que estive lá, me abriguei numa caverna e acabei encontrando alguns filhotes dormindo. Tentei manter distância, mas um dos grandões voltou bem na hora. Era grande feito uma montanha e estava coberto de neve! E não para por aí, porque depois...\" – Bjerg Balbuciador"},{"s":"08FR030","n":"Boadir do Gelo Preto","f":"''Ela era f-feroz! Servos reduzidos a gelo escuro, avalanches sob suas garras, um rugido que derrubava a neve das montanhas! Uma rainha guerreira e nada menos! M-matar servos é trabalho de uma rainha guerreira.'' – Bjerg Balbuciador"},{"s":"05FR002T1","n":"Combatente Mamute","f":"Poucas feras freljordanas são tão assustadoras quanto um mamute protegendo sua manada."},{"s":"01FR043","n":"Coração da Fofuteia","f":"\"Só mais uma historinha, mas silêncio para a mamãe não dar bronca!\"\n\"Há muito tempo, saqueadores atacaram a aldeia de Avarosa. Os aldeões eram poucos e pareciam perdidos, mas um poro apareceu para ajudar...\""},{"s":"08FR024","n":"Cão das Neves Yadulskiano","f":"Embora sejam originários de Yadulsk, esses filhotes foram domesticados por várias tribos de Freljord para fins de rastreamento, caça e resgate em avalanches. Com uma constituição robusta e um apetite saudável por diversão, eles são adorados da tundra à taiga."},{"s":"01FR027","n":"Elnuk Bovino","f":"Os contos populares avarosianos falam do \"Velho Tio Elnuk\", um senhorzinho rabugento e teimoso que só queria um pedacinho de grama e uma discussão para enfiar o pé na lama."},{"s":"01FR022","n":"Falcão dos Presságios","f":"\"Nossos rapinadores chegaram aos portões avarosianos três vezes... e três vezes foram recebidos por arcos e flechas. Que tipo de bruxaria os avisa de nossos ataques?\" – Steffen, Tano das Cicatrizes"},{"s":"01FR014","n":"Filhote de Yeti","f":"\"Ele era tão pequeno e tranquilo! É difícil acreditar que cresceria e se tornaria... bem... um yeti.\" – Armadilheiro avarosiano"},{"s":"07FR008","n":"Filhote Gélido","f":"Há muitos perigos em Freljord, especialmente para quem ainda não aprendeu suas frias verdades."},{"s":"01FR043T1","n":"Fofuteia de Poros","f":"\"No início, ela não sabia do que aqueles pequeninos eram capazes. Mas aí apareceu outro, depois outro, até a sala ficar completamente cheia! E todos os poros se juntaram...\"\n\"Hora de dormir! Se vocês não dormirem em cinco minutos...!\""},{"s":"07FR010","n":"Garrafiada Gélida","f":"Embora a garrafiada gélida cace principalmente pequenos mamíferos, as garras dessa fera freljordana são suficientes para transformar quase qualquer coisa em uma refeição."},{"s":"01FR026","n":"Garreroz Alfa","f":"O vigor de um cavalo de guerra aliado à selvageria imprudente de um gato."},{"s":"06FR033","n":"Javali de Caça","f":"O ciclo da vida e da morte parece diferente em Freljord. A natureza implacável faz com que nada seja desperdiçado."},{"s":"06FR027","n":"Lesmamute Felpudo","f":"Embora os trolls não sejam muito conhecidos por seu intelecto, podem ser surpreendentemente engenhosos."},{"s":"01FR018","n":"Lobo das Glacipresas","f":"Os predadores das terras nortenhas descobriram que as presas mais fáceis são aquelas já incapacitadas pelo frio do inverno."},{"s":"01FR049","n":"Lobo Espreitador","f":"\"Quem nasceu lebre, nunca será lobo.\"\n– Provérbio da Garra do Inverno"},{"s":"04FR019","n":"Matriarca das Glacipresas","f":"Os lobos das Glacipresas, agachados e cautelosos, cercaram o drüvask. O cheiro da morte, mordaz e intenso, impregnava o ar."},{"s":"07FR008T1","n":"Mãe Gélida","f":"Em Freljord, para a sorte de alguns, existem guardiãs que acham importante aprender a sobreviver para não virarem, elas próprias, lições."},{"s":"07RU015","n":"O Rei Poro","f":"Ingvar reconhece potencial quando vê. Mesmo com um visual um pouco rústico, esse amado companheiro poderia facilmente ser o governante de um gazilhão de trilhões de Poros... com um pouco de imaginação."},{"s":"07RU015T4","n":"O Rei Poro","f":"\"MANHÊÊÊ, vem ver! O Senhor Alteza Rei Poro tá viviiiinho da Siiiilva! Olha, tá mesmo! Eu não tô inventando dessa vez, eu juro de pés juntinhos!\" – Ingvar, a Jovem"},{"s":"01PZ020","n":"Poro Audacioso","f":"Seu primeiro lançamento foi puro acidente: escorregou e caiu dentro do canhão do Dia do Progresso enquanto se arrumava. Agora é o orgulho de Piltover, voando pelos céus para o deleite de todos."},{"s":"01NX034","n":"Poro Carinhoso","f":"\"Noxus não é lugar para... para frac... Dá pra alguém TIRAR ESSA COISA DE CIMA DE MIM?!\" – Darius"},{"s":"04SH049","n":"Poro Destinado","f":"Ele não sabia exatamente o que tinha encontrado... mas brilhava bastante e parecia o lanche ideal."},{"s":"06FR021","n":"Poro Emburrado","f":"\"Bora, você tem que tomar o remédio! Se não tomar, não vai melhorar!\" – Ingvar, a Jovem"},{"s":"04FR015","n":"Poro Mitológico","f":"Dizem que há uma figura lendária conhecida por todos os poros. Contam que, durante suas viagens, ele dá todos os tipos de presentes mágicos aos mais dignos de seus amigos peludos."},{"s":"01IO005","n":"Poro Parrudo","f":"\"Pode parecer loucura, mas a última coisa que me lembro é de ter sentido algo... felpudo?\" – Brigante Navori"},{"s":"01FR053","n":"Poro Poderoso","f":"\"Meu parceiro aqui perdeu um olho defendendo o Rei Poro de um Garreroz gigantesco! Afinal, não é o tamanho do martelo, mas o tamanho do coração que importa.\" – Pastor de Poros"},{"s":"05BC160","n":"Poro Primitivo","f":"Os poros de outrora tinham crânios muito mais espessos do que seus parentes contemporâneos, o que os tornava um pouco mais burros, porém mais hábeis na arte da cabeçada."},{"s":"01FR008T1","n":"Poro Radiante","f":"\"Ah, que bom garoto! Até o inverno mais frio vira primavera.\" – Pastor de Poros"},{"s":"02BW010","n":"Poro Saqueador","f":"\"Ele tá no quadro de procurados faz tempo, pois é um verme impiedoso e rabugento que não poupa absolutamente ninguém. Mas sabe o que é pior? Ele... ele é uma fofura.\"\n– Gangplank"},{"s":"01FR008","n":"Poro Solitário","f":"\"Passei a vida inteira em Freljord e, mesmo assim, nada me abalou mais do que encontrar esse coitadinho.\" – Pastor de Poros"},{"s":"09FR010","n":"Poro Ultrafofuxo","f":"''Hehe! Olhe só aquele pelo!'' – Pastor de Poros"},{"s":"01DE049","n":"Poro Valente","f":"\"O novo recruta tem a coragem e perseverança dos nossos melhores soldados. Será que ele entrará para a Vanguarda algum dia? Ele é... menor que os outros, mas veremos.\"\n– Sargento da Vanguarda"},{"s":"04SH049T1","n":"Poro Venerado","f":"Dos soberanos divinos que eu conheço, esse aí gosta de Poritos até demais."},{"s":"06FR030","n":"Precursor dos Servos","f":"Mal se ouvia o clamor estranho e agudo da criatura, mas quando ele ecoou pelas paredes de pedra da ravina, os batedores sentiram a vibração em suas entranhas. Diante de seus olhos, rachaduras surgiram rapidamente pela superfície do gelo, de forma rápida e desproporcional."},{"s":"07FR016","n":"Sauriano Glacial","f":"Com um coração enorme escondido por baixo de uma carapaça grossa, esses corcéis são vitais para abrir caminho de forma confiável pelas montanhas congeladas."},{"s":"05BC140","n":"Trenó de Poros","f":"\"Aí um dos poros disse 'PRA LÁ!', e lá se foram em direção ao horizonte, enquanto os outros poros saíram em disparada atrás deles, se esforçando bastante pra acompanhar!\"\n– Ingvar, a Jovem"},{"s":"01FR017","n":"Tropa de Elnuks","f":"\"Avarosianos são como Elnuks – comedores de grama com olhos sem vida, facilmente abatidos até por um guerreiro sem cicatrizes. Por isso só sobrevivem em bandos.\" – Vrynna, Mãe das Cicatrizes"},{"s":"07FR017","n":"Trovoado Cristalino","f":"A violência do trovoado cristalino é indiscriminada e imediata, sendo capaz de mudar o rumo de uma batalha em instantes. Muitos veem o pássaro como o primeiro presságio de uma tempestade grande e terrível que redefinirá a estrutura da terra em sua essência."},{"s":"06NX031","n":"Yeti Acorrentado","f":"A multidão se espantou quando os dois yetis acorrentados foram trazidos para o lendário fosso de luta de Bordent. Ninguém achava que os animais fossem fortes o bastante para quebrar as correntes, pois ninguém nunca tinha enfrentado o poder de um yeti antes."},{"s":"01FR031","n":"Yeti Ancestral","f":"\"O que foi isso? Parecia um espirro. Geleiras... espirram?\"\n– Bjerg, o Andarilho"},{"s":"01FR028","n":"Yeti Enfurecido","f":"Yeti? Isso aí nem exis–ARGHHH!"},{"s":"01FR056","n":"Yeti Gélido","f":"\"AaaaaaaAAaaaAaaaaah!\" – Bjerg, o Andarilho"},{"s":"w03ba7454cd","n":"Fera do Freljord (arte conceitual 1)","w":1},{"s":"w8f9f85c514","n":"Fera do Freljord (arte conceitual 2)","w":1},{"s":"w65a78f2a30","n":"Fera do Freljord (arte conceitual 3)","w":1},{"s":"w6e2322b601","n":"Fera do Freljord (arte conceitual 4)","w":1},{"s":"w4369094937","n":"Fera do Freljord (arte conceitual 5)","w":1}]},"ionia":{"groups":[{"id":"kinkou","name":"Ordem Kinkou","desc":"Monges-ninjas que guardam o equilíbrio entre o reino espiritual e o mundo físico. Evitam extremos e se opõem à corrupção.","items":[{"s":"01IO050","n":"Desbravadora Kinkou","f":"Aonde quer que vá, ela se certifica de que outros poderão segui-la."},{"s":"06IO035","n":"Estudante Kinkou","f":"\"Priorize o equilíbrio em todos os níveis. Mente, corpo e espírito. Resista aos impulsos urgentes da juventude. Eleve sua perspectiva.\" – Shen"},{"s":"05BC058","n":"Kennen","f":"Kennen também tinha ouvido o rugido de alguma coisa... oculta. Não importava se era humano ou monstro — os Kinkou protegeriam suas terras a qualquer custo."},{"s":"05BC058T2","n":"Kennen","f":"\"Somos o vento e o trovão! Somos a chuva e o relâmpago! Essa é... A TEMPESTADE!\""},{"s":"01IO040","n":"Lâmina Vital Kinkou","f":"\"Este lugar já abrigou nossas escolas, templos e casas. Agora vagamos por essas ruínas infestadas de sombras. A Ordem de Zed corrompeu este lugar sagrado. E eles pagarão por isso.\""},{"s":"01IO032","n":"Shen","f":"\"Como mãos atadas, o plano mortal e o espiritual se entrelaçam.\""},{"s":"01IO032T1","n":"Shen","f":"\"Suas ações coexistem em harmonia e, sob minha vigilância, nenhum há de sobrepor o outro.\""},{"s":"ufa471d924e","n":"Os Kinkou","f":"Os Kinkou se consideram os guardiões do equilíbrio sagrado de Ionia. Seus sacerdotes percorrem tanto Runeterra quanto o reino espiritual, mediando conflitos entre eles e, quando necessário, intervindo por meio da força. Durante a guerra com Noxus, a Ordem Kinkou foi expulsa de seu antigo templo pelos seguidores de Zed, um ex-sacerdote.","u":1},{"s":"lakali","n":"Akali","f":"A Assassina Renegada.\nAbandonando a Ordem Kinkou e seu título de Punho das Sombras, Akali agora ataca sozinha, pronta para ser a arma mortal de que seu povo precisa. Embora mantenha tudo o que aprendeu com seu mestre Shen, ela se comprometeu a defender Ionia de seus inimigos, um assassinato de cada vez. Akali pode atacar em silêncio, mas sua mensagem será ouvida em voz alta e clara: temam a assassina sem mestre.","l":1},{"s":"lyunara","n":"Yunara","f":"A Fé Inabalável.\nCom uma fé inabalável em Ionia, Yunara passou séculos isolada no Reino Espiritual treinando com as Aion Er'na, uma lendária relíquia Kinkou. Apesar dos sacrifícios, o juramento de Yunara de varrer o desequilíbrio e os conflitos das terras ionianas permanece intacto, assim como sua fé.","l":1},{"s":"w72ad4d50bf","n":"Estudante Kinkou (arte conceitual)","w":1}]},{"id":"shadow","name":"Ordem das Sombras","desc":"Fundada por Zed, um ex-Kinkou. Acreditam que o pacifismo enfraqueceu Ionia e usam magia sombria e assassinato para defendê-la.","items":[{"s":"04IO014","n":"Aprendiz das Sombras","f":"\"Você não passa de fumaça, um mero sussurro entre os ventos. Seus punhos precisam se fundir às trevas como as sombras fazem na escuridão. Vamos, de novo!\" – Madame Shi"},{"s":"01IO057","n":"Assassina das Sombras","f":"Ela desliza com graça\nTaciturna pelas sombras\nDeixando o vestígio das garras."},{"s":"01IO013","n":"Demônio da Sombra","f":"\"O que você sacrificaria pelo poder? A transformação começa com um juramento... e só termina depois de tomar tudo o que podia de você.\" – Zed"},{"s":"06NX019","n":"Desertor Noxiano","f":"\"Andei sonhando de novo, ouvindo aquela voz no escuro. Dez anos... Uma década inteira sendo o cão obediente do império. Faça isso. Mate aquilo. E pra quê? Pra glória de Noxus? A glória não passa de uma mentira bonita, e eu caí nela. Mas isso acabou. Kayn me mostrou um caminho diferente, e ele leva à vingança.\"\n— Diário de Royce, o Carrasco"},{"s":"06DE010","n":"Desertora dos Cavaleiros-Patrulheiros","f":"Anos de repressão sobre sua magia criaram dentro dela um complexo ódio por si mesma, que era maliciosamente descontado em suas vítimas. Após desertar dos cavaleiros-patrulheiros, sua fúria não tinha finalidade — até que uma voz a chamou na escuridão. A voz falava de uma nova ordem, uma em que ela poderia praticar sua crueldade sem restrição alguma."},{"s":"06IO025","n":"Fanático da Lâmina Sombria","f":"Nas trevas, ele a viu: uma arma capaz de cortar as sombras. Naquele momento, ele ouviu uma voz distante, porém poderosa, chamando-o. Usando a veracidade das palavras que ouvia como guia, ele a seguiu — e chegou a Kayn."},{"s":"06SI006","n":"Guardiã da Caixa","f":"\"A Caixa não revela seus segredos livremente, Shieda Kayn. Eles têm um preço terrível. Mas, se tiver coragem de olhar para a sombra das sombras, descobrirá que coisas maravilhosas e aterrorizantes jazem ali.\" – Ysdra, Guardiã da Caixa"},{"s":"06RU005T8","n":"Kayn","f":"Um súbito e intenso lampejo de raiva tomou conta de Kayn, e uma terrível dor lancinante passou por trás de seus olhos, deixando-o de joelhos. A risada triunfante de Rhaast ecoou ao seu redor, zombeteira e impiedosa. Ele sabia que esse dia chegaria — o dia em que finalmente prevaleceria ou sucumbiria perante o Darkin..."},{"s":"06RU005T1","n":"O Assassino das Sombras","f":"Um poder extraordinário corria por suas veias. Livre da influência do Darkin, o poder total das sombras estava sob seu comando. Kayn riu, fundindo-se à escuridão, e emergiu momentos depois — apenas para cortar silenciosamente a garganta do guarda diante dele."},{"s":"01IO007","n":"Ren Lâmina Sombria","f":"“Corra, lute, recue... Não adianta, as sombras já vieram ao seu encontro.\""},{"s":"01IO009T1","n":"Sombra Viva","f":"Uma lâmina de sombra é tão afiada quanto uma de aço."},{"s":"01IO027","n":"Vidente Taciturna","f":"\"A carne é inconfiável. Frágil. Delicada como as fronteiras entre a luz e as sombras.\""},{"s":"01IO009T2","n":"Zed","f":"\"Poucos se lembram de vigiar a própria sombra. É o último erro que cometem.\""}]},{"id":"navori","name":"Irmandade Navori","desc":"Rebeldes e foras-da-lei da província de Navori. Lutaram contra Noxus; hoje nem sempre se sabe de que lado estão.","items":[{"s":"01IO017","n":"Batedor Navori","f":"\"Eu vou dar um jeito nele, não se preocupe. É só me tirar de lá que eu divido os lucros com você. Prometo que vale a pena!\""},{"s":"06IO039","n":"Caudalonga Navori","f":"O caudalonga fez amizade com seu companheiro brigante numa noite de inverno enquanto compartilhavam o que restava de uma fogueira abandonada. Ao final da semana, eles haviam descoberto um senso comum de traquinice e um forte interesse no brilho dourado das moedas."},{"s":"01IO044","n":"Conspirador Navori","f":"\"Rápido, precisamos sair daqui! Meu nome? Juro que explico tudo no caminho...\""},{"s":"04IO006","n":"Defensor Costeiro","f":"Querida Kay,\nEles chegaram esta manhã em uma fila de navios que riscou o horizonte e manchou o nascer do sol. Suas máquinas dispararam contra as Planícies Prateadas, e agora uma densa camada de fumaça polui o ar de verão. Não podemos mais ficar parados. Com ancinhos ou pás, foices ou espadas, hoje enfrentaremos nosso destino.\nAmo você e nosso lar muito mais do que sou capaz de descrever.\n– Carta chamuscada"},{"s":"01IO052","n":"Salteador Navori","f":"\"Eu era um músico viajante, conhecido em todas as aldeias daqui até o Placídio. Até os noxianos chegarem. Agora tento sobreviver roubando uns trocados. Mamãe tinha razão, eu devia ter sido curandeiro...\""},{"s":"ufe00d1b066","n":"A Grande Resistência","f":"Foi no Placídio que o povo de Ionia finalmente pegou em armas contra seus inimigos noxianos. No entanto, o custo da vitória daquele dia foi imenso - e agora muitos se perguntam se enfrentar o inimigo foi a decisão certa, já que agora o equilíbrio de sua terra natal pode ter se perdido para sempre.","u":1},{"s":"u355695faeb","n":"O Placídio de Navori","f":"No coração do continente, o Placídio é dos locais mais sagrados de Ionia. Muitos enfrentaram a longa jornada até lá para estudar em escolas renomadas ou meditar em seus jardins mágicos e verdejantes. Sem dúvida, foi por isso que a região se tornou um alvo tão tentador para os exércitos invasores de Noxus...","u":1}]},{"id":"dancers","name":"Dançarinos do Placídio","desc":"Os bailarinos e músicos do Placídio, o coração sagrado de Navori: Irelia, que luta como quem dança com suas lâminas, e quem faz da música e da dança uma forma de resistir.","items":[{"s":"04IO009","n":"Dançarina das Fitas","f":"\"Que vergonha, rapazes! Tanto poder e nenhum ritmo? Realmente, nem todo mundo nasceu pra brilhar...!\""},{"s":"04IO005","n":"Irelia","f":"\"Quando estudávamos a arte e a beleza, nossos corações batiam mais fortes. Mas quando derrubaram nossos muros e nosso sangue, desabamos no solo...\""},{"s":"04IO005T2","n":"Irelia","f":"“... Nossos corações estão cheios de pesar, mas nós estamos cheios de propósito e vamos dançar mais uma vez.\""},{"s":"04IO001","n":"Músicos de Batalha","f":"Para alguns, a música representa um refúgio coletivo contra o sofrimento e a violência. Para outros, ela é uma forma de resistência."},{"s":"04IO002","n":"Zinneia, Crescendo de Aço","f":"\"Aproximem-se, queridos. Hoje, nossos pés vão deslizar pelo solo que nos alimentou, com os movimentos ensinados por nossas famílias. Somos filhos de Ionia, e hoje dançaremos pela arte, pela liberdade e uns pelos outros!\""}]},{"id":"monks","name":"Mestres e monastérios","desc":"Monges, mestres de artes marciais e sábios espirituais, como Lee Sin, Master Yi e Karma, e os Seguidores do Dragão, guerreiros que tomam nomes das partes de um dragão (olho, garras, escamas, cauda) e evocam sua força.","items":[{"s":"01IO042","n":"Aluno em Treinamento","f":"\"Para que lutar quando não tem ninguém vendo os seus golpes?\""},{"s":"02IO005T1","n":"Cauda do Dragão","f":"\"Discípulos devem se mover com graciosidade, pois o sopro do Dragão criou os ventos e as ondas que movimentam nosso mundo.\" – Ensinamentos do Dragão"},{"s":"02IO004","n":"Chifres do Dragão","f":"\"Discípulos devem lutar com todo o seu poder, pois o Dragão puxou o chão debaixo das ondas e nos deu as terras que hoje chamamos de lar.\" – Ensinamentos do Dragão."},{"s":"06IO001","n":"Discípula de Doran","f":"''Aprendi tudo que podia para continuar essa arte sagrada. Assim como Doran, o mestre dele e o mestre do mestre dele... espero que seus espíritos guiem meu martelo.''\n– Discípula de Doran, pergaminho escrito à mão"},{"s":"06IO014","n":"Discípulo Vastayês","f":"Ting deu um sorrisinho enquanto os atacantes invadiam o templo. Finalmente uma chance para ele provar seu valor! Primeiro Wukong, agora Yi... Ambos dispensaram seus talentos. Deixe os outros correrem até o ''mestre''! Ele estava pronto. Ele era o Vento de Shimon."},{"s":"02IO002","n":"Escamas do Dragão","f":"\"Discípulos devem agir com compaixão, pois o Dragão nutriu as Primeiras Terras, concedendo calor e vida.\"\n– Ensinamentos do Dragão"},{"s":"06IO016","n":"Evocadora de Dragões","f":"\"A forma da água reflete a forma do seu desejo. Diga-me, viajante... o que você vê?\""},{"s":"02IO001","n":"Garras do Dragão","f":"\"Discípulos devem escutar com atenção, pois o Dragão rugiu os primeiros sons e abençoou nossos jovens espíritos com o dom da magia.\" – Ensinamentos do Dragão"},{"s":"01IO020","n":"Guardiã das Máscaras","f":"\"Hoje seu rosto se tornará o reflexo da disciplina, do treinamento, da humildade e do equilíbrio. Hoje você se tornará Kinkou.\""},{"s":"06IO011","n":"Jun, a Prodígio","f":"Ao sinal de Yi, Jun desferiu uma série de golpes tão precisos quanto os do próprio mestre. Apesar de desviar habilmente dos ataques, ele se curvou perante ela com um sorriso orgulhoso no rosto."},{"s":"01IO041T1","n":"Karma","f":"\"Traremos paz a Ionia, custe o que custar.\""},{"s":"02IO006T1","n":"Lee Sin","f":"\"...já para os tiranos, o Dragão sopra fogo.\""},{"s":"06IO008","n":"Master Yi","f":"Master Yi se lembrou da arma Darkin. Desde sua descoberta, um terrível pressentimento passou a incomodá-lo. Como alguns de seus alunos demonstraram interesse demais no assunto, Yi colocou as lâminas curvadas sob vigilância nas profundezas do templo. Com certo esforço, ele afastou tais pensamentos e continuou a meditar. Repassar os ensinamentos do Wuju era tudo o que importava, e Jun demonstrava um talento promissor."},{"s":"06IO008T1","n":"Master Yi","f":"Em sua visão periférica, Yi viu o brilho do aço e ouviu o inconfundível barulho de um corpo sem vida caindo no chão. Poderia ser ela? Como ele pôde falhar tanto com seus pupilos? Eles não tinham nenhum preparo nem treinamento, mas ele era um mestre do Wuju, então nem a vergonha nem as sombras venceriam naquele dia."},{"s":"01IO026","n":"Mentor Inspirador","f":"\"Levei anos para cultivar este físico imponente! Dias incansáveis apreciando pássaros, descrevendo as nuvens e levantando bandejas de pão doce! Quem mais se dedicaria tanto?\""},{"s":"01IO038","n":"Monja Solitária","f":"\"Meus reflexos e instintos são a única companhia que desejo ter.\""},{"s":"06IO029","n":"O Espírito do Wuju","f":"\"Mestre Doran acreditava que cada olho do Espírito do Wuju mostrava uma perspectiva única da natureza de uma pessoa. Mas, por mais que eu tente, as lentes do meu elmo só comtemplam vários tons de verde. O que foi que ainda não entendi?\" – Lui, Discípula de Doran"},{"s":"02IO003","n":"Olho do Dragão","f":"\"Discípulos devem pensar com clareza, pois o Dragão atrai o sol que há no céu e revela o mundo que nos cerca.\"\n– Ensinamentos do Dragão."},{"s":"uaa6665197c","n":"Os Grandes Monastérios","f":"Apesar de ser o berço de muitas formas especializadas de artes marciais, Ionia não cultiva exércitos. Em vez disso, os ensinamentos marciais estão ligados a diferentes filosofias, transmitidas de geração em geração com grande reverência e cuidado. Nas montanhas do nordeste da região, o monastério de Hirana é há muito um santuário para aqueles que buscam entender melhor sua conexão com o reino espiritual.","u":1},{"s":"lmonkeyking","n":"Wukong","f":"O Macaco Rei.\nWukong é um trapaceiro vastaya que usa sua força, agilidade e inteligência para confundir os oponentes e deixar a situação a seu favor. Depois de encontrar uma eterna amizade no guerreiro conhecido como Master Yi, Wukong se tornou o último aprendiz da ancestral arte marcial conhecida como Wu Ju. Armado com um cajado encantado, Wukong tenta evitar que Ionia caia em ruína.","l":1},{"s":"w65365b90ce","n":"Guardiões do templo (arte conceitual 1)","w":1},{"s":"wf54cdb04e3","n":"Guardiões do templo (arte conceitual 2)","w":1}]},{"id":"wanderers","name":"Espadachins errantes","desc":"Lâminas sem mestre que vagam com o vento, como os irmãos Yasuo e Yone.","items":[{"s":"04IO004","n":"Lâmina Florescente","f":"\"Alguns pensam que as flores são frágeis e delicadas. Eles se esquecem da força que é necessária para se agarrar ao solo e inspirar esperança a cada florescer.\"\n– Zinneia, Crescendo de Aço"},{"s":"01IO016","n":"Sábio do Zéfiro","f":"\"Enquanto o guerreiro chorava por sua perda, o ancião o consolava: 'Procure o sábio dos céus. Só ele pode devolver o que está perdido, mas ainda guardado na memória.'\"\n– Saga das Primeiras Terras"},{"s":"01IO015T1","n":"Yasuo","f":"\"... está sempre ao meu lado.\""},{"s":"01IO056","n":"Yone, o Perseguidor de Ventos","f":"\"Quando eu era criança, perguntei ao meu irmão: 'O vento corre ou o vento segue?'. Na época, ele me seguia para se espelhar em mim. Hoje, eu o persigo para fazer justiça.\""},{"s":"lyone","n":"Yone","f":"O Inesquecido.\nEm vida, ele era Yone; meio-irmão de Yasuo e um respeitado aluno da escola de espadachins de seu vilarejo. Mas, ao morrer pelas mãos do irmão, ele se viu perseguido por uma entidade maligna do reino espiritual e foi forçado a exterminá-la com sua própria espada.","l":1}]},{"id":"pit","name":"O Fosso de Sett","desc":"Lutas clandestinas, apostas e seguranças: o submundo que Sett, meio-vastaya, comanda com os punhos.","items":[{"s":"07IO009","n":"Contadora Cuidadosa","f":"Em meio a pescadores ambiciosos e picaretas interesseiros, Lise tem uma qualidade que Sett valoriza acima de tudo: é confiável. Ela nunca falta, nunca faz corpo mole e nunca deu motivos de dúvida para Sett. Isso deu a Lise carta branca e mandou um recado para os encrenqueiros: se apostar contra a casa, vai perder."},{"s":"07IO014","n":"Mestre Bingwen, o Analista","f":"Bingwen, o Pássaro, já foi lutador e ganhou esse nome pela postura e agilidade semelhantes às de uma garça. Desde que se aposentou, assumiu o papel de treinador, usando seus olhos afiados e seu rigor para separar \"o joio do trigo\" em termos de talento."},{"s":"07IO019","n":"Mixologista Cativante","f":"\"Na primeira rodada, todo mundo se apresenta. Na segunda, eles ficam à vontade. Os problemas começam a aparecer na terceira, e, a partir da quarta, ninguém guarda mais nenhum segredo. Você não imagina as coisas que eu escuto!\""},{"s":"07IO013","n":"Profissional da Arena","f":"\"Alguns estão nessa por dinheiro, outros por sangue, e outros pelo clamor da multidão. Eu? Nunca consegui decidir. Preciso de tudo isso, e tenho isso tudo pra dar e vender.\""},{"s":"07IO012","n":"Segurança Temporário","f":"''Se quiserem achar que você é idiota, deixe acharem. Deixe os inescrupulosos pensarem que estão no controle. Não há nada melhor do que ver a cara deles quando percebem que subestimaram você.'' – Sett"},{"s":"07IO011","n":"Sett","f":"Sob efeito do rugido da multidão que lota sua arena clandestina exclusiva, Sett aproveita um raro momento de introspecção. Ele se lembra de tudo pelo que lutou e do que ainda vem pela frente. Mas de uma coisa ele tem certeza: é bom ser o Chefe."},{"s":"07IO011T1","n":"Sett","f":"\"O problema de ser o chefe é que você fica mole se não cuidar. Os calos começam a cicatrizar, e logo você vira o que jurou que nunca seria. Então eu recebo todo esse caos de braços abertos. Até que enfim alguém está despertando minha fera interior!\""},{"s":"07IO023","n":"Veterano","f":"\"Não vou tirar a máscara, garota. E, a menos que você queira ficar com a cara igual a ela, não vai perguntar de novo.\""}]},{"id":"vastaya","name":"Vastaya de Ionia","desc":"Os povos-fera que vivem nas florestas e penhascos de Ionia, como Ahri e as tribos de Lhotlan.","items":[{"s":"05IO004T2","n":"Ahri","f":"\"Consigo lembrar de mil momentos que nunca vivi — mas, de agora em diante, farei minhas próprias lembranças.\" – Ahri"},{"s":"07IO049","n":"Airis","f":"''Xiu, estamos quase chegando. Você disse que queria conhecer minha amiga, lembra? Confie em mim, ela vai te adorar.''"},{"s":"05IO020","n":"Cantaventos","f":"O caos dá garras aos indefesos. Um lobo cerca sua presa, mas é interrompido por um galho caído. Um falcão mergulha para atacar, mas sai da trajetória graças a um vento forte. Nós somos o galho. E o vento."},{"s":"05IO025","n":"Matriarca Caudamanto","f":"O mistério é mais fascinante que sua solução."},{"s":"05IO007","n":"Sai'nen das Mil Caudas","f":"A floresta oferece seus segredos de bom grado... mas poucos têm coragem de fazer perguntas a ela."},{"s":"01IO048","n":"Yusari","f":"\"Sua Ordem nos expulsou de nossas terras. Você provou o seu poder, mestre Zed. Agora, me deixe provar que também sou digno de seus ensinamentos.\""},{"s":"ubad0fb6807","n":"Vastaya","u":1},{"s":"lrakan","n":"Rakan","f":"O Charmoso.\nEsbanjando charme e vivacidade, Rakan é um conhecido encrenqueiro vastayês e o melhor dançarino-guerreiro que a tribo Lhotlan já viu. Para os humanos das terras montanhosas de Ionia, seu nome sempre foi sinônimo de festivais animados, festas incontroláveis e música subversiva.","l":1},{"s":"lxayah","n":"Xayah","f":"A Rebelde.\nMortal e precisa, Xayah é uma vastaya revolucionária que trava sua própria batalha para salvar seu povo. Ela usa sua agilidade, malícia e plumas afiadas para retalhar qualquer um que atrapalhe seu caminho. Xayah luta ao lado de seu parceiro e amante, Rakan, para proteger sua tribo em extinção e restaurar a antiga glória de sua raça.","l":1}]},{"id":"artists","name":"Artistas e visionários","desc":"Pintores, músicos e atores de Ionia: Hwei, o pintor herdeiro do Templo de Koyehn, e Jhin, o assassino que faz da morte uma obra de arte.","items":[{"s":"06IO003","n":"A Contrarregra","f":"\"Ato quatro: Uma jovem sacerdotisa entra em nossa história. A tragédia dela é contada pelos lábios pálidos daqueles que ela traiu. Desesperada para se redimir de sua transgressão, ela carrega em seus braços um grande fardo, um presente dourado para os noxianos que ela acolheu em sua terra. Ficamos nos perguntando: foi a tristeza ou a bala que partiu seu coração?\""},{"s":"06IO004","n":"A Criadora","f":"\"Um talento extraordinário, a Criadora. Uma artesã lendária! Uma arte inigualável! Execução impecável! Já é uma grande honra estar na presença dela, imagine portar um instrumento feito por ela.\" – Testemunha Kashuri"},{"s":"06IO015","n":"A Testemunha","f":"Qual é o papel dela neste estranho e terrível espetáculo? Ah, mais do que ouvinte, ela é observadora, as lentes que filtram tudo e a tudo julgam em contraste com a verdade e a beleza. A Testemunha!"},{"s":"06RU002","n":"Jhin","f":"\"Prelúdio: Estamos na cidade de Qayanvi, onde um velho mestre convoca um jovem pupilo. A tarefa dele é espantar um grupo de vilões perversos e recuperar artefatos sagrados roubados. O ator está ansioso, mas ainda não está em posição. Por enquanto ele só se prepara, aguardando nas coxias.\""},{"s":"06RU002T1","n":"Jhin","f":"\"E em seguida: o encerramento.\""},{"s":"06IO044","n":"Melodia Celeste","f":"''Alguns buscam paz na meditação. Outros buscam conhecimento para autorreflexão. Aqueles que encontram o próprio centro, seja por expressão ou criação, trarão paz tanto para si quanto para os outros.\" – Karma"},{"s":"lhwei","n":"Hwei","f":"O Visionário.\nHwei é um pintor melancólico que cria obras de arte geniais para combater os criminosos de Ionia e trazer conforto às vítimas deles. Por trás de sua melancolia, esconde-se uma mente emocionalmente dilacerada, assombrada pelas visões vibrantes de sua imaginação e pelas memórias horríveis do massacre em seu templo.","l":1}]},{"id":"spirits","name":"Guardiões da natureza e do mundo espiritual","desc":"Quem cuida das florestas e conversa com os espíritos: Ivern, o Pai Verde, e Lillia, a corça feérica e tímida que procura os sonhos não realizados.","items":[{"s":"05IO003","n":"Ancestral Sem Rumo","f":"\"Himon'she, é uma honra poder viajar com você. Disseram que você tinha uma sabedoria imensurável. Aonde estamos indo?\"\n\"Ora, minha querida, eu estava seguindo você!\" – Ahri e o Ancestral Sem Rumo"},{"s":"01IO014","n":"Ancião da Clareira Verdejante","f":"O conhecimento ioniano é registrado por escrito, mas são os contos e ensinamentos dos venerados anciãos de Ionia que dão vida a esses textos."},{"s":"01IO045","n":"Arauto da Primavera","f":"\"Durante o reinado invernal\nOuvimos pegadas sobre o chão nevado.\nPor onde passava, videiras e folhas subiam ao alto\nAbrindo caminho à nova estação do Arauto.\"\n– Poema Shon-Xan"},{"s":"01IO019","n":"Defensora da Clareira Verdejante","f":"\"A clareira protege seus nativos. E você... você não é daqui...\""},{"s":"09IO053","n":"Dona Raiz","f":"\"Uau, um dia toda essa beleza vai mergulhar no sono eterno, e nós também. Tomara que eu mergulhe primeiro. Hehe!\""},{"s":"01IO006","n":"Dupla da Clareira Verdejante","f":"\"Ei, cuidado com os galhos! Esquerda, ESQUERDA!\"\n\"Quando eu estiver nos SEUS ombros, Felpudinho, podemos ir pra onde você quiser. Até lá, quem decide sou eu!\""},{"s":"01IO053","n":"Evocador Esmeralda","f":"\"Guerras são estimuladas pelos nossos instintos mais básicos, mas eles não têm poder sobre nossas maiores virtudes: confiança, paciência e reflexão.\""},{"s":"09IO055","n":"Fadinha Floral","f":"\"Nossa Lillia está toda descabelada. Vá dar um jeito nisso, sim? Lembre-se: a primeira mecha é dos desejos, a segunda, dos sonhos e, a última, de tudo que não é o que parece.\" – Mãe-Espírito"},{"s":"05IO001","n":"Guardiã do Arvoredo","f":"\"Dizem que você não fala pra poupar a todos do peso que o seu conhecimento tem. Hmm... Aposto que você só se cansou de responder a tantas perguntas.\" – Ahri"},{"s":"05IO006T1","n":"Guardião Fronteiriço","f":"\"Minha melhor qualidade? Eu durmo feito pedra.\""},{"s":"09IO046","n":"Jardineira Ophelis","f":"Cuidar da Árvore dos Sonhos e do jardim ao redor é uma grande honra, porém exige sacrifícios. Em um ritual de respeito e apreciação, os guardiões do jardim oferecem as próprias memórias, perdendo uma parte de si todas as noites."},{"s":"09IO052T1","n":"Lillia","f":"Parecia que uma podridão perversa criou raízes em seu interior... e ameaçou prender os sonhadores nos seus próprios pesadelos perigosos."},{"s":"01IO043","n":"Moldador de Rios","f":"\"Somos os orgulhosos filhos das Primeiras Terras. Seus rios mágicos fluem por nossas veias vastayesas assim como por nosso reino.\""},{"s":"05IO026","n":"Os Lamentados","f":"Se quiser venerar a caçada, terá que lamentar os caçados."},{"s":"01IO023","n":"Protetora Adornada","f":"\"Em momentos de conflito, os aldeões recorriam à guardiã do Vale do Outono. Aqueles que conquistavam seu coração recebiam bênçãos capazes de mudar os rumos da batalha.\"\n– Saga das Primeiras Terras"},{"s":"livern","n":"Ivern","f":"O Pai do Verde.\nIvern, conhecido por muitos como Espinhoso ou Velho Lenhador, é um ser muito peculiar. Metade homem e metade árvore, caminha pelas florestas de Runeterra, cultivando vida por onde passa. Ele conhece todos os segredos do mundo natural e é um grande amigo de toda e qualquer coisa que cresça, voe ou caminhe.","l":1}]},{"id":"outros","name":null,"desc":null,"items":[{"s":"08IO019","n":"Adnere, o Confiável","f":"''Esta terra é repleta de lições. Nunca esqueça: o passar de cada estação deve ser celebrado, pois é apenas no fim que um novo começo pode nascer.''"},{"s":"08IO019T1","n":"Avicultores de Adnere","f":"''Veja! A ninhada do papai está eclodindo de novo!''\n''Uau! Mais um! Por que tem tantos?''\n''Você pergunta isso TODO ANO, Arya.''\n''UÉ?! Ninguém nunca me responde!''\n''Xiu! Não assuste eles. E me diz quantos tem aí, porque vamos precisar pensar em muitos nomes.''"},{"s":"07IO043","n":"Oráculo Que Tudo Vê","f":"O olho livre do mundo material tudo vê. Por mais que o oráculo pareça cego, quem o confunde com um alvo fácil é repreendido de forma célere e sem misericórdia."},{"s":"06NX023","n":"Pescadora Ioniana","f":"A vida de Trisk virou de ponta-cabeça quando, durante o que seria sua última participação num torneio de pescaria, ela pescou Jax, que se debatia, desesperado. Ele se recusa a comentar sobre o incidente, mas o monstro marinho do qual Trisk o salvou fica maior cada vez que ela reconta essa história."},{"s":"uca1e480faa","n":"Criando uma casa","u":1},{"s":"u6f67704987","n":"Diversidade rica","u":1},{"s":"ue203b21092","n":"Interior da casa","u":1},{"s":"u76b75e8714","n":"Mercador de frutas","u":1},{"s":"u55666ff107","n":"Mercador de itens","u":1},{"s":"lsyndra","n":"Syndra","f":"A Soberana Sombria.\nSyndra é uma destemida maga ioniana com um poder incrível ao seu dispor. Quando criança, ela causava pavor nos anciões da aldeia com sua magia imprudente e indomada. Mandada embora para aprender a controlar seus poderes, ela acabou descobrindo que seu suposto mentor estava reprimindo suas habilidades.","l":1}]}],"places":[{"s":"06IO037","n":"A Chama Sombria","f":"\"O que é a vida senão uma sombra da existência? Abrace a Escuridão e viverá para sempre.\" – Zed"},{"s":"09IO049","n":"A Colheita das Gotas de Orvalho","f":"As gotas de orvalho da Árvore-Mãe permitem vislumbrar um sonho em algum lugar de Runeterra. Cada uma delas deve ser colhida, cultivada e protegida com cuidado."},{"s":"06IO010","n":"Monte da Ventania","f":"Para a maioria das pessoas, a paz é um lar feliz e o acolhimento tranquilo encontrado em um abraço carinhoso. Para Yasuo, é o momento raro quando os ventos se acalmam e oferecem promessas em vez de lembranças."},{"s":"05IO021","n":"Muda de Salgueiro Divino","f":"Uma vez, o Salgueiro Divino cresceu em Omikayalan. Agora, o que cresce por lá pode ser mais forte ou mais fraco — afinal, o importante mesmo é ser algo novo."},{"s":"09IO051","n":"O Caminho da Raiz","f":"O Jardim do Esquecimento é o lar de uma estranha variedade de criaturas grandes e pequenas; algumas são mais sencientes do que gostariam de ser."},{"s":"09IO058","n":"O Coração da Árvore","f":"Espíritos oníricos são os habitantes mais abundantes do Jardim. De todos os formatos, tamanhos e temperamentos, muitos deles entram em gotas de orvalho e guiam os sonhadores até seus desejos mais profundos."},{"s":"09IO045T1","n":"Soninho do Orvalho","f":"Sonhos diurnos, sonhos noturnos, sonhos do meio da manhã... A Árvore dos Sonhos tem galhos com ramos para todos eles."},{"s":"06IO030","n":"Vale da Névoa","f":"''O Vale da Névoa é um lugar sagrado. As espadas aqui encontradas chegaram há séculos... Acredito que qualquer lâmina deixada aqui com um poema na empunhadura atrairá espíritos de antigos portadores perdidos que, por fim, irão abençoá-las.''\n– Discípula de Doran, pergaminho escrito à mão"},{"s":"u4cd2a4f873","n":"A Vida Como Entidade Única","f":"Os povos das muitas províncias de Ionia sempre se viram como parte do mundo natural e adaptaram seus costumes de modo a viverem em harmonia com uma flora e uma fauna fantásticas. Para quem vê de fora, tal relação pode parecer estranha, mas foi por meio dessa interdependência que a terra e seus habitantes sobreviveram e floresceram por tantas gerações.","u":1},{"s":"u071e20bae3","n":"Arcos","u":1},{"s":"u328d530b36","n":"As Primeiras Terras","f":"A magia transcorre todas as partes de Ionia: seu povo, sua história e, principalmente, a terra em si. Todos os aspectos da vida lá coexistem em um delicado equilíbrio e ainda há muito a ser descoberto e explorado. Aqueles que habitam este vasto continente buscam harmonia entre as diversas raças e diferentes habitats, muito mais antigos do que a maioria em Runeterra.","u":1},{"s":"u3b4a5204fd","n":"Construída em Meio à Natureza","f":"A arquitetura ioniana é caracterizada por um senso de graciosidade e fluxo natural, buscando refletir a beleza etérea da terra ao seu redor. Grandes espaços abertos garantem que ninguém se esqueça totalmente do que antes existia ali de forma orgânica.","u":1},{"s":"ub37a1da7cb","n":"Fazenda ioniana","u":1},{"s":"u272f73378e","n":"Lago dos lírios iluminados","u":1},{"s":"u96354d4889","n":"Mercado","u":1},{"s":"u80db80d50c","n":"Mercado da floresta","u":1},{"s":"u698583c5f1","n":"Mercado da vila","u":1},{"s":"ueba336b272","n":"Ninho do Dragão","u":1},{"s":"ud40660a8bb","n":"Os Cânions Arco-íris de Shi","u":1},{"s":"ufa87c85d68","n":"Os Luonn-Kon","u":1},{"s":"u23a3d22100","n":"Passadiço ioniano","u":1},{"s":"ufc86111c67","n":"Região costeira","u":1},{"s":"u8a19809c73","n":"Templos no penhasco","u":1},{"s":"w1e2e64059b","n":"Ionia (arte conceitual 1)","w":1},{"s":"we71b9da709","n":"Ionia (arte conceitual 10)","w":1},{"s":"wb535ef524c","n":"Ionia (arte conceitual 11)","w":1},{"s":"w0dbddc5dcb","n":"Ionia (arte conceitual 12)","w":1},{"s":"w3faf9ea65c","n":"Ionia (arte conceitual 13)","w":1},{"s":"w34aa5492fe","n":"Ionia (arte conceitual 14)","w":1},{"s":"wd07ae8a2c4","n":"Ionia (arte conceitual 15)","w":1},{"s":"w3e26ca0c9e","n":"Ionia (arte conceitual 16)","w":1},{"s":"w31aef8f1c2","n":"Ionia (arte conceitual 2)","w":1},{"s":"wa00800ac0a","n":"Ionia (arte conceitual 3)","w":1},{"s":"w25756cd9b7","n":"Ionia (arte conceitual 4)","w":1},{"s":"we26dbb4802","n":"Ionia (arte conceitual 5)","w":1},{"s":"w98c2eb3589","n":"Ionia (arte conceitual 6)","w":1},{"s":"w5bb28a7f40","n":"Ionia (arte conceitual 7)","w":1},{"s":"w95208b4a9f","n":"Ionia (arte conceitual 8)","w":1},{"s":"wbb2ee9c0ba","n":"Ionia (arte conceitual 9)","w":1}],"creatures":[{"s":"07IO046","n":"Asaluz Real","f":"\"Vagando por essas selvas, descobri que os espécimes mais bonitos são sempre os predadores mais letais.\" – Anura"},{"s":"04IO020","n":"Cardume Disperso","f":"As canções estranhas e belas dos Sorvedores de Nuvens conseguiram deter parte da Névoa Negra... mas não por muito tempo."},{"s":"07IO047","n":"Cobra Fascinante","f":"\"Acha que essas flores valem alguma coisa? E não me chame de louco, mas elas não parecem estar... dançando?\"\n– Furtivista Piltovense"},{"s":"01IO021","n":"Cria do Vento","f":"\"A primavera floresce primeiro nos penhascos de Ionia, onde asas recém-formadas batem e acariciam a terra com as suaves brisas da estação.\"\n– Saga das Primeiras Terras"},{"s":"08IO012","n":"Dragão do Oceano","f":"\"Que fera grandiosa você é! Ver suas garras rasgando as ondas é uma beleza só. Se um dia decidir caçar algo além de peixes e aves marinhas, vai ser um prazer enfrentar você.\"\n– Nilah"},{"s":"01IO028","n":"Escamossauro","f":"Um dos habitantes mais velhos da Clareira Verdejante, ele aprendeu a se adaptar para sobreviver às provações do tempo."},{"s":"09DE033","n":"Espiritinhos","f":"''Espiritinhos são criaturas magníficas. Com o tempo e o sonhador ideal, o potencial deles é simplesmente infinito!'' – Mãe Espírito"},{"s":"09DE036","n":"Espíritos Arbóreos","f":"''Vamos, espiritinhos. Mostrem o caminho a quem sonha.''\n– Lillia"},{"s":"08IO023","n":"Espíritos Marítimos Saltitantes","f":"Durante certas épocas do ano, quando o vento sopra sobre o mar, alguns zaunitas juram que podem ver fracas impressões de duas enormes criaturas com nadadeiras dançando alegremente com as marés do oceano."},{"s":"04IO015","n":"Gotinha Dançante","f":"\"A Água é flexível, adaptável. Ela assume a forma necessária no momento, avançando em direção às margens ou recuando para bem longe delas.\" – Monge Ioniano"},{"s":"08IO014","n":"Heisho, Concha do Mundo","f":"Para os habitantes deste vilarejo de Ionia, Heisho é, além de cuidador, amigo. Tendo carregado a casa de todos nas costas desde tempos imemoriais, eles podem confiar no portador do vilarejo para buscar litorais pacíficos em tempos difíceis."},{"s":"09DE029","n":"Luminispírito","f":"''Vamos lá, Senhor Espírito. Vamos queimar essas sombras assustadoras!'' – Alina Sonhaluz"},{"s":"01IO030","n":"O Empíreo","f":"\"O próprio céu se erguia enquanto espirais de nuvens e ventanias pressionavam nossa brigada. Tentamos segui-lo, mas quem consegue perseguir o vento?\" – General da Legião"},{"s":"04IO013","n":"Protetor Sagrado","f":"\"Nós lutamos para proteger esta terra, e ela retribui erguendo-se para nos defender. Nos fortalecemos com sua ira e a usamos para afugentar os inimigos. É assim que mantemos o equilíbrio.\" – Sacerdote ioniano"},{"s":"01IO031","n":"Sorvedor de Nuvens","f":"Suas canções eram ouvidas até nas aldeias – longas e suaves ondas de som que se propagavam do céu para a encosta, tão disformes e estranhas quanto as nuvens vespertinas."},{"s":"w99cf73ee83","n":"Espírito de Ionia (arte conceitual 1)","w":1},{"s":"w8bb2e76e6d","n":"Espírito de Ionia (arte conceitual 2)","w":1},{"s":"w3bd2f583c5","n":"Espírito de Ionia (arte conceitual 3)","w":1},{"s":"w2a33c5a8a0","n":"Espírito de Ionia (arte conceitual 4)","w":1},{"s":"w3c5ccee8fd","n":"Espírito de Ionia (arte conceitual 5)","w":1},{"s":"w814f43817d","n":"Espírito de Ionia (arte conceitual 6)","w":1}]},"bandle":{"groups":[{"id":"squads","name":"Batedores e artilheiros","desc":"Os yordles que protegem Bandópolis e saem para explorar: Teemo, Tristana e seus esquadrões.","items":[{"s":"05BC070","n":"Ava Dedicada","f":"\"Regra 378: um bom escoteiro sempre dispõe de coragem, bravura e prontidão!\""},{"s":"05BC120","n":"Capitão Yordle","f":"\"Se aventurar por aí significa topar com os caras mais malvados e fazer amizade com eles!\""},{"s":"05BC018","n":"Cavaleiro Pomposo","f":"\"Novecentos e noventa e oito... Novecentos e noventa e nove... mil! Prontinho, Pio, impecável como sempre. Beleza, agora é a minha vez!\""},{"s":"05BC049","n":"Conquiliologista","f":"\"Hoje será um dia memorável! Uma dia recheado de exploração nas profundezas! Espero que tudo ocorra... MAR-avilhosamente bem! Hehe!\"\n– Registro Ecológico do Conquiliologista, dia 1"},{"s":"05BC179","n":"Desbravador Yordle","f":"\"Poppy! Que bela execução da nossa nova tática! O que você acha de chamá-la de 'Floracão Aveleiro'?\"\n\"Olha, eu só acertei o malvado com o meu martelo. A gente não pode chamar essa tática só de 'Martelo'?\"\n\"Mas esse já é o nome das últimas três!\" – Kip e Poppy"},{"s":"05BC099","n":"Escoteiro Bombado","f":"\"Quer saber qual é o meu segredo? Vai ter que perguntar pros meus bíceps. São eles que fazem a magia acontecer.\""},{"s":"05BC145","n":"Escudeira Yordle","f":"\"Minha lança já pertenceu a uma grande heroína... Eu pedi pra Poppy segurar ela um pouquinho!\""},{"s":"05BC105","n":"Fuzinúsculos","f":"Isso sim é que é equipe."},{"s":"05BC039","n":"Granadeiro Bronco","f":"\"A Alice tem duas balas: uma dá 'oi' e a outra dá 'tchau'. Quer que eu te apresente pra ela?\""},{"s":"05BC167","n":"Soldada de Bandópolis","f":"\"Colocando bandido no lugar e criança pra nanar!\""},{"s":"01PZ008T2","n":"Teemo","f":"\"... fique longe da zona de detonação!\""},{"s":"05BC133T1","n":"Tristana","f":"\"... e não importa o que aconteça... SÓ CONTINUA ATIRANDO!\""},{"s":"05BC108","n":"Yordle Explorador","f":"\"A glória da exploração não tem preço, mas as maiores descobertas são sempre... hã... lucrativas.\""},{"s":"05BC122","n":"Yordle Novato","f":"\"Gigantus gramíneos. Essas criaturas aterrorizantes se camuflam deitando sobre o solo como grama normal e atacam qualquer desavisado que passar por ali. Ao se deparar com um, é melhor não parar de correr!\" – Ava Dedicada"}]},{"id":"monks","name":"Monges elementais","desc":"Yordles que dominam o vento, o fogo e o trovão em monastérios escondidos. Kennen é um deles (e Kinkou).","items":[{"s":"05BC063","n":"Guerreira do Tornado","f":"O Tornado a mantém calma com exercícios de respiração... e com a canalização de seus dilemas internos em um ciclone brutal de lâminas mortais."},{"s":"05BC155","n":"Monge da Brasa","f":"\"Pequenas centelhas se tornam grandes chamas. Somos as brasas da sua destruição!\""},{"s":"05BC056","n":"Monja dos Ventos","f":"\"A técnica da nossa escola é derivada do controle sobre a respiração. Assim como as tempestades são derivadas dos ventos.\""},{"s":"05BC127T1","n":"Nuvem Tempestuosa","f":"A Nuvem Tempestuosa se chocou com a Aberração em uma mistura crepitante de névoa e raios. A fera grunhiu enquanto caía, o olhar monstruoso revirando para dentro da órbita ocular. Kennen se aproximou cautelosamente à medida que a Nuvem Tempestuosa ia se dissipando. Os Kinkou saíram vitoriosos, mas isso não duraria muito. Sempre haveria outra ameaça. Outro monstro. Mas eles estariam prontos."},{"s":"05BC046","n":"Punho de Trovão","f":"Quando Masa acertou o boneco de treinamento, um raio irrompeu de seu punho, partindo a madeira em dois e chamuscando os pelos de suas mãos. Ele puxou a corda, examinando sua mão cor de bronze e refletindo sobre o treinamento — finalmente estava pronto. De repente, um rugido monstruoso ecoou ao longe."},{"s":"05BC127","n":"Rissu, a Tempestade Silenciosa","f":"Preparar uma Nuvem Tempestuosa levava tempo — tempo que Rissu não tinha. Suas mãos trabalhavam sem parar enquanto a Aberração se aproximava. Um pouco de nuvem aqui, uns raios ali e... CRACK! BUM! Ela conseguira! Mas será que seria o bastante?"}]},{"id":"inventors","name":"Inventores e mechas","desc":"Bombas, robôs e máquinas gigantes: Heimerdinger, Ziggs e Rumble não sabem parar quietos.","items":[{"s":"05BC086","n":"Abalante","f":"\"Dizem que sou uma piada. Que tenho terra no lugar dos miolos. Que eu faço muito barulho, mas não derrubo nada. Bom, tenho só uma coisa pra dizer pros meus adversários... Vou fazer o chão sob vocês tremer!\"\n– Entrevista pré-luta"},{"s":"06BC051","n":"Atiradora de Bananas","f":"''OPA! ALGUÉM AÍ PRECISANDO DE POTÁSSIO?'' – Nana, momentos antes do ''Incidente''"},{"s":"05BC079","n":"Escavinho","f":"\"Achou que eu deixava o meu dinheiro enterrado embaixo da arena? HAH! Acha que eu sou o quê, um pirata? Agora vai lá fechar o buraco antes da próxima luta! ... ... Tim, temos que mudar o dinheiro de lugar de novo.\" – Karl, o Mandante da Arena"},{"s":"05BC235","n":"Ferreiro Yordle","f":"\"A Poppy nunca me escuta, mas acho bom você escutar: O que importa não é o martelo, e sim o yordle que o empunha.\""},{"s":"05BC138","n":"Gambiarreiros","f":"\"Essa foi uma luta das boas. Bom trabalho, pessoal. Agora limpem toda essa imundice e, hã, vocês já sabem: o que ainda der pra usar... é só consertar e colocar à venda na loja de novo! AHAHAHA!\" – Karl, o Mandante da Arena"},{"s":"05BC192","n":"Gêmeos Bombardeiros","f":"O Confusilador Bomberante-X fez exatamente o que foi criado para fazer: tocar o caos. Além disso, é muito fácil fazer baliza com ele."},{"s":"05BC212","n":"Inspetor de Segurança","f":"Wilfred não botou muita fé no começo. Durante a inspeção, também não. Na verdade, ele continuou desconfiado até o final — mas Ziggs e os outros especialistas em hexplosivos provaram que sabiam dar um show e tanto."},{"s":"05BC080","n":"Ligeirinho e Bofetão","f":"\"Eu não escolhi essa vida, foi essa vida que ME escolheu!\"\n– Entrevista pós-luta"},{"s":"05BC196","n":"Mech Puladuna","f":"\"Viu só? Espalha por toda parte! EU NÃO GOSTO DE AREIA! E a limpeza vai custa uma fortuna!\" – Karl, o Mandante da Arena"},{"s":"05BC171","n":"Mechforce Geodo","f":"Movido por gemas mineradas nas cavernas abaixo de Bandópolis, o Mechforce emite um escudo defensivo capaz de resistir às armas mais poderosas — além de ser uma gracinha."},{"s":"05BC172","n":"Professor Von Mech","f":"\"Alguém tira essas malditas bolas de pelo da minha mesa!\" – Karl, o Mandante da Arena"},{"s":"05BC073","n":"Química Criativa","f":"Giselle era uma das alunas mais brilhantes do Professor Heimerdinger – até ouvir falar dos estranhos experimentos que Ziggs realizava em Zaun. Depois disso, era só \"hexplosivos\" pra cá e \"escreve uma carta de recomendação pra eu poder estagiar com ele\" pra lá."},{"s":"05BC170","n":"Ranzinzim Destruidor","f":"Se mexer com o mech, vai levar chifrada."},{"s":"05BC173","n":"Roleta Marítima","f":"Por razões óbvias, \"talugas de força\" nunca se tornou uma verdadeira unidade de medida."},{"s":"05BC088T2","n":"Rumble","f":"\"Sabe, eu sei que a Tristy já tem um lança-chamas, uma eletrobroca e aquela maça gigantesca, mas pô... eu NÃO PODIA deixar de adicionar uns foguetes. Heh heh.\""},{"s":"05BC082","n":"Segurança e Parafuso","f":"\"Aquele buraco que vocês fizeram no teto durante a última luta vai ser descontado do seus salários!\" – Karl, o Mandante da Arena"},{"s":"05BC089","n":"Tectrompete","f":"Os mechs e os yordles estavam feridos, surrados, abatidos. Porém, eles ouviram o som sintético e metálico da trombeta, e ganharam mais garra, mais vida: Doot Doot!"},{"s":"lcorki","n":"Corki","f":"O Bombardeiro Ousado.\nCorki, o piloto yordle, ama duas coisas acima de qualquer outra: voar e seu glamoroso bigode... não necessariamente nessa ordem. Depois de deixar Bandópolis, ele se estabeleceu em Piltover e se apaixonou pelas máquinas maravilhosas que encontrou por lá.","l":1}]},{"id":"gloom","name":"Os sombrios","desc":"Yordles que preferem a escuridão: Veigar, o mestre do mal (baixinho), e Vex, que acha tudo um saco.","items":[{"s":"05BC094","n":"Acólito Bulboscuro","f":"\"Sim, tenho quase certeza de que o rapaz lá em cima tem muitas histórias para contar. Todos sabem que ele tem muito a dizer, mas ninguém consegue entender NADA do que ele diz.\" – Alfaiate Esnobe"},{"s":"05BC057","n":"Alfaiate Esnobe","f":"\"Ao instituir uma seita secreta, é preciso garantir que cada fanático ofereça algo único para essa união de supervilões. Um dos meus companheiros, por exemplo, tem um senso de estilo letal.\"\n– Trecho do Cap. 4 de \"Como Ser um Supervilão\", escrito por Lorde Veigar"},{"s":"05BC098","n":"Catalisador Desequilibrado","f":"A escuridão se materializa em inúmeros tamanhos e de várias formas – e algumas delas são INCRIVELMENTE fofinhas."},{"s":"05BC169","n":"Errante Tecsombra","f":"Agora você o vê. Agora não vê. E, agora, você já era."},{"s":"09BC011","n":"Espíritos Melancólicos","f":"''Sonhos têm um jeito esquisito de mudar os espíritos. Esses parecem ser... opa! Isso aí é bolo?'' – Lillia"},{"s":"05BC093T2","n":"Líder Supremo Veigar","f":"\"Aha. Muaha. Ahahaha. AHAHA. AHAHAHAHAHA! MUAHAHAHA! MUAHAHAHAHAHAHAHA!\"\n– Trecho do Cap. 12 de \"Como ser um supervilão\", escrito por Lorde Veigar"},{"s":"09BC003","n":"Presente Grotesco","f":"''Olha só, não foi um presente tão ruim no fim das contas.''\n– Vex"},{"s":"09BC018","n":"Sombra","f":"''Isso aí, Sombra! Mostra pra eles. Nada de presentes, confete e PRINCIPALMENTE chapeuzinhos de aniversário.'' – Vex"},{"s":"09BC004","n":"Sossega o Facho","f":"\"Veeeeex! Pera aí! Tenho uma coisinha pra você! É um convite para sua própria FESTA DE ANIVERSÁRIO! E seu presente adiantado! Não me aguentei. Você tá animada? Precisamos decidir o que vestir, o bolo e... Vex?''"},{"s":"05BC096","n":"Tenor do Terror","f":"Se Veigar precisava de ajuda para harmonizar o conceito de justiça, então não havia ninguém melhor do que esses dois para fazer o serviço. Eles entendem tudo de harmonização – e de tacar o terror."},{"s":"05BC119","n":"Tropa","f":"\"Um verdadeiro supervilão nunca terá tropas demais! Esses camaradinhas sabem seu lugar, obedecem cada palavra e sempre voltam para receber mais instruções.\"\n– Trecho do Cap. 2 de \"Como ser um supervilão\", escrito por Lorde Veigar"},{"s":"09BC001T3","n":"Vex","f":"''Bem, isso é horrível. E não do jeito bom.''"}]},{"id":"artists","name":"Artistas e festeiros","desc":"Músicos, pintores, contadores de histórias e organizadores de festa. Em Bandópolis, sempre há uma comemoração.","items":[{"s":"06BC019","n":"A Especialista em Chás","f":"Ashane era uma renomada especialista em chás antes de se perder no Fim do Reino. Enquanto realizava experimentos com novos sabores, acabou misturando duas folhas que a colocaram em um sono profundo. Ela sonhou com criaturas estranhas e estruturas impossíveis, cujas silhuetas contrastavam com o horizonte infinito. Porém, ao acordar, Ashane descobriu que aquilo não foi um sonho."},{"s":"05BC184","n":"Bardos Barulhentos","f":"\"Esta é uma canção\nSobre Poppy, a queridinha da nação!\nPoppy, a grandiosa, poderosa... em ação!\n– Letra riscada do 'Livro de Canções de Reginaldáctilo e Fatimisqueiro, Bardos Extraordinários'"},{"s":"06BC036","n":"Paparo, o Grande","f":"\"TODO MUNDO ama o Paparo! Todo verão, ele nos traz amuletos de todo o mundo, e eles sempre são ou deliciosos, ou lindos, ou confusos! Às vezes, são as três coisas ao mesmo tempo! – Ava Dedicada"},{"s":"05BC146","n":"Pintora de Bandópolis","f":"\"A arte da pintura não se trata de copiar o que se vê, e sim de expressar como VOCÊ vê o mundo. E acabei de ver que você se mexeu DE NOVO! Para de se mexer!\""},{"s":"05BC010","n":"Treinador de Tubarões","f":"A rotina do Treinador se repete toda noite: peixe com cerveja na janta e uma tragada rápida de seu cachimbolha, seguido de beijinhos na cabeça de seus tubarões e uma historinha antes de dormirem."},{"s":"09SI014","n":"Tristálio","f":"Romântico sombrio, poeta atormentado e apreciador da filosofia, Tristálio não se importa com um pouco de melancolia e perdição. Sua amada leva a fama de ser um pouco irritadiça, mas essa característica apenas a torna mais adorável a seus olhos."}]},{"id":"fae","name":"Magia feérica de Bandópolis","desc":"A magia que atravessa portais e sonhos: Lulu e seu companheiro feérico Pix, e Norra, a Mestra dos Portais e guardiã da biblioteca mais invejada de Bandópolis, com sua gata mágica Yuumi, que hoje guarda o Livro dos Limiares.","items":[{"s":"06BC016","n":"Biblioteca Viva","f":"Ele considera que seu dever é ter uma quantidade incrível de conhecimento, então coleciona tomos de vários viajantes que passaram pelo Fim do Reino. Infelizmente, todo esse conhecimento acabou subindo à cabeça dele."},{"s":"05BC020","n":"Bibliotecária Assistente","f":"\"Jelly é minha MELHOR AMIGA! Ahn, depois de você, Livro. E da Norra. Tá, Jelly é minha TERCEIRA MELHOR AMIGA. Isso ainda é muito bom, né?!\" – Yuumi"},{"s":"06BC026","n":"Byrdo, Tocante de Sinos","f":"\"... na segunda vez foi um estrondo. Eu estava varrendo o chão quando, de repente, vi meu jantar espalhado pela mesa e minhas panelas e frigideiras cambaleando sob duas pernas, saindo porta afora! Corri tão rápido quanto esses joelhos me permitiram e as encontrei naquele templo, vasculhando as prateleiras como se estivessem procurando por algo.\" – O conto do Velho Gaff, parte 2"},{"s":"03IO018","n":"Cuidador Felpudo","f":"Os silfos roxos são criaturinhas tão dóceis que todos que os encontram querem cuidar deles. Bom, quase todos."},{"s":"05BC005","n":"Donzelas das Algas","f":"\"Nossa, acabei de ter um sonho muito estranho. Eu estava cavucando as algas, procurando meu chapéu de concha... Até que, de repente, escutei uma melodia encantadora. Porém, quando dei por mim, já estava sentado aqui, com a caneta na mão, escrevendo este relato. E não me lembro de ter sentado para tirar um cochilo...\"\n– Registro Ecológico do Conquiliologista, dia 22"},{"s":"07BC018","n":"Estudioso do Portal","f":"No decorrer de qualquer pesquisa sempre há surpresas... Felizmente, dessa vez, é uma boa."},{"s":"01IO008","n":"Fada das Lâminas","f":"\"Ah, você me acha 'engraçadinha', é? 'Fofinha'? Olha só que fofinho ISSO AQUI!\""},{"s":"07BC005","n":"Fada das Lâminas Esculpida","f":"\"Olha só, essa é novidade.\" – Fada das Lâminas"},{"s":"06BC024","n":"Guia do Reino","f":"Gaspar foi o primeiro yordle a chegar no Fim do Reino. Por muitos anos, ele vagou sozinho entre caminhos e trajetos distorcidos que pareciam não levar a lugar algum. Depois de decidir que ninguém deveria passar por isso, ele agora ajuda outros viajantes perdidos a encontrar o caminho de volta para casa."},{"s":"03IO003","n":"Guia Feérico","f":"\"Shh! Por aqui! Vamos fazer uma curva fechada à esquerda depois da casa na árvore e passar direto pelas flores falantes. Lu, tá me ouvindo? Lu? Lu! LULU! NÃO dê comida a elas. Não pode.\""},{"s":"03IO010","n":"Jovem Bruxa","f":"Sir Ribery Montague partiu em busca de uma grande jornada ou de uma família nobre para bajular. Mas o destino o levou a um Bandobosque escondido, onde a jovem Bri logo o transformou em sapo e saiu arrastando o coitado a todas as aventuras DELA. Pobre Rib!"},{"s":"03IO002T1","n":"Lulu","f":"\"Uau! Olha só isso, Pix! Esse mundo é totalmente diferente! Vamos deixar tudo bem colorido!\""},{"s":"06BC031","n":"Maduli, Guarda do Portão","f":"\"Levei um susto grande, grande mesmo. Braços brotando pra tudo quanto é lado. Uns dentes grandes como rochas. Ah, e quando a criatura passou aquela baqueta nos dentes, saiu uma melodia tão estranha que eu pensei que ia morrer. Fugi, ah se fugi. Mas não antes de ver... buracos no céu! Devia ter centenas deles!\"\n– O conto do Velho Gaff, parte 4"},{"s":"06BC015T2","n":"Norra","f":"Com um zunido e um estalo, vários pedacinhos do totem ganharam vida, uma bugiganga girando aqui, uma engenhoca piscando acolá. Enquanto a sala ressoava e gemia, um portal se materializou lá no alto... e uma vaga silhueta de orelhas de gato tomou forma. Norra gritou, derramando seu chá de tanta alegria. Será que ela finalmente encontrou o caminho de casa?"},{"s":"05BC066","n":"Pena Rápida","f":"\"C... a... d... ê... a... N... o... r... r... a...? Ai, ai, o que eu falo?\"\n– Mordomo Roedor"},{"s":"03IO017","n":"Pix!","f":"\"Ser amiga do Pix é pra quem tem sorte! Ele é pequenininho, legal e muito forte!\nEle adora gambás e gosta muito de... hããã, blá-blá-blás!\"\n– Lulu"},{"s":"07BC020","n":"Senhor Catatreco","f":"Ninguém sabe quando o Senhor Catatreco começou sua coleção nem de onde veio. Ele parece ser amigável o bastante… ainda que deixe um rastro preocupante de riscos de tropeção aonde quer que vá."},{"s":"03IO007","n":"Trevor Dorminhão","f":"Você deve seguir seus sonhos, não manifestá-los com feitiços declamados inadvertidamente enquanto passeia por uma floresta mágica. Agora SILÊNCIO, por favor."},{"s":"01IO036","n":"Vigia da Clareira Verdejante","f":"\"Patrulha, nós temos uma... não... DUAS criaturas peludas gigantescas vindo para cá! Chame refor... Ah. Espera aí. A luneta estava ao contrário de novo...\""},{"s":"05BC183","n":"Vovô Feérico","f":"\"Venham, ouçam minhas palavras,\nO triste conto do Vovô Fada.\nTodos os dias, ele dava de comer às aves esfomeadas,\nUma mistura estranha de sementes e coalhadas...\"\n– Grande História de Bandópolis"},{"s":"05BC029","n":"Yuumi","f":"Yuumi tinha que confessar que, apesar de todo o rebuliço, gostava bastante do Livro. Gostava do cheiro dele. Gostava das ilustrações. Ela gostava até de atravessar os portais dele...! Mas nada era tão bom quanto ter Norra sã e salva em casa."},{"s":"05BC029T4","n":"Yuumi","f":"\"Vou aonde você for!\" – Yuumi"}]},{"id":"citizens","name":"Cidadãos de Bandópolis","desc":"Prefeitos, empresários da arena, tios e vizinhos: o povo comum de Bandópolis, entre festas e confusões.","items":[{"s":"05BC129","n":"Mandante da Arena","f":"\"A cada minuto que se passa, nasce um novo trouxa no mundo, e eu vou tirar proveito de todos eles... Essa arena de mechs vai virar uma MINA DE OURO!\""},{"s":"09BC006","n":"Prefeito Bombadão","f":"O tempo desacelerou quando o prefeito estranhamente musculoso saiu daquele bolo inacreditavelmente alto. ''Muitos PARABÉÉÉÉÉNS PRA VOCÊ!'', disse o prefeito mostrando os músculos. ''Da melhor (e mais musculosa) autoridade eleita de Bandópolis!''\n\nDe todos os seus sonhos, esse era o que Vex mais odiava."},{"s":"05BC116","n":"Prefeito de Bandópolis","f":"Não se sabe se houve mesmo eleições para prefeito em Bandópolis, mas, sem dúvidas, ter um bigode de respeito seria um pré-requisito à candidatura."},{"s":"05BC091","n":"Promoter da Arena","f":"\"INGRESSOS! COMPRE OS SEUS INGRESSOS! TÁ PELA METADE DO PREÇO! Ai, ai, ai, se eu não vender isso, o chefe vai me matar... literalmente.\""},{"s":"09BC002","n":"Tio Milty","f":"Apesar de ser bem diferente de sua sobrinha tristonha, o Tio Milty sempre se esforçou para criar uma conexão com ela... principalmente se for com uma história assustadora à luz de velas."}]},{"id":"outros","name":null,"desc":null,"items":[{"s":"05BC110","n":"Alpinista Erudito","f":"\"Tá bom, tá bom, você já me contou que ela gosta muito de chá, de meias, de você, de botões e de colecionar cacarecos, mas ainda não me contou COMO ela é!\""},{"s":"05BC130","n":"Chapa Quente","f":"Os churrascos de verão do Otto tinham certa fama. Embora ficasse animado com a grelha, ele deixava aos convidados poucas opções além de carne \"bem passada\" ou \"muito bem passada\"."},{"s":"06BC028","n":"Cultista Florente","f":"Pessoas, plantas, animais... A influência corruptora dos Darkin não poupa nada nem ninguém."},{"s":"05BC007","n":"Empilhadores de Pedras","f":"Os yordles ainda não entenderam como a gravidade funciona. Mas tudo bem — a gravidade também não entendeu como Bandópolis funciona."},{"s":"05BC102","n":"Feiticeiro Fastidioso","f":"Se não há dor maior do que a dor de se cortar com papel, então pode-se dizer que ninguém conhece a dor melhor do que um bibliotecário."},{"s":"05BC162","n":"Líder Nakotak","f":"O Chefe Nakotak se proclamou líder da tribo depois de ter encontrado um grande osso de dinossauro nos montes de neve ao redor de suas terras. Os outros não sabiam que ossos de dinossauro equivaliam à liderança da tribo, mas nenhum se importou muito. Então, o cargo ficou para Nakotak."},{"s":"05BC151","n":"Maga dos Espelhos","f":"\"Ah, ela é uma mestra excepcional em armar jogos de espelhos — faz todos os meus designs parecerem ainda mais refinados. E, com uma pequena manipulação nas luzes, até consegue dar um pouco de verticalidade para um certo alguém...\" – Alfaiate Esnobe"},{"s":"08BC006","n":"Pioneira dos Portais","f":"''Estou preocupado com o Bunches! Ah, ele parece estar cada vez mais nervoso esses dias. Até mesmo um saltinho entre portais o deixa angustiado! Não consigo entender...''\n– Registros de expedição da Divisão de Grandes Distâncias da Guilda dos Exploradores, alocação: Bandópolis"},{"s":"05BC085","n":"Sentinato Arruaceiro","f":"\"Dá pra abaixar isso aí?! Eu mal consigo me ouvir contando todo esse dinheiro!\" – Karl, o Mandante da Arena"},{"s":"08BC002","n":"Skip, o \"Rei do Recife\"","f":"''Sim, sou bonitão, rápido e maneiríssimo. Não sabia, velhote? Sou o rei desse recife, e você tá invadindo meu reino!''\n''E-Espere! Volte aqui agora mesmo! Preciso daquele espécime para minha pesquisa!'' – Conquiliologista"},{"s":"05BC152","n":"Viajantes Aborrecidos","f":"\"Pior. Viagem. De todas.\" – Elle"},{"s":"05BC069","n":"Yordle Palestrinha","f":"Nunca deixe ele desembestar a falar."},{"s":"u981c2c7026","n":"A Transmogrificação Visual de Heimerdinger","f":"Os yordles nem sempre controlam esse encanto e podem aplicá-lo de várias formas. O renomado inventor Heimerdinger, por exemplo, confeccionou dispositivos tecnológicos peculiares para que ele e Ziggs pudessem transitar livremente pela sociedade piltovense.","u":1},{"s":"u48f0c20375","n":"As Aparências Enganam...","f":"Em partes do mundo onde a população é menos esclarecida, a aparição de um yordle pode ser considerada um evento assustador ou sobrenatural. Felizmente, eles têm muita facilidade em se camuflar e geralmente são protegidos por uma espécie de encanto místico, permitindo que passem despercebidos ou assumam uma aparência menos chamativa.","u":1},{"s":"ub4822a8d77","n":"Mais Forte que a Vida ou a Morte","f":"Fascinados pelas relações que observam entre os mortais de Runeterra, os amáveis yordles costumam formar laços profundos e duradouros uns com os outros; e para o povo de Bandópolis, não há vínculo maior do que a família que você escolhe.","u":1}]}],"places":[{"s":"09BC012","n":"A Reunião de Família","f":"Saudade do que nunca vivi não se aplica. Os jantares em família são calmos por aqui, do jeitinho que a Vex gosta."},{"s":"05BC073T1","n":"Bomba Rudimentar","f":"\"É mesmo uma obra de arte incrível, não é?!\" – Giselle, Química Criativa"},{"s":"05BC027","n":"Campo Minado de Hexplosivos","f":"\"Como assim 'isso não parece seguro'?\" – Ziggs"},{"s":"09BC013","n":"Dádiva Alada","f":"O velho Trevor Dorminhão está sempre viajando de um sonho para outro. Por sorte, esse aqui parece ser bem calmo... mas, estranhamente, todo mundo por aqui parece querer asas iguais às dele..."},{"s":"06BC041","n":"Rebimbocas da Sucatita","f":"Grande ou pequena, inanimada ou não, se você precisa encontrar alguma bugiganga, procure a Sucatita! Só não pergunte à Sucatita onde está, porque ela não é adepta à catalogação."},{"s":"u11b0cad2c8","n":"A Árvore de Bandópolis","f":"Muito antes de os yordles chamarem Bandópolis de lar, havia apenas uma árvore. Ninguém sabe quando ou por que, mas ela cresceu e preencheu o espaço por trás da realidade e estendeu seus galhos pelo Reino Espiritual até que não era mais possível determinar o início ou o fim; ela simplesmente era e sempre foi.","u":1},{"s":"ubc8f2ab460","n":"Geometria de Trânsito","f":"Alguns portais só podem ser abertos com uma série de gestos específicos, normalmente definidos por símbolos peculiares inscritos em pontos próximos. Este portal em particular abre caminho para uma caverna profunda, cujas reentrâncias se enchem com água quando a maré baixa e revela um padrão de círculos rúnicos.","u":1},{"s":"u7d2c314959","n":"Nas Profundezas do Bandobosque","f":"Embora a localização dos portais possa mudar ao longo do tempo, muitos permanecem sempre no mesmo local. Às vezes, nesses lugares conhecidos como bandobosques, a magia espiritual transita entre os dois reinos, afetando a flora e a fauna local de formas estranhas e imprevisíveis.","u":1},{"s":"u7d0dc50f6f","n":"Portões do Outro Mundo","f":"Runeterra está ligada a um lugar encantado no reino espiritual conhecido como Bandópolis. Os caminhos raramente são vistos por mortais, pois só se abrem em circunstâncias específicas, ou para aqueles capazes de ler e interpretar a linguagem dos yordles.","u":1},{"s":"w7d8ddc8bf3","n":"Bandópolis (arte conceitual 1)","w":1},{"s":"w6396abb6e0","n":"Bandópolis (arte conceitual 10)","w":1},{"s":"w03d8bc1e23","n":"Bandópolis (arte conceitual 11)","w":1},{"s":"w790d8c5d6f","n":"Bandópolis (arte conceitual 12)","w":1},{"s":"wd03362558b","n":"Bandópolis (arte conceitual 13)","w":1},{"s":"w6e9553cbf5","n":"Bandópolis (arte conceitual 14)","w":1},{"s":"w1e195b3d87","n":"Bandópolis (arte conceitual 15)","w":1},{"s":"w901f89ecf0","n":"Bandópolis (arte conceitual 16)","w":1},{"s":"we9fafb6f9a","n":"Bandópolis (arte conceitual 17)","w":1},{"s":"w2ff8d072c6","n":"Bandópolis (arte conceitual 2)","w":1},{"s":"w9c3afa2399","n":"Bandópolis (arte conceitual 3)","w":1},{"s":"wab6e4cbe22","n":"Bandópolis (arte conceitual 4)","w":1},{"s":"wd7b8aad8b3","n":"Bandópolis (arte conceitual 5)","w":1},{"s":"w14de909050","n":"Bandópolis (arte conceitual 6)","w":1},{"s":"w3a03525c9c","n":"Bandópolis (arte conceitual 7)","w":1},{"s":"w5f578a242a","n":"Bandópolis (arte conceitual 8)","w":1},{"s":"w8c3693178f","n":"Bandópolis (arte conceitual 9)","w":1}],"creatures":[{"s":"05BC004","n":"Arirolvo","f":"\"Curiosos e brincalhões, os arirolvos são uma espécie bem divertida e... Espera, eu não tinha preparado um terceiro sanduíche?\"\n– Registro Ecológico do Conquiliologista, dia 7"},{"s":"05BC050","n":"Benêmona","f":"\"Quem for suscetível a náuseas deve se aproximar desta gigante gentil com EXTREMA CAUTELA. Acredite, seu estômago vai te agradecer... Pensando bem, eu não deveria ter comido aquele segundo sanduíche de cogumelo...\"\n– Registro Ecológico do Conquiliologista, dia 3"},{"s":"05BC084","n":"Chio","f":"Estatura pequena, personalidade GRANDE."},{"s":"05BC100","n":"Cogumelhotinho","f":"\"Como é? Dois recrutas estavam patrulhando a floresta, deram de cara com um monstro de grama aterrorizante e estão prestes a morrer de forma lenta e dolorosa? Bom garoto! Me leva até lá!\" – Teemo"},{"s":"05BC188","n":"Conchianos Curiosos","f":"Conhecidos por sua timidez, sabe-se que os conchianos se escondem em suas conchas até que a curiosidade os force a sair. Quando emergem, demonstram toda sua personalidade brincalhona, pregando peças e imitando com maestria os sons de outras criaturas marinhas."},{"s":"06BC021","n":"Criação de Sucata","f":"Ele havia nascido no dia anterior, mas Marv, apelido dado carinhosamente por Norra, já tinha muito orgulho de ser seu assistente. Porém, ele insistia severamente em ser chamado de \"sucata\", e não \"lixo\", que carrega uma certa conotação negativa."},{"s":"05BC221","n":"Círculo dos Cogumelos","f":"As cabecinhas de alfinete são fofas de tirar o chapéu."},{"s":"05BC010T1","n":"Dentinho","f":"\"Já dizia o ditado: 'Não morda a mão que te alimenta'. Mas valha-me Bandópolis, eles mordem não só a minha mão, como também QUALQUER COISA QUE ALCANÇAREM!\"\n– Registro Ecológico do Conquiliologista, dia 13"},{"s":"05BC177","n":"Dragão de Papel","f":"\"Mais uma dobra, e tá vendo? Uma girafa! Ele se chama Meias.\"\n\"Por que 'Meias'?\"\n\"Norra ama meias, então vai amá-lo também!\" – Mordomo Roedor"},{"s":"03IO008T1","n":"Esquilo","f":"Um brilho cintilante o atirou no chão! Com uma audição repentinamente aguçada, ouviu ao longe a gargalhada de uma yordle. Ele olhou para baixo e se deparou com patas peludas... presas a braços peludos..."},{"s":"03IO011","n":"Esquilo Bombado","f":"O segredo dele é vitamina de nozes, quatro vezes ao dia."},{"s":"07BC011","n":"Felpudinhos Ferozes","f":"Para o desprazer dessa trupe de furtivistas piltovenses, eles só parecem inofensivos."},{"s":"03IO001","n":"Florzinha de Estimação","f":"Todos querem um mascote fiel, mas ninguém está preparado para a responsabilidade. Tem que levar para passear, oferecer uma dieta balanceada, adaptar a casa... Dá muito trabalho."},{"s":"05BC167T1","n":"Gatoruja Faminto","f":"\"... Mas, um dia, ele chegou sem nada\nE nas aves crescia uma fome exaltada\nElas atacaram, causando puro desconforto\nAté que não sobrasse nada além de um homem morto!\"\n– Conto-da-carochinha de Bandópolis"},{"s":"05BC168T1","n":"Gigagrompe","f":"Então, acontece que cutucar os grompes do Vale Nakotak com um graveto faz com que reajam de forma muito... expansiva! Quem dera aqueles yordles tivessem descoberto isso através de testes extensivos e geracionais. Quem. Dera."},{"s":"05BC015","n":"Lagartiquinho","f":"\"Come a pimenta!\", vociferou Nakotak, provavelmente. \"Não, come a pimenta VOCÊ!\", retrucou Jojo, também provavelmente. Enquanto discutiam, um lagarto pequeno passou correndo, perseguindo uma mosquinha. A dupla de yordles fitou o lagarto, a pimenta e depois um ao outro. Se lâmpadas existissem, uma teria queimado."},{"s":"05BC015T1","n":"Lagarto Lávico","f":"Jojo e Nakotak gritavam rindo e riam gritando enquanto fugiam. As chamas do Lagarto Lávico já haviam chamuscado os pelos de suas costas, consumido árvores e estavam começando a derreter o frágil monte de neve. Foi DEMAIS."},{"s":"05BC032","n":"Lanterninha Reluzente","f":"\"A Lanterna segue a Norra, mariposas-luna seguem a Lanterna, os ratos seguem as mariposas-luna! Segue, segue!\""},{"s":"05BC023T1","n":"Megapeximboi","f":"... mas, como dizem, yordles fazem yordlezices!"},{"s":"06BC042","n":"Metamorfos Curiosos","f":"Camaleão vê, camaleão vira."},{"s":"05BC014","n":"Minidáctilo","f":"As criaturas do Vale Nakotak são tão diversas e alegres quanto a terra que habitam... e tão propensas a explodir quanto ela."},{"s":"05BC001T1","n":"Minipeximboi","f":"Ahn, um minipeximboi tão petitico!"},{"s":"05BC112","n":"Muda de Pinstouro","f":"As Mudas de Pinstouro são criaturas tímidas e, apesar de sua primeira reação ser recuar, se ameaçadas..."},{"s":"03IO007T1","n":"Murmuduende","f":"Outro duende apareceu de repente, com um olhar travesso e malicioso. \"Chega de queijo para o Trevor\", anunciou Bri. Todos assentiram."},{"s":"05BC019","n":"Peixe Arco-íris","f":"A Peixe Arco-íris ficou feliz em fazer reconhecimento aéreo, mesmo que isso significasse dar o maior salto de sua vida. Ela aceitaria qualquer folga, por menor que fosse, do olhar faminto de Yuumi."},{"s":"08BC004","n":"Portia, a Peculiar","f":"''Claro que conheço a velha Portia! Ela é meio avoada, mas pode te levar rapidinho a qualquer lugar com um portal. Uma giradinha da cauda, e pronto!'' – Pioneira dos Portais"},{"s":"05BC106","n":"Resmunguesma","f":"\"Mesmo com seu pequeno porte, a resmunguesma apresenta um grande apetite e algo que só consigo descrever como 'um terrível mau humor'.\"\n– Registro Ecológico do Conquiliologista, dia 17"},{"s":"05BC168","n":"Sapo Pintado","f":"Durante várias gerações, os yordles do Vale Nakotak buscaram entender seus vizinhos, os grompes. Primeiro, o Líder Hegabo tentou cutucá-los com um graveto. Em seguida, o Líder Babobu tentou cutucá-los com um graveto. O Líder Nakotak tinha um plano inédito: cutucá-los com um graveto."},{"s":"05BC148","n":"Silfo Furioso","f":"Consistente por fora, duro e amargo por dentro."},{"s":"03IO009","n":"Silfo Saboroso","f":"Energia: 104 kJ (25 kcal), Carboidratos: 5,88g, Açúcares: 3,53g, Fibras: 3g, Gorduras: 0,18g, Proteína: 0,98g, Água: 92g..."},{"s":"05BC175","n":"Telescópio Errante","f":"A parte mais estranha não era ver o telescópio levantar, se espreguiçar e andar por aí, mas vê-lo fazer questão de se vestir conforme o clima, o que dava início à jornada em busca de um cachecol confortável para telescópios."},{"s":"05BC014T1","n":"Terrordáctilo","f":"Quando enfurecidos, os Terrordáctilos atravessam os céus erraticamente, deixando um rastro pitoresco de caos e yordles petrificados."},{"s":"w593da78e5e","n":"Criatura de Bandópolis (arte conceitual 1)","w":1},{"s":"wfb2b30068e","n":"Criatura de Bandópolis (arte conceitual 2)","w":1},{"s":"wf34ca3d07e","n":"Criatura de Bandópolis (arte conceitual 3)","w":1},{"s":"w1f71c37bda","n":"Criatura de Bandópolis (arte conceitual 4)","w":1},{"s":"w50f2fdbf18","n":"Criatura de Bandópolis (arte conceitual 5)","w":1},{"s":"wbbaba06029","n":"Criatura de Bandópolis (arte conceitual 6)","w":1}]},"noxus":{"groups":[{"id":"trifarian","name":"Trifarix e a Legião Trifariana","desc":"O núcleo político e militar de Noxus: o Trifarix reúne Força (Darius), Visão (Swain) e Astúcia (o Sem-Rosto), e a Legião é a elite disciplinada do exército.","items":[{"s":"03NX002","n":"Arrel, a Rastreadora","f":"\"Esconda-se... e te encontraremos.\nRespire... e te ouviremos.\nCorra... e te mataremos.\""},{"s":"01NX044","n":"Aríete","f":"\"Senhor, eles se recusam a abrir os portões. Exigiram falar com Darius, mas ele está a dois dias daqui. Devemos enviar alguém para buscá-lo?\"\n\"Não, não será necessário.\""},{"s":"01NX016","n":"Aspirante a Trifariano","f":"\"Você ganhará este título quando seu machado já tiver perdido o fio no combate e suas botas estiverem ensopadas de sangue.\"\n– Veterano da Legião"},{"s":"01NX033","n":"Avaliadora Trifariana","f":"\"É preciso um olhar meticuloso para selecionar quem é digno de entrar na Legião Trifariana. Ela consegue distinguir claramente as ovelhas dos lobos.\" – General da Legião"},{"s":"02NX005","n":"Balista de Ferro","f":"\"É fácil armar um cerco com as ferramentas certas. Primeiro trazemos eles pra fora, depois as balistas fazem o resto.\"\n– Engenheiro de Cerco"},{"s":"01NX008","n":"Basilisqueiro","f":"Esta unidade até usa cavalos, mas não como montaria. Eles são bons como ração."},{"s":"01NX051","n":"Capitão Farron","f":"Dentro do Sumidouro de Zaun, o jovem Benn Farron foi considerado uma ameaça. Instável. Inaceitável. Mas nas fileiras de Noxus, ele foi acolhido. Condecorado. Implacável."},{"s":"07NX028","n":"Capitão Kalrix","f":"O objetivo do império de Noxus é, acima de tudo, a expansão. Madeira, pedra ou aço — nada pode parar o avanço de um aríete noxiano."},{"s":"03NX005","n":"Caçadora Brutal","f":"\"Aí está você. Nós SABÍAMOS que não viria sem resistir. Ou, pelo menos, era o que esperávamos.\""},{"s":"01NX038T2","n":"Darius","f":"\"Se ficar em nosso caminho, eu te corto ao meio com minhas próprias mãos!\""},{"s":"02NX004","n":"Demolidora Imperial","f":"\"Rápida e silenciosa... até a explosão.\""},{"s":"02NX006","n":"Devasta-Cidades","f":"A voz do ancião estava estranhamente calma quando ele perguntou: \"Qual é o sentido de juntar pedras para construir muros mais altos, se os noxianos sempre conseguem jogá-las de volta para o nosso lado?\""},{"s":"09NX032","n":"Domador de Yetis","f":"O sucesso da máquina de guerra noxiana se dá em parte por sua flexibilidade. Quando terrenos difíceis ou condições adversas exigem adaptação, os militares utilizam os recursos locais mais improváveis."},{"s":"03NX003","n":"Escudeiro da Lâmina","f":"\"É como as caçadoras disseram: cem dias e noites. Cem bolhas nos pés, cem insetos no café da manhã, cem conversas sobre \"lâmina\" e \"vingança\". E bem mais de cem encheções de saco dessas três. Vou te contar, viu...\""},{"s":"01NX010","n":"General da Legião","f":"Todo noxiano conhece os três Princípios da Força, mas para que um soldado seja promovido, ele deve aprender a dominá-los."},{"s":"01NX037","n":"Granadeiro da Legião","f":"Todo noxiano aprende que servir ao império é aproveitar bem a vida, mas poucos têm uma vida tão espetacular quanto os granadeiros da Legião."},{"s":"02NX010","n":"Montapresa Encouraçado","f":"\"Não há como parar uma fera de guerra depois que está em movimento. O melhor a fazer é sair do caminho.\"\n– Basilisqueiro"},{"s":"01NX017","n":"Percussionista da Legião","f":"A Legião espalhou o alcance do império ao som de cada batida dos tambores dela. Nada podia detê-los. E nada os deteve."},{"s":"01NX041","n":"Quebra-escudos Trifariano","f":"\"Não estou com paciência para fazer um cerco. Mandem os Quebra-escudos.\" – Darius"},{"s":"01NX012","n":"Retaguarda da Legião","f":"Em Noxus, onde soldados são venerados por sua audácia no campo de batalha, ficar na retaguarda não passa de um castigo."},{"s":"01NX040","n":"Sabotadora da Legião","f":"\"Nossos Quebra-escudos conseguem cortar um homem ao meio, mas a Legião tem outros talentos à disposição para um toque mais... discreto.\" – Swain"},{"s":"01NX021","n":"Saqueador da Legião","f":"A Legião Trifariana é seguida por salteadores oportunistas que se aproveitam dos fracos e feridos em seu caminho."},{"s":"02NX007","n":"Swain","f":"\"Um poder além da compreensão mortal me permite ver o que os outros não veem. Eu enxergo nas trevas que os outros temem.\""},{"s":"02NX007T2","n":"Swain","f":"\"Qualquer sacrifício é válido para testemunhar minha visão de Noxus se concretizando.\""},{"s":"01NX026","n":"Trifariano Imprudente","f":"\"A imprudência é um defeito. Nas mãos da Legião, ela se torna uma ferramenta.\" – Swain"},{"s":"u8e3eca0fe7","n":"A Legião Trifariana","f":"A força militar mais nobre, respeitada e experiente do exército noxiano é “a Legião”, liderada por Darius em pessoa. Além de serem os melhores soldados de Noxus, eles são leais e extremamente dedicados ao império e aos seus líderes.","u":1},{"s":"uce08f14a3f","n":"Armadura Noxiana","f":"Armas, ferramentas e implementos forjados em Noxus tendem a compartilhar a mesma estética severa que pode ser vista na arquitetura e vestimentas do império.","u":1},{"s":"ue1fae662e1","n":"Armamento Noxiano","f":"As forjas de Noxus nunca param, confeccionando espadas, machados e armaduras em grandes quantidades para o seu exército. O império valoriza mais a função do que a forma e seus designs muitas vezes agregam funcionalidades extras, como alças em forma de gancho para derrubar os inimigos de suas montarias.","u":1},{"s":"uf0ea68be42","n":"Artífices de Guerra","f":"Os artífices de guerra são patrulheiros, engenheiros e guerreiros habilidosos que planejam e supervisionam a construção de estradas, pontes e fortes. Geralmente a primeira indicação de uma expansão noxiana não é a presença de tropas, mas a presença de um artífice solitário patrulhando o território inimigo para identificar possíveis rotas de invasão.","u":1},{"s":"uc9733f6137","n":"Força na Variedade","f":"Até mesmo dentro da Legião Trifariana, há pouca uniformidade nas hierarquias. Em Noxus, os talentos e habilidades naturais dos guerreiros são valorizados, e eles não tentam impor seus próprios padrões para que os guerreiros se adequem a uma determinada forma de combate.","u":1},{"s":"u1d944d5736","n":"Machado de Darius","u":1},{"s":"ub7f9024efa","n":"Os Bandos Guerreiros de Noxus","f":"Noxus tem um dos maiores exércitos do mundo, formado por tropas de elite como a Legião Trifariana e por centenas de bandos guerreiros individuais. Liderados por seus próprios chefes, marechais e capitães, cada bando é único e possui sua própria cultura, hierarquia e estilo de combate.","u":1},{"s":"lkled","n":"Kled","f":"O Cavaleiro Intratável.\nUm guerreiro tão destemido quanto genioso, Kled é a personificação da bravata de Noxus. Muitos dizem que o yordle lutou em todas as campanhas que os pelotões conduziram e obteve todos os títulos militares, sem nunca ter recuado de uma batalha.","l":1}]},{"id":"blackrose","name":"A Rosa Negra","desc":"Uma sociedade secreta de magos que manipula Noxus nas sombras há séculos, liderada por LeBlanc.","items":[{"s":"04NX007","n":"Atakhan, Emissário da Devastação","f":"Uma aberração gigantesca e desconhecida cobria o local envolto por fumaça. Lá, os magos seguiam entoando um cântico em um coro desarmônico, com suas vozes alcançando um tom rouco e frenético encoberto por medo. O monstro respirava fundo, sentindo o pavor crescente daquelas pessoas, e ganhava um enorme poder a cada arfada."},{"s":"06NX036","n":"Escudeiro Rúnico","f":"Durante meses, ele trabalhou arduamente em meio ao frio e à chuva, uma tarefa ingrata sem fim à vista. No entanto, o fim chegou. Finalmente, ele seria alguém na vida."},{"s":"04NX010","n":"Espinho da Rosa","f":"\"Aelana, minha querida amiga! Por acaso já falou com o Lorde Duin? Ah, que pena. Eu mal via a hora de colocar o papo em dia. Espero que ele não tenha se afobado hoje. Eu não gostaria nada se alguma coisa acontecesse com o nosso companheiro...\" – Lady Auvray, Espiã da Rosa Negra"},{"s":"04NX008","n":"Estrategista Indomável","f":"Nos gabinetes reservados da Rosa Negra, os nobres noxianos movem suas peças, e a morte acomete vítimas distantes."},{"s":"04NX004T2","n":"LeBlanc","f":"\"... todos queremos a mesma coisa.\""},{"s":"03NX001","n":"Tecelã de Runas","f":"\"Muitas armas são ferramentas grosseiras que valem tão pouco quanto as mãos de quem as fez. Mas uma arma infundida com magia rúnica é muito mais do que mero aço.\""},{"s":"lbriar","n":"Briar","f":"A Fome Contida.\nA incontrolável sede de sangue de Briar, um experimento fracassado da Rosa Negra, exigia uma estrutura especial para controlar sua mente frenética. Após anos de confinamento, essa arma viva se libertou de todas as restrições e ficou livre no mundo. Agora ela não é controlada por ninguém, seguindo apenas sua própria fome de conhecimento e sangue...","l":1}]},{"id":"floricorvus","name":"Conservatório Floricorvus","desc":"Academia fundada em segredo pela Rosa Negra. Annie ateou fogo à escola e fugiu; os alunos se dividem entre a Trifarix e a Rosa Negra.","items":[{"s":"06NX008","n":"A Monitora","f":"\"Muitas das crianças estão em uma idade em que suas inclinações naturais as levam a se rebelar contra as orientações formais. Por sorte, a mais velha é aceita pelo resto e simpática à nossa causa. Se os alunos resolverem ignorar nossas lições, ensinaremos através dela.\" – Diretora Telsi"},{"s":"06NX012T7","n":"Annie","f":"\"Eu a encontrei. Ela é de Amoline, sem dúvida. Os mesmos olhos, a mesma risada. Vou trazê-la de volta dentro de quinze dias. Após falar com a garota, peço que seja gentil com ela. Acredito que há bondade ali, em meio à escuridão.\"\n– Trecho de uma carta de Fynn Retrick"},{"s":"08NX014","n":"Diretora Telsi","f":"A aula da diretora Telsi sobre disciplina pessoal é repleta de tarefas árduas, palmadas e detenções. Essa aula sempre foi obrigatória para os alunos do Conservatório Floricorvus. Caso contrário, ninguém se matricularia."},{"s":"06NX015","n":"Estudante Manalma","f":"\"Conheço Daani já há alguns anos. Rapaz adorável. Família adorável. Então, em minha última viagem, fui até a aldeia dele e encontrei o pobre Daani sentado na praça, sozinho. Disse que estava esperando a família voltar para casa. O pobre rapaz deve ter ficado sentado lá por meses. Não tive coragem de dizer a ele o que eu tinha visto no caminho...\" – Fynn Retrick"},{"s":"06NX013","n":"Lançador de Feitiços","f":"Aluno: Sydell Kythera\nProfessora: J. Willough\nRelato: Fui picada por uma aranha no antebraço esquerdo. Sydell alega um mal-entendido, mas seu sorriso desmente sua inocência. Ele terá duas semanas de tarefas adicionais (refeitório).\"\n– Carta de Disciplina da Floricorvus"},{"s":"06NX012T1","n":"Tibbers","f":"O demônio Tybaulk infestou as mentes de inúmeras vítimas ao longo dos séculos. Lentamente, inexoravelmente, ele os levava ao fogo e observava as chamas devorarem a carne queimada. Mas, na jovem Annie, Tybaulk encontrou uma determinação completamente indomável e um talento para a magia comparável até ao seu próprio."},{"s":"06NX028T1","n":"Tybaulk","f":"\"... ela me corrói. Essa presença sombria. Escuto seus sussurros. Fogo. FOGO. Nas chamas, vejo seus olhos. Sombrios e sempre abertos. Encarando. Sorrindo. Incitando-me a intervir. Incitando-me a descansar também. Silhuetas no inferno. Estendendo a mão. Venha para casa. Venha para casa.\"\n– Restos de um diário decrépito de Nockmirch"}]},{"id":"ironlegion","name":"Legião de Ferro de Mordekaiser","desc":"O exército de Mordekaiser, o antigo tirano que voltou dos mortos: legionários de ferro, revenantes e as almas acorrentadas que lutam por ele.","items":[{"s":"09SI013","n":"A Conquista de Ferro","f":"No Reino Cinzento, figuras atormentadas constituem um exército espectral. Depois que os portões do reino mortal forem abertos, ninguém poderá detê-los."},{"s":"08SI015","n":"Amálgama de Ritos Vis","f":"Feras de guerra têm valor para qualquer exército. No Reino Cinzento, elas são fusões de almas torturadas, cada uma mais sedenta e violenta em sua não senciência."},{"s":"08SI026","n":"Cultista do Aperto Mortal","f":"Aos olhos de seus seguidores, o Revenã de Ferro é a única esperança para os que buscam o oblívio. Paz pela dominação é um conceito que os sectários aceitam de braços abertos."},{"s":"08SI003","n":"Espectros Agrilhoados","f":"\"Faz muito tempo que fomos acorrentados. Em breve, você também entenderá nosso sofrimento, e todos nós sofreremos por toda a eternidade, até que nos seja concedido o esquecimento pela mão do Mestre...\""},{"s":"08NX024","n":"Legionário de Ferro","f":"\"Arranque as almas das jaulas que são seus corpos!\"\n– Mordekaiser"},{"s":"08SI007","n":"Legião dos Desgarrados","f":"Não importa que forma as almas tinham antes de serem aprisionadas no Reino Cinzento. Lá, a individualidade tem pouco valor. Anônima e destemida, a Legião, com sua uniformidade, é ainda mais útil ao Revenã de Ferro."},{"s":"08SI042","n":"Mordekaiser","f":"Preso à sua armadura guardada no coração do Bastião Imortal, Mordekaiser forjou o próprio trono no Reino Cinzento. Para cada um que busca destruí-lo, muitos outros servirão a ele tanto na vida quanto na morte."},{"s":"08SI042T1","n":"Mordekaiser","f":"\"Sirvam a mim! Abdiquem de suas almas miseráveis. Eu lhes darei o ferro eterno. Sou o esquecimento inevitável!\""},{"s":"08SI037T1","n":"Ocasoquilador das Mil Garras","f":"O arranhar de mil mãos com garras de ferro e o ranger de dentes espectrais prometem um fim terrível para qualquer um que se recuse a servir."},{"s":"08NX025","n":"Revenã Terebrado","f":"\"Você sorri, mas eu conheço a verdade do seu coração traiçoeiro! Eles sorriram ao meu lado e comeram à minha mesa enquanto planejavam me enfiar uma espada pelas costas. Não serei feito de bobo de novo. Você vai morrer como os outros: implorando perdão aos berros!\""},{"s":"u70b2411b1d","n":"Camadas da História","f":"O Bastião Imortal, no coração de Noxus, existe há muito mais tempo do que o próprio império. Dizem que ele foi erguido sob as ordens do temido revenã Mordekaiser e partes dele foram demolidas e reconstruídas ao longo de vários séculos, por isso suas ruas têm vários níveis e alguns distritos estão hoje soterrados. Poucos se atrevem a andar pelas suas ruas durante a noite sem guardas para protegê-los.","u":1}]},{"id":"crimson","name":"Círculo Carmesim e a Legião Cinza","desc":"Os hemomantes de Vladimir e a Legião Cinza da Senhora do Sangue, de mortos reerguidos, como Sion.","items":[{"s":"05NX016","n":"A Senhora do Sangue","f":"Na calada da noite, a Senhora Faris Noradi retirou sua Legião Cinérea da capital noxiana. Após três semanas árduas e sangrentas, o exército enfim se aproximou do pequeno posto demaciano que os batedores haviam identificado. Era hora da demonstração."},{"s":"05NX009","n":"Alma Perdida","f":"Os demacianos rastejaram em direção às muralhas e encontraram a morte descendo por elas. Embora tenham conseguido derrubar alguns membros da Legião Cinérea, o curso sombrio da guerra logo se mostrou inevitável."},{"s":"01NX005","n":"Aristocrata Carmesim","f":"\"Ah, você também? Para o Baile do– \"A minha é insuportável.\" \"Então o meu pai me renegaria... Vamos usar vestidos combinando?\""},{"s":"05NX005","n":"Belicista Ancestral","f":"Conforme os poderes da Senhora Noradi aumentavam, ela se perguntava se eles poderiam se imbuir nos cadáveres das tumbas mais antigas de Noxus. Para ela, a luz da vida era uma mera faísca superficial. Mas, naquela chama fraca, as sombras da guerra ainda dançavam."},{"s":"03NX009","n":"Cavaleira Colérica","f":"\"Não há nada melhor do que caçar outros soldados. Para achá-los, é preciso pensar e se sentir como eles. Para capturá-los, é preciso temê-los como eles te temem. Esse é um vínculo que poucos conhecerão, mas que eu saboreio acima de tudo.\""},{"s":"05NX013","n":"Cavaleiro Caído","f":"\"Só depois de esfregarem a armadura do cavaleiro com folhas de erva-embreada eles foram poupados da crueldade do basilisco. Assim como essas feras, as plantas são nativas dos campos, e são tão pungentes quanto venenosas.\"\n– Anotações do Dr. Esslanger"},{"s":"05NX018","n":"Cavaleiro Reerguido","f":"\"Pela noite, a morte seguiu sua marcha.\" – A Senhora do Sangue"},{"s":"01NX048","n":"Curador Carmesim","f":"\"Prezados companheiros!\" \"Lisonjeado estou! Aliás, eu recebi um convite.\" \"–Regozijo! Isso!\" \"Sim! Vou apresentar minha família.\" \"Refinadas como sempre. E você, Kye? Também vai?\""},{"s":"05NX015","n":"Desafiador Caído","f":"\"Os primeiros minotauros que ressuscitei eram dóceis e inofensivos. Nem o tumulto da guerra nem a ameaça de morte eram capazes de atiçar seus sentidos.\"\n– Anotações do Dr. Esslanger"},{"s":"04NX021","n":"Desafiador Emérito","f":"Após inúmeras batalhas, Beryn jurou nunca mais empunhar uma espada, mesmo que isso significasse abrir mão da própria vida. Mas quando a estranha névoa avançou sobre Noxus e dominou Thea, ele soube que teria de quebrar seu juramento, pois iria salvá-la a qualquer custo."},{"s":"05NX017","n":"Desafiador Reerguido","f":"\"Foi seguindo a sugestão da boa Senhora que finalmente despertamos a criatura. Uma pequena dose de sal iodado na corrente sanguínea — letal para qualquer vivo, mas apenas excruciante para o nosso paciente. Para quem ressuscita, não há motivação maior do que a dor.\"\n– Anotações do Dr. Esslanger"},{"s":"01NX045","n":"Desafiador Selvagem","f":"\"A seguir, GARRAS! Tivemos uma batalha SANGRENTA da última vez contra os Cinco Psicóticos... que agora são três. Façam suas apostas sobre a vítima de hoje! Quatro para um!\" – Karl, Agente de Apostas da Arena"},{"s":"01NX030","n":"Discípula Carmesim","f":"\"Edvin! Aí está você, bonitão. Estava pensando em você agorinha!\" \"Oh, então vamos juntos.\" \"Não se preocupe, eu te acompanho.\" \"Gostei! Ou quem sabe não usar nada?\""},{"s":"01NX032","n":"Evocador Carmesim","f":"\"Até se eu recusasse, vocês me arrastariam. Então... tudo bem.\""},{"s":"05NX006","n":"Granadeiro Renascido","f":"\"Temos entre nós um caso irregular. Embora a maioria dos ressuscitados abomine o retorno à vida, esse sujeito parece compreender a sua sorte e apreciar as oportunidades advindas disso. Interessante.\"\n– Anotações do Dr. Esslanger"},{"s":"05NX004","n":"Médico Sepulcral","f":"O Dr. Esslanger era um médico aposentado e respeitado, cuja reputação fora conquistada ao longo de anos de dedicação e trabalho. Mas foi apenas quando uma jovem nobre foi levada ao seu consultório, com o sangue escurecido pela traição, que ele realmente começou a servir a Noxus."},{"s":"05NX002","n":"Nobre Rebelde","f":"\"Quer inspirar lealdade em um possível traidor? Nada melhor do que mostrar a volta de um conspirador assassinado para lutar sob a bandeira noxiana. De uma forma ou de outra, todos acabam se submetendo.\" – A Senhora do Sangue"},{"s":"06NX041","n":"Pombo Carmesim","f":"\"É bastante divertido, alimentar os pássaros. Apostei com o pobre Feoward que eles sugariam o sangue tão profundamente quanto um basilisco de Bordent, e vejam só: os pombos são realmente noxianos!\" – Edvin Cortain, Curador Carmesim"},{"s":"05NX007","n":"Revenã das Lâminas Gêmeas","f":"\"Nitidamente, os demacianos perderam a vontade de lutar perante o renascimento de nossos mortos, que haviam sido dilacerados de forma tão altruísta pelos bravos membros da Vanguarda. A vitória nunca esteve em jogo.\"\n– Trecho do relatório de campo da Senhora do Sangue; destinatário desconhecido"},{"s":"04NX018","n":"Sangríneo Carmesim ","f":"\"Quase ninguém os têm como bichinhos de estimação, sabia? Um corte feito por essas garras pode abrir veias facilmente... mas, por mim, tudo bem.\" – Clara, Discípula Carmesim"},{"s":"05NX001T3","n":"Sion","f":"No calor da batalha, ele se lembrou. Lembrou-se de sua vida como um orgulhoso servo de Noxus. Um general respeitado que deu a vida para derrubar o rei de Demacia. Lembrou-se de sua morte e do imenso vazio que se seguiu. Ele tivera uma boa vida e uma boa morte. Mas isso... isso era loucura."},{"s":"05NX001T1","n":"Sion Reanimado","f":"\"Apesar da névoa persistente, ao despertarmos Sion, todo o espectro da guerra instigou nele uma vida feroz e, ao mesmo tempo, relutante em terminar.\"\n– Anotações do Dr. Esslanger"},{"s":"01NX006","n":"Vladimir","f":"Brutal. Frio. Cruel. Intrigante. Perspicaz. Charmoso.\nIrresistível..."},{"s":"01NX006T1","n":"Vladimir","f":"\"Achou minha festinha banal, meu bem? Então vou mostrar o que é um show de verdade.\""}]},{"id":"arena","name":"Arenas e gladiadores","desc":"Nas arenas de Noxus, glória vale tanto quanto ouro. Draven é o astro; muitos lutam para sair da obscuridade.","items":[{"s":"01NX003","n":"Agente de Apostas da Arena","f":"\"... você vai apostar na Shiraza como ÚNICA SOBREVIVENTE, mas tem aquele garoto ioniano... É, ele perdeu um braço... mas não morreu. É um sobrevivente também, viu só? Mas você pode dobrar a aposta...\""},{"s":"01NX007","n":"Apresentador da Arena","f":"Ele urrou de alegria. Naquele momento, o coração da arena pulsava junto ao seu, e a empolgação da multidão era retratada em seu punho erguido e vitorioso."},{"s":"07NX006","n":"Cavalheiro Cortês","f":"\"Olha, eu costumo gostar de estabelecer algumas regras, tipo: 'não toque no meu cabelo nem no meu rosto', mas para que isso? Você não vai encostar um dedo em mim.\""},{"s":"07NX001","n":"Demolidora Destemida","f":"\"O ramo de armas exige uma relação saudável com as informações. Conceitos, testes, reformas, alterações: tudo isso requer informação. Nada como um rápido teste de campo para criar uma amostra funcional e abrir umas crateras!\"\n– Lani"},{"s":"01NX020T3","n":"Draven","f":"\"QUAL É O MEU NOME?!\""},{"s":"01NX009","n":"Favorito do Público","f":"Alguns Desafiadores são adorados por seu carisma. Outros, por suas técnicas ligeiras. Vessid não tem nada disso a seu favor, mas ninguém esmaga os rivais com mais eficiência que ele."},{"s":"01NX035","n":"Fã Número 1 do Draven","f":"\"Quer um autógrafo? E-Entra na fila!\""},{"s":"01NX024","n":"Kato, o Braço","f":"\"A Shiraza é uma ótima namo... digo, amiga! A gente não tá namorando. Mas se estivesse, eu desejaria um feliz aniversário de namoro. Obrigado, sem mais perguntas.\""},{"s":"01NX014","n":"Shiraza, a Lâmina","f":"\"Ele disse o quê?! Esse cara não tem nada na cabeça. Mas aqueles ombros...\""},{"s":"lalistar","n":"Alistar","f":"O Minotauro.\nUm poderoso guerreiro com uma temível reputação, Alistar busca vingança por seu clã, morto pelas mãos do império de Noxus. Apesar de ter sido escravizado e forçado a uma vida de gladiador, sua vontade indestrutível o impediu de se tornar uma fera de verdade.","l":1}]},{"id":"renegades","name":"Desertores e mercenários","desc":"Quem largou a Legião ou nunca entrou nela: mercenários, rebeldes e exilados como Riven e Rell, a fugitiva dos laboratórios da Rosa Negra.","items":[{"s":"07NX015","n":"A Dama Saqueadora","f":"\"Ah, a Dama. Adora um drama, aquela ali. Alguns podem torcer o nariz para uma certa pompa, mas, quando ela está inspirada, todo mundo sai ganhando.\" – Elegância Afiada"},{"s":"07NX004","n":"Artífice Astuta","f":"\"Em certos lugares, abrir uma loja pode ser difícil, mas, assim que viram o que eu e Lani estávamos vendendo, o dinheiro começou a entrar. Não vi nosso alvo entre os interessados, mas tem muita gente pensando em violência esta noite. Afinal, descobrir quem quer matar quem é uma boa forma de sondar o terreno.\" – Miel"},{"s":"07NX005","n":"Capitã Indari","f":"\"Já trabalhei com muitos agentes. Alguns eram fáceis de lidar, outros eram desafiadores... E tem a Samira. Eu já me acostumei com o fato de que não posso controlá-la. Em vez disso, eu administro o caos, miro na direção correta e, de vez em quando, participo.\""},{"s":"06NX030","n":"Desertor da Legião","f":"\"Ato um: Um ex-soldado, tendo abandonado seu posto após o roubo de um antigo artefato Kashuri, se esconde em um bar de Qayanvi, onde esbanja arrogância e bebe sem parar. Mal sabe ele que seu tesouro roubado conta tudo o que vê para o seu verdadeiro dono! Sua vida se esvai como vinho, o carmesim noxiano sobre ouro ioniano.\""},{"s":"08NX012","n":"Obtentor Armado","f":"\"Achei que seria mais fácil cavar no deserto, mas não! Com tempo suficiente, a areia inevitavelmente se transforma em pedra. Venho mais uma vez solicitar financiamento para ferramentas novas.\" – Registros de expedição da Divisão de Grandes Distâncias da Guilda dos Exploradores, alocação: Shurima"},{"s":"03NX007T1","n":"Riven","f":"\"... e eu não fugirei daqueles que querem me destruir.\""},{"s":"07NX007","n":"Samira","f":"\"Estou sempre perseguindo algum alvo que fez mais dívidas do que podia pagar. E fugir dessas dívidas rende inimigos do pior tipo. O tipo que recorre a mim.\""},{"s":"07NX007T1","n":"Samira","f":"\"Imaginei que não se tratasse de um simples caso de inadimplência. Indari chama essas coisas de ‘complicações’. Eu chamo de diversão.\""},{"s":"lrell","n":"Rell","f":"A Dama de Ferro.\nProduto de um experimento brutal nas mãos da Rosa Negra, Rell é uma arma humana rebelde que está determinada a destruir Noxus. Sua infância foi repleta de sofrimento e horror; a jovem teve que suportar procedimentos indescritíveis para aperfeiçoar e fortalecer seu controle mágico do metal – até que, um dia, empreendeu uma fuga violenta, matando muitos de seus captores no processo.","l":1}]},{"id":"houses","name":"Casas Nobres","desc":"As famílias antigas de Noxus (Darkwill, Swain, Talis), os assassinos da Família Du Couteau, como Katarina, e os Medarda, que ascenderam com Ambessa.","items":[{"s":"07NX008","n":"Elegância Afiada","f":"\"Meu preço é alto, e eu não trabalho para qualquer um. Se tiver a sorte de me contratar, você leva elegância, atitude e lâminas que nunca erram o alvo. Mas, acima de tudo, você leva estilo. Porque quem não ama matar com classe?”"},{"s":"01NX042","n":"Katarina","f":"\"Nada como um bom alvo demaciano para aguçar os sentidos...\""},{"s":"01NX042T2","n":"Katarina","f":"\"Não, senhor! Só vi um vulto vermelho. Quando me dei conta, olhei para cima e... parecia a cena de um massacre.\"\n– Guarda da fronteira de Demacia"},{"s":"06NX024","n":"Lorde Jubalarga","f":"\"Ato dois: Um lorde duvidoso e sem muitas posses, além de uma manopla Kashuri roubada, encanta uma plateia de ionianos. No entanto, sua máscara é grosseira e não esconde muito. Ele implora por sua vida, alegando ignorância. A mão de ferro que queria usar para governar agora está vazia.\""},{"s":"08NX009","n":"Lorde Mallat","f":"\"Foram necessários séculos de planejamento para capturar aquele terrível belicista. E seus amigos patéticos pretendem derrotá-lo com 'alegria'? Garota tola. Você só vai despertar a ira do Revenã e, assim, colocar todos nós em risco.\""},{"s":"lambessa","n":"Ambessa","f":"Matriarca da Guerra.\nTodos que conhecem o nome Medarda respeitam e temem a líder da família, Ambessa. Como general noxiana, ela incorpora uma combinação mortal de força implacável e determinação destemida em batalha. Seu papel como matriarca não é diferente, exigindo grande astúcia para fortalecer os Medardas sem deixar espaço para fracasso ou compaixão.","l":1},{"s":"lcassiopeia","n":"Cassiopeia","f":"O Abraço da Serpente.\nCassiopeia é uma criatura mortífera que costuma manipular e submeter os outros às suas vontades. A filha caçula e mais bela da nobre família noxiana Du Couteau, ela se aventurou pelas criptas subterrâneas de Shurima em busca de um poder ancestral. Lá, Cassiopeia foi mordida por um dos terríveis guardiões da tumba, cujo veneno a transformou em uma víbora predadora.","l":1},{"s":"lmel","n":"Mel","f":"O Reflexo da Alma.\nMel Medarda é a suposta herdeira da família Medarda, que já foi uma das mais poderosas em Noxus. Sob a aparência de aristocrata elegante, há uma política talentosa que faz questão de saber cada detalhe a respeito de todas as pessoas que conhece.","l":1},{"s":"ltalon","n":"Talon","f":"A Sombra da Lâmina.\nTalon é a adaga na escuridão, um assassino impiedoso capaz de atacar sem aviso e escapar antes que qualquer alarme soe. Ele construiu uma reputação perigosa nas ruas brutais de Noxus, onde foi forçado a lutar, matar e roubar para sobreviver.","l":1}]},{"id":"outros","name":null,"desc":null,"items":[{"s":"u258376cc33","n":"A Vida é uma Batalha","f":"Os noxianos respeitam a força acima de tudo, e a única maneira de se manter forte é sendo constantemente desafiado. Eles valorizam as oportunidades de enfrentamento, pois a falta de desafios leva à fraqueza; e até aqueles no auge de seu poder devem sempre buscar novas formas de se provar, se não quiserem que seu poder esteja com os dias contados.","u":1},{"s":"ueb187cdb7e","n":"Arte de Noxus","f":"Os noxianos consideram a magia mais uma poderosa ferramenta em seu arsenal. Aqueles que sabem usá-la são muito respeitados e costumam ser recrutados e buscados até mesmo fora de Noxus, para que seus talentos sejam aprimorados e utilizados em benefício do império.","u":1},{"s":"u0bbca95a44","n":"Arte de Noxus","u":1},{"s":"u9791e94f76","n":"Culturalmente Inclusiva","f":"Noxus se expande e derrota culturas e cidades próximas, oferecendo aos povos conquistados uma escolha: jurar lealdade a Noxus e ser julgado apenas pelo seu valor, ou ser destruído. Isso não é um subterfúgio ou algum tipo de estratagema, os noxianos seguem sua palavra e muitos dos que adotaram o estilo de vida de seus conquistadores têm chance de melhores possibilidades.","u":1},{"s":"ud70a8622bc","n":"Sangue Velho, Sangue Novo","f":"Desde que tenha força de vontade e determinação para alcançar o sucesso, qualquer pessoa pode prosperar em Noxus. Um grande exemplo disso é seu chefe militar, Darius, que veio de uma origem humilde para se tornar um dos líderes mais poderosos do império.","u":1}]}],"places":[{"s":"06NX029","n":"A Botica Cinzenta","f":"\"Hoje me peguei pensando na minha pequena enfermaria na Colina Toporrosa, e nos anos que passei lá tentando desvendar os segredos da fisiologia. Anos! Agora estou trabalhando para Madame Noradi há alguns meses, e já me dei conta de que não tinha aprendido nada. Como eu era simplório. E afortunado.\"\n– Notas do Dr. Esslanger"},{"s":"06NX028","n":"Conservatório Floricorvus","f":"\"... a essa altura, com certeza a notícia do fracasso da Academia Rosaguarda já chegou a você. Espero que aprenda com os erros da sua irmã. Espero que administre suas instalações de maneira a beneficiar o império.\"\n– Carta queimada encontrada nos escombros do conservatório"},{"s":"09NX025","n":"O Maioral da Arena","f":"A arena ficou popular, já que qualquer um pode ganhar fama dentro dela. Esse fã específico testemunhou o máximo de embates do Draven que pôde; se tiver a oportunidade, ele também acha que pode alcançar o topo."},{"s":"07NX034","n":"Salão de Banquetes Carmesim","f":"''Venham, meus amigos, sentem-se! A companhia é boa, e as bebidas não têm fim. Mal posso esperar para que vejam o que temos para o jantar.'' – Vladimir"},{"s":"uf984de26e8","n":"Arte de Noxus","u":1},{"s":"uecd8e3069d","n":"Arte de Noxus","u":1},{"s":"ubcf4b45af0","n":"Estado de Conflito Perpétuo","f":"Noxus é um império agressivo e expansionista, sempre buscando ampliar suas fronteiras e conquistar novas terras. Mas nem sempre é preciso recorrer à violência — na verdade, muitas nações se renderam perante ao Grande General por enxergarem a possibilidade de mais estabilidade e segurança junto ao império. Aqueles que desafiam Noxus, porém, são sumariamente destruídos.","u":1},{"s":"ub4bb916d25","n":"Opressiva e Protegida","f":"As cidades noxianas se caracterizam por suas estruturas imponentes, ruas claustrofóbicas, prédios ameados, muralhas inclinadas e portões imensos. As cidades refletem a força e o domínio do império, e são altamente protegidas; se um inimigo tentar um ataque surpresa contra uma cidade noxiana, ele enfrentará uma forte resistência a cada esquina, pois até as casas mais humildes são verdadeiras fortalezas.","u":1},{"s":"u8873e8f303","n":"Presença Noxiana em Shurima","f":"Vários portos e cidades ao norte de Shurima se juntaram voluntariamente ao império. Os habitantes nativos desses assentamentos vivem em relativa paz com seus vizinhos noxianos e veem a permuta de alimentos e o acordo comercial como um preço que vale a pena pagar em troca da proteção militar contra invasores.","u":1},{"s":"w016606b3af","n":"Noxus (arte conceitual 1)","w":1},{"s":"w7d9ca37403","n":"Noxus (arte conceitual 10)","w":1},{"s":"w52efa0f556","n":"Noxus (arte conceitual 11)","w":1},{"s":"w12a1b2aa71","n":"Noxus (arte conceitual 12)","w":1},{"s":"w694289788d","n":"Noxus (arte conceitual 13)","w":1},{"s":"w879d7bc45a","n":"Noxus (arte conceitual 2)","w":1},{"s":"w8adf4b3ccc","n":"Noxus (arte conceitual 3)","w":1},{"s":"w977c11ae18","n":"Noxus (arte conceitual 4)","w":1},{"s":"wbfa185fcbf","n":"Noxus (arte conceitual 5)","w":1},{"s":"wb9fd9d817b","n":"Noxus (arte conceitual 6)","w":1},{"s":"w7cbd962c04","n":"Noxus (arte conceitual 7)","w":1},{"s":"w25c6b9d156","n":"Noxus (arte conceitual 8)","w":1},{"s":"w4d7b1f74cd","n":"Noxus (arte conceitual 9)","w":1}],"creatures":[{"s":"03NX017","n":"Basilisqueiro Sanguinário","f":"Os treinadores de basilisco deixam as feras sem comer nos dias que antecedem à batalha. Quando as criaturas são soltas, ficam absolutamente indomáveis, incapazes de distinguir aliados de inimigos."},{"s":"06RU025T1","n":"Carcaça Desesperada","f":"\"Não estou saciada. Mais.\" – Vora"},{"s":"06NX009","n":"Cinzento em Cativeiro","f":"\"Ato três: Uma guardiã cruel e seu animal de estimação. O cinzento é inocente mesmo em seu terrível propósito. O artefato que carrega força a subserviência. A guardiã se recusa a gritar enquanto é devorada por seu animal de estimação. Ah, se todos os noxianos fossem tão nobres no momento de sua morte...\""},{"s":"08NX003","n":"Cospe-Fogo Enfurecido","f":"A expansão noxiana usurpou vários povos, assentamentos e culturas diferentes. Frequentemente, criaturas selvagem também estão à mercê da máquina da guerra, mas, no caso desse dragão, cada passo brutal de Noxus é respondido por uma fúria infernal igualmente brutal."},{"s":"07NX033","n":"Courósseo de Três Caudas","f":"\"Cuidado, seus imbecis! Noxianos só compram feras de combate em perfeitas condições. Qualquer arranhão vai sair direto do seu salário!\" – Magnata Magnânimo"},{"s":"06NX032","n":"Cão-dragão Obediente","f":"\"Os cães-dragão são maravilhosos, não acha? Sempre querendo agradar. Tão maleáveis. Se ao menos meus inimigos tivessem as mesmas qualidades.\" – Espinho da Rosa"},{"s":"04NX019","n":"Escamossauro Feroz","f":"Surpreso pela resiliência da criatura encontrada na costa de Ionia, o jovem general insistiu em levá-la com ele, ansioso para encontrar a fonte de tamanha força."},{"s":"02NX001","n":"O Leviatã","f":"Quando os ionianos o viram pairando no horizonte, pensaram que fosse um monstro. Eles não estavam de todo enganados. O navio de aço era apavorante. A maior realização da engenharia naval noxiana."},{"s":"08NX019","n":"Reptílio Farpado","f":"Embora útil para a máquina de guerra de Noxus, o repitílio também é estimado nas arenas de luta da capital. Poucos oponentes, humanos ou animais, estão dispostos a enfrentar essa fera na arena, e, portanto, as raras batalhas com sua participação atraem gente de toda a cidade."},{"s":"u33d8f7543d","n":"Basilisco","f":"Os basiliscos, répteis monstruosos encontrados nas montanhas do sul, são predadores vorazes que atingem proporções gigantescas. Enquanto jovens, são feras muito utilizadas para montaria e poucos conseguem resistir a suas investidas. Quando eles se tornam grandes demais para serem controlados, passam a ser utilizados como feras de carga ou, às vezes, como aríetes de batalha para derrubar muralhas de cidades sitiadas.","u":1},{"s":"ubf9a207dae","n":"Cães-dragão","f":"Os cães-dragão são uma espécie carnívora, de tamanho semelhante ao de um lobo, que habitam as montanhas ao norte da capital noxiana. Eles são ferozes, caçam em grupo e são muito utilizados em Noxus como feras de batalha, animais de guarda e animais de estimação de luxo (apesar de perigosos). Ter um ou mais cães-dragão é uma clara demonstração de poder e riqueza.","u":1},{"s":"w0ae91c6bbf","n":"Fera de Noxus (arte conceitual 1)","w":1},{"s":"wb4809bdb31","n":"Fera de Noxus (arte conceitual 2)","w":1},{"s":"waf9c54538a","n":"Fera de Noxus (arte conceitual 3)","w":1},{"s":"w41e96e254a","n":"Fera de Noxus (arte conceitual 4)","w":1}]},"piltover":{"groups":[{"id":"academy","name":"Academia e inventores","desc":"A Academia de Piltover reúne gênios, professores e aprendizes. Heimerdinger é o mais antigo deles.","items":[{"s":"01PZ009","n":"Aeronauta Amador","f":"\"Máquinas voadoras particulares? Nada mais que um sonho infantil! Na verdade, acabei de mandar meu pupilo jogar o último protótipo no lixo. Cadê ele mesmo?\" – Engenheiro piltovense"},{"s":"01PZ019","n":"Aprendiz Dedicado","f":"Nem todo mundo nasceu pronto para contribuir com o progresso de Piltover. Alguns precisam de orientação, por exemplo, aqueles que olham para a invenção com as lentes erradas."},{"s":"01PZ056T10","n":"Heimerdinger","f":"\"PROGRESSOOOOO!\""},{"s":"05PZ022T1","n":"Jayce","f":"\"Canhão preparado e martelo a postos. Esse vai ser um momento digno dos livros de história, pessoal.\""},{"s":"02PZ002","n":"Mecânica Chefe Zevi","f":"Aos cinco anos de idade, ela criou a primeira faca sônica de multifrequência do mundo. Embora não fosse muito prática (servia principalmente para cortar sanduíches), o feito a levou à Divisão de Armamentos dos Vigias."},{"s":"01PZ018","n":"Prodígio da Academia","f":"Como ela consegue mirar? Ótima pergunta."},{"s":"01PZ023","n":"Professor Von Yipp","f":"\"Hoje eu apresento ao comitê minha mais nova invenção, demonstrada pelo meu estimado colega...\""},{"s":"u72b69e2288","n":"Vaido Violante","f":"Vaido, um ex-aprendiz de Corvin Revek, trabalha em vários projetos ao mesmo tempo, mas estabilizar a saída de energia das suas famosas Manoplas de Atlas é sua maior prioridade.","u":1}]},{"id":"clans","name":"Clãs mercantes","desc":"As famílias ricas que governam Piltover pelo comércio: Ferros, Medarda, Kiramman e outras.","items":[{"s":"01PZ029","n":"Benfeitor Ilustre","f":"\"Eu era um homem raivoso, que destruía a concorrência para ganhar dinheiro e fama. Agora, eu invisto minha fortuna no altruísmo e espero que minha penitência me absolva dos meus erros.\""},{"s":"05PZ028","n":"Cruza-céu dos Ferros","f":"\"O povo desta cidade venera a 'inteligência', mas de que adianta a mente mais brilhante sem os recursos necessários para expressá-la? Basta. Mostrarei a Piltover o que é a verdadeira grandeza. E ela sobrevoará as cabeças de todos, bloqueará o sol e carregará o meu nome.\" – Albus Ferros"},{"s":"05PZ024","n":"Financista dos Ferros","f":"\"Uma das únicas coisas boas de ter os Ferros financiando o meu trabalho é poder trabalhar com o Reggie. O cara não é só uma das pessoas mais competentes que eu já conheci, como também é um sujeito sensacional.\"\n– Trecho do diário de Jayce"},{"s":"u7f5cae93cb","n":"Insígnias de Clãs de Mercadores","f":"Cada um dos clãs mercantis de Piltover tem suas próprias insígnias para identificar suas casas, oficinas, expedições, galpões, invenções, marcas e locais de negócios. Cada insígnia apresenta muitos significados e interpretações, alguns deles óbvios, outros nem tanto.","u":1},{"s":"ue1498a83e8","n":"Jago Medarda","f":"Jago, o atual mestre do Clã Medarda, comanda respeito e poder imensos através de Piltover. Com a renda gerada pelas patentes de pistão de seu pai, Jago financia pesquisas que estudam como usar hextec para acelerar os Portões Solares.","u":1},{"s":"u2055d1a0f6","n":"Riqueza e Status","f":"É comum que as entradas dos prédios mercantis sejam incrivelmente elaboradas. Mesmo as habitações que precedem a tecnologia hextec foram, desde então, ornamentadas com detalhes elaborados para reforçar ainda mais a impressão de que Piltover é uma cidade afogada em ouro.","u":1},{"s":"lcamille","n":"Camille","f":"A Sombra de Aço.\nMunida para operar além dos limites da lei, Camille é a chefe de inteligência do Clã Ferros, uma elegante agente de elite responsável pelo bom funcionamento da engrenagem de Piltover e da cidade baixa de Zaun. Adaptável e precisa, ela vê técnicas medíocres como uma vergonha que deve ser eliminada.","l":1}]},{"id":"wardens","name":"Vigias e investigadores","desc":"A guarda de Piltover. Caitlyn, a xerife, e Vi, que trocou as ruas de Zaun pelo distintivo.","items":[{"s":"05PZ012","n":"Arquivista da Delegacia","f":"Detetives não são nada sem pistas. O trabalho do arquivista é coletar todas as informações e encontrar possibilidades ainda não identificadas."},{"s":"05PZ006T2","n":"Caitlyn","f":"Ela entrou com tudo, apontou o rifle para o criminoso e olhou pelo visor. Lá, sorrindo do outro lado do vidro, havia um rosto familiar."},{"s":"05PZ004","n":"Esquadrão Policial","f":"Desde a chegada ao local da ação até a montagem do aríete, a preparação não demorou muito. Agora era só esperar o sinal da Caitlyn."},{"s":"01PZ006","n":"Guardião da Praça","f":"Você tem vinte segundos para cooperar."},{"s":"02PZ010","n":"Investigador Veterano","f":"Alguns agentes confiam em seus instintos para resolver um caso. Outros, em seus contatos. Mas os pontos fortes do Agente J. S. Harknor são a diligência e a burocracia. Muita burocracia."},{"s":"02PZ007","n":"Investigadora Perspicaz","f":"\"Todos os detetives reagem aos acontecimentos, mas um bom detetive pode prevê-los, e um detetive excepcional não deixa que aconteçam.\" – O Manual dos Vigias"},{"s":"05PZ015","n":"Motoqueira da Justiça","f":"\"A policial foi vista perseguindo o suspeito em alta velocidade na direção de uma armadilha armada por ela mesma. Após a captura, a agente emitiu sua própria multa por excesso de velocidade, alegando (de forma um tanto dramática) que a 'justiça é uma via de mão dupla'.\"\n– Trecho do relatório de operação de um Vigia"},{"s":"05PZ009","n":"Policial Infiltrado","f":"Como todas as crianças zaunitas, Zayne Asako precisou amadurecer rápido para sobreviver à violência das ruas sombrias. Depois de perder o irmão para a violência desnecessária das gangues, ele se alistou na polícia de Piltover na esperança de que a razão e a lei finalmente tornassem sua cidade segura."},{"s":"02PZ008T2","n":"Vi","f":"\"Olha só! Parece que seus amiguinhos cansaram. Você vai me dizer onde escondeu o hextec ou prefere fazer amizade com a parede também?\""},{"s":"02PZ005","n":"Vigias da Ronda","f":"A técnica de corrida da Vigia Mir era uma grande piada entre os outros executores. O Vigia Kepple nunca entendeu."},{"s":"u286d143941","n":"Calibre Hexlyene de Vishlaa","f":"Originalmente fabricado para os Vigias de Piltover, os designs para essa arma de hexenergia foram, desde então, trancafiados por serem considerados perigosos demais.","u":1},{"s":"u4895958f17","n":"Vigias","f":"Os Vigias são homens e mulheres com a tarefa de manter a lei de Piltover. A organização é financiada por impostos comerciais e contribuições “voluntárias” dos clãs mercantis, armando os Vigias com uniformes e equipamentos. Muitas dessas doações tomam a forma de tecnologia hextec única, como armas ou outros dispositivos especializados.","u":1}]},{"id":"hextech","name":"Hextec e progresso","desc":"Jayce e os inventores do hextec, a fusão de magia e tecnologia que mudou a Cidade do Progresso.","items":[{"s":"04PZ015","n":"Adaptatron 3000","f":"\"Ah, sim! O Adaptatron 3000! Adaptável, inventivo e muito bem apessoado! Se essa belezinha falasse, com certeza teríamos MUITO o que conversar.\" – Heimerdinger"},{"s":"07PZ015T1","n":"Bugiganga Fujona","f":"\"Agora, deixe-me ver... Talvez se adicionássemos... Ai, caramba! Alguém vai atrás daquela engenhoca!\" – Professor Heimerdinger"},{"s":"05PZ025","n":"Chefe da Forja","f":"\"Para tirar uma ideia do papel, é preciso ter duas coisas: uma é um bom financiamento, e a outra, uma boa forja. E não estou falando só das ferramentas ou do maquinário da forja, não — se a pessoa no comando não tiver o que é preciso para fazer tudo funcionar... a sua ideia não vai sair do papel.\" – Jayce"},{"s":"07PZ017","n":"Comerciante de Bombas de Clarão","f":"\"...E sabe o que mais torna essas belezinhas melhores do que cogumelos? Você decide quando elas explodem! ISSO é que é valor agregado!\""},{"s":"03PZ012","n":"Equipaníaco Armado","f":"\"Opa, braço novo! Sempre quis um desses. E o que temos aqui? Rodas de gravidade pras pernas? Ligas eletrônicas? DENTES DE METAL? Na verdade, deixa o meu rosto quieto. Eu gosto dele.\""},{"s":"01PZ059","n":"Esmagobô Dourado","f":"MATAR. ESMAGAR. DESTRUIR. REPETIR."},{"s":"01PZ056T1","n":"Mk0: Triturador de Corda","f":"\"HOJE EMBARCO EM UMA NOVA AVENTURA CIENTÍFICA: AUTÔMATOS! É como dizem, criar coisas geniais requer uma mente genial! Quem disse isso? Eu, É CLARO!\"\n– Notas de laboratório de Heimerdinger, Prefácio"},{"s":"01PZ056T4","n":"Mk1: Robô Assistente","f":"\"Percebi uma coisa: com duas mãos, posso manusear no máximo duas chaves! Achei a solução: MAIS MÃOS. Haha, brincadeira. UM ROBÔ ASSISTENTE!\"\n– Notas de laboratório de Heimerdinger, Vol. 1"},{"s":"01PZ056T7","n":"Mk2: Torre Evolutiva","f":"\"Medidas de segurança para o laboratório! Há relatos de um roubo na oficina do jovem Jayce. Hunf! Vocês não perdem por esperar, intrusos!\"\n– Notas de laboratório de Heimerdinger, Vol. 2"},{"s":"01PZ056T8","n":"Mk3: Torre Apex","f":"\"Ah, o doce aroma da ciência! Consegui aprimorar minhas torres! Devo dizer que este modelo causa vibrações hipotérmicas pelas minhas vértebras! Brrr!\"\n– Notas de laboratório de Heimerdinger, Vol. 3"},{"s":"01PZ056T9","n":"Mk4: Lança-tormentas","f":"\"PROGRESSO! Enfim conciliei o poder bruto da hexenergia e do meu arremessador de bolas! Apresento: o LANÇA-TORMENTAS! Agora vou dormir.\"\n– Notas de laboratório de Heimerdinger, Vol. 4"},{"s":"01PZ056T2","n":"Mk5: Propulsor de Foguetes","f":"\"Após alguns problemas de produção, principalmente com propulsão e orientação, enfim apresento meus COMBUSTÍVEIS PROPELADOS!... Preciso de um nome melhor.\"\n– Notas de Laboratório de Heimerdinger, Vol. 5"},{"s":"01PZ056T6","n":"Mk6: Devastador de Piso","f":"\"Perdi minha criação. E o entrepiso. Estou preocupado com meu robô, mas a gritaria no laboratório de cerâmica mantém minha esperança viva!\"\n– Notas de laboratório de Heimerdinger, Vol. 6"},{"s":"01PZ056T5","n":"Mk7: Esmagador Blindado","f":"\"Sonhei com uma grande criatura mecânica que obedecia a todos os meus comandos! PRECISO concretizar esse sonho. Testar estabilidade, avaliar coordenação e armadura...\"\n– Notas de laboratório de Heimerdinger, Vol. 7"},{"s":"05PZ023","n":"Operário da Forja","f":"\"Pois é, andei ajudando bastante o Jayce e o pessoal a mexer aqui e ali nesse troço novo. Chamamos de tecnologia Poderomativa. O Jayce diz que vou aparecer como coinventor quando a papelada ficar pronta. Bom que os mandachuvas ficam sabendo quem é o cérebro, né?\""},{"s":"03PZ019","n":"Porobot Recauchutado","f":"Não é tão macio quanto os verdadeiros, mas é tão bonitinho quanto um!"},{"s":"05PZ029","n":"Portador Hextec","f":"O Portador Hextec foi inicialmente construído para transportar materiais brutos por Piltover. Com o tempo, porém, parece que os moradores da cidade desenvolveram certo carinho por ele. A equipe da forja de Jayce o apelidou de Latinha, enquanto um lorde piltovense aparentemente doou um chapéu a ele e, agora, até mesmo as crianças que o encontram o enfeitam com o que tiverem em mãos."},{"s":"08PZ025","n":"Protótipo de Porobot","f":"''É só um protótipo'', gritou o aprendiz enquanto as chamas consumiam o laboratório. ''Eu não programei ele para engolir todos os equipamentos que tiver pela frente! Eu nem sei pra ONDE aquele metal todo tá indo!''"},{"s":"01PZ003","n":"Robô de Montagem","f":"\"Qualquer zé-ninguém pode construir uma máquina, mas só um intelecto superior seria capaz de infundir o VERDADEIRO progresso em um cérebro mecanizado! Logo aqueles burocratas nojentos voltarão rastejando...\" – Klas Henwick"},{"s":"01PZ015","n":"T-Hex","f":"\"ENFIM ACABEI! CENTO E NOVENTA METROS DE ALIMENTAÇÃO ROTATIVA, METAL HEXTEC E ENERGIA CELULAR DE QUADRÂNIO DE PURA DEVASTAÇÃO! Meu melhor trabalho, eu diria.\"\n– Notas de laboratório de Heimerdinger, Vol. 8"},{"s":"ucc1d1d5184","n":"Armas Hextec","u":1},{"s":"u5115a879f9","n":"Artifício de Piltover","u":1},{"s":"uc5405cbf0c","n":"Bateria em Cubo Hextec","f":"A primeira tentativa de capturar poder cristalino em uma forma portátil foi a Configuração Hexaédrica, com fragmentos cortados do Vale de Odyn.","u":1},{"s":"uc53f31c831","n":"Conduíte de tubos pneumáticos","f":"Uma rede emaranhada de tubos a vácuo, usada para transportar mensagens seladas entre os Salões Comerciais, se estende pela cidade, permitindo comunicações rápidas através de toda Piltover.","u":1},{"s":"ufbf8a6e163","n":"Hexarco de Ekalavya","f":"O poder das hexbobinas deste arco torna seus projéteis tão poderosos que podem perfurar aço forjado a frio.","u":1},{"s":"ubea213337c","n":"Hextec","f":"Hextec é a nova fusão emergente de magia e tecnologia, usada para criar artefatos requintados que podem ser utilizados por qualquer um, não apenas por aqueles que possuem uma aptidão para as artes arcanas. Ela aproveita o poder mágico contido em cristais extremamente raros e seu poder é limitado apenas pela imaginação de seus usuários.","u":1},{"s":"u658a8c77c3","n":"Manoplas de Atlas","f":"Melhorias hextec extremamente raras e poderosas que aumentam consideravelmente a força e destreza do usuário. O uso contínuo resultou em danos aos ossos do usuário, mas isso não diminuiu a demanda por tais itens.","u":1},{"s":"u20577031bb","n":"Veículo Anelar","u":1},{"s":"lorianna","n":"Orianna","f":"A Donzela Mecânica.\nOrianna já foi uma menina curiosa de carne e osso, mas hoje é uma maravilha tecnológica totalmente composta por partes mecânicas. Ela ficou terrivelmente doente depois de um acidente em um dos distritos inferiores de Zaun, e seu corpo enfraquecido precisou ser substituído por primorosos mecanismos, peça por peça.","l":1}]},{"id":"explorers","name":"Exploradores","desc":"Aventureiros, navegadores e pilotos de balão. Ezreal é o explorador mais famoso (e mais imprudente).","items":[{"s":"07PZ021","n":"Anura e Froop","f":"\"Não vou te machucar, colega! Vim até essa selva pela ciência, não pela destruição.\""},{"s":"09PZ045","n":"Cartografia Alada","f":"\"Estar lá no alto é a maneira mais certa de reconhecer a própria insignificância.\""},{"s":"01PZ036T1","n":"Ezreal","f":"\"O impossível é o meu possível preferido!\""},{"s":"01PZ035","n":"Jae Medarda","f":"Herdeiro do prestigioso Clã Medarda de Piltover, Jae prefere caçar artefatos antigos a administrar os negócios da família... para o desgosto do pai."},{"s":"01PZ042","n":"Marinheira Intrépida","f":"Muitos piltovenses exploram o desconhecido por meio da ciência na segurança da Cidade do Progresso. Já outros preferem embarcar rumo ao horizonte e desvendar um mistério bem maior: o mundo."},{"s":"08PZ018","n":"Marinheiro Ventonato","f":"\"Sim, eu tinha o que queria. Mas tudo que conquistei foi roubando, e roubar deixa um homem vazio. A primeira coisa que encontrei para seguir foi o vento... então agora estou aqui, esperando que ela me leve a um caminho melhor.\""}]},{"id":"seraphine","name":"Seraphine e o palco de Piltover","desc":"A jovem cantora que ouve o mundo como música e quem a acompanha do público.","items":[{"s":"06PZ010","n":"Acusticista","f":"Ele sonhara em deixar Zaun e viajar pelo mundo com uma música em seu coração. Agora, o mundo jazia adormecido em seu quarto, esperando pelas músicas que o amanhã poderia trazer."},{"s":"06PZ020","n":"Bolota, o Hextécnico","f":"Você não encontrará o nome dele nos projetos nem o verá creditado nas canções, mas aqueles que sabem concordaram: Bolota era o coração de toda a operação."},{"s":"06PZ014","n":"Presidente do Fã-clube","f":"\"O que importa não é a grandeza da sua voz, e sim a do seu coração!\" – Presidente do fã-clube"},{"s":"06PZ021T2","n":"Seraphine","f":"Ela nunca ouvira nada igual — talvez ninguém tivesse ouvido. Em união, naquele palco, criaram algo novo."}]},{"id":"outros","name":null,"desc":null,"items":[{"s":"06PZ007","n":"Cultista Ambicioso","f":"\"Sempre me dispus a fazer sacrifícios em nome da ciência. Apesar dos riscos pessoais, o poder irrestrito e inesgotável que ganhei com a troca foi uma recompensa mais do que adequada.\""},{"s":"01PZ014T1","n":"Engenhoca Ilegal","f":"\"Definitivamente NÃO é um equipamento dentro das normas.\" – Oficial de Vistoria, Agência Piltovense de Segurança"},{"s":"07SH005","n":"Magnata Magnânimo","f":"\"Vocês perderam tudo para O QUÊ?! Uma cientista com uma aberração réptil? E o que estão esperando, seus paspalhos? Andem logo e tragam meu dinheiro de volta!\""},{"s":"07SH039","n":"Soldado Adaptável","f":"\"Essa belezinha aqui pode transformar até um novato em um profissional em escalar árvores e saltar rochas. Custou uma fortuna, mas tenho certeza de que posso pagar esses empréstimos com a pele de uma ou duas feras raras...\""},{"s":"01PZ024","n":"Volticista Instável","f":"Nome: Klas Henwick | Idade: 51 | Licença: Condicional de Classe 2 | Situação: Revogada | Obs.: Ignorou repetidos avisos para reduzir a potência após explosão do laboratório (Caso 13X764NM). ENTRADA PROIBIDA."},{"s":"u0049066423","n":"Iluminando a Cidade do Progresso","f":"Uma fonte de luz nas ruas mais ricas em Piltover, essas luzes trespassam a escuridão (e o Cinza de Zaun emergente) com facilidade.","u":1},{"s":"u7e61f30dd1","n":"Residentes da Cidade","f":"A natureza cosmopolita de Piltover permite que seus habitantes sejam tão variados quanto a cidade, mas ainda assim eles compartilham um caráter particular. Um cidadão de Piltover é tipicamente autossuficiente, não espera nada de graça e sempre tenta fazer o seu melhor. Eles se opõem a interferências externas e enxergam um mercado aberto e livre como algo essencial para a contínua prosperidade da cidade.","u":1}]}],"places":[{"s":"uaddf9c554e","n":"Avenida Sideral, entrada da Caixa-Forte de Piltover","u":1},{"s":"u2be99792fa","n":"Caixa-Forte de Piltover","u":1},{"s":"u75732e8a62","n":"Cofres Eclípticos, o banco mais seguro de Piltover","u":1},{"s":"ue9bf456089","n":"Comércio e Progresso","f":"A antiga cidade de Zaun era um posto comercial shurimane ao norte, mas foi a criação dos portões marinhos de Piltover, mais de três mil anos depois, que trouxe ainda mais prosperidade.","u":1},{"s":"u183d5c789d","n":"Corte Ventazul","u":1},{"s":"uaff743b826","n":"Estruturas Maravilhosas","f":"As novas estruturas de Piltover são graciosas misturas de mármore polido, treliças de bronze e vidro cintilante que ficam ao lado de construções mais antigas, feitas de pedra lavrada e madeira desgastada. Torres plissadas encrustadas de ouro e prata estendem-se para os céus limpos, com pontes arqueadas atravessando fossos entre os cumes de colinas.","u":1},{"s":"u33d8399209","n":"Impactos por Valoran","f":"O comércio é o sangue de Piltover e seu comando das principais rotas marítimas de leste a oeste fizeram seus cofres incharem com ouro. Uma consequência disso foi a rápida expansão do império noxiano, cujos exércitos e suprimentos agora podem viajar pela expansão de Valoran com relativa facilidade.","u":1},{"s":"u1bace67821","n":"Oficina do Instituto Horológico","f":"Oficinas de pesquisadores hextec são exemplos magníficos do que um patrono rico pode fazer por um inventor.","u":1},{"s":"u865c7bec6d","n":"Oficinas","u":1},{"s":"uc96bef669c","n":"Os Portões Solares","f":"A construção destes portões marinhos fez de Piltover um centro de comércio entre Valoran e Shurima, trazendo riqueza inimaginável aos líderes da cidade.","u":1},{"s":"u89e80c40f8","n":"“Incognium Runeterra”, de Zindelo","u":1},{"s":"wfffb1fb855","n":"Piltover (arte conceitual 1)","w":1},{"s":"w0f8b309495","n":"Piltover (arte conceitual 10)","w":1},{"s":"w863a91daa6","n":"Piltover (arte conceitual 11)","w":1},{"s":"w29263ad456","n":"Piltover (arte conceitual 2)","w":1},{"s":"w46c45eab87","n":"Piltover (arte conceitual 3)","w":1},{"s":"w8be6a9d088","n":"Piltover (arte conceitual 4)","w":1},{"s":"w443cceffa1","n":"Piltover (arte conceitual 5)","w":1},{"s":"wc59df8539d","n":"Piltover (arte conceitual 6)","w":1},{"s":"wdf4212ecd8","n":"Piltover (arte conceitual 7)","w":1},{"s":"w16f7dd35e5","n":"Piltover (arte conceitual 8)","w":1},{"s":"w60a97a744e","n":"Piltover (arte conceitual 9)","w":1}],"creatures":[{"s":"08PZ026T1","n":"Andorinha do Vendaval","f":"\"Essas andorinhas do vendaval são criaturas fugazes. Metade do tempo, elas parecem ser feitas inteiramente de água! Ainda assim, aprendi da forma mais difícil a não perturbá-las...\"\n– Marinheira Intrépida"},{"s":"04PZ002","n":"Declínio Felino","f":"\"MAS OS MEUS PLAAAAAAAAAN... MIAUUUUUU!\""},{"s":"08PZ020","n":"Eolinuvem Glorioso","f":"\"Meu querido Zéfiro. Desça das nuvens e repouse em meus ombros por um tempo, sim?\" – Janna"},{"s":"06PZ041","n":"Gatinho Ardiloso","f":"Quando não estão dormindo no meio do dia ou vomitando no meio da noite, os gatos estão sempre fazendo algum tipo de travessura."},{"s":"01PZ033T1","n":"Gatástrofe","f":"Trarei seu fim iMIAUdiatamente."},{"s":"02PZ001","n":"Submiaurino","f":"Nada poderia impedir sua fuga daqueles humanos simplórios. Nem mesmo uma aguinha..."},{"s":"w56cf98abee","n":"Baleias voadoras (arte conceitual)","w":1}]},"zaun":{"groups":[{"id":"chempunks","name":"Quimiopunks e gangues","desc":"As gangues das ruas de Zaun, entre explosivos, gás e roubos. Jinx é a mais caótica de todas.","items":[{"s":"01PZ047","n":"Barril Cáustico","f":"\"Eu te diria pra usar um traje... se lá embaixo não fosse abafado igual sovaco de raxinim. Mas pode usar luvas. E reza pra gosma não cair em nada importante.\" – Ziel, capataz zaunita"},{"s":"01PZ054","n":"Bombardeiro Novato","f":"\"Tem certeza?\"\n\"Não.\"\n\"Você devia ter dito que sim.\"\n\"Você não devia ter perguntado.\""},{"s":"01PZ007","n":"Carro Alegórico","f":"O estrondo dos canhões atraiu multidões para a praça, ansiosas para ver o show. Depois todos passariam semanas tirando confete do cabelo."},{"s":"01PZ044","n":"Detonador Quimiopunk","f":"\"... seu solo rapidamente mergulha em uma escala menor harmônica antes de arpejar – sim, isso é uma palavra – na transposição da ponte. Você não entenderia a obra dele.\"\n– Max Bliff, guarda do portão"},{"s":"01PZ030","n":"Indivíduo Suspeito","f":"\"Olá, nobres colegas Barões da Química!\""},{"s":"01PZ040T1","n":"Jinx","f":"\"É a maior diversão até alguma coisa explodir... aí vira FESTA!\""},{"s":"01PZ051","n":"Malucânica","f":"\"Você quer ser um verdadeiro estouro? Veio ao lugar certo!\""},{"s":"05BC006","n":"O Arsenal","f":"Aonde quer que Ziggs fosse, Arnie ia atrás. Seu jeito sereno era perfeito para contrabalancear a energia caótica de Ziggs. Arnie tinha inúmeras funções, como verificar o estoque de munições, apagar incêndios e colocar as mãos sobre as orelhas de Ziggs quando ele (sempre) esquecia os protetores auditivos."},{"s":"06PZ019","n":"Segurança Zaunita","f":"Se tudo fosse do jeito dele, NINGUÉM entraria."},{"s":"05BC163T1","n":"Ziggs","f":"\"Nós passamos?! CARAMBA, PASSAMOS!\"\n\"Hehe, olha, 'passar' é uma palavra meio forte... mas vocês deram um show e tanto!\" – Ziggs e Wilfred, Inspetor de segurança"},{"s":"udf66fb9606","n":"Assassinos de Aluguel","u":1},{"s":"u146e70b3fd","n":"Pivetes do Sumidouro","u":1},{"s":"u609bd87e05","n":"Punks Químicos","f":"Apesar da maioria das gangues problemáticas formarem-se nas partes inferiores de Zaun, seus membros vêm de todos os níveis da cidade, inclusive Piltover.","u":1}]},{"id":"barons","name":"Barões químicos","desc":"Os chefões que controlam Zaun por trás das fábricas e do brilho: uma aliança frágil de conveniência. Renata Glasc é a baronesa mais nova, e Urgot, ex-carrasco noxiano libertado da mina-prisão Dredge, impõe sua sombra sobre o submundo.","items":[{"s":"06PZ036","n":"A Diva de Zaun","f":"\"Zaun! Espero que estejam prontos pra gritar, porque a gente vai afundar esse lugar de novo!\" – Diva de Zaun"},{"s":"01PZ021","n":"Capangas de Midenstokke","f":"\"Sr. Berz, achamos o senhor dormindo DENTRO do cofre, coberto de engrenagens de ouro e segurando a porta quebrada.\"\n\"Não era eu. Era só alguém parecido comigo.\"\n\"O senhor continua segurando a porta.\"\n\"Prove.\""},{"s":"01PZ048","n":"Corina Veraza","f":"\"Os piltovenses de mente fechada só conhecem engrenagens e sucata, não sabem apreciar a delicadeza de cada haste, pétala e célula do meu cultivar. Eles não merecem o gracioso fim que terão.\""},{"s":"05PZ014","n":"Corina, Mestra do Crime","f":"Quando os Vigias de Piltover arrombaram sua porta, Corina sorriu. Enquanto eles pisoteavam suas preciosas flores, elas lançavam nuvens de pólen tóxico. Tudo conforme planejado."},{"s":"uba831ea3fc","n":"Baronesa Velveteen Lenare","f":"Uma baronesa da química com muitos interesses de negócios em Piltover, Lenare lida principalmente com pesquisas em tecnologia golem. Seu corpo destruído estava morrendo, então ela fez com que transplantassem sua cabeça em um substituto movido a hexenergia. Ela visita Piltover regularmente para banhos de fluídos e transfusões de sangue e óleo.","u":1},{"s":"u1cce0283bf","n":"Barão Petrok Grime","u":1},{"s":"u16394f5bd2","n":"Barão Saita Takeda","f":"Takeda não faz segredo do seu desdém contra outros Barões da Química. Alegando ser de uma linhagem de uma casta exilada de guerreiros de uma terra distante, ele tem planos para muito além dos seus territórios e interesses.","u":1},{"s":"ub2216d17e5","n":"Barão Wencher Spindlow","f":"Outrora um tenente inferior, Spindlow assassinou seu chefe e tomou seu império. Armado com um par de bastões de choque, ele é um assassino sem piedade que vê o assassinato e o caos como ossos do ofício.","u":1},{"s":"u76452121ba","n":"Barões da Química","f":"Uma aliança tênue de conveniência existe entre os poderosos Barões da Química de Zaun, indivíduos poderosos que controlam, cada um, uma zona da cidade. São eles e seus brutamontes que impedem que Zaun seja tomada pelo caos.","u":1},{"s":"u449ee05545","n":"Traficante de brilho","u":1},{"s":"lrenataglasc","n":"Renata Glasc","f":"A Baronesa da Química.\nRenata Glasc ressurgiu das cinzas da casa onde vivera quando criança sem nada além do próprio nome e das pesquisas de seus pais em alquimia. Nas décadas que se seguiram, tornou-se a Baronesa da Química mais rica de Zaun, uma magnata extremamente influente que conquistou o poder atando os interesses de todos aos próprios. Trabalhe com ela e receba recompensas imensuráveis.","l":1},{"s":"lurgot","n":"Urgot","f":"O Encouraçado.\nNa época em que era um poderoso carrasco noxiano, Urgot foi traído pelo império para o qual havia tirado tantas vidas. Aprisionado em correntes de ferro, ele foi forçado a aprender o verdadeiro significado da força na Draga — uma mina carcerária nas profundezas de Zaun.","l":1}]},{"id":"firelights","name":"Fogos-Vivos e defensores do povo","desc":"O bando de Ekko, que protege o povo de Zaun e luta contra quem o explora, e outros que defendem os desvalidos da cidade: Janna, o vento que ouve as preces de Zaun, e Zeri, a faísca do Sumidouro.","items":[{"s":"04PZ001","n":"Ekko","f":"O lance não é quanto tempo você tem, é como você usa."},{"s":"06PZ042","n":"Imperfeccionista Maligna","f":"\"Bem, tudo o que tenho a dizer sobre hoje é que as coisas podiam ter sido melhores. É só. Eu do futuro... você sabe o que fizemos.\"\n– Diário de Kay"},{"s":"08PZ001T3","n":"Janna","f":"\"Nem mais um passo! Viole minha proteção e você se juntará ao vento uma vez que eu arrancar o fôlego dos seus pulmões!\""},{"s":"08PZ008","n":"Maryam, a Protetora do Templo","f":"Convencida de que foi salva pelo espírito do vento quando jovem, Maryam pregou as virtudes de Janna de sua terra natal, Shurima, até Zaun. Agora ela é matriarca do templo de Zaun e se dedica a transmitir a bondade de Janna aos jovens e oprimidos."},{"s":"04PZ012","n":"Perfeccionista Prática","f":"\"A Kay é incrível. Ela segue sempre aquela ideia que diz que 'a prática leva à perfeição', sabe? E pode apostar que ela pratica MESMO.\" – Shomi"},{"s":"04PZ004","n":"Skatista Sagaz","f":"\"Ahh, Shomi manda MUITO no hoverboard. Uma vez, elu deu um mortal cortante, caiu direto num giro de bombordo e saiu voando no mergulho triplo! Foi algo assim. A questão é que elu é o máximo, entendeu?\" – Perfeccionista Prática"},{"s":"lzeri","n":"Zeri","f":"A Faísca de Zaun.\nUma jovem obstinada e vivaz da classe operária de Zaun, Zeri canaliza magia elétrica para carregar a si mesma e a uma arma personalizada. O poder volátil espelha o que ela sente, as centelhas refletindo o estilo de vida ultrarrápido dela. Profundamente compassiva para com os outros, Zeri leva o amor da família e do lar dela consigo a todas as lutas.","l":1}]},{"id":"evolution","name":"A Evolução Gloriosa","desc":"Viktor e seus seguidores, que acreditam que a humanidade deve ser melhorada pela máquina.","items":[{"s":"01PZ013","n":"Experimentador Aprimorado","f":"Mesmo que seus sonhos tenham lhe custado as mãos, ele continuou acreditando. Nada ficaria em seu caminho."},{"s":"07PZ009","n":"Relologi Aprimorado","f":"\"Esse carinha só precisava de uns ajustes. Engrenagens novas aqui, um braço novo ali, e mais uma chance na vida. O tempo é um presente que todos deveriam ganhar mais.\" – Ekko"},{"s":"04PZ020","n":"Trocobô Defeituoso","f":"''Um novo Cassinobô? Não tinham fechado a fábrica há tempos atrás?''\n''Eu achava que sim. Alegaram algo sobre 'bombas giratórias' e 'incêndios não intencionais'.''\n''Ah, tá''\n''...Quer jogar?''\n''Com certeza''\n– Clientes zaunitas"},{"s":"03PZ003T1","n":"Viktor","f":"\"Ah, Piltover. Quando garoto, eu me inspirava em você, a 'Cidade do Progresso'. Mas, como homem, vejo suas bases corruptas construídas sobre o sofrimento de Zaun, o nosso lar. Hoje, começa uma nova era de inovações zaunitas... e vocês serão os primeiros a testemunhar nossa ascensão!\""},{"s":"lblitzcrank","n":"Blitzcrank","f":"O Grande Golem a Vapor.\nUm gigante de metal lustrado, fumaça e eletricidade constante, Blitzcrank caminha pelas ruas de Zaun trabalhando incansavelmente para melhorar a cidade subterrânea e fornecer ajuda àqueles que precisam.","l":1}]},{"id":"sump","name":"Trabalhadores do Sumidouro","desc":"Mecânicos, catadores e encanadores dos níveis mais baixos e tóxicos da cidade.","items":[{"s":"04PZ005T1","n":"Bando do Sumidouro","f":"\"A beleza individual deles é inegável, mas basta juntar alguns para que construam uma máquina insana que sai derrubando partes das Vielas.\" – Maquinista Zaunita"},{"s":"01PZ034","n":"Catador do Sumidouro","f":"As crianças zaunitas logo começaram a explorar os antigos túneis de mineração e os níveis mais profundos das Vielas. Encontraram um mundo surpreendente, e amigos incríveis."},{"s":"04PZ005","n":"Chireano do Sumidouro","f":"Os primeiros mineradores zaunitas que encontraram os chireanos os viram como criaturas tímidas e simplórias. Mas, com o passar dos anos, à medida que os chireanos foram se acostumando aos humanos, revelaram fortes laços sociais e habilidades aparentemente natas com a tecnologia."},{"s":"01PZ025","n":"Comerciante de Cogumelos","f":"\"É do bom mesmo?\"\n\"Claro! Todos de primeira qualidade! Foram eles mesmos que disseram!\"\n\"Ok, então me d... Peraí, quê?\"\n\"Ahan! Esse aqui vai casar!\"\n\"Quantos você já usou?\"\n\"Vai casar com uma ostra!\""},{"s":"01PZ038","n":"Draga do Sumidouro","f":"No Sumidouro, tudo é aproveitado."},{"s":"01PZ045","n":"Pedinte Zaunita","f":"\"Esses ratos do Sumidouro que deviam cuidar uns dos outros.\"\n\"Eles preferem sentir pena de si mesmos.\"\n\"É um absurdo. Ah... Você viu minha bolsa?\""},{"s":"08PZ024","n":"Peixeiro Picareta","f":"\"Hoje é pague um leve dois. Só hoje! Peixe fresco, pescado faz só um... hã, mês? Dois por um! Como assim você não quer o segundo? É de graça!\""},{"s":"06PZ025","n":"Solidão","f":"\"Ao voltar para casa do Entressol, vi novamente a pobre coitada aos prantos em uma viela. Ver como todos desviam dela de forma tão incisiva parte meu coração, assim como seu desânimo palpável. Então, amanhã, se nos cruzarmos novamente, tentarei ajudá-la como for possível.\"\n– Anotações do diário de Lady Sempesci"},{"s":"01PZ032","n":"Sucatonguejo","f":"Todos tentam capturá-lo. E o coitadinho só quer brincar nas poças!"},{"s":"01PZ017","n":"Vendedor de Barris Usados","f":"\"Foi o Ziel que te mandou? Eu já falei: o que é dele é dele. Não posso reembolsar algo que nunca vi antes, né? Mas recebi um lote de barris novos que até tô disposto a negociar...\""},{"s":"u5924a9b1f2","n":"Catador do Sumidouro","u":1},{"s":"uf6959a4020","n":"Mecânico","u":1},{"s":"u5e9b0e0d72","n":"Mercador horticultor","u":1},{"s":"ue5fe60fd96","n":"Pesquisador Quimtec","u":1},{"s":"u3663299519","n":"Quimio-encanadores","u":1},{"s":"u136055125c","n":"Residente do Calçadão","u":1},{"s":"ud9b79eeaef","n":"Respirador do Sumidouro com elmo de Cinza","u":1},{"s":"u95cff541da","n":"Viginauta","u":1},{"s":"ltwitch","n":"Twitch","f":"O Semeador da Peste.\nUm rato zaunita empesteado de nascença e um apreciador da imundície por paixão, Twitch não tem medo de sujar as patas. Mirando com uma balestra embebida em químicos no centro do coração dourado de Piltover, ele jurou mostrar àqueles na cidade de cima quão imundos eles realmente são.","l":1}]},{"id":"experiments","name":"Experimentos e monstros de Zaun","desc":"O que sai dos laboratórios e do lixo químico da cidade: Singed, o alquimista, Warwick, transformado em monstro por experimentos dolorosos, Zac, nascido de um vazamento tóxico no Sumidouro, e o Dr. Mundo, o louco de Zaun.","items":[{"s":"ldrmundo","n":"Dr. Mundo","f":"O Louco de Zaun.\nCompletamente maluco, tragicamente perigoso e terrivelmente roxo, Dr. Mundo é o que mantém muitos zaunitas dentro de casa nas noites mais escuras. A criatura que hoje se autoproclama médico já foi um paciente do manicômio mais infame de Zaun. Após \"curar\" toda a equipe do local, Dr.","l":1},{"s":"lsinged","n":"Singed","f":"O Químico Louco.\nSinged é um alquimista brilhante com moral duvidosa cujos experimentos embrulhariam o estômago até do criminoso mais brutal. Vendendo suas habilidades para quem paga mais, ele pouco se importa com o uso que fazem de suas misturas nocivas e vê o caos subsequente como mais um experimento. Sua criação mais infame é a \"cintila\", que deu aos Barões da Química o poder sobre Zaun.","l":1},{"s":"lwarwick","n":"Warwick","f":"A Ira Desimpedida de Zaun.\nWarwick é um monstro que assombra os becos cinzentos de Zaun. Transformado por mórbidos experimentos, seu corpo é interligado por um intricado sistema de câmaras e bombas, um maquinário que preenche suas veias com uma ira alquímica. Ele surge das sombras para caçar os criminosos que aterrorizam o submundo da cidade.","l":1}]},{"id":"outros","name":null,"desc":null,"items":[{"s":"07PZ019","n":"Lagartuagem Quimtec","f":"\"Eu preciso desenhar um MONTÃO de perna no cavalo, Senhor Lagarto, porque a gente tem que chegar BEEEM RAPIDINHO no castelo. Ah, não! Ele ficou meio... torto. E um tiquinho verde.\" – Ingvar, a Jovem"},{"s":"01PZ012","n":"Mordidinha Flamejante!","f":"\"PEGUEM ELES, MORDIDINHAS!\" – Jinx"},{"s":"u8172ba9c55","n":"Acordos hextec clandestinos","u":1},{"s":"uda780a29ab","n":"Carabina Hex","u":1},{"s":"u00bc97cb49","n":"Esofiltros reutilizáveis","u":1},{"s":"u2dba992e79","n":"Exofiltrador integral","u":1},{"s":"u2cdb1fab09","n":"Nebulizador de gás do Sumidouro","u":1},{"s":"uc9a5813fc9","n":"Quimtec","u":1}]}],"places":[{"s":"09PZ044","n":"A Prece da Luz de Velas","f":"Esse templo para Janna tem poucas paredes sólidas, o que condiz com os poderes da deusa. Mesmo assim, várias velas sempre estão acessas, mesmo quando uma tempestade violenta assola o restante de Zaun."},{"s":"06PZ040","n":"Bar do Beco","f":"Depois de secar os últimos copos, o taverneiro parou por um momento para examinar o lugar. Esse cantinho, esse lar longe de casa, já tinha testemunhado muitos estranhos se tornarem amigos, além de apresentar grafites e marcas de muitas noites agitadas. O taverneiro sorriu para si mesmo. Não era um lugar perfeito, mas era dele."},{"s":"03PZ020","n":"Fundição de Núcleos Hex","f":"\"Deixe que falem o que quiserem sobre meus métodos, eles não podem negar o progresso... A luz do meu conhecimento brilha como uma centelha em meio à escuridão da ignorância!\" – Viktor"},{"s":"07PZ013","n":"Monumento do Sumidouro","f":"Nas profundezas sob as ruas de Zaun, você é o que você come."},{"s":"08PZ009","n":"Templo Afundado","f":"Muito se perdeu no colapso desastroso que acabou separando Zaun de Piltover. Janna pode ter perdido seu templo para as ondas, mas salvou as pessoas que lá ofereciam sua adoração."},{"s":"uac54358ac3","n":"A Torre da Faculdade de Tecmaturgia ascende em Piltover","u":1},{"s":"u882da5d212","n":"Cidade de Ferro e Vidro","f":"A maioria das estruturas de Zaun são criadas de treliças de ferro, sejam forjadas nas muitas fundições ou moldadas de material descartado do topo. Apesar da funcionalidade brutal das porcas e parafusos das estruturas de Zaun, seus habitantes ainda conseguem criar maravilhas de tirar o fôlego que perfuram a poluição para atingir o céu.","u":1},{"s":"ud00fe95200","n":"Descensor privado hexdráulico","u":1},{"s":"u727cf7965f","n":"Descensor Público Hexdráulico","u":1},{"s":"uc5eee251b0","n":"Estação do Respiradouro, entrada do Bar Brilhante","u":1},{"s":"ua8da20882f","n":"Nível do Sumidouro","u":1},{"s":"u960052e71c","n":"Os Mercados da Fronteira prosperam onde Piltover e Zaun se encontram","u":1},{"s":"u670996a48a","n":"Uma vida vibrante enche as profundezas de Zaun","u":1},{"s":"w6f3fb92b32","n":"Zaun (arte conceitual 1)","w":1},{"s":"we858492a41","n":"Zaun (arte conceitual 2)","w":1},{"s":"w0f670597b5","n":"Zaun (arte conceitual 3)","w":1},{"s":"w58d7f7494c","n":"Zaun (arte conceitual 4)","w":1},{"s":"w30c910ef74","n":"Zaun (arte conceitual 5)","w":1},{"s":"w3ed128bf15","n":"Zaun (arte conceitual 6)","w":1},{"s":"w1d216e6ed3","n":"Zaun (arte conceitual 7)","w":1},{"s":"w3321b413c1","n":"Zaun (arte conceitual 8)","w":1}],"creatures":[{"s":"01PZ053","n":"Bando de Raxinins","f":"\"Isso mesmo! Um bando inteiro se esgueirando por aí! Eles PARECEM loucos, mas sei que estão planejando alguma coisa! Cogumelos. Queijo... sorvete. Do que eu tava falando?\"\n– Comerciante de Cogumelos"},{"s":"04PZ016","n":"Bumbuíno","f":"Jinx já teve um fornecedor mais convencional, mas eles brigaram. E por \"brigaram\", queremos dizer que o fornecedor caiu de uma janela. E por \"caiu de uma janela\", queremos dizer que ele foi defenestrado por uma explosão (causada pela Jinx, claro)."},{"s":"04PZ013","n":"Elnuk Voluntário","f":"\"BELEZA, AMIGUINHO, FICA AÍ PARADINHO ENQUANTO EU VIRO ESSE NEGÓCIO AQUIIIII E BUM! RÁ! ELNUKS PRA TODO LADO! A gente só vai precisar de mais feno. E espaço.\" – Perfeccionista Prática"},{"s":"03PZ002","n":"Miaudroide","f":"\"Passei anos na academia de Piltover lutando com garras e presas só pra ouvir que minhas tecnologias são 'perigosas demais' e que minha presença é 'fofinha demais'! Pois eu vou pra Miaun... ops, Zaun. Lá, sei que uma mente brilhante compartilha das minhas ambições...\""},{"s":"05PZ035","n":"Raxinim Fedorento","f":"O fedor de um raxinim no auge da temporada de cogumelos é inigualável. Imagine um esgoto a céu aberto cheio de peixes estragados e ovos podres, e já dá para ter uma boa ideia do que esperar."},{"s":"01PZ058","n":"Raxinim Grandona","f":"\"Vi uma grandona, aham! Ela é pesada como um cavalo e astuta como um krugue. Tem que ficar de olho naquela espertinha. Não é à toa que é a rainha deles!\"\n– Comerciante de Cogumelos"},{"s":"w38aad45e6a","n":"Criatura de Zaun (arte conceitual)","w":1}]},"runeterra":{"groups":[{"id":"camavor","name":"Camavor, o reino do Trono de Prata","desc":"Reino extinto a leste, fundado pelos gêmeos Camor e Avora e aliado aos dragões da Vovó Víbora. Ruiu quando o rei Viego deixou de governar para trazer Isolde de volta, e a Ruína levou seu povo junto: Viego, Kalista, Hecarim, o comandante Ledros e o jovem dragão Smolder, herdeiro do antigo juramento.","items":[{"s":"03SI010","n":"Cavaleiro do Crepúsculo","f":"A cada pôr do sol, a noite abre suas asas escuras e apaga os últimos resquícios de esperança."},{"s":"01SI024","n":"Cavaleiro Espectral","f":"Não estando mais presos aos corpos, o cavaleiro e sua montaria se tornaram um só, determinados a avançar em batalhas que não compreendiam mais."},{"s":"06SI042","n":"Cavaleiro Imortal","f":"Soldados que foram treinados para resistir a punições em vida eram apenas mais diligentes e capazes na morte — inabaláveis pelo frio, dor ou medo."},{"s":"01SI033","n":"Comandante Ledros","f":"A maioria dos espíritos se perde com o passar do tempo e o desgaste de suas memórias. Mas a angústia deixou Ledros ancorado ao passado. Há coisas que nem o tempo consegue dissipar."},{"s":"04SI028","n":"Dragão Camavorano","f":"Por vários séculos, a Névoa Negra recrutou e deformou criaturas por todo o mundo, transformando-as em versões assombrosas do que eram antes."},{"s":"08SI040","n":"Erastin, o Desonrado","f":"Os dragões de Camavor já foram magníficos e respeitados, mas nem mesmo eles estavam a salvo da corrupção da Ruína que tudo consome. Erastin não é exceção: sua majestade, há muito perdida, agora está distorcida na pitoresca aparência de imortal."},{"s":"01SI042","n":"Hecarim","f":"Isso não é um trovão. A Sombra da Guerra se aproxima."},{"s":"01SI042T1","n":"Hecarim","f":"Escute. Ele está cavalgando. O som dos cascos no chão. O ranger da armadura, gasta e enferrujada. Os gritos distantes dos soldados, ecos do passado. O silêncio ensurdecedor que vem em seguida..."},{"s":"01SI030T2","n":"Kalista","f":"\"Os enganados terão sua vingança!\""},{"s":"04SI054","n":"Soldada Camavorana","f":"Com uma lealdade inabalável, os soldados de Camavor marcharam com Viego na vida e na morte."},{"s":"04SI055","n":"Viego","f":"''Tem algo de muito intrigante na história do jovem rei. Algo em seu coração... uma fome que não pode ser saciada, um desejo impossível de ser realizado.'' – Dos registros de Nunyo Necrit de Camavor"},{"s":"04SI055T2","n":"Viego","f":"\"Refletindo agora, é claro, para mim, que nem a morte de Isolde ou a ânsia por grandeza causaram os delírios de Viego, foi só porque algo que ele desejava profundamente lhe fora negado.\" – Dos registros de Nunyo Necrit de Camavor"},{"s":"u3be94773a2","n":"Hecarim","u":1},{"s":"lsmolder","n":"Smolder","f":"O Filhote Flamejante.\nEscondido entre os penhascos escarpados da fronteira noxiana e sob o olhar atento da mãe, um jovem dragão está aprendendo o que significa ser herdeiro da linhagem dos dragões imperiais de Camavor. Brincalhão e ansioso por ser grande, Smolder busca qualquer desculpa para colocar em prática suas habilidades em desenvolvimento.","l":1},{"s":"w34a5130ebe","n":"Comandante Ledros (arte conceitual 1)","w":1},{"s":"wedd2853716","n":"Comandante Ledros (arte conceitual 2)","w":1},{"s":"w26fb549b2a","n":"Comandante Ledros (arte conceitual 3)","w":1},{"s":"wca83d04779","n":"Infantaria camavorana (arte conceitual 1)","w":1},{"s":"w2b53309a3b","n":"Infantaria camavorana (arte conceitual 2)","w":1},{"s":"w641f1772a6","n":"Infantaria camavorana (arte conceitual 3)","w":1},{"s":"w33dca44db3","n":"Necrit, o último conselheiro real (arte conceitual)","w":1},{"s":"wfc68fec664","n":"Necromantes de Camavor (arte conceitual)","w":1},{"s":"w5ae8a998f7","n":"Vennix, capitã camavorana (arte conceitual)","w":1},{"s":"wd7a30ac4bf","n":"Viego (arte conceitual)","w":1},{"s":"wfc3ff9832c","n":"Viego, o rei (arte conceitual 1)","w":1},{"s":"w3e472334f2","n":"Viego, o rei (arte conceitual 2)","w":1},{"s":"w264d0f0152","n":"Viego, o Rei Arruinado (arte conceitual)","w":1}]},{"id":"kathkan","name":"Kathkan e a Sétima Camada","desc":"Nação vizinha e antiga rival de Camavor, que prospera desde a queda dela. Sob a capital, uma ordem secreta de heróis, a Sétima Camada, vigia o demônio Ashlesh. Nilah, hoje sua portadora, foi a primeira kathkani a pisar em Valoran em mais de setecentos anos.","items":[{"s":"08BW008","n":"Nilah","f":"Ao norte, um novo desafiante aguarda Nilah e seu grupo de caçadores de monstros: um ser chamado Volibear, que ameaça destruir a mesma Freljord que um dia o adorou. Para Nilah, a chance de testar suas habilidades contra um monstro que outros chamam de ''deus'' é uma oportunidade única na vida. Sem falar nas monstruosidades menores que ela terá que adicionar à lista de conquistas pelo caminho."},{"s":"08BW008T1","n":"Nilah","f":"''Monstro! Sou Nilah da Sétima Camada! Meu nome será lembrado pela história, não o seu.''"},{"s":"wabf61e25b0","n":"Nilah (arte conceitual 1)","w":1},{"s":"wa8c886ba48","n":"Nilah (arte conceitual 2)","w":1},{"s":"w566a6c6a5e","n":"Nilah (arte conceitual 3)","w":1},{"s":"w6876cb28e2","n":"Nilah: retrato (arte conceitual)","w":1}]},{"id":"legends","name":"Lendas","desc":"Figuras que não pertencem a uma só terra: viajantes, guardiões cósmicos, demônios, feras míticas e pesadelos que aparecem por toda Runeterra, do Bardo e de Ryze a Kindred e Nocturne.","items":[{"s":"04SI004","n":"As Asas e a Onda","f":"Os Kinkou só falam de dois deuses: a primeira onda, que nutre a vida em suas águas quentes, e o último vento, que arranca a vida com suspiros gélidos e terminais."},{"s":"06RU001T4","n":"Bardo","f":"\"Toquem as cornetas para jovens e idosos\nToquem alto para todos os povos.\nReis se curvam para reverenciar\nO Protetor que segue sempre a viajar.\" – Canção Popular de Runeterra"},{"s":"08RU014","n":"Dragão Ancião","f":"\"Reza a lenda que este dragão é o mais velho de todos. O rei de todas as feras aladas. Se nós o domarmos... ora, Alatis, o que mais poderia se opor a nós? O mundo finalmente entenderia que homens e dragões são mais fortes juntos.\"\n– Volix, Aliado dos Dragões"},{"s":"08RU014T9","n":"Dragão Ancião","f":"Um calor sem igual jorrou da boca do Dragão Ancião. Alatis levantou voo. \"Mantenha-se firme\", gritou Volix. \"Mantenham a formação! O mundo nos conhecerá como os homens que domaram o rei das feras!\""},{"s":"06RU025T5","n":"Evelynn","f":"Enquanto Evelynn assombrava Runeterra, ela atraiu a atenção de demônios inferiores, todos esperando destruir a Criadora de Viúvas e deleitar-se com seu poder. Ela massacrou a maioria, é claro, mas alguns indivíduos talentosos chamaram sua atenção. Hoje, eles vivem ligados à ela e, quando dá na telha, Evelynn deixa eles brincarem um pouquinho."},{"s":"04SI009","n":"Fiandeiro de Almas","f":"\"Era uma vez um pobre infeliz que resolveu cortejar uma aranha, sem nem imaginar que poderia acabar na teia dela...\""},{"s":"04SI005T1","n":"Kindred","f":"A morte toma a forma de caçadores\nPessoa alguma sai ilesa\nUma caça com arco e flecha\nOutro persegue sua presa."},{"s":"04SI013","n":"Mãe Mascarada","f":"Dizem que a Mãe Mascarada criou os Kindred e todas as encarnações da morte. Mas, se não foi ela quem fez a própria máscara, quem terá lhe dado?"},{"s":"04SI007","n":"O Demônio Etéreo","f":"\"Agora que meu tempo neste lugar chega ao fim, ando pensando não em minha primeira morte, mas na segunda. Quem será a última alma a lembrar-se do meu nome? E, quando ela também se for... o que será de mim?\" – Benfeitor Ilustre"},{"s":"04SI014","n":"Presa","f":"\"Elas brilham na floresta escura, salpicando as árvores como estrelas no céu noturno, sem perceber que estão sendo seguidas.\" – Ovelha"},{"s":"04SI012","n":"Raposa Astral","f":"Algumas tribos targonenses contam histórias sobre a Raposa, uma divindade da morte representada por uma estrela solitária no céu. Reza a lenda que, a cada nova morte, essa divindade desce até a montanha e guia a nova alma até os céus, a fim de criar sua própria constelação sombria."},{"s":"06RU006T5","n":"Ryze","f":"Ryze voltou ao presente. Os cenários mentais que ele visitou responderam às suas perguntas e o encheram de propósito. As falhas do povo de Runeterra, por maiores que fossem, não deveriam condená-los ao esquecimento."},{"s":"04SI003","n":"Ícone Decadente","f":"Quem esquece o próprio deus da morte, senão aqueles amaldiçoados com a imortalidade? E o que pode ser mais terrível para um deus da morte do que ser esquecido?"},{"s":"lbrand","n":"Brand","f":"A Vingança Flamejante.\nA criatura conhecida como Brand já se chamou Kegan Rodhe, um aldeão da gélida Freljord, e é hoje uma lição das consequências que a tentação por poderes maiores pode trazer. Enquanto buscava uma das lendárias Runas Globais, Kegan traiu seus companheiros e a pegou para si e, em um instante, o homem já não existia mais.","l":1},{"s":"lfiddlesticks","n":"Fiddlesticks","f":"O Terror Ancestral.\nAlgo despertou em Runeterra. Algo ancestral. Algo terrível. O eterno terror conhecido como Fiddlesticks vaga pelos confins do mundo mortal, atraído por áreas dominadas por uma paranoia palpável, onde se alimenta de vítimas apavoradas.","l":1},{"s":"lnocturne","n":"Nocturne","f":"O Eterno Pesadelo.\nUma fusão demoníaca provinda dos pesadelos que assombram todas as mentes conscientes, a coisa conhecida como Nocturne se tornou uma força primordial de puro terror. De aspecto caótico e líquido, ele é uma sombra sem rosto com olhos frios e armada com lâminas enfurecidas.","l":1},{"s":"lshaco","n":"Shaco","f":"O Bufão Demoníaco.\nCriado anos atrás como um brinquedo para um príncipe solitário, Shaco, a marionete encantada, agora se deleita com assassinatos e desordem. Corrompido por magia das trevas e pela perda de seu dono querido, o boneco que já fora gentil agora encontra prazer somente na miséria das próprias almas que ele atormenta.","l":1}]},{"id":"rt-darkin","name":"Os Darkin","desc":"Antigos Ascendidos de Shurima presos em armas após a guerra contra Icathia. Possuem quem os empunha e espalham ruína por onde passam.","items":[{"s":"06RU026","n":"Aatrox","f":"Mesmo através dos continentes, Aatrox sentiu o despertar dela. Como o ódio ainda queimava. Ele já havia quebrado suas estátuas, e agora poderia travar uma guerra final contra a Covarde de Icathia e, ao destruí-la, acabar com essa existência lamentável."},{"s":"06RU026T3","n":"Aatrox","f":"A batalha se intensificou. Xolaani finalmente encontrara coragem para enfrentá-lo e, enquanto os dois antigos inimigos guerreavam, o próprio solo começou a definhar e se curvar sob sua fúria. Um exército de celestiais desceu sobre eles, desesperado para salvar sua terra agonizante — mas era tarde demais. Aatrox teria seu dia. Ele encontraria sua paz."},{"s":"06FR018T1","n":"Anaakca","f":"Com vigor renovado, a grande guerreira Anaakca marchou através de Freljord para as terras demacianas ao sul. Os postos avançados se prepararam o melhor que puderam para repelir seu ataque, mas nenhum mero mortal se colocaria entre a fúria de Anaakca e o covarde que a causou."},{"s":"06BC029T1","n":"Baalkux","f":"Baalkux sentiu os galhos da árvore agarrarem o cajado dentro do qual ele jazia adormecido. Ele atacou rapidamente. Sua vida irrompeu do cajado Darkin e percorreu os galhos e ramos ancestrais da árvore. Não havia coração para dominar. Não havia sangue para controlar. Foi então que Baalkux pôde finalmente voltar ao seu general e expiar suas antigas transgressões."},{"s":"06MT006T2","n":"Horazi","f":"Dentro dos confins da matéria celestial ardente que a aprisionou, Horazi foi agraciada com uma perspectiva mais completa sobre as coisas. Ela vislumbrou os segredos do cosmos e a infinita passagem de tempo que antecedia e sucedia sua própria existência. Ela aprendeu muito, mas, ainda assim, seu ódio pela covarde Xolaani se manteve intacto."},{"s":"06BW014T1","n":"Ibaaros","f":"Ibaaros, o Campeão das Dunas, se ergueu das águas. Ele sentia o sangue correr com o mesmo anseio familiar de anos atrás. O anseio de servir. Obedecer. Submeter-se."},{"s":"06DE011T1","n":"Joraal","f":"Um poderoso Ascendente estrategista conhecido como Égide da Eternidade, Joraal parecia inatingível até mesmo aos olhos dos deuses-guerreiros imortais de Shurima. Contudo, a guerra contra o Vazio se estendeu e, embora tivesse um corpo forte, a mente de Joraal entrou em colapso. E que colapso."},{"s":"06NX020T1","n":"Naganek de Zuretta","f":"Músculos antigos se flexionaram mais uma vez. A guerreira ouviu o chamado de seu general e entendeu onde precisavam dela: no sul, nas terras que ela conhecia como Icathia."},{"s":"06IO023T1","n":"Praa, o Andafendas","f":"O chamado de seu general o despertou. Quando recuperou seus sentidos, Praa se viu olhando para uma terra exuberante e desconhecida através de um véu poderoso. Lentamente, inexoravelmente, atravessou a barreira e pisou no solo de Runeterra mais uma vez. Por Aatrox. Pela vitória. Pela paz. Pela morte."},{"s":"06RU005T2","n":"Rhaast","f":"Rhaast soltou um uivo triunfante. Anos de espera, anseio, e agora... finalmente estava livre. Ele ergueu as lâminas de Xolaani e as levou à língua, saboreando o gosto de sangue fresco. Ele fechou os olhos em êxtase, e um sorriso apareceu em seu rosto pela primeira vez em milênios. A diversão havia começado."},{"s":"06SH004T1","n":"Servo Darkin","f":"Por muito tempo, esses poucos devotos cuidaram dos templos de sua senhora. Por muito tempo, eles varreram as areias e expulsaram possíveis profanadores. Por muito tempo, oraram por seu retorno. Sua bondade. Seu controle."},{"s":"06PZ008T2","n":"Styraatu","f":"Furiosa e impaciente, Styraatu irrompeu na usina de processamento. Sua fúria já era famosa antes mesmo de os tentáculos invadirem sua mente, mas agora... Agora, ela iria se vingar de todo mundo. Primeiro aqui, nesta terra de tecnologia, depois no sul, onde lutaria ao lado de seu general mais uma vez."},{"s":"06SI007T1","n":"Taarosh","f":"A lenda diz que Taarosh estava a meros instantes de destruir Xolaani quando os Darkin foram atacados pelos targonenses. Com o passar dos séculos, ele sentiu que a terra ao seu redor se corrompeu, sendo manchada por podridão e o cheiro perpétuo da morte. Ele sonhava em mergulhar Xolaani nesse mesmo sofrimento depois de reivindicar sua liberdade."},{"s":"06RU009","n":"Varus","f":"E se, com o tempo, influenciado pelas vozes mortais em seu interior, o homem que virou Darkin se lembrasse de si mesmo? E se, em vez de dominar essas vozes, ele começasse a acreditar nelas?"},{"s":"06RU009T6","n":"Varus","f":"Varus foi fortalecido, amparado e lembrado de quem era e do que ainda iria se tornar. Ele abraçou a soma de suas partes em vez de resistir a elas — e, quando elas agiam, faziam-no como uma só."},{"s":"06SH004T2","n":"Xolaani","f":"Os Ascendentes de Shurima estavam condenados desde o momento em que pegaram suas armas para enfrentar o Vazio. Esse era um inimigo que nunca poderia ser derrotado — e, embora os deuses-guerreiros tivessem imortalidade garantida, suas mentes não tinham essa mesma resistência. A loucura os consumiu."},{"s":"06MT035T1","n":"Xolaani, a Ruína dos Aspectos","f":"Mais. Mais. Mesmo a grande heroína das lendas, Mihira, não conseguiu resistir à força esmagadora de Xolaani. A terra parecia pulsar agora, tal era o poder hemomântico que crescia dentro de Xolaani. Ela parou um momento para observar o campo de batalha e chorou com a alma inundada de alegria. Em breve, este mundo estaria unido em paz. Em amor. Em silêncio."},{"s":"06MT035","n":"Xolaani, a Tecelã de Sangue","f":"Xolaani observou enquanto Anaakco caía de joelhos, subjugado pela própria inimiga que desejava tão desesperadamente destruir. Aos poucos, os batimentos do seu coração ressoaram em uníssono com os outros. Outro coração para controlar. Outro corpo para comandar."},{"s":"lnaafiri","n":"Naafiri","f":"Fera das Cem Mordidas.\nPelas areias de Shurima, um coro de uivos ressoa. É o chamado dos cães das dunas, predadores vorazes que formam matilhas e disputam o direito de caçar nessas terras áridas. Entre eles, uma matilha se destaca, pois é movida não apenas por instintos caninos, mas pelo poder ancestral dos Darkin.","l":1},{"s":"lzaahen","n":"Zaahen","f":"O Indissociável.\nUm deus caído com poder divino e profano, Zaahen caça os outros Darkin em constante desafio à corrupção que ameaça consumi-lo. Outrora selado por livre vontade em sua glaive para evitar o jugo da loucura, ele agora se vê liberto, de coração nobre e propósito brutal. Zaahen trava uma luta eterna em seu âmago, mas, enquanto a suportar, ele há de superar todos os que buscam arruinar Runeterra.","l":1}]},{"id":"rt-shards","name":"Runas Globais","desc":"Fragmentos dos poderes que criaram o mundo. Quem os encontra raramente sai ileso.","items":[{"s":"06RU006T1","n":"Fragmento de Loucura","f":"Os deuses-guerreiros de Shurima eram considerados inigualáveis. Perfeitos. Mas anos de guerra contra um inimigo implacável acabaram enfraquecendo seus espíritos, e depois os destruíram completamente. Xolaani e Aatrox se voltaram um contra o outro em uma disputa que logo ameaçou a própria existência de Runeterra."},{"s":"06RU006T2","n":"Fragmento de Traição","f":"De todos os erros que Ryze testemunhou em seu tempo em Runeterra, este foi o mais significativo. Como seu próprio mestre, que ensinou a Ryze as virtudes do controle e da paciência, pôde se entregar tão completamente às Runas Globais? Como?!"},{"s":"06RU006T4","n":"Fragmento de Violência","f":"Ryze observava enquanto o cenário mental diante dele se construía. Viu os icathianos guerrearem com Shurima em uma tentativa desesperada de liberdade. Ryze sabia muito bem o que viria a seguir, mas assistiu mesmo assim. Tentáculos roxos e cruéis irromperam, consumindo o campo de batalha. Icathia alcançou a liberdade, mas, na Escuridão, liberou o Vazio sobre Runeterra."}]}],"places":[{"s":"w4d1f23ad91","n":"Mapa de Camavor","w":1},{"s":"wee5ca60858","n":"Mapa do continente camavorano","w":1},{"s":"w63c1db2648","n":"O campo de Camavor","w":1},{"s":"wcfb9b16dd1","n":"Salão do trono de Camavor (arte conceitual)","w":1}],"creatures":[]},"bilgewater":{"groups":[{"id":"buhru","name":"Os Buhru (fé de Nagacáburos)","desc":"O povo das Ilhas das Serpentes, devoto da Mãe Serpente. Illaoi é sua sacerdotisa mais forte.","items":[{"s":"06BW035","n":"A Voz do Mar","f":"Invocar Nagacáburos não exige um ritual complicado. Ela atende ao chamado daqueles cujas almas são páreo para o oceano e a oscilação de suas marés. É uma batalha que poucos conseguem travar."},{"s":"06BW026","n":"Cultista Buhru","f":"A origem do poder era irrelevante; a deusa dela não se importaria com isso. O que interessava era a glória que ela conquistaria aniquilando monstros."},{"s":"06BW006","n":"Illaoi","f":"O \"Olho de Nagacáburos\" é apenas um nome, mas Illaoi o encara como um desafio de vida, como se sua deusa fosse uma companhia constante e que se chateia com facilidade."},{"s":"06BW006T1","n":"Illaoi","f":"Uma lição de vida: se um dia você tiver a chance de pular das cordas de um bom navio e cair como uma punição bombástica em cima dos seus inimigos, aproveite. É incrivelmente revigorante."},{"s":"06BW009","n":"Líder Buhru","f":"\"Lembre-se da sabedoria do oceano! Se você não se mover, será movido! Siga minha voz se estiver perdido, pois seu inimigo sabe exatamente onde está.\""},{"s":"06BW011","n":"Nagacáburos","f":"\"A Mãe Serpente. A Grande Cráquem. A Mulher Barbada. Nagacáburos não se importa com nomes, e menos ainda com os mortos inquietos.\" – Illaoi"},{"s":"02BW062","n":"Navegadora Nativa","f":"\"Eleve a luz da Mãe Serpente\nDas ondas até a imensidão.\nO céu observa com olhos acinzentados\nUm suave reflexo de sua contemplação.\nEla sorri, está em paz...\"\n– Oração para Nagacáburos"},{"s":"06BW006T3","n":"Tentáculo","f":"Nada simboliza melhor o que vive lá embaixo. Se vai machucar você ou não, é irrelevante para o medo, o pânico que se instala no seu peito. A natureza traz o espetáculo, mas a sua mente traz a intenção."},{"s":"06BW016","n":"Vigia Buhru","f":"A simplicidade é o melhor da vida. Gotas de água salgada no rosto, o canto dos pássaros... e um inimigo simples no horizonte."},{"s":"06BW007","n":"Ídolo Vigilante","f":"Quando os terrores debandam das Ilhas das Sombras, o ídolo se ilumina como um farol reluzente no horizonte."},{"s":"u8c1ea7bd1b","n":"As Ilhas das Serpentes","f":"Apesar de grande parte de Valoran conhecer o arquipélago como as Ilhas da Chama Azul, para o povo nativo de Buhru elas sempre foram as Ilhas das Serpentes. A cultura antiga de Buhru é muito respeitada, reverenciada e, às vezes, imitada na vida diária de Águas de Sentina, incluindo a medicina tradicional e as técnicas de caça a monstros.","u":1},{"s":"u6100aa8039","n":"Nagacáburos","f":"Uma parte essencial à cultura Buhru é Nagacáburos: deusa da vida, do crescimento e do movimento perpétuo. Também conhecida como a Mãe Serpente, o Grande Cráquem ou a Mulher Barbada, ela é comumente desenhada como uma cabeça enorme e monstruosa com muitos tentáculos espirais.","u":1}]},{"id":"pirates","name":"Piratas e Tripulações","desc":"As tripulações que fizeram a fama de Águas de Sentina. Gangplank foi o rei de todas elas.","items":[{"s":"02BW004","n":"Ajudante do Apavorador","f":"\"Podemos atacar ao amanhecer, quando eles estão alertas e com os canhões prontos para responder. Ou atacamos ao escurecer, quando eles nunca vão esquecer...\""},{"s":"02BW032T1","n":"Barril de Pólvora","f":"\"Onde há um barril, há um caminho.\" – Ditado de Águas de Sentina"},{"s":"02BW060","n":"Corsária Atiradora","f":"\"Ser baixa é uma baita vantagem de combate. Ninguém tem o cuidado de olhar pra baixo.\""},{"s":"07BW021","n":"Corsária Ousada","f":"\"Eu ficaria longe se fosse você. Ela tem a péssima mania de transferir os próprios problemas para os outros.\" – Samira"},{"s":"02BW013","n":"Degoladora à Espreita","f":"\"Aí o babaca disse que meus quadris 'se moviam como as ondas do mar'. Mandei calar a boca ou eu arrancava a língua dele fora.\""},{"s":"02BW034","n":"Estátua de Macaco","f":"\"Aqui está uma... lembrancinha. A tripulação roubou de um velho rival meu. Parece que aquele papo de 'poderes misteriosos e ancestrais' não era totalmente mentira...\" – Miss Fortune"},{"s":"02BW032T3","n":"Gangplank","f":"\"Só de olhar nos olhos dele, você percebe que só há a mais pura raiva. Um dia, o chefe fará com Águas de Sentina o mesmo que fizeram com ele.\" – Suboficial"},{"s":"02BW034T1","n":"Miquinho Explosivo","f":"\"Que bichinhos mais travessos, hein? Eles ajudam um bocado, mas dizem que o temperamento é muito explosivo...\"\n– Ajudante da Sereia"},{"s":"02BW002","n":"O Apavorador","f":"\"Uhhh, podem se despedir e baixar as velas,\npois O Apavorador se aproxima.\nRumo a mares profundos, onde há pilhas de moribundos,\npois O Apavorador se aproxima!\" – \"O Apavorador se aproxima\""},{"s":"02BW028","n":"Rex Correnteza","f":"\"Deixe os marinheiros, deixe os destroços.\nA batalha já acabou.\nA fumaça clareou a água, o capitão encontrou Rex,\nE o navio se despedaçou.\" – \"Voltando Pra Casa, Sally\""},{"s":"02BW008","n":"Suboficial","f":"Ele descobriu que poucas coisas motivavam tanto um marinheiro quanto um estopim aceso."},{"s":"u211419ec2f","n":"Canhões","u":1},{"s":"u6401b179dd","n":"Capitães e Tripulação","f":"Águas de Sentina é o lar de caçadores de moeda, gangues de docas e contrabandistas vindos de todos os cantos do mundo. Para aqueles que fogem da justiça, de dívidas ou de perseguição, ela é uma cidade de novos começos; ninguém nas ruas tortuosas de Águas de Sentina se importa com o seu passa","u":1}]},{"id":"bounty","name":"Caçadores de recompensa e pistoleiros","desc":"Gente que vive de cartazes de \"procurado\". Miss Fortune é a mais temida.","items":[{"s":"02BW015","n":"A Sereia","f":"A Sereia é inconfundível. As velas peroladas e a madeira polida a deixam tão imponente quanto a capitã que conduz o leme."},{"s":"02BW005","n":"Assassina de Aluguel","f":"\"É você na foto? Credo, é ainda mais feio do que eu imaginava. Espero que sua cabeça valha a pena.\""},{"s":"02BW022T2","n":"Miss Fortune","f":"\"Quase ninguém vê o esplendor dessas armas de perto. Sorte a sua.\""},{"s":"02BW035","n":"Xerife Lariette Rose","f":"Águas de Sentina pode não ter leis, mas algumas almas destemidas fazem valer sua própria noção de justiça."},{"s":"u078b01caa1","n":"Armas","u":1},{"s":"ub151ef1d9c","n":"Bacamarte da Miss Fortune","u":1},{"s":"uedf3081fdb","n":"Quadro de Recompensas","f":"O mais próximo que se pode conseguir de leis e um governo em Águas de Sentina é o quadro de recompensas. Nele estão escritos os nomes dos criminosos mais procurados de Águas de Sentina, ranqueados com base em quanto se paga por suas cabeças. Dizem que o Rei dos Ladrões, Gangplank, adicionava regularmente uma serpente de prata ao próprio nome, como um desafio aberto à toda cidade.","u":1}]},{"id":"hunters","name":"Caçadores de monstros e açougueiros","desc":"Os que caçam monstros marinhos e retalham as presas nas Docas da Matança. Pyke era um deles. Também aqui está o grupo de Nilah, que veio de Kathkan, uma terra desconhecida, para desafiar criaturas lendárias.","items":[{"s":"02BW055","n":"Capataz Farpada","f":"Quando ela dispara, os Anzóis devem ser rápidos. O sangue na água atrai muitas companhias... e nenhuma delas é bem-vinda."},{"s":"02BW058","n":"Carniceiro Farpado","f":"Para entrar nos Anzóis Farpados, é preciso sangrar. Os marinheiros devem provar que conhecem navios, combate e tábuas de corte. Os candidatos mais repugnantes passam pelos três de uma vez só."},{"s":"02BW047","n":"Catadores de Refugo","f":"Só alguém muito especial para estragar um equipamento tão bem construído. Mas se há uma coisa em que eles são bons, é nisso. Só nisso."},{"s":"02BW021","n":"Caçador de Escamâminas","f":"\"Ouvi dizer que ele nada quilômetros atrás de seu alvo e, quando encontra, nunca erra. Não sei se é um homem ou um peixe, mas sei que conhece essas águas melhor do que ninguém.\" – Carniceiro Farpado"},{"s":"02BW039","n":"Caçadores de Peixe-Jaula","f":"O sonho da fortuna leva inúmeras tripulações ao alto-mar. Essas pobres almas logo descobrem como as águas podem ser impiedosas e por que tão poucos retornam."},{"s":"08BW038","n":"Dançarina dos Chakrans","f":"Ela se move em uma dança de água e lâminas, extraindo aço do turbilhão de espuma e dos respingos. Ela não precisa ver para sentir o fluxo de suas armas; elas são movidas pelas águas, e às águas sempre devem retornar."},{"s":"09BW028","n":"Devoto Dedicado","f":"''Como assim eu preciso de mais treinamento? Eu já treinei MUITO! Olha só!''"},{"s":"08BW026","n":"Devoto do Desafio","f":"''Ah, você tá mesmo se esforçando? Sinto que preciso me segurar... Odeio isso!''"},{"s":"02BW027","n":"Frota Caçadora","f":"O ouro que brilha sob as ondas não vem de moedas nem lingotes, mas dos chifres reluzentes do astuto adversário do Capitão da Frota Carniceira."},{"s":"08BW025","n":"Mestre Vigia","f":"''Ei, cara, que alvoroço é esse? Relaxa! Não há nada na água que não possamos enfrentar!'' – Devoto do Desafio"},{"s":"08BW015","n":"O Dançarino das Marés","f":"''Ouvi dizer que aquele navio com formato estranho é o mais rápido que Águas de Sentina já viu. Bem ágil, também. A capitã é bem peculiar, mas parece que ela sabe o que está fazendo. Talvez a gente aprenda uma coisa ou outra.''\n– Barman de Águas de Sentina"},{"s":"04BW005","n":"Pyke","f":"\"... minhas visões voltaram. Vejo o olhar desesperado dele vidrado em mim enquanto o peixe-jaula o dilacera vivo. Tentamos puxar, mas o barco era muito pequeno e a criatura era grande demais. Não tive escolha. Tive que cortar a corda dele. Não teve jeito.\"\n– Carta ensanguentada"},{"s":"04BW005T2","n":"Pyke","f":"Primeiro, foram seus antigos companheiros de tripulação. Depois, outros capitães, trapaceiros, apostadores e bêbados. Aos poucos, a sede de vingança de Pyke foi se transformando em simples desejo de matar. Agora, em vez de botar na lista só quem o fez mal no passado, Pyke deixa para trás uma pilha de corpos que mostra claramente no que ele se transformou."},{"s":"08BW009","n":"Timoneiro Experiente","f":"''A mente é um rio. Ao longo do tempo, a dedicação de seu fluxo esculpe a face das montanhas e, pouco a pouco, pode crescer cada vez mais e tocar novas margens.''"},{"s":"08BW023","n":"Vikrash, o Exuberante","f":"''Vejam, meus amigos, como todo o mundo se move conosco! As ondas dançam sob o casco, o vento sopra pelas velas, e os pássaros viajam pela brisa. Alegrem-se e juntem-se a mim nesse grande chamado!''"},{"s":"u19ff66b1d9","n":"Arpoeiros","f":"Um das funções mais importantes em uma tripulação de caça é a do arpoeiro, que fisga e mata as criaturas, e geralmente as tripulações são formadas em torno de um veterano que possa ensinar aos outros uma coisa ou outra durante o percurso. Muitos arpoeiros são exímios atiradores ou mergulhadores particularmente corajosos... mas poucos sobrevivem por tempo suficiente para que sua reputação se espalhe.","u":1},{"s":"u50b544108c","n":"Baías de Entalhadura","u":1},{"s":"u4447e9b545","n":"Galpões de Matança","u":1},{"s":"u9015b7dc5e","n":"Invocadores de Serpentes","f":"As margens de Águas de Sentina são protegidas por trompas que, quando tocadas, desorientam as ondas através da água para esconder a localização de Águas de Sentina de monstros marinhos.","u":1},{"s":"u9320b9d015","n":"Mestra do Arpão","u":1},{"s":"u75bc5d6221","n":"Ossos do ofício","f":"Os melhores caçadores de monstros sabem que as técnicas antigas são, em geral, as melhores. Seguindo as tradições das Ilhas das Serpentes, essas astuciosas armadilhas e ganchos cruéis são produzidos especialmente para atrair e matar criaturas específicas, e tais ferramentas são passadas de geração em geração.","u":1}]},{"id":"marine","name":"Vida Marinha","desc":"Quem vive do mar e dentro dele: marinheiros, aventureiros das ondas e criaturas simpáticas (ou nem tanto), como Fizz, o trapaceiro das marés, e Nautilus, o Titã das Profundezas.","items":[{"s":"05BW011","n":"Almirante Shelly","f":"\"PLESTE BEM ATENÇÃO, SOLDADO. FIQUE SABENDO QUE EU TENHO MAIS DE 300 MORTES NA MINHA CONTA E SOU A MAIOR ALMILANTE DE TODA A MALINHA, ENTÃO, QUANDO EU MANDÁ NADÁR, CÊ NADA, TÁ BÃO? TÁ BÃO ENTÃO, OBLIGADA!\""},{"s":"02BW040","n":"Artilharia Cascuda","f":"\"TALVÊS MINHA MAIÓ FORSSA É MEU COMANDU SOBE AS PEÇOA E AXO QUE O GEITO QUE EU ISCREVO\"\n– Bilhete escrito na areia"},{"s":"02BW046T3","n":"Fizz","f":"... enquanto outros juram que ele é só uma criança travessa que garante uma jornada segura de volta ao lar."},{"s":"02BW057","n":"Mergulhador Evasivo","f":"\"Juro que vi algo muito estranho nos recifes... O que colocaram nas laranjas? É só isso que eu quero saber..\"\n– Suboficial"},{"s":"02BW053","n":"Nautilus","f":"\"Foi uma âncora que destruiu tudo. Até puxou o Finn lá pra baixo. Só sobraram alguns de nós, mas a noite vem chegando... e o frio também. Desculpa, mãe. Você tinha razão. O Titã vive.\" – Bilhete encontrado"},{"s":"02BW053T1","n":"Nautilus","f":"Todos pagam o dízimo, de um jeito ou de outro."},{"s":"08BW028","n":"Polvaventureiro","f":"\"Exemplar peculiar. Bastante azul. Olhos bem grandes. Grandes demais, até. Levarei para estudá-lo melhor.''\n– Registros de expedição da Divisão de Grandes Distâncias da Guilda dos Exploradores, alocação: Piltover"},{"s":"02BW038","n":"Zap Nadajato","f":"Zap já completou o circuito da Via Azure em pouco menos de três minutos. Ela teve até que desviar do casco do Jilldaw perto da chegada! As correntes naquele dia estavam DEMAIS!"}]},{"id":"underworld","name":"O Submundo Sentinense","desc":"Apostas, contrabando e lutas clandestinas. Jack, o Rei do Crime, comanda o submundo de Águas de Sentina e as arenas onde se aposta em campeões do fosso. Twisted Fate faz fortuna e inimigos em cada mesa, e Tahm Kench cobra o preço de tudo.","items":[{"s":"07BW004","n":"A Corte do Rei","f":"A embarcação particular do Jack o levou pelas águas de Runeterra com seu bando, de Águas de Sentina a Ionia. Como ela viaja debaixo d'água sem afundar é um mistério, mas dizem que é sob a superfície que mora o verdadeiro perigo..."},{"s":"07BW013","n":"Anjinho","f":"\"Isso é o melhor que você sabe fazer? Que fofo. Minha vez.\""},{"s":"02BW007","n":"Apostadora Audaciosa","f":"\"Na maioria das vezes, não tem mistério. As mesas ficam cheias de idiotas que não prestam atenção no jogo e só querem saber de farra. Problema deles. Quanto mais moedas no meu bolso, melhor.\""},{"s":"07BW018","n":"Babs Delirante","f":"\"Jack, querido, espia aqui! Tem uma coisa que te interessa, né?\""},{"s":"07BW040T2","n":"Bull","f":"O corpo dele é uma tapeçaria de cicatrizes e tatuagens que recontam sua lenda brutal. Hoje, Bull atua como mentor e parceiro de treino de Jack. Está guardando o que lhe resta do espírito de batalha para um oponente digno de um último confronto."},{"s":"02BW016","n":"Cassinobô","f":"Um dos protótipos disparou três bombas e explodiu. Os modelos mais recentes não contam com esse \"recurso\"."},{"s":"08BW037","n":"Crupiê Honesto","f":"\"Viu, que tal apostar mais alto, hein? Sabe como é, quem não arrisca não petisca. Essa mesa promete, pode confiar. E a casa é bem generosa neste belíssimo estabelecimento. Juro pela língua da mamãe.\""},{"s":"07BW002","n":"Jack","f":"\"Precisa ter coragem sobrando ou inteligência faltando pra me desafiar, mas, seja como for, o resultado é sempre o mesmo. Meu conselho? Só se preocupe em sair com vida.\""},{"s":"07BW002T2","n":"Jack","f":"\"Jack não é de todo mau. Na verdade, os poucos que conquistaram seu respeito até dizem que ele é encantador... quase honesto. Mas quando ele sente o cheiro de sangue, bem... Acho que não há ninguém tão perigoso.\" – Bull"},{"s":"03BW006","n":"Jack, o Vencedor","f":"Anos no ringue de boxe ensinaram muitas lições valiosas a Jack. Ele aprendeu que, se o oponente pode sangrar, ele pode ter medo. Aprendeu o poder de um olhar silencioso. E o poder da violência sem limites."},{"s":"07BW040T1","n":"Mako","f":"\"Você é peixe pequeno. É melhor continuar nadando.\""},{"s":"02BW009","n":"Malandro da Sinuca","f":"\"Não faz sentido. Eu tava com tudo, mas aquela última... não teve jeito. Acho que hoje não é meu dia...\" – Apostadora Audaciosa"},{"s":"02BW033","n":"Mercador Clandestino","f":"\"Tudo o que você quiser, eu tenho! Até um 'estoque especial'... Mas se perguntarem, você não comprou de mim!\""},{"s":"02BW006","n":"Mágico Mistificador","f":"\"Marvolio? Cadê... cadê minhas mãos?\"\n\"Agora elas vão aparecer! Tchã-rã! Ahem... Tchã... rã...!\"\n\"... CADÊ MINHAS MÃOS?!\"\n\"HORA DE PARTIR. MUITO OBRIGADO A TODOS!\""},{"s":"07BW040","n":"Nukkle","f":"\"Uma mordidinha aqui, um cortezinho acolá, tudo na tranquilidade. Um pouco de sangue na água nunca fez mal a ninguém. Bem, pelo menos não a mim.\" – Nukkle"},{"s":"07BW014","n":"Pablo Cinco-Socos","f":"\"É assim que se faz, Jack! Continua a espalhar esse seu charme de Águas de Sentina que eu te deixo pronto pra qualquer luta. Ahh, isso me lembra os velhos tempos, quando eu era tão lindo que me chamavam de Pablo-Pintura... Como não? Ah, mas chamavam! Aquela pancada na cabeça deve ter bagunçado sua memória.\" – Pablo Cinco-Socos"},{"s":"03BW007","n":"Polvo Boxeador","f":"\"Claro, o Pablo anda passando por uma fase difícil... e ele já levou umas porradas por aí, sim... mas sabe de uma coisa, camarada? Ele é o único por aqui que dá oito socos de uma vez.\" – Sabichão"},{"s":"07BW001","n":"Produtor Pérfido","f":"\"Pro trabalho sujo, procure o Jack. Quer saber onde, quando, quem e quanto? É só falar comigo.\""},{"s":"03BW008","n":"Rãdivinha","f":"\"A velha Babs já passou por muita coisa. Já matou uns habitantes locais quando era jovem, mas acho que isso a deixa mais autêntica.\" – Lagarto Boêmio"},{"s":"03BW003","n":"Sabichão","f":"Chegar ao poder costuma ser uma empreitada violenta... mas geralmente não é essa bagunça."},{"s":"03BW015","n":"Senhor Resmunguejo","f":"\"DÁ PRA COMEÇAR A LUTA LOGO?! VOU MOSTRAR PRA ESSE COROA FOLGADO POR QUE EU TENHO TANTOS APELIDOS. 'PABLO OITO SOCOS', 'O CRÁQUEM CRAQUE', 'O TERROR DOS TENTÁCULOS'! TU PODE SER VELHO, MAS QUANDO EU ARREBENTAR TUA FUÇA, VAI CHORAR FEITO CRIANCINHA!\" – Polvo Boxeador"},{"s":"03BW004T3","n":"Tahm Kench","f":"\"Você fez um trato, colega, e embora vá colher seus frutos, lembre-se... um dia vou querer a minha parte também.\""},{"s":"07BW003","n":"Trombadinha","f":"\"Ei, volta aqui, traste! Isso é o dinheiro da minha batata!\" – Anjinho"},{"s":"02BW026T3","n":"Twisted Fate","f":"\"...não seria uma aposta se ninguém perdesse.\""},{"s":"02BW011","n":"Yordle Vigarista","f":"\"Amigos adoram se ajudar, sabia? E você? Gosto da luz no seu olhar e do brilho no seu alfanje! De fato, é um belo alfanje...\""},{"s":"lgraves","n":"Graves","f":"O Foragido.\nMalcolm Graves é um mercenário, jogador e ladrão de renome. Um homem procurado em todas as cidades e impérios pelos quais já passou. Apesar do pavio curto, ele segue um estrito código de honra entre criminosos normalmente imposto pelos canos da sua escopeta, Destino. Nos últimos anos, ele retomou uma parceria problemática com Twisted Fate.","l":1}]},{"id":"outros","name":null,"desc":null,"items":[{"s":"02BW017","n":"Caixeiro Cítrico","f":"\"Todo marujo se 'achar' durão! Soco pra lá, soco pra cá... Legal, legal mesmo. Mas ainda 'precisar' de laranja! Deixa pele bonita, dente forte e eu feliz. Então, ou come, ou anda na prancha. Simples.\""},{"s":"07BW025","n":"Inferna","f":"\"Ser piromaníaco no mar traz algumas vantagens. A água não deixa as chamas fugirem do controle e nunca pede uma parte dos lucros.\""},{"s":"06BW029","n":"Náufrago Piltovense","f":"Pesh conheceu Jax em uma briga nas docas, e a fuga oportuna dos dois foi mais conveniente do que qualquer parceria. Desde então, Pesh leva Jax para lá e para cá, já que as coisas parecem simplesmente quebrar perto dele. E, se tem uma coisa que Pesh gosta mais do que uma boa briga, são coisas precisando de conserto."},{"s":"07BW027","n":"Pai Fúria","f":"As origens do Pai Fúria são tão turvas quanto uma nuvem carregada — mesmo quem pergunta nunca escuta uma resposta direta. Pelo menos, não uma que dê pra ouvir em meio ao estrondo da destruição que ele causa."},{"s":"02BW050","n":"Solista Serena","f":"\"Uma jornada musical nos aguarda! Venha curtir os ritmos de Runeterra! O ingresso custa só algumas moedas, e gorjetas são muito bem-vindas...\" – Promotor de Eventos"},{"s":"06BW018","n":"Steem","f":"O primeiro encontro de Evelynn com Steem superou todas as expectativas que ela poderia ter. Evelynn se lembra de seu sorriso em meio ao sofrimento, e como ele era tão apaixonado quanto ela pela violência. Depois de finalmente derrotar Steem, ela preferiu não destruir o demônio, mas uni-lo a ela para sempre. Ela pensou que, juntos, talvez eles possam compartilhar com o mundo o amor mútuo pela carnificina."},{"s":"u943c2a8208","n":"O Barqueiro","f":"Uma figura comum em cada cemitério flutuante, estes marinheiros lúgubres levam os mortos para seu local de descanso final.","u":1},{"s":"u2a309c7349","n":"Um Túmulo na Água","f":"Em Águas de Sentina, os mortos não são enterrados - eles são entregues de volta ao oceano. Os cemitérios do porto consistem de inúmeras boias, abaixo das quais estão afundados os corpos dos mortos. Os mais ricos são sepultados dentro de caixões caros e submersos abaixo de lápides flutuantes luxuosas, enquanto os pobres são comumente amarrados em massa a velhas âncoras sob barris cheios d’água.","u":1}]}],"places":[{"s":"09BW022","n":"A Campeã da Arena","f":"Anjinho passou anos tentando vencer a maior luta de todas. Toda noite, ela sonha com uma pilha de moedas grande o suficiente para encher a Baía de Águas de Sentina. Dinheiro da plantação de batatas, claro."},{"s":"04BW009","n":"Baía do Estripador","f":"Não demorou muito para que as enseadas mais traiçoeiras de Águas de Sentina se tornassem lar de inúmeros monstros marinhos. Eles estão sempre ali, esperando chegar a próxima leva de tripulantes imprudentes que ignoraram os avisos do chefe do porto."},{"s":"07BW035","n":"O Covil do Vigarista","f":"\"Eu acho que você deve conhecer sua mão e mantê-la em segredo... ou se preparar para perder tudo.\" – Twisted Fate"},{"s":"ubf4033436f","n":"Alta e seca","f":"Há uma verdade comumente aceita em Águas de Sentina: quanto mais alto você subir, mais fácil de se afogar. Os que têm os bolsos cheios frequentam as tavernas da melhor parte da cidade, desfrutando de boa bebida e conversas animadas; ainda assim, em um dia ou dois, eles voltam para o cais, onde tentam montar uma nova tripulação para sua próxima viagem.","u":1},{"s":"u071f1f12de","n":"Arquitetura Antiga","f":"Vários acampamentos dentro da maior cidade foram construídos sobre os restos de uma civilização muito mais antiga. Templos abandonados há tempos foram convertidos em casas e locais de comércio, com caminhos de andaimes levando de um lugar ao outro.","u":1},{"s":"ud7dfa7909c","n":"As Docas da Matança","f":"Ataques de monstros marinhos são uma ameaça constante na região de Águas de Sentina mas, ao longo dos anos, uma infinidade de indústrias têm lucrado com a caça e a exploração dessas criaturas gigantescas. Os navios as arrastam de volta para o porto para serem transformadas em carne, óleo, couro e escamas para armaduras, e até seus ossos e dentes são negociados nos mercados das docas.","u":1},{"s":"uad5bc0ce8c","n":"Baía de Águas de Sentina","f":"Circundada por encostas traiçoeiras e penhascos altíssimos, a Baía de Águas de Sentina é tão perigosa quanto aqueles que a chamam de casa. Frequentemente seduzidos por oportunidades aparentemente ilimitadas, os visitantes logo se tornam residentes pois percebem que, quanto mais tempo ficam, mais podem explorar os outros por poder e riquezas.","u":1},{"s":"ubb6c8eda66","n":"Cais dos Escultores","f":"Da Casa da Morte de MacGregan até os entornos das Águas Sangrentas, as Docas da Matança operam dia e noite para transformar a morte em lucro. Somente os capitães mais bem-sucedidos podem sonhar em ter seu próprio cais, então a maioria é forçada a regatear pelo melhor acordo antes que seus prêmios comecem a apodrecer na água.","u":1},{"s":"u9a68f34d1f","n":"Docas da Matança","u":1},{"s":"uf12fc7bf5f","n":"Ponte da Carnificina","f":"A Ponte da Carnificina, pairando ameaçadoramente acima do cais principal, é uma antiga estrutura de pedra construída nos penhascos, conectando os movimentados cais aos notórios guetos que se multiplicam. Alguns ainda a usam para chegar ao Templo de Nagacáburos, mas a maioria se encontra aqui para duelar ou negociar mercadorias ilícitas.","u":1},{"s":"u9af8e4424e","n":"Templo Buhru","u":1},{"s":"u7fa227bc5d","n":"Um Novo Começo","f":"Pela falta de recursos naturais para construções, boa parte de Águas de Sentina foi construída com o que as pessoas conseguiram trazer, achar ou roubar, desde alvenaria de demolição até os cascos dos navios em que vieram.","u":1},{"s":"u90e9b9060e","n":"Vida na Água","f":"Os habitantes mais humildes de Águas de Sentina vivem em um labirinto de canais tortuosos e enseadas escondidas, sem separação entre a casa que construíram e o mar onde ganham a vida. De fato, atravessar essas águas perigosas não é apenas um risco da profissão, é parte do cotidiano.","u":1},{"s":"wbaebbf1bfa","n":"Águas de Sentina (arte conceitual 1)","w":1},{"s":"w4b545b9d30","n":"Águas de Sentina (arte conceitual 10)","w":1},{"s":"w4ac1692c7e","n":"Águas de Sentina (arte conceitual 11)","w":1},{"s":"w4a5d54b602","n":"Águas de Sentina (arte conceitual 12)","w":1},{"s":"w0dcbe9a95a","n":"Águas de Sentina (arte conceitual 2)","w":1},{"s":"w44ddef5350","n":"Águas de Sentina (arte conceitual 3)","w":1},{"s":"w8940ffd80a","n":"Águas de Sentina (arte conceitual 4)","w":1},{"s":"w947e6cecb8","n":"Águas de Sentina (arte conceitual 5)","w":1},{"s":"wdfbb829dd6","n":"Águas de Sentina (arte conceitual 6)","w":1},{"s":"waca4254c10","n":"Águas de Sentina (arte conceitual 7)","w":1},{"s":"w07e4b9c61b","n":"Águas de Sentina (arte conceitual 8)","w":1},{"s":"w30caaca496","n":"Águas de Sentina (arte conceitual 9)","w":1}],"creatures":[{"s":"02BW041","n":"A Fera Submarina","f":"\"Não tema a fera que você conhece\nPois alguns sobrevivem ao seu furor\nMas aquele que quebra a proa\nArrasta todos para o terror\" – Escrito na viga de uma taverna de Águas de Sentina\""},{"s":"04BW001","n":"Barbatelo Rubro","f":"Ao que tudo indica, Barbatelos Rubros quebram a quilha de embarcações por pura diversão. É muito raro que devorem os náufragos depois, deixando o banquete para outras criaturas desfrutarem."},{"s":"03BW017","n":"Bolheixe Ondulante","f":"\"Atenção, lecluta! Xua mixão é se infiltlá nas linhas inimigas, plantá o maió número di bolias pussível e contá pa gente TUDU QUI VOXÊ VIU. TENDEU?!\" – Almilante Shelly, Artilharia Cascuda"},{"s":"02BW019","n":"Bolhurso","f":"Correntes vívidas de magia circulam pelos rochedos das Ilhas das Serpentes, alimentando os extraordinários habitantes do oceano."},{"s":"04BW003","n":"Cardume de Afianhas","f":"\"Plic, ploc, respinga o sangue noite afora,\nTic, toc, é melhor se afogar agora\nNhac, nhoc, vêm os dentinhos nos fazer gritar\nTrac, troc, e nas profundezas nunca mais acordar!\"\n– Cantiga de ninar de Águas de Sentina"},{"s":"07BW042","n":"Caçador do Convés","f":"\"Mantemos esse carinha desgrenhado por perto por um motivo: não temos problemas com ratos do cais há anos!\"\n– Ajudante do Apavorador"},{"s":"02BW030","n":"Colecionadora de Naufrágios","f":"\"Hoje em dia, há mais tesouros sob as ondas do que na superfície. Seria moleza de conseguir, se não fosse por ela.\"\n– Carniceiro Farpado"},{"s":"02BW014","n":"Criaturas Coralinas","f":"Nas águas rasas, há muitos tipos de vida marinha, mas nada se compara aos recifes da Via Azure. A Via é um lugar mágico e deslumbrante, cheio de surpresas."},{"s":"02BW046T2","n":"Dentão","f":"Embora muitos discordem sobre o temperamento e as intenções de Fizz, quando se trata do Dentão, as opiniões são unânimes."},{"s":"02BW056","n":"Devorador das Profundezas","f":"\"Eu navegava, meio na surdina\nPela Baía de Águas de Sentina\nQuando ela surgiu, por trás da escarpa\nA Dama Orelhuda Naufragada...\" – \"Canção da Dama Orelhuda Naufragada\""},{"s":"07BW039","n":"Grinzo, o Príncipe Dragão","f":"\"Senhor Lagarto, o que faz aqui? Você também gosta de Poros?!\" – Ingvar, a Jovem"},{"s":"08PZ006","n":"Iascylla, Acrostólio das Profundezas","f":"\"Venha, Iascylla! Você é velha mesmo se Ashlesh sabe seu nome. Mas, velha ou jovem, bonita ou feia, não importa. Não há honra maior para nenhum monstro do que cair sob minha lâmina em mar aberto.\" – Nilah"},{"s":"03BW002","n":"Lagarto Boêmio","f":"\"Ah, como as pessoas são burras! Basta uma bebida geladinha e uma cadeira quentinha para contarem qualquer segredo a rostos amigáveis. E quem tem um rosto mais amigável do que o jovem Leonard, hein?\" – Rãdivinha"},{"s":"06BW038","n":"Megapresa","f":"\"O que ele quer?!\"\n\"Está... atrás das laranjas!\"\n\"Pelo amor da Mulher Barbada, DÁ LOGO O SACO INTEIRO!\" – Marinheiros azarados"},{"s":"02BW036","n":"Narval Dourado","f":"Reza a lenda que uma baleia de chifres roubou da Mulher Barbada. Como punição, a Mulher cobriu de ouro a gananciosa criatura, condenando-a a atrair a avareza alheia para todo o sempre."},{"s":"02BW037","n":"Olho Abissal","f":"\"Arr, arr, eles gritaram\nRumo a Nashramae eles zarparam\nMas a natureza agiu, levando muitos a perecer\nE os outros encontrarão o olho que tudo vê!\" – \"O Olho Que Tudo Vê\""},{"s":"04BW007","n":"Peixe-jaula","f":"\"Nada melhor do que um peixe-jaula pra te mostrar quem merece confiança e quem merece a morte.\" – Pyke"},{"s":"02BW030T4","n":"Platewyrm Feroz","f":"As feras irromperam das ondas e destruíram o casco com suas mandíbulas vorazes. Não adiantava implorar misericórdia à Mulher Barbada. A ganância do capitão já havia selado o destino de todos."},{"s":"06BW036","n":"Rato do Cais","f":"\"Não há lugar mais sangrento em Águas de Sentina do que a baía. Veja só esses ratos. Criados no sangue. Eles sempre querem mais. Nunca estão satisfeitos, os desgraçados.\"\n– Carniceiro Farpado"},{"s":"08BW031","n":"Sefirsa, Flagelo das Profundezas","f":"Apesar do apetite mesmo pelas feras marinhas mais estranhas, alguns monstros são demais até para os capitães mais experientes de Águas de Sentina. Eles falam de Sefirsa aos sussurros, como uma luz hipnótica que se move nas profundezas à sombra das ondas; um monstro empoleirado sobre uma quantidade enorme de navios naufragados e homens afogados."},{"s":"06BW044","n":"Tritão Travesso","f":"\"Monstrinhos nojentos e ladrões, esses aí. Mas são facinhos de achar quando já afanaram algo, pelo menos.\""},{"s":"04BW015","n":"Tubarilho","f":"\"Pode até não parecer, mas o que não falta neles é sede de sangue. Se baixar a guarda agora, eles vão saber onde caçar quando ficarem maiores. É melhor colocar luva pra mexer com eles.\" – Caçadores de Peixe-Jaula"},{"s":"uc75cd43526","n":"Bestas Marinhas","u":1},{"s":"u060222e38f","n":"Monstros das Profundezas","f":"Não se sabe se os monstros marinhos em torno de Águas de Sentina inspiraram a crença na Mãe Serpente ou se foi o contrário, mas, seja qual for a resposta, os leviatãs se tornaram uma aparição constante nas várias culturas de Águas de Sentina.","u":1},{"s":"we94f6aaa58","n":"Criatura de Águas de Sentina (arte conceitual 1)","w":1},{"s":"wba37cb2ab8","n":"Criatura de Águas de Sentina (arte conceitual 2)","w":1},{"s":"w74ccb09aea","n":"Criatura de Águas de Sentina (arte conceitual 3)","w":1}]},"targon":{"groups":[{"id":"solari","name":"Os Solari","desc":"A fé do Sol, guardada por sacerdotes e guerreiros Ra'Horak. Leona é o Aspecto do Sol.","items":[{"s":"03MT028","n":"Escudeira Solari","f":"\"Tolos são os que não vivem sob o manto da noite\". A escudeira se endireitou e ordenou: \"Abaixe as armas e entregue-se pacificamente\".\nA Lunari se agachou em silêncio, preparando as lâminas curvas mais uma vez.\nQue assim seja.\nA Solari também se preparou, levantando o escudo para refletir os raios do sol nascente."},{"s":"06MT044","n":"Estrelacórnio Solari","f":"Os estrelacórnios nascem das estrelas, e alguns são mais brilhantes do que outros."},{"s":"03MT057","n":"Forjassol Solari","f":"Quando a luz adentrou o local, o Forjassol voltou sua atenção a ela. O artefato Solari transformou os raios brilhantes do sol em um encantamento poderoso para a arma que ele empunhava."},{"s":"03MT044","n":"Guardião do Sol","f":"\"Guardião reluzente, sua ira queima como o sol do meio-dia. Venha e castigue aqueles que se atreveriam a invadir este lugar sagrado.\" – Inscrição do Guardião do Sol"},{"s":"04MT013","n":"Ignifalco Solari","f":"Os Solari acreditam que foram os ignifalcos de Targon, com seu brilho radiante, que atraíram a atenção da Chama Imortal e inspiraram seu ciclo de morte e renascimento."},{"s":"03MT054T1","n":"Leona","f":"Era para isso que Leona havia se preparado. Ela sabia que encontraria Diana descendo a montanha, recuando antes que o sol raiasse. Ela respirou fundo para acalmar o coração acelerado, silenciando-o com sua determinação melancólica. Neste encontro, ela teria a vantagem. Desta vez, ela enfrentaria sua velha amiga de frente."},{"s":"03MT026","n":"Rahvun, a Lança da Alvorada","f":"\"Mantenham a fé, Ra-Horak, e nossa luz nunca se apagará!\""},{"s":"03MT096","n":"Sacerdotisa Solari","f":"Assim como qualquer outro targonense, os Solari também buscam orientação nas estrelas, pois o Sol é a estrela mais adorada em sua fé."},{"s":"03MT088","n":"Soldado Solari","f":"Sob o calor do sol, ele vigiava a prisão da herege, ignorando os suaves apelos que logo se transformaram num silêncio amargo."},{"s":"u44108f95a1","n":"Armas dos Ra’Horak","f":"Os ferreiros Solari produzem belas lâminas douradas que refletem a divina luz do sol, e essas armas costumam ser carregadas e ostentadas na parte exterior da armadura dos guerreiros sagrados.","u":1},{"s":"ub8420d5a2d","n":"Astrolábio dourado","f":"Os sacerdotes Solari ficam ainda mais atentos aos céus e usam astrolábios para medir o movimento dos corpos celestiais e prever eventos futuros.","u":1},{"s":"ua0c4319f91","n":"Os Solari","f":"Embora quase todos os Rakkor adorem o sol, aqueles que dedicam suas vidas exclusivamente a isso são conhecidos como Solari. Os Solari, grupo religioso dominante no Monte Targon, acreditam que o sol seja a fonte de toda a vida. Para eles, qualquer outra fonte de luz é, além de falsa, uma ameaça ao futuro de seu povo.","u":1},{"s":"u1817027fb2","n":"Santuário de orações dos Solari","f":"No sagrado Templo da Alvorada, os guerreiros Rakkor mais valorosos buscam um lugar entre os Ra’Horak, a ordem militante de elite dos sacerdotes Solari. Esse templo em particular foi construído de modo a garantir seu alinhamento aos principais eventos celestiais, que podem ser observados por orifícios cuidadosamente posicionados de acordo com cada evento.","u":1},{"s":"uec44bdc4c6","n":"Templo do solstício","f":"A entrada do Templo Solari, nas encostas orientais do Monte Targon, foi esculpida em mármore com detalhes dourados. Em tempos difíceis, padres ou escribas podem passar semanas meditando no sacrário externo, sem água nem comida, tirando todo o seu sustento do sol, a fonte de toda forma de vida.","u":1},{"s":"w167ce4dd23","n":"Solari (arte conceitual 1)","w":1},{"s":"w1003462292","n":"Solari (arte conceitual 2)","w":1},{"s":"wd52d44dad6","n":"Solari (arte conceitual 3)","w":1}]},{"id":"lunari","name":"Os Lunari","desc":"Os devotos da Lua, perseguidos pelos Solari como hereges. Diana e Aphelios lutam por eles.","items":[{"s":"03MT220","n":"A Encruzilhada","f":"\"Mãe Lua, a noite chegou,\nQue possamos deter os que nos fazem mal,\nE ensiná-los a se redimir.\"\n– Oração Lunari"},{"s":"06MT038","n":"A Luz Sinuosa","f":"\"Mãe Lua, dê-nos forças,\nEmbora a escuridão nos rodeie,\nCom a sua luz, iremos triunfar.\"\n– Prece Lunari"},{"s":"03MT217T13","n":"Aphelios","f":"\"... serão ensinadas por Aphelios e Alune...\" – Porta-Voz Lunari"},{"s":"03MT221","n":"As Presas","f":"\"Mãe Lua, mostrai-me o caminho,\nRevelai os céus,\nMostrai-me o além.\"\n– Oração Lunari"},{"s":"06MT032","n":"Cultista Lunari","f":"Ela buscou um fim para o conflito entre Sol e Lua, dia e noite. O arco oferecia poder, embora custasse um preço terrível. Ainda assim, ela se dedicou a ele na esperança de que a guerra fosse cessada de uma vez por todas."},{"s":"03MT047","n":"Cygnus, o Caçador da Lua","f":"Os Lunari esperaram o anoitecer e a segurança que ele trazia. O caminho parecia deserto, mas Cygnus sabia que o acampamento dos Solari estava logo adiante. Ele gesticulou, e os outros formaram uma fila atrás dele."},{"s":"03MT056T1","n":"Diana","f":"Apressada, Diana desceu a montanha, com a espada desembainhada e coberta de pólen de pétala noturna. Ela sabia que Leona a encontraria. Fazia parte de seu plano. Seu coração acelerou de ansiedade, e ela respirou profundamente para acalmá-lo. Neste encontro, ela teria a vantagem. Desta vez, ela enfrentaria sua velha amiga de frente."},{"s":"03MT100","n":"Dragão do Eclipse","f":"Escama de dragão (Dragão do Eclipse, Draco obscuratus)\nNotas: a escama tem incríveis propriedades ópticas. É altamente refletora sob a luz solar direta.\nRabisco: TAMBÉM BRILHA À NOITE!\n– Notas de Anden Mayne, Pesquisador Acadêmico"},{"s":"03MT089","n":"Guardiã Crescente","f":"\"Guardiã estoica, o toque gentil da lua cheia restaura sua força. Desperte e nos proteja dos que se atreveriam a invadir este lugar sagrado.\" – Inscrição da Guardiã Crescente"},{"s":"03MT094","n":"Lunari Espreitadora","f":"\"Voltemos nossos olhos para os céus, para o Sol, para nossa dama... Espere... O quê...? O que é aquilo...?\" – Sacerdote Solari"},{"s":"03MT073","n":"Lunari Portadora do Anoitecer","f":"\"As pétalas noturnas florescem à noite e apenas na lua cheia. Símbolo do orgulho Lunari, seu pólen é usado há séculos, pois apenas nós sabemos como colhê-las de forma segura.\""},{"s":"06MT042","n":"Protetora Crepuscular","f":"Nas horas crepusculares e logo antes do nascer do sol, ouve-se o pio da coruja, um lembrete dos espaços liminares entre o anoitecer e o amanhecer."},{"s":"03MT075","n":"Sacerdotisa Lunari","f":"\"Ah, estrelas do céu, que viajam como muitos peregrinos pela noite. Fiquem conosco um instante, contem-nos o que viram.\" – O Hino da Noite"},{"s":"03MT216","n":"Sombras Celestes","f":"\"Mãe Lua, permita-me lembrar,\nQue, embora em solidão,\nSeus filhos dançam no céu,\nE eu não estou só.\"\n– Oração Lunari"},{"s":"03MT063","n":"Sonhaluna","f":"\"Olha só todas as nossas amigas no céu hoje! Tá vendo aquela estrela mais brilhante? É o olho do Mensageiro observando a gente! E aquele grupo escuro ali... é o Trapaceiro se escondendo atrás das nuvens! E aquela ali... QUIETO, KULUN! Você não pode sair derrubando as coisas...!\""},{"s":"u8fc9318918","n":"Armas proibidas","f":"Já as armas dos Lunari tendem a ser elegantes e simplistas. Muitas vezes, são feitas de pedras iridescentes da lua.","u":1},{"s":"uf3aaf36f49","n":"Esperança no futuro","f":"Ainda que não seja possível trazer de volta os inúmeros Lunari mortos pelos Solari ao longo dos anos, parece que o equilíbrio de poder no Targon está mudando, pois dizem por aí que o Aspecto da Lua voltou a assumir uma forma mortal...","u":1},{"s":"u907b20f3bd","n":"Os Lunari","f":"Considerados hereges pelos Solari, os Lunari cultuam a luz argêntea da lua. Seu culto é mantido em segredo, e eles precisam se esconder dos que desejam erradicar de Targon qualquer influência lunar — embora alguns digam que, muito tempo atrás, os dois grupos viviam em paz e cultuavam os céus em união.","u":1},{"s":"wa0fae0639d","n":"Lunari (arte conceitual 1)","w":1},{"s":"w3b9f45b3f3","n":"Lunari (arte conceitual 2)","w":1}]},{"id":"aspects","name":"Aspectos e Celestiais","desc":"Mortais que escalaram a montanha e receberam um ser celestial, como Pantheon e Taric, e os próprios Celestiais.","items":[{"s":"08MT027","n":"Arauto da Convergência Celestial","f":"\"Um anel de fogo arde sobre nós. Na escuridão anunciada, somos todos iguais.\" – Porta-Voz Lunari"},{"s":"06MT053","n":"Artesã Generosa","f":"Com olhos bondosos e a expressão oculta atrás de um véu, ela oferece cristais de oração a quem estiver pronto para a peregrinação. Ela não cobra por essa ação. Afinal, o preço será pago na Montanha."},{"s":"03MT087","n":"Aurelion Sol","f":"\"Pode escrever o que quiser sobre mim, criatura medíocre! Só não esqueça de dizer que sou lindo, magnífico e muitíssimo inteligente. Quer que eu soletre?\""},{"s":"03MT087T1","n":"Aurelion Sol","f":"Aurelion Sol é lindo. E magnífico. E também muitíssimo inteligente."},{"s":"03MT048","n":"Doadora de Dádivas","f":"\"Dizem que o Protetor abençoou as gemas. Se usá-las, o espírito dele acompanhará você.\""},{"s":"06MT029","n":"Esmus, Sopro do Mundo","f":"\"... mas ouvi dizer que Esmus foi criada pelo próprio Protetor, e com o nascimento dela, o som veio ao mundo!\"\n\"Minto! Sabe-se que Esmus tem o rosto de uma velha cantora que tinha o coração de um anjo, mas a voz dos mortos... até que o próprio Bardo lhe concedeu uma voz de pura beleza!\"\n\"Minto! Esmus é...\"\n– Parte de Nascimento de Esmus, um famoso jogo de bardos"},{"s":"06MT018","n":"Guardião da Lei","f":"\"Temo que o dia finalmente tenha chegado... a Justiça retorna com asas douradas, e traz consigo um exército brilhante!\"\n– Guardião Mitológico Skai'en"},{"s":"05MT013","n":"Iula","f":"Iula ainda lembra o ardente pesar que atravessou seu corpo ao ouvir sobre a morte do marido. Quando Pantheon apareceu perguntando se ela o ajudaria a destruir a criatura que havia se deleitado com a dor que sentira, a resposta dela foi rápida."},{"s":"08MT005","n":"Mihira, Aspecto Ascendente","f":"\"Foi em nome das minhas filhas que eu aceitei a divindade. Foi pela minha família que abri mão da minha própria humanidade, para que, com esta espada flamejante, eu possa forjar um novo mundo de verdade e justiça.\""},{"s":"06MT031","n":"Mihira, o Aspecto da Justiça","f":"\"Alguns reverenciam os Aspectos como deuses. Outros os veem como mensageiros do reino além. Outros ainda os temem... e talvez com razão.\" – Guardião Mitológico Skai'en"},{"s":"05MT003","n":"Pantheon","f":"Este é Atreus, que teve sua liberdade roubada pelos próprios Aspectos que venerava. Estas são as chamas da Guerra, que deixaram Atreus com dádivas que poucos mortais conseguem compreender. Este é um homem pronto para lutar e morrer por aqueles que ama."},{"s":"05MT003T2","n":"Pantheon","f":"Este é Pantheon, que ergueu sua lança e jurou afugentar todos os deuses e demônios desta terra que chamamos de lar."},{"s":"03MT029","n":"Pastora de Estrelas","f":"\"Desde que vi um deles cruzar o céu noturno, me apaixonei pelos estrelacórnios. Na época, eu nem imaginava que conheceria tantos!\""},{"s":"03MT079","n":"Pestinha Estelar","f":"\"Adultos são CHATOS. As únicas crianças legais são a Zoe e a galera dela. Eles me ensinam um montão de coisa. Diferente daquela tia sacerdotisa radiante... BLÉÉÉ!\""},{"s":"03MT055T1","n":"Soraka","f":"\"O que você doa de si mesmo para ajudar os outros retorna multiplicado por cem. Esse é o poder da doação. A generosidade é uma dádiva que cura também a mente, o corpo e o espírito de quem doa.\""},{"s":"03MT058T1","n":"Taric","f":"\"Por que Taric ajuda o próximo? Bem, ele chegou a Targon desnorteado, com a intenção de escalar a montanha para expiar seus pecados... e conseguiu. Melhor do que ninguém, ele sabe que qualquer coisa pode voltar a ser bela.\" – Vidente da Montanha"},{"s":"03MT009T1","n":"Zoe","f":"\"Ah, a vastidão do espaço e incontáveis realidades espalhadas, amontoadas e pressionadas bem diante da gente! E queeeem saaaabe a gente até encontre meu cãozinho espacial favorito!\""},{"s":"03MT012","n":"Árbitro do Pico","f":"O Árbitro é o teste final da montanha, pois somente o guardião pode ver além das façanhas do alpinista e enxergar seu espírito."}]},{"id":"rakkor","name":"Os Rakkor e os peregrinos","desc":"As tribos que vivem nas encostas do Monte Targon, e os alpinistas que tentam chegar ao topo.","items":[{"s":"06MT017","n":"Clérigo Divino","f":"\"É dito que, quando Mihira partiu deste lugar, ela deixou uma parte de si para trás — uma chama sagrada, ardendo intensamente. Há anos minha família cuida desse fogo, mantendo-o aceso na esperança de que ela retorne.\""},{"s":"03MT030","n":"Contempladora de Estrelas","f":"\"As estrelas não podem ficar conosco para sempre. Depois de cuidar delas, eu as devolvo aos céus numa labareda fugaz de luz estelar... e cascos agitados.\""},{"s":"07MT007","n":"Estudioso Imolado","f":"\"A Camphor já levou muita coisa de muita gente. Quando chegar a sua hora de morrer, morra do seu jeito. Não dê essa satisfação a ela.\" – Pantheon"},{"s":"03MT080","n":"Guardião da Nascente","f":"\"Na maior parte do tempo, eu cuido das nascentes, mas a principal responsabilidade de um pastor é o seu rebanho. Às vezes, as prioridades podem entram em conflito.\""},{"s":"05MT005","n":"Idealizador de Sagas","f":"Tor sentiu sua vida esvaindo a cada pulsação. Porém, em meio àquela sepultura e à escuridão, onde deveria ser envolto pelo medo, ele encontrou propósito: não só encararia a morte de bom grado, como também levaria consigo o demônio que ousou encurtar sua vida. É assim que ele seria lembrado. Esta seria a saga de Tor."},{"s":"05MT010","n":"Mística Cega","f":"Eshiyme já foi uma profetisa renomada que usava sua Visão para guiar quem precisasse. Porém, essa dádiva fora roubada por Camphor, que desejava saciar-se com a inevitável angústia de Eshiyme. Camphor nunca poderia ter imaginado a coragem da profetisa."},{"s":"06MT004","n":"Pastor Errante","f":"Jax ajudou Chaska a salvar o bando da investida de silfos furiosos. Depois, Chaska salvou Jax de silfos furiosos. Quando um dos dois não está passeando por aí, eles viajam juntos."},{"s":"03MT081","n":"Peregrinos da Montanha","f":"Todos que se aventuram no Monte Targon têm seus motivos. Alguns querem provar algo a alguém, outros querem provar algo a si mesmos."},{"s":"03MT076","n":"Vidente da Montanha","f":"\"As estrelas têm muito que ensinar e orientar. Para nós, elas são uma constante, uma forma de traçar nosso caminho.\""},{"s":"03MT033","n":"Vovô Rumul","f":"\"Escute, Osu. Está ouvindo? Sinos! O vovô está de volta!\"\n– Illi, Pastora de Estrelas"},{"s":"u4e14a0c63c","n":"A despedida","f":"Em uma cerimônia sagrada de despedida, os alpinistas prestes a iniciar sua jornada são celebrados. Este dia marca o momento em que o destino de suas almas é colocado nas mãos de Targon. A maioria nunca volta.","u":1},{"s":"ubf520976e0","n":"A vida entre as tribos","f":"Há milhares de anos, os Rakkor suportam as dificuldades da vida nas montanhas e, muitas vezes, até fazem essa vida parecer fácil. Na verdade, eles estão sempre atentos aos perigos que vêm de cima ou de baixo.","u":1},{"s":"ub08a88f2c9","n":"Arranjo do zênite","f":"Astrônomos e astromantes de toda a região de Targon acompanham meticulosamente os movimentos do sol, da lua e das estrelas, na esperança de entender a vontade dos Aspectos e acelerar sua vinda para este mundo.","u":1},{"s":"u5113c04a6c","n":"Casa dos Rakkor","f":"Targon é uma região extensa e montanhosa, habitada por um povo talentoso e devoto. Por milhares de anos, as tribos migratórias dos Rakkor esculpiram no coração da montanha seus lares sazonais, mercados e câmaras cerimoniais.","u":1},{"s":"ud9ac4012ac","n":"Em torno da montanha","f":"Para os Rakkor que vivem mais próximos ao Monte Targon, a vida é uma peregrinação sem fim. Ao longo de todo o ano, eles seguem o sol e migram entre os solstícios, permanecendo sempre sob a luz sagrada.","u":1},{"s":"u3a3cbc779f","n":"Equipamento de escalada","f":"Até as crianças das tribos Rakkor são treinadas para usar ganchos e picaretas, equipamentos essenciais para sobreviver na montanha.","u":1},{"s":"u23bd6ad1ec","n":"Itens religiosos","f":"Segurando incensos aromáticos e extratos de certas ervas e plantas raras, essas cumbucas feitas de pedra são frequentemente usadas em rituais religiosos.","u":1},{"s":"ub1b03d253a","n":"Os guerreiros","f":"Apesar de não buscarem a guerra, os Rakkor contam com milícias bem preparadas em todas as suas tribos e assentamentos. Dizem que é praticamente impossível surpreender as forças dos Rakkor em suas próprias terras.","u":1},{"s":"u0007ae5506","n":"Os Rakkor","f":"As tribos Rakkor — palavra que significa “a Tribo do Último Sol” — contam com muitos artesãos, artífices e mercadores habilidosos, mas, apesar disso, preferem valorizar uma vida simples e as preces aos céus.","u":1},{"s":"ucbfa63fb61","n":"Padrões dos mortos","f":"Às vezes, eles iniciam a empreitada em grupos, pois sabem que só podem contar uns com os outros; em caso de exaustão ou ferimento, não existe a menor esperança de receber ajuda lá de baixo. Numa altitude tão elevada, os cadáveres não se decompõem: parece que, aos poucos, eles vão se fundindo à rocha, incorporando-se aos padrões circulares e às nervuras da montanha.","u":1},{"s":"u5427758b51","n":"Talhado na montanha","f":"Várias gerações dos Rakkor construíram mercados, casas, pontes e câmaras cerimoniais usando as formas da própria montanha como modelo. Resistentes a nevascas e tempestades, essas moradias oferecem bastante conforto... sem serem extravagantes.","u":1},{"s":"u5207ff993b","n":"Uma jornada ao pico da montanha","f":"Deixando os laços com Runeterra para trás, alguns alpinistas dizem que o Monte Targon parece se expandir e se contrair sob seus pés, como se a montanha tivesse vida própria. Por esse motivo, ninguém nunca conseguiu traçar caminhos confiáveis até o topo. Cada subida é diferente e, enquanto algumas trilhas levam muitos meses para serem percorridas, outras são concluídas em um só dia.","u":1},{"s":"u05920915d0","n":"Vida de peregrino","f":"Durante suas migrações, as tribos de Targon tentam carregar o mínimo de coisas possíveis. Um sistema de roldanas ajuda a transportar os pertences essenciais pelas encostas, enquanto ferramentas e equipamentos pesados são guardados em abrigos em volta da montanha e passam por reparos ou reformas conforme necessário.","u":1}]},{"id":"marai","name":"Os Marai","desc":"Vastaya de Ionia que, séculos atrás, seguiram até a costa do Monte Targon e construíram uma vila escondida sob um recife de coral. Dependem das pedras da lua para afastar os predadores das profundezas. Nami vem desse povo.","items":[{"s":"05BW004","n":"Avatar das Marés","f":"Para os Marai, Leo'lei é presságio de grandes mudanças. Dizem que cada movimento de suas graciosas asas influenciam o curso das marés."},{"s":"05BW002","n":"Aventureiro Saltareias","f":"\"Alguns deles caçam a gente, mas, até aí, eles sempre caçam de tudo. Sabe, a maioria das criaturas da superfície que já conheci só quer curtir o mar como a gente. No fundo, somos todos iguais.\""},{"s":"05BW010","n":"Grande Mãe Marai","f":"O lar ancestral dos Marai é protegido pela luz celestial de uma pedra da lua. A cada cem anos, a luz começa a diminuir, e um novo Conjurador das Marés precisa encontrar outra pedra. Sem ela, o povo Marai cairia na escuridão e seria vitimada pelos horrores que assolam as profundezas."},{"s":"05BW008","n":"Guarda Abissal","f":"Muitos na nossa tribo acham Loto um pouco desconcertante. Eles só enxergam um lutador incansável e o pesar em seu olhar aflito. Mas eu sei o que ele carrega no peito: o medo de não ser forte o bastante para nos salvar... e um amor extraordinário.\" – Tama, Cantora Marai"},{"s":"06BW047","n":"Marai Arteira","f":"''Bibi é um pouco... perturbada, eu sei. Mas é por isso que amamos ela!'' – Ai'la, Vigia Marai"},{"s":"05BW005T1","n":"Nami","f":"\"Acha que ela já está longe daqui?\"\n\"Espero que sim, Tama.\"\n\"Consigo até imaginar... Ela com olhos cintilando à luz da lua e o brilho da água salgada nas escamas.\"\n\"Esse fardo... O destino do nosso povo não deveria ser carregado só por ela.\"\n\"Ela está fazendo a parte dela assim como nós, Loto. Tudo que podemos fazer é acreditar nela e amá-la com todo o nosso coração.\""},{"s":"05BW001","n":"Vigia Marai","f":"Os Marai raramente se aventuram para longe de casa, mas Ai'la nasceu com a curiosidade nas veias. Mesmo fazendo jus ao dever que tem com a tribo, ela passa cada minuto acordada sonhando com o dia em que poderá ser livre de verdade."},{"s":"wfb0daf437a","n":"Marai (arte conceitual 1)","w":1},{"s":"w46dfca26a8","n":"Marai (arte conceitual 2)","w":1},{"s":"w670fc6a88f","n":"Marai (arte conceitual 3)","w":1}]},{"id":"ottrani","name":"Os Ottrani e os dragões de Targon","desc":"Adoradores de dragões das encostas de Targon, os Ottrani, e os sonhadores que ouvem a canção dos dragões celestes.","items":[{"s":"08MT031","n":"Adorante de Dragões Ottrani","f":"No alto das encostas de Targon, ume Ottrani solitárie dedicou sua vida aos dragões. Elu se enfeita com escamas caídas e restos de ossos e traça seu caminho a partir de dentes de dragão espalhados pelo chão e da fumaça que sobe montanha acima."},{"s":"03MT014","n":"Arauta dos Dragões","f":"As nuvens rodopiavam em torno de suas formas gigantescas, e até o céu parecia tremer com seus lamentos. Ela sabia o que estava por vir, mas, em vez de medo, sentia o reconfortante abraço do destino."},{"s":"09MT005","n":"Sonhadora da Canção Dracônica","f":"Os dragões estão próximos. Posso sentir. Neste exato momento, eles viajam pelos meus sonhos.''"}]},{"id":"outros","name":null,"desc":null,"items":[{"s":"07MT006","n":"Amantes Desafortunados","f":"\"Poucas paisagens são mais esplêndidas que o encontro entre o sol e a lua.\" – Diana"},{"s":"03MT086","n":"Artista Sonhadora","f":"\"Este é o meu favorito! Eu chamo de 'Identidade Metafísica da Psique Consciente'. Mas se você inclinar a assim... fica parecendo duas colheres.\""},{"s":"04MT004","n":"Azuporã","f":"\"TO-DO MUN-DO fala 'OI, ZUZU!'... OI, ZUZU! Uma vez achei que ele também tinha falado 'OI, ZUZU!', mas acho que foi o eco da minha voz. TUDO BEM, ele é todo mágico, azul e tal, nem picisa falar! TÁ BOM, TCHAU, ZUZU, VAMU LÁ!\"\n– Aventuras com Lasquinha, parte 5"},{"s":"05MT004","n":"Camphor, a Dúvida","f":"Durante séculos, a demônia Camphor vagou pelas terras de Targon, tirando de suas vítimas os pontos fortes que as definiam. Dos poderosos, ela tomava a força; dos sábios, o conhecimento. Mas ela não tinha interesse nessas dádivas — era a insegurança, a miséria e o sofrimento causados que a saciavam. Camphor era um monstro em todos os sentidos da palavra."},{"s":"03MT062","n":"Faiscóloga Avoada","f":"\"... e aí a brilhoboleta é igualzinha poeira estelar que cai no chão e depois voa de volta e elas são tão incríveis e eu vi uma tão linda ontem à noite e eu tô com fome e ela voou até as ESTRELAS e depois... \""},{"s":"04MT005","n":"Lasquinha","f":"\"Oi, tudo bom? Eu xô o Lasquinha e vim mostá Tágon pa voxês! É beeeeem gandão, então picisa de sapato bom pa andá! VAMO!\"\n– Aventuras com Lasquinha, parte 1"},{"s":"08MT015","n":"Lisa e Dolly","f":"\"Olha, Dolly! Estou fazendo igual você me ensinou! Será que um dia vamos poder mostrar pra mamãe o quanto eu aprendi? Você acha que ela já sabe? Sério?! Espero que você esteja certa.\" – Lisa"},{"s":"06MT016","n":"Mensageiro Alado","f":"\"Sim... Reconheço você. A mensagem que carrega... só pode ser uma convocação.\" – Ryze"},{"s":"03MT041","n":"Mentor das Pedras","f":"\"Você entendeu alguma coisa do que ele disse?\"\n\"Nada. Mas ele parecia legal, né?\"\n– Emir e Haley, Peregrinos da Montanha"},{"s":"08MT009","n":"Protetor Velado","f":"Esse protetor velado não esqueceu a bênção que o elevou além de uma mera fera. Ele paga essa dívida garantindo que qualquer um que busque certo santuário nas encostas do Targon faça uma jornada segura."},{"s":"03MT060","n":"Protetor Vigoroso","f":"\"Ninguém conhece os caminhos de Targon como eu, então acabo tendo que cuidar de uns estrelacórnios mais teimosos. Mas que bom que eles têm a mim!\""},{"s":"04MT002","n":"Quebra-pedras","f":"De tempos em tempos, os grandes colossos de Targon despertam e abrem novos caminhos no topo da grande montanha. Esses eventos nunca são tranquilos, e muito menos seguros."},{"s":"03MT071","n":"Viajante Tyari","f":"Quando viaja, você deve se entregar à jornada, que inevitavelmente mudará quem você é. Quando viaja, você acaba voltando com algo novo... e deixando para trás parte do seu antigo eu."}]}],"places":[{"s":"09MT002","n":"Anfitrião das Escamas de Névoa","f":"Este Ottrani solitárie se dedica à adoração dos dragões. Elu os reverencia com tanta fé que consegue ver as nobres feras tanto no mundo real quanto no mundo onírico."},{"s":"04MT009","n":"Escadas Espiraladas","f":"\"Pimela palada! Eu chamo aqui de tontolia, porque AAAAH é deglau pa lá e pa cá e te deixa tonto! A vista também é legal, e essa é uma das coisas que eu mais gosto em Tágon. Tá bom, VAMO!\" – Aventuras com Lasquinha, parte 2"},{"s":"04MT004T1","n":"Insígnia de Perspicácia","f":"\"Zuzu aaaaaama esse lugar mais que tudo no mundo! Ele diz que é MUITO mágico! Uhhh, ahhh!\" – Lasquinha"},{"s":"03MT052","n":"Nascente Estelar","f":"\"Lá em cima, na cachoeira sagrada\nBem no fundo, nascentes de cura\nLuz reluzente, água iluminada\nVeja como o rio perdura\nNo topo da montanha de cristal.\"\n– Verso Ottrani"},{"s":"03MT219","n":"O Templo Velado","f":"É aqui, no Reino Espiritual, que Alune entra em comunhão com seu irmão Aphelios. É ela quem conforta o assassino silencioso com suas palavras e quem levanta o véu para entregar-lhe as armas da retaliação."},{"s":"04MT014","n":"Olho dos Ra-Horak","f":"\"O sol derramará a luz d'Ela sobre nós. Os fracos e indignos vão se acovardar diante do olhar d'Ela!\" – Sacerdotisa Solari"},{"s":"08BW036","n":"Pináculo Coralino Marai","f":"\"Faz tempo que o coral é nosso abrigo e aliado. Ele cuida da gente, e nós cuidamos dele, assim ninguém sucumbe à escuridão da Treva.\" – Grande Mãe Marai"},{"s":"06MT039","n":"Poleiro do Dragão","f":"\"Dizem que os dragões celestiais nascem das nebulosas, brotando totalmente formados da poeira cósmica. Mas como nós, meros mortais, podemos saber? De longe, tudo o que vemos é a luz deles.\" – Arauta dos Dragões"},{"s":"04MT001","n":"Trilha do Desabamento","f":"\"Pexual, ICUTA AQUI: cuidado que a QUEDA É GANDE e eu até já caí! Eu sou de péda, então num faz mal, mas vocês... cuidado. Olha, é o Lochoso! Vamo lá dar oi!\"\n– Aventuras com Lasquinha, parte 3"},{"s":"06MT047","n":"Vórtice Místico","f":"\"Então eu vi... milhares deles, todos cantando e dançando de várias formas. Logo em seguida, vi um clarão, e todos se foram, e o templo também. Não restou uma pedra sequer. E em minhas mãos? Bem, o Velho Gaff ficou lá segurando um sino.\" – O conto do velho Gaff, parte 3"},{"s":"u0a78bcb72e","n":"A chegada ao topo","f":"Nos raros casos em que um mortal digno alcança o cume do Monte Targon, os céus se abrem em um espetáculo de auroras cósmicas. Poucos puderam testemunhar essa visão radiante entre as nuvens e o firmamento estrelado, onde dizem haver uma deslumbrante cidade feita de ouro e prata, habitada por seres divinos e eternos.","u":1},{"s":"u5eca277a73","n":"A estrada tortuosa","f":"As trilhas mais antigas nas montanhas contam com portais ancestrais de metal reluzente, e o maior deles marca o término de cada fase da migração dos Rakkor. Os Rakkor celebram o momento em que cruzam cada um desses limites, depois seguem o caminho iluminado do sol.","u":1},{"s":"ubfce8fb368","n":"A vida à beira do precipício","f":"Embora muitos Rakkor se contentem em viver nas partes inferiores do Monte Targon, a cada estação, peregrinos de todas as partes são atraídos para o local... e os mais ousados, ou desavisados, até se atrevem a encarar a perigosa escalada até o pico da montanha.","u":1},{"s":"u248ad487ef","n":"Formações extraordinárias","f":"Para os pastores que levam seus rebanhos para pastar nas encostas da montanha, às vezes é fácil ignorar as estranhas gravuras que parecem emergir das rochas do Monte Targon. Para os ancestrais targonenses, essas gravuras eram a prova de que a própria montanha fora forjada por intelectos divinos.","u":1},{"s":"u8fabd62fb6","n":"Gravações nas pedras","f":"Hoje, alguns Rakkor acreditam que essas formas extraordinárias fazem parte de um grande mapa que retrata reinos desconhecidos para além dos céus. Outros dizem que as gravuras são alertas de uma terrível guerra que um dia assolará o mundo inteiro, colocando irmãos contra irmãos. Apesar dessas especulações, a verdadeira origem e o propósito das gravuras nas rochas ainda são um mistério.","u":1},{"s":"ude65cb62d1","n":"Inverno eterno dos cumes","f":"Nos pontos mais altos, ventos inclementes e perigosos barrancos de neve desafiam o ciclo natural das estações, criando um inverno sem fim. Essa paisagem atípica, onde plantas e animais são visões raras, é um perigo para qualquer viajante.","u":1},{"s":"u106237a71c","n":"O teste supremo","f":"As partes mais altas do Monte Targon, implacáveis até mesmo para os alpinistas mais experientes, são alvo de ventos cortantes, tempestades polares e avalanches frequentes. Aqueles que sobrevivem à escalada descrevem noites árduas, castigadas por um frio rigoroso e estranhas visões de figuras etéreas.","u":1},{"s":"u663d12ef43","n":"Quatro estações","f":"Nos vales inferiores, os Rakkor podem caçar e colher alimentos, plantar e alimentar seus animais. Durante a primavera e o verão, principalmente, a flora e a fauna locais prosperam até nas alturas mais elevadas.","u":1},{"s":"u20ed4a2974","n":"Riscos sobrenaturais","f":"No entanto, o maior perigo do Monte Targon não é a altitude extraordinária, mas a forma como ele desafia o caráter de cada um. Os Rakkor consideram a escalada um teste de caráter para os aspirantes, pois, quando a solidão se torna insuportável, eles são acometidos por arrependimentos e por visões perturbadoras de tempos e lugares remotos.","u":1},{"s":"webff85ca16","n":"Targon (arte conceitual 1)","w":1},{"s":"w55b5f563b0","n":"Targon (arte conceitual 2)","w":1},{"s":"we95397bf15","n":"Targon (arte conceitual 3)","w":1},{"s":"w2f9cab52e5","n":"Targon (arte conceitual 4)","w":1},{"s":"wc670324c6d","n":"Targon (arte conceitual 5)","w":1},{"s":"w3e68190bc4","n":"Targon (arte conceitual 6)","w":1},{"s":"w34f0b76d74","n":"Targon (arte conceitual 7)","w":1}],"creatures":[{"s":"03MT083","n":"A Chama Imortal","f":"\"Por muitas eras, a Chama Imortal voou solitária. Um dia, ela se deparou com um jovem pássaro de asas douradas como chamas, similares às dela. A Chama Imortal ficou feliz, pois nunca havia encontrado outro ser como ela. Mas, com o passar dos anos, o jovem pássaro foi envelhecendo e minguando. A Chama Imortal, que até então desconhecia a morte, chorou faíscas e suspirou labaredas..."},{"s":"03MT059","n":"A Irmã Dourada e A Irmã Prateada","f":"\"Da imensidão dos céus\nDuas entidades foram geradas:\nUma coberta por um brilho prateado,\nA outra, envolta em chamas douradas...\"\n– Hino das Horas"},{"s":"03MT034","n":"A Serpente","f":"\"No primeiro equinócio de Targon, o povo da montanha tentou sua primeira trégua. Mas, quando os líderes abaixaram as armas, um deles soltou um repentino grito de dor! Os soldados sacaram as lanças, e qualquer esperança de paz se esvaiu. Eles só não sabiam que o verdadeiro traidor era uma serpente escondida sob seus pés, um sinal perpétuo de tempos violentos.\"\n– Conto popular targonense"},{"s":"03MT040","n":"Brilhoboleta","f":"\"A esperança é uma coisa delicada que voa cada vez mais alto e não deve ser aprisionada.\" – Sacerdotisa Lunari"},{"s":"03MT092","n":"Cabra da Montanha","f":"As cabras do Monte Targon são ainda mais perigosas do que as outras, pois as gemas em seus chifres liberam fragmentos afiados no momento do impacto."},{"s":"05MT006","n":"Chamabranca Ferido","f":"\"Os targonenses não precisam de mais provas para atestar a crueldade dos deuses. Olhe o que fizeram conosco. Olhe o que fizeram com nossos queridos companheiros.\" – Pantheon"},{"s":"05MT012","n":"Colosso Liberto","f":"Colossos são os antigos e venerados protetores dos pontos mais reverenciados de Targon. Prejudicá-los é o mesmo que prejudicar a montanha. Torturá-los é um crime imperdoável a olhos targonenses."},{"s":"08MT030","n":"Dragão das Gemas Dócil","f":"Os Dragões podem variar muito, tanto em temperamento quanto em aparência. Temos espécies propensas à destruição avassaladora, como os Dragões Infernais, mas também outras que protegem famílias e o meio ambiente, como o lento e afetuoso Dragão das Gemas."},{"s":"04MT003","n":"Elemental da Terra","f":"\"Esse aqui é o LOCHOSO! Ele é um gandão que vive aqui faz um TEMPÃO. Eu sei que ele é legal e tem jeito de bonzinho, mas ele leva um monte de coisa pesada nas costas e pode cair em cima das pessoas às vezes, então CUIDADO, tá? Bigado, vamo indo então!\"\n– Aventuras com Lasquinha, parte 4"},{"s":"03MT016","n":"Esmagador Assustado","f":"\"Puxa, o grande Esmagador tá com medo de passar pelo portalzinho? Tudo bem, vamos fazer o seguinte... HAHAHAHA, brincadeira, VAI NA FÉ!\" – Zoe"},{"s":"03MT007","n":"Estrelacórnio Inexperiente","f":"\"Como qualquer iniciante, um dia os jovens estrelacórnios precisam fazer seu primeiro voo. Nesse aspecto, eles são como qualquer outra estrela no céu, pois caem com a mesma facilidade. Felizmente, estamos aqui para segurá-los e, no momento certo, devolvê-los.\" – Lidari, Guardiã das Estrelas"},{"s":"03MT020","n":"Estrelacórnio Resplandecente","f":"\"Está vendo aquela estrela se movendo no céu escuro? É um estrelacórnio adulto. Enquanto os jovens nos emprestam sua magia de cura até poderem retornar aos céus, os adultos dominam esse poder por conta própria. Dizem que ver um e saber do que se trata dá muita sorte. Mais sorte ainda é poder cuidar de um.\" – Lidari, Guardiã das Estrelas"},{"s":"07MT003","n":"Filhote Cósmico","f":"Como a lágrima de um alvorecer, elas cruzam os céus com seu brilho calmo e radiante, curando feridas e consertando o que está quebrado."},{"s":"03MT001","n":"Furins Furtivos","f":"Pelo silêncio cristalino das encostas montanhosas, ecoou o som tilintante de gelo caindo e, bem acima deles, algo que os viajantes podiam jurar ser... risadas."},{"s":"03MT006","n":"Inviolus Vox","f":"\"Olhe para os céus e veja o que eu vejo! Primeiro os sinais, pois, à noite, eles brilham. Depois a fúria, pois, de dia, tudo queima. Você vai ver! Todos nós vamos ver!\" – Arauta dos Dragões"},{"s":"03MT072","n":"Marcabrasa Derretida","f":"Inúmeros desafios esperam quem escala o Monte Targon. Alguns deles, como a subida interminável, sugam suas forças lentamente. Já outros são bem mais imediatos."},{"s":"06MT041","n":"Matilha de Cães Estelares","f":"Os cães estelares não ouviam nem atendiam aos alpinistas em suas jornadas. Eles seguiam alheios, aparentemente envolvidos pela magia da montanha."},{"s":"03MT090","n":"O Acometedor","f":"\"O ouro do sol brilha em seus chifres, e as luzes do fogo em seu coração. Que o trovão dos nossos escudos ecoe como o trovão de seus cascos pelo horizonte!\" – Grito de guerra Solari"},{"s":"03MT010","n":"O Destruidor","f":"\"Para proteger os espaços entre o céu e a terra, um guardião com chifres foi colocado nas estrelas sobre as montanhas. Ágil e poderoso, ele vigia o céu noturno em busca de intrusos e, ao detectá-los, saúda-os com um estrondo que faz tremer toda e qualquer coisa.\" – As Histórias do Minotauro"},{"s":"03MT021","n":"O Dividemente Infinito","f":"Dizem que os viajantes que encaram a criatura nos olhos são atingidos por um conhecimento tão profundo, uma perspectiva tão impressionante, que suas mentes acabam por se desfazer."},{"s":"03MT037","n":"O Flagelo","f":"As lendas falam de um Flagelo que se esconde nos confins mais remotos do Reino Celestial. Lá, ele aguarda a hora do fim dos tempos, quando exercerá o poder das estrelas para estraçalhar os pilares do mundo."},{"s":"03MT022","n":"O Grande Além","f":"\"Ah, minha constelação favorita. Gosto de pensar que ela será a primeira a cair sobre essa montanha esquecida.\" – Aurelion Sol"},{"s":"03MT050","n":"O Guerreiro","f":"Dizem que a estrela mais brilhante no céu noturno é a do guerreiro. Um ser ancestral e imortal, que desce das estrelas para provar seu valor em combate. Ele nunca foi derrotado, mas toda história tem um fim, e toda estrela deve morrer."},{"s":"03MT018","n":"O Mensageiro","f":"\"Quando as folhas começam a cair dos galhos secos, a Dama da Primavera envia seu mensageiro para avisar ao Senhor do Inverno da mudança de estação. A voz do mensageiro faz as estrelas se reorganizarem no céu, enquanto seu fiel coração aquece o solo.\"\n– Canção das Estações"},{"s":"03MT095","n":"O Trapaceiro","f":"\"Eu tava lá tranquilo, cuidando da minha vida, quando me aparece um sujeito todo trabalhado no ouro. Alvo fácil, né? Eu chego junto, jogo um charme e aumento o preço. Só depois, quando vou guardar as moedas, é que eu reparo... que o safado pagou usando o MEU PRÓPRIO DINHEIRO! O Trapaceiro só podia estar brilhando mais forte naquela noite.\" – Yordle Vigarista"},{"s":"03MT214","n":"O Voo","f":"\"Mãe Lua, dai-me confiança,\nConcedei-me a convicção do Voo,\nMostrai-me o caminho.\"\n– Oração Lunari"},{"s":"03MT039","n":"Poroboleta","f":"No espaço, ninguém ouve sua alegria."},{"s":"03MT038","n":"Protetor Chamabranca","f":"As crianças de Targon foram as primeiras a fazerem amizade com os dragões mais jovens e pacíficos. Essas criaturas mais novas podem ter sentido a curiosidade inocente das crianças e preferiram, em vez de machucá-las, oferecer proteção."},{"s":"06MT007","n":"Serpe Seráfica","f":"\"Ah, agora eu entendi... As formas deixadas na montanha eram meras impressões; caminhos para os seres do reino além das estrelas...\" – Guardião Mitológico Skai'en"},{"s":"03MT070","n":"Viajante","f":"\"Sempre fomos um só e o mesmo. Separados apenas pela montanha, pela jornada e por um mar de estrelas.\""},{"s":"04MT018","n":"Íbex Amedrontado","f":"''Não tenha medo do vendaval trovejante\nQuando ele soprar pela montanha uivante\nNão se preocupe, não há o que temer\nDescanse, mamãe vai te proteger.'' – Canção de ninar targonense"},{"s":"03MT067","n":"Íbex de Cristal","f":"Aqueles que pretendem escalar o Targon devem se familiarizar com a fauna local. Nenhuma criatura conhece melhor os perigos de Targon, tampouco pode percorrer seu terreno gelado com tanta agilidade."},{"s":"u4285bfaec0","n":"Bólor","f":"Famosos pelo canto vibrado que emitem antes de um abate, o bólor predatório plana em longos saltos pelas correntes termais com seus membros penados e aerodinâmicos, e ama caçar tamus solitários.","u":1},{"s":"u687112004b","n":"Feras das montanhas","f":"As várias espécies nativas de Targon desenvolveram mecanismos especiais para sobreviver a condições climáticas de frio extremo, com grossas camadas de gordura e pelos espessos que as protegem de ventos cortantes e nevascas. Cascos fendidos dão apoio em inclinações íngremes e pontos de apoio estreitos, enquanto garras em gancho facilmente se prendem no gelo.","u":1},{"s":"uf1a81ccda8","n":"Ibik","f":"O ibik é um herbívoro raro e solitário que vive nas planícies baixas de Targon, e seu leite gorduroso e doce é considerado uma verdadeira iguaria. Durante a hibernação anual, a pele áspera e cinzenta do ibik o ajuda a se camuflar entre as pedras, onde acaba ficando completamente coberto pela neve que cai no inverno.","u":1},{"s":"u094ad8e65e","n":"Tamu","f":"Os Rakkor criam grandes rebanhos de tamus. Seus pelos macios são tosquiados duas vezes por ano para produzir roupas e outros tecidos.","u":1},{"s":"wad03e9bfbe","n":"Criatura de Targon (arte conceitual 1)","w":1},{"s":"w897e3ef4a3","n":"Criatura de Targon (arte conceitual 2)","w":1},{"s":"w9237f160a3","n":"Criatura de Targon (arte conceitual 3)","w":1},{"s":"wf41c59378a","n":"Criatura de Targon (arte conceitual 4)","w":1},{"s":"w11491efafe","n":"Criatura de Targon (arte conceitual 5)","w":1},{"s":"w661bc11169","n":"Criatura de Targon (arte conceitual 6)","w":1},{"s":"w3e4e3eecd9","n":"Criatura de Targon (arte conceitual 7)","w":1},{"s":"wce0de5b693","n":"Criatura de Targon (arte conceitual 8)","w":1}]},"ixtal":{"groups":[{"id":"yuntal","name":"Os Yun Tal","desc":"A casta dominante de Ixtal, formada pelos elementalistas mais sábios e dotados. Vestem roupas tecidas com vidálio para mostrar e amplificar seu poder. Qiyana e Milio vêm dessa herança (cada um à sua maneira).","items":[{"s":"u683d28c9f2","n":"As províncias","f":"Os Yun Tal de maior confiança podem ser selecionados como prefeitos das vilas e assentamentos mais distantes de Ixaocan, como Ohmka, Xolen ou Paretha. Seus deveres incluem a resolução de conflitos locais, o teste de possíveis aspirantes e a garantia abrangente de que o povo de Ixtal tenha o mínimo possível de interações com forasteiros...","u":1},{"s":"ua18b2d6026","n":"Casta dominante","f":"Por incontáveis gerações, os segredos de Ixtal foram preservados pelos seus elementalistas mais talentosos e sábios. Não há critérios formais para fazer parte dos Yun Tal, mas os aspirantes serão testados até o limite absoluto de suas habilidades, e qualquer aprovação deve ser unânime entre os presentes.","u":1},{"s":"u441bb27dc6","n":"Conhecimento esotérico","f":"Quanto mais alguém se afasta da arcologia cardeal, mais especializados e prestigiosos serão os domínios. No alto das montanhas, magos dessa arcologia relativamente pequena combinaram seus conhecimentos sobre fogo, pedra e magnetismo para extraírem metais preciosos da terra, criando sofisticadas formas com simples gestos.","u":1},{"s":"uc9ae8c4b60","n":"Domínio sobre o Reino Material","f":"As arcologias estão conectadas pela intersecção de linhas de poder. Cada uma representa uma forma ou disciplina específica da magia elemental. As maiores abrigam dezenas de milhares de profissionais ixtalenses, com uma hierarquia social baseada no tempo dedicado aos estudos, aumentando sua progressão rumo ao domínio supremo.","u":1},{"s":"u89aba8339f","n":"O vidálio","f":"Dentro da arcologia cardeal de Ixaocan há um grande salão, propositalmente posicionado no centro exato de Ixtal e, até onde os ixtalenses sabem, de toda Runeterra. Pendurado no teto desse salão fica o Vidálio, um antigo artefato que materializa a magia em forma de trama.","u":1},{"s":"ubbf4db56b9","n":"Os axiomata","f":"Para o povo de Ixtal, o mundo nada mais é do que uma vasta confluência de forças materiais que somente eles são capazes de dominar. Cada permuta de magia elemental — da mais simples à mais complexa — é governada por um Axioma numerado, considerado sagrado pela arcologia que o ensina.","u":1},{"s":"ud60c7911d0","n":"Uma infância privilegiada","f":"Os atuais ocupantes da posição mais alta dentro dos Yun Tal foram abençoados com dez filhas, chamadas respeitosamente de \"as Yunalai\". Dada a linhagem de gerações de maestria herdada, não foi nenhuma surpresa que todas estivessem prontas para enfrentar o Vidálio ainda bem jovens.","u":1},{"s":"u649b4533e9","n":"Vestidos de poder","f":"Ao ser aceito pela casta dominante dos Yun Tal, um iniciado terá sua própria magia tecida ao seu redor pelo Vidálio, que cria vestimentas reluzentes capazes de responder às necessidades de seu portador. Essa é a prova do status de um verdadeiro mestre elemental que, por sua vez, guiará e instruirá os demais.","u":1},{"s":"lmilio","n":"Milio","f":"A Chama Gentil.\nMilio é um menino de Ixtal com um coração enorme e caloroso. Apesar da pouca idade, dominou o axioma do fogo e descobriu algo novo: o fogo tranquilizante. Com esse novo poder, Milio quer ajudar sua família a escapar do exílio unindo-se aos Yun Tal, a exemplo do que sua avó fez um dia.","l":1},{"s":"lqiyana","n":"Qiyana","f":"A Imperatriz dos Elementos.\nNa cidade-selva de Ixaocan, Qiyana planeja seu próprio e implacável caminho até o trono de Yun Tal. Última na fila para suceder seus pais, ela enfrenta qualquer um no seu caminho com uma confiança impetuosa e domínio sem precedentes sobre a magia elemental. Com a própria terra obedecendo a todos os seus comandos, Qiyana se vê como a maior elementalista na história de Ixaocan.","l":1},{"s":"wc2c8493b70","n":"Os Axiomata (arte conceitual)","w":1},{"s":"w4b1024436a","n":"Yun Tal (arte conceitual 1)","w":1},{"s":"w0651b2565c","n":"Yun Tal (arte conceitual 2)","w":1},{"s":"w240fd4d326","n":"Yun Tal (arte conceitual 3)","w":1}]},{"id":"jungle","name":"Vastaya e caçadores da selva","desc":"Quem vive entre as árvores de Ixtal e conhece a selva como ninguém: Nidalee, a caçadora, Neeko, a camaleoa vastaya, e Rengar, o caçador de troféus.","items":[{"s":"07RU012T2","n":"Neeko","f":"\"Formas e cores, cores e formas... Neeko pode ser todas elas!\""},{"s":"07SH013T4","n":"Nidalee, a Matriarca","f":"\"Os homens a chamam de Kashdaji como insulto. Mas ela comanda a selva, e eles não conseguem esconder o fato de que estão com medo.\" – Do diário de campo de Anura, dia 32"},{"s":"07SH013T6","n":"Sombra no Arbusto","f":"Nunca se sabe o que pode estar escondido nos arbustos."},{"s":"07SH009","n":"Vingador Vastayês","f":"\"Não temam, pequeninos. Eu os protegerei... e minha dívida com Nidalee será paga.\""},{"s":"lrengar","n":"Rengar","f":"O Acossador da Alcateia.\nRengar é um feroz caçador de troféus vastaya que gosta da emoção proporcionada pela caça e pelo abate de criaturas perigosas. Ele vasculha o mundo em busca das feras mais perigosas que pode encontrar, procurando principalmente por Kha’Zix, a criatura do vazio que arrancou seu olho. Rengar não persegue suas presas por fome nem por glória, mas pela simples beleza da caçada.","l":1}]},{"id":"guardians","name":"Guardiões e espíritos elementais","desc":"Os que guardam a terra de Ixtal: Skarner, o colosso de cristal, Malphite, o fragmento do Monólito, e Zyra, a flor espinhenta.","items":[{"s":"04MT008","n":"Malphite","f":"\"Última palada do tour em Tágon! É o PAPAI! Ele é o MAIOR gigante de Tágon e canta uma musiquinha bem legal. Só não tenta subir nele que senão dá cosquinha, e se ele fizer um ATCHIM quando você tiver subindo, vai cair!\"\n– Aventuras com Lasquinha, parte 6"},{"s":"04MT008T1","n":"Malphite","f":"\"Bum, bum, bum!\""},{"s":"lskarner","n":"Skarner","f":"O Soberano Primordial.\nSkarner, um Brackern ancião e colossal, é reverenciado em Ixtal como um dos membros-fundadores de Yun Tal, a casta dominante. Dedicado a manter sua nação a salvo do resto do mundo, Skarner vive em sua câmara no subsolo de Ixaocan, onde pode ouvir as vibrações da terra e detectar possíveis ameaças.","l":1},{"s":"lzyra","n":"Zyra","f":"A Ascensão dos Espinhos.\nNascida em uma antiga catástrofe mágica, Zyra é a fúria da natureza em forma física e uma sedutora criatura híbrida entre planta e humana, que faz surgir a vida a cada passo que dá. Ela vê os muitos mortais de Valoran como nada além de presas para suas crias semeadas e não sente nada ao destroçá-los em um turbilhão de farpas mortais.","l":1}]},{"id":"people","name":"O povo de Ixaocan","desc":"O dia a dia da cidade-arcologia: cada habitante aprende os Axiomata e a magia faz parte da rotina, do trabalho às mensagens memorizadas.","items":[{"s":"u964c1f0779","n":"A magia, por si só, não é o bastante para manter uma população…","f":"A magia, por si só, não é o bastante para manter uma população mortal, mas pode melhorar significativamente as condições de agricultura e caça. Com uma simples aplicação do Terceiro Axioma para criar correntes favoráveis sob a superfície, até um pescador iniciante pode pegar um peixe enorme.","u":1},{"s":"u9a021583fe","n":"A tradição exige que mensagens de grande importância sejam…","f":"A tradição exige que mensagens de grande importância sejam memorizadas, e não escritas. Esta mensageira traz um anúncio da arcologia cardeal. O Quinto Axioma acelera sua viagem e amplifica suas palavras para que todos possam ouvi-las.","u":1},{"s":"u8807eb3c33","n":"Assim que as propriedades naturais do material são descobertas e…","f":"Assim que as propriedades naturais do material são descobertas e compreendidas, ele pode ser manipulado com mais facilidade. Esculpir pedras com um martelo e um cinzel pode levar muitas horas, mas um elementalista habilidoso pode alcançar o mesmo resultado em minutos.","u":1},{"s":"u81aa0fe72a","n":"O domínio de um Axioma nem sempre protege o usuário do poder…","f":"O domínio de um Axioma nem sempre protege o usuário do poder elemental utilizado. Este metalúrgico mantém uma forja em pleno funcionamento apenas com seu sopro de fogo, mas pode queimar as mãos caso se descuide.","u":1},{"s":"ufb54f97929","n":"Os ixtalenses almejam fazer dos Axiomata parte de suas vidas…","f":"Os ixtalenses almejam fazer dos Axiomata parte de suas vidas diárias há muito tempo. Usando o Décimo Sexto Axioma, este minerador consegue erguer pedras do chão e carregá-las como se fossem meras plumas.","u":1},{"s":"u238b514122","n":"Protegida por magia e isolamento, Ixtal não precisa de exércitos.","f":"Protegida por magia e isolamento, Ixtal não precisa de exércitos. O mais próximo que eles têm de soldados profissionais são os guardiões do caminho de Ixaocan, que patrulham constantemente as linhas de poder entre as arcologias, serviço pelo qual recebem muito respeito.","u":1}]}],"places":[{"s":"uba785e5885","n":"Ixaocan","f":"Na verdade, Ixtal não é a floresta sem habitantes que muitos imaginam. Longe de olhares indiscretos e dedos gananciosos, as vastas arcologias do Ixaocan permanecem escondidas e seguras pelas mais vastas florestas tropicais. A arcologia cardeal, sede da casta governante Yun Tal, já existia antes mesmo que os antigos shurimanes erguessem seu primeiro Disco Solar.","u":1},{"s":"u7c1f5679d4","n":"Uma fronteira inexplorada","f":"Quem está fora das fronteiras ixtalenses sabe muito pouco sobre a história da região. Ao longo dos anos, incontáveis expedições de Noxus, Águas de Sentina e, mais recentemente, do Clube de Exploradores de Piltover mergulharam na floresta em busca de tesouros misteriosos ou novas reivindicações territoriais... apenas para desaparecerem sem deixar o menor rastro.","u":1}],"creatures":[{"s":"07SH038","n":"Filhote Pakaa","f":"A fofura é uma aparência, mas a ferocidade é um instinto. Com tempo e aprendizado, até mesmo o menor dos pakiti se torna forte e selvagem."},{"s":"uef3f3abed7","n":"Os dragões elementais","f":"Curiosamente, as ruínas abandonadas e espalhadas por toda Ixtal abrigam um número surpreendente de dragões. Essas criaturas apavorantes não lutam ao lado dos mortais desde os últimos dias da guerra de Shurima contra o Vazio. Agora, em sua maior parte, parecem satisfeitas por serem deixadas em paz.","u":1}]},"shurima":{"groups":[{"id":"empire","name":"O Império e os Ascendidos","desc":"Azir voltou e quer reconstruir o império. Ao seu lado e contra ele, os Ascendidos: Nasus, Renekton, Xerath.","items":[{"s":"04SH003T5","n":"Arauto Dourado","f":"Mais poderoso do que nunca, Azir reergueu seus soldados mais leais para liderar os exércitos."},{"s":"04SH058","n":"Artífice das Areias","f":"Poucos aprendem os mistérios do deserto, e quase ninguém consegue comandar suas areias como Azir. Dominar esse poder e conhecer os segredos das areias é uma dádiva concedida apenas aos seguidores mais fiéis e capazes de Azir."},{"s":"04SH003T2","n":"Azir","f":"\"Apesar da soberba, o imperador Azir também é generoso. Ele se preocupa, acima de tudo, com todos que marcham ao seu lado em direção ao futuro esplêndido de Shurima. Enquanto isso, a nação cresce, e o povo se une mais uma vez sob seu comando.\"\n– Escriba Kah'nir, História do Batalhão dos Ascendentes"},{"s":"04SH003T3","n":"Azir","f":"\"Pouco antes de Azir cumprir seu destino, seu amigo de longa data, a quem recentemente chamara de 'irmão', foi tomado pelo ódio e o empurrou do platô. Nesse fatídico momento, Shurima foi amaldiçoada à ruína por milhares de anos.\" – Escriba Kah'nir, História do Batalhão dos Ascendentes"},{"s":"04SH003T14","n":"Combatente de Arenito","f":"\"Aquelas criaturas feitas de redemoinhos de areia apareceram do nada! E, depois de acabar com nossos grupos, elas simplesmente... desapareceram, se fundindo com o deserto.\" – Sobrevivente do Deserto"},{"s":"04SH101","n":"Conselheiros Devotos","f":"\"Jurei fidelidade a Azir e a Shurima, meu lar! Não vai fazer o mesmo?\""},{"s":"08SH005","n":"Defensores do Disco Solar","f":"\"Somos os guardiões do deserto eterno, a história viva, os andarilhos da trilha do esplendor. Nos ajoelhamos perante o Disco Solar e nada mais, para que o mundo se ajoelhe diante da glória de Shurima.\" – Azir"},{"s":"04SH102","n":"Embaixadora Dourada","f":"\"Nosso futuro glorioso está sob as areias, e cabe a nós pavimentar o caminho para Azir. O império dourado do deserto renascerá!\""},{"s":"07SH023","n":"General das Areias Caídas","f":"\"Embora talvez você não passe de grãos de areia para esse inimigo, eu te vejo. Sinto sua presença nas dunas. Compartilhe sua força comigo, e vamos destruir nossos inimigos juntos!\""},{"s":"08SH004","n":"General das Dunas","f":"Os vastos exércitos de Shurima estão prontos para provar o poder do deserto. Quando a ordem é dada, eles avançam sem hesitação."},{"s":"04SH003T8","n":"Gladiador Eterno","f":"\"Contemplem! Estão vendo como nosso Campeão permanece firme sobre o leão? Até mesmo o rei da selva sucumbe ao seu poder, pois ele representa a Vontade de Azir!\" – Voz dos Reerguidos"},{"s":"04SH003T11","n":"Guarda do Imperador","f":"A guarda dourada do imperador avança com coordenação ímpar, e seus guerreiros disciplinados causam tanto pavor quanto admiração a todos que os observam."},{"s":"04SH012","n":"Hierofante Consagrado","f":"\"Olha lá! É Padjuman, um dos anciãos de Nashramae! Eu acho que todo mundo veio aqui pra cidade, papai!\" – Espectador empolgado"},{"s":"04SH057","n":"Marechal Inspiradora","f":"Receber a bênção de Azir é uma grande honra. Dar uma bênção em nome dele, uma honra maior ainda."},{"s":"04SH047T2","n":"Nasus","f":"\"Com as esperanças renovadas pela ascensão de Shurima, depois de anos vagando pelo deserto, Nasus voltou para fazer as pazes com seu irmão. O que ele não esperava era encontrar Renekton, aguardando por ele, enlouquecido por anos de sofrimento nas mãos de Xerath na tumba.\" – Escriba Kah'nir, História do Batalhão dos Ascendentes"},{"s":"04SH047T3","n":"Nasus","f":"\"Nasus e seu irmão Renekton serviram ao império por muitos anos. Nasus era um estudioso; Renekton, um bravo guerreiro. Quando os dois precisaram enfrentar o traidor Xerath, Nasus foi forçado a fazer uma escolha terrível...\" – Escriba Kah'nir, História do Batalhão dos Ascendentes"},{"s":"04SH072","n":"Profetisa","f":"\"Ah, você não esperava encontrar água no meio do deserto, né? Não se preocupe. Venha, beba um pouco, lave os pés. Descanse na sombra. A nova Shurima de Azir é um verdadeiro oásis.\""},{"s":"04SH046","n":"Quimera de Arenito","f":"Quando Azir voltou, os shurimanes viram feras lendárias que, apesar de serem de areia, eram muito impressionantes."},{"s":"09SH010","n":"Reconstrutora do Império","f":"A ascensão do Imperador deu esperança a Shurima. Determinada a ajudar a concretizar a visão de Azir, essa maga autointitulada \"Reconstrutora do Império\" viaja pelo deserto com o intuito de restituir as ruínas enterradas ao seu antigo esplendor."},{"s":"04SH067","n":"Renekton","f":"\"É muito fácil esquecer que um dia ele já foi humano, pois a imagem crocodiliana lhe cai muito bem, dado o amor pela crueldade da batalha...\" – Escriba Kah'nir, História do Batalhão dos Ascendentes"},{"s":"04SH067T1","n":"Renekton","f":"\"Quando ele finalmente tiver a chance de se vingar de seu irmão Nasus, nada impedirá Renekton. Ele destruirá tudo, e Shurima retornará às ruínas.\" – Escriba Kah'nir, História do Batalhão dos Ascendentes"},{"s":"04SH067T4","n":"Renekton","f":"“Todos os anos na escuridão com aquele traidor, que encheu a cabeça dele com palavras de ódio e ressentimento, alimentando o desprezo dele pelo irmão, só alimentaram sua raiva e o tornaram mais forte.\" – Escriba Kah'nir, História do Batalhão dos Ascendentes"},{"s":"06SH055","n":"Sacerdotisa da Luz do Deserto","f":"Os fiéis se mantêm firmes conforme o mal se aproxima, oferecendo seus últimos suspiros para invocar a luz da justiça. Eles sabem que esse chamado desesperado por salvação será atendido antes que a escuridão consuma tudo."},{"s":"04SH003T1","n":"Soldado de Areia","f":"As legiões de Azir já eram conhecidas por serem imbatíveis mesmo antes do renascimento de Shurima – porém, agora, são realmente imensuráveis."},{"s":"04SH026","n":"Vigilante das Dunas","f":"\"O imperador comanda. Eu e a areia obedecemos.\""},{"s":"04SH077","n":"Voz dos Reerguidos","f":"\"Tempos atrás, eu a ouvi falar.\" O velho soldado sorriu e, por um instante, sua neta conseguiu imaginar: Shurima, dourada e reluzente, com o imponente Azir governando a cidade anunciada pela Voz dos Renascidos. \"Ela resgatou em nós uma paixão há muito adormecida.\""},{"s":"lrammus","n":"Rammus","f":"O Tatu Blindado.\nIdolatrado por muitos, dispensado por alguns e misterioso para todos, Rammus é um ser curioso e enigmático. Protegido por um casco espetado, ele inspira teorias cada vez mais divergentes sobre sua origem por onde quer que passe — de semideus, a oráculo sagrado, a uma fera qualquer que foi transformada por magia.","l":1}]},{"id":"mercs","name":"Mercenários e caçadores de tesouros","desc":"Gente que vive das ruínas e dos contratos do deserto. Sivir é a mercenária mais cara de Shurima.","items":[{"s":"08SH012","n":"Barbara, a Caçadora de Relíquias","f":"\"Bom trabalho, Barb. Sabia que podia contar com você. Espera! Como assim eles te viram?!\" – Brutamontes de Vekaura"},{"s":"04SH056","n":"Barganhadora","f":"\"Meu amigo, consegui para você esta raridade de beleza incomparável na lendária Tumba dos Imperadores e a retirei das mãos do grande Renekton. Na saída, fui cercada por dez, vinte cavaleiros montados em saurens sedentos de sangue! É um verdadeiro milagre que essa relíquia tenha vindo parar nas suas mãos.\""},{"s":"04SH129","n":"Brutamontes de Vekaura","f":"''Pronto, Barb. Esse era o último guarda deste andar, mas ainda precisamos ter cuidado.''\n''BLARGH-BLAAA!''\n''Fale baixo, Bárbara.''\n''Blarb.''\n''É isso aí, garota.''"},{"s":"04SH103","n":"Caçadora Implacável","f":"\"E... pronto. Bem amarradinho. Renekton gosta quando suas refeições ainda estão se contorcendo.\""},{"s":"04SH055","n":"Exploradora das Ruínas","f":"Antes de tentarem a sorte nas criptas, os mercenários e saqueadores de tumbas de Shurima precisam aprender a enfrentar as ameaças mais difusas do deserto. Primeiro, o calor escaldante. Depois, os inúmeros incursores dispostos a fazer carnificina."},{"s":"07SH003","n":"Furtivista de Dirigível","f":"\"Rá! Tentem me pegar agora, suas feras tolas. Nem a gravidade pode derrotar a espécie superior!\""},{"s":"04SH125","n":"Larápia de Vekaura","f":"Tena esperou pacientemente até a saliva cáustica de seu bichinho corroer as grades douradas do portão dos fundos do palácio. Ela estava prestes a encontrar um tesouro de valor inestimável; mais que suficiente para restituir a antiga glória de Vekaura."},{"s":"04SH015","n":"Raz Sanguescama","f":"\"Quando esse crocodilão nasceu, fizeram apostas pra adivinhar quanto tempo ele sobreviveria. Diziam que ele era uma aberração, o fracote da ninhada... mas ninguém pensou que ele acabaria devorando todos os irmãos. Hehe.\""},{"s":"04SH005","n":"Saqueador Sanguinário","f":"Os Escavareias fazem tudo com os companheiros: lutam, caçam, matam... e se alimentam."},{"s":"04SH020T1","n":"Sivir","f":"\"Se quiser trabalhar comigo, vai ter que ouvir o que eu falo pra todo mundo: faça sua parte e receberá tudo que trabalhou pra conquistar. Mas, se me atrapalhar ou ficar no meu caminho, eu mesma te mato.\""},{"s":"04SH032","n":"Trituradora Impiedosa","f":"O soldado, com a força que lhe restava, tentou pegar a lança, mas aquela mulher aplicou ainda mais força sobre seu peito, até ele desistir. \"Nada disso\", repreendeu ela, mostrando os dentes afiados em um sorriso perverso. \"Agora ela é minha.\""}]},{"id":"nomads","name":"Nômades, saqueadores e catadores","desc":"Os que sobrevivem no deserto: tribos nômades, salteadores, catadores e os montadores de dormuns.","items":[{"s":"ua0a954bdc1","n":"Catadores","f":"Os catadores de Shurima vivem pilhando comida, itens valiosos e mercadorias. Em geral, eles adentram as ruínas de cidades abandonadas e destruídas pela areia. Catadores são os principais alvos para saqueadores quando se locomovem a pé, então eles normalmente montam em nadadores da areia para evitar emboscadas.","u":1},{"s":"u78e81bd3b9","n":"Habitantes de classe alta da cidade","u":1},{"s":"u101d1e8438","n":"Habitantes de classe baixa da cidade","u":1},{"s":"uc1c13895fb","n":"Montadores de Dormuns","f":"Os montadores de dormuns usam ganchos em garra para atravessar a complexa série de cordas que conecta as habitações da vila móvel. Assim que um deles fica velho demais para “andar pelas cordas”, eles são levados até o chão para viver pelo resto de seus dias como um habitante da terra.","u":1},{"s":"ufeee8dd532","n":"Os Perdidos","u":1},{"s":"ueec2d5324f","n":"Os Shakkal","f":"Estes salteadores nômades são conhecidos por sua agilidade, usando suas braçadeiras de osso endurecido e lanças para se lançarem contra suas vítimas em velocidades aterrorizantes.","u":1},{"s":"ufcb9b51b49","n":"Saqueadores","f":"Os saqueadores de Shurima sobrevivem não através do comércio, mas da violência. Esses bandos normalmente tentam se esconder no ambiente a fim de atrair viajantes incautos para armadilhas antes de matá-los, levando seus pertences e, em casos muito raros, comendo-os.","u":1}]},{"id":"time","name":"Os guardiões do tempo","desc":"Zilean e os que estudam a magia do tempo, entre relógios, profecias e ruínas de Urtistan.","items":[{"s":"04SH034","n":"A Mão do Relógio","f":"O constante ruído nos níveis inferiores da torre são causados pela Mão do Relógio, o guardião que controla as engrenagens lá embaixo."},{"s":"04SH001","n":"Aprendiz de Cronomante","f":"Durante seu dias como estudante de cronomancia, Tai precisou aprender a conciliar a incerteza com a determinação. Era melhor depositar esperança em uma possível vitória do que ficar pensando no que poderia dar errado."},{"s":"04SH044","n":"Curador Mecanizado","f":"As estruturas que protegem a torre de Zilean são capazes de suportar a rigidez do deserto por milênios – e não é só por conta da construção engenhosa."},{"s":"04SH091","n":"Khahiri, o Aluno","f":"\"Lembre-se do que aprendemos\", disse Zilean, com a voz mais suave do que o normal. \"Tem certeza de que está pronto?\"\nKhahiri abriu um sorriso confiante para o mentor. \"Eu volto logo. Além disso, passei anos me preparando para este momento. Se não agora, quando?\""},{"s":"04SH021","n":"Khahiri, o Regressado","f":"Khahiri sumiu por apenas um instante antes de reaparecer repentinamente. Recebido por suspiros de surpresa e preocupação, ele estava praticamente uma década mais velho e empunhava uma arma estranha de aparência letal."},{"s":"04SH011","n":"Pesquisadoras de Xenótipo","f":"O Vazio traz consigo inúmeras surpresas. Crescendo ininterruptamente e encontrando cada vez mais formas de se infiltrar na torre, assemelha-se a um espinheiro invasivo, mas é infinitamente mais letal. Infelizmente, estudá-lo é algo difícil de se fazer, já que é preciso ter pesquisadores hábeis e talentosos que possam entender e prever sua ameaça."},{"s":"04SH104","n":"Preservacionista","f":"Sempre que quer um momento de paz, Zilean volta ao último jardim de Icathia, ainda intocado."},{"s":"04SH014","n":"Relologi","f":"Os Relologi foram os primeiros a se mexer, exatamente na hora em que Zilean programou que acordassem. Eles sacudiram seus corpos e começaram a descer os muros antigos, procurando outros iguais a eles."},{"s":"04SH039T1","n":"Zilean","f":"No passado e no futuro, infinitas possibilidades se apresentavam. Ele via todas elas ao mesmo tempo. Um conjunto vertiginoso que só ele podia decifrar. Com um só gesto, Zilean revelava épocas inteiras, mas nenhuma mostrava como salvar Icathia."}]},{"id":"taliyah","name":"Taliyah e as tecelãs de pedra","desc":"A tecelã de pedras que deixou Noxus para proteger seu povo, e quem molda a terra do deserto.","items":[{"s":"04SH089","n":"Naturalista do Deserto","f":"\"Kadira quebrou outra coisa hoje! Dessa vez, foi só uma parede de pedra, mas ela parecia bem antiga e deve ter sido importante para os antepassados de alguém. Ela tentou se safar dizendo que, em Tereshni, as paredes eram mais resistentes! Enfim, fiquei superirritada!\"\n– Diário de Zaifa"},{"s":"06SH051","n":"Pastora de Pedregursos","f":"\"Os rochidos tratam Sadira como se fosse uma deles. Ela fugiria com eles em um piscar de olhos se eu deixasse, a pestinha!\" – Kadira, Naturalista do Deserto"},{"s":"04SH038","n":"Saltador de Pedras","f":"“Hoje, iniciamos nossa jornada até Nashramae! Samir quer atravessar o Grande Sai antes da próxima lua cheia e está destruindo TUDO pela frente! Eu não sabia que uma simples prancha podia derrubar uma duna inteira. O Sami também não, mas ele está bem.\"\n– Diário de Zaifa"},{"s":"04SH073T2","n":"Taliyah","f":"Taliyah deixou Ionia quando soube que sua terra natal havia passado por enormes transformações. Ela voltou para Shurima e encontrou um imperador renascido, seu povo pleno, e os xer'sai mais ativos do que nunca. Assim, sua única escolha foi amadurecer rápido."},{"s":"04SH041","n":"Vigilante do Sai","f":"\"Hoje tivemos problemas! Uma tempestade enorme começou a dar as caras pelo oeste, e Taliyah atravessou túneis xer'sai rumo ao sul. Eu descobri um templo ao norte, e agora estamos protegidos pelos muros de terracota. Os outros já estão dormindo, e as chamas, assim como eu, estão se esgotando. Espero ter bons sonhos.\"\n– Diário de Zaifa"}]},{"id":"baccai","name":"Os Baccai","desc":"Ascendentes falhos de Shurima: quando a ascensão fracassou, sobraram criaturas retorcidas pelo que poderiam ter sido. Alguns ainda guardam santuários e relíquias do império.","items":[{"s":"04SH009","n":"Baccai Enfurecido","f":"Quem guarda rancor alimenta cada vez mais esse sentimento, mesmo que os responsáveis por ele já estejam mortos há muito tempo."},{"s":"06SH005","n":"Baccai Esquecido","f":"Ele segurava um cinto trançado, um presente que recebeu de seu amigo Rhaast antes da cerimônia de Ascensão de ambos — mas, mesmo que reverenciasse o poder do Darkin, também guardava um ressentimento que escondia em seu coração bestial."},{"s":"04SH002","n":"Ceifeiro Baccai","f":"\"Todos os baccai fugiram ou foram poupados de seu sofrimento após Ascensões malsucedidas, e ninguém nunca os viu desde então. Quem sabe há quanto tempo estão escondidos naquelas tumbas sombrias carregando o peso de seu fracasso?\" – Escriba Kah'nir, História do Batalhão dos Ascendentes"},{"s":"06SH037","n":"Definharra Baccai","f":"A sanidade deles definhou como dunas ao vento. Em seu lugar, uma semente de raiva cresceu e virou uma fúria que nem as águas do deserto puderam aplacar."},{"s":"04SH081","n":"Fiandeira Baccai","f":"Cada grão derrubado por ela rouba-lhes um segundo da vida, que se esvanece como areia ao vento."},{"s":"04SH097","n":"Guardiã do Sacrário","f":"Os baccai são responsáveis por defender o sacrário interior, proteger os tesouros antigos que estão lá dentro e zelar pelos mortais que se acham espertos ou poderosos demais para resistir ao peso do julgamento do Curador."}]},{"id":"xerath","name":"Xerath e seus acólitos","desc":"O mago ascendido preso por Azir e os que se entregaram a ele em troca de poder, e agora erguem obeliscos pelo deserto.","items":[{"s":"05SH016","n":"Acólito Ruinoso","f":"Todos os acólitos de Xerath sacrificaram algo em troca de poder, mas seus seguidores mais poderosos foram ainda mais além. Eles se tornaram meras sombras das pessoas que um dia já foram, transformando-se em conduítes e fontes de energia para seu novo imperador."},{"s":"05SH017","n":"Arauta do Mago","f":"Enquanto erguia o olhar em direção ao sol vermelho que pairava nos céus de Shurima, a Arauta abriu os braços e entoou aos ventos: \"Viva o Mago Ascendente!\". Sua voz ecoava pelo círculo de colunas destruídas que jaziam ao seu redor. \"Viva Xerath!\""},{"s":"05SH012T1","n":"Dami'yin, o Liberto","f":"\"Devemos usufruir da energia mágica que a terra fornece em seus focos de poder e aprimorar os exércitos do nosso grande imperador!\" – Arauta do Mago"},{"s":"05SH011","n":"Devoto Eterno","f":"Por mais que a tumba fosse recheada de riquezas, isso pouco importava aos olhos dos mortos e exilados."},{"s":"05SH002","n":"Errante das Ruínas","f":"Os acólitos já eram bem-sucedidos antes de buscar Xerath. Mas, agora que tinham estudado o que ele um dia estudou, eram imbatíveis."},{"s":"05SH015","n":"Vidente das Areias","f":"O horizonte à frente vibrava com energia — onde outros viam apenas areia e sedimentos, ela enxergava linhas energéticas, malhas ofuscantes de pura energia que jaziam ali, ao seu dispor."},{"s":"05SH014T1","n":"Xerath","f":"\"Se Xerath soubesse que Azir planejava libertá-lo de seu aprisionamento, talvez Shurima não tivesse caído... mas parte da humanidade dos mortais sempre sucumbe ao ritual de Ascensão — e qualquer perdão ou clemência que o mago um dia tivera foram apagados de sua mente.\"\n– Escriba Kah'nir, História do Batalhão dos Ascendentes"},{"s":"05SH014T2","n":"Xerath","f":"\"Xerath cultivou as sementes da vingança durante anos, tramando contra Azir em meio à escuridão da Tumba dos Imperadores. Lá, ele alimentava seu desejo de reunir acólitos conhecedores de seus caminhos arcanos para montar seu exército e ver Shurima moldada à sua imagem. Agora, o Mago Ascendente marcha mais uma vez por uma Shurima revivida por Azir.\"\n– Escriba Kah'nir, História do Batalhão dos Ascendentes"}]},{"id":"outros","name":null,"desc":null,"items":[{"s":"06SH034","n":"Dominação","f":"Às vezes, tudo o que o poderoso quer é se sentir impotente."},{"s":"07SH018","n":"Guardião do Segredo","f":"Ele não sabia exatamente o que tinha visto, que forma a calamidade poderia assumir, nem quando... mas conhecia este mundo e seu povo. Eles não estão prontos. Talvez nunca estejam."},{"s":"uc853d93096","n":"A filha de Setaka, ascendeu como Hierofante de Zuretta","u":1},{"s":"lamumu","n":"Amumu","f":"A Múmia Triste.\nReza a lenda que Amumu é uma alma solitária e melancólica da antiga Shurima que vaga sem rumo pelo mundo em busca de um amigo. Amaldiçoado por um feitiço ancestral para permanecer só pela eternidade, seu toque traz a morte e sua afeição, a ruína. Aqueles que afirmam já tê-lo visto o descrevem como um morto-vivo franzino e coberto por faixas asquerosas.","l":1}]}],"places":[{"s":"05SH012","n":"Altar Erguido","f":"\"Devemos erguer um obelisco em cada foco de poder — um instrumento que o grande Mago Ascendente poderá usar para extrair poder direto das areias.\" – Arauta do Mago"},{"s":"04SH006","n":"Areias Instáveis","f":"Séculos de passos mal trilhados ensinaram os shurimanes a ler bem as areias. Apenas eles sabem quais áreas se manterão firmes e quais cederão sob seus pés. Para os leigos, tudo parece igual."},{"s":"06SH032","n":"Arsenal Enterrado","f":"\"Por que você fica fuçando tudo?\"\n\"Ué, você acha que são armadilhas? E que uma pedra vai aparecer do nada pra...\"\n\"CORREEEE!\"\n– Argus e Silvio, ladrões de túmulos"},{"s":"04SH060T1","n":"Bomba-relógio","f":"Usar o tempo \"de forma produtiva\" também pode significar \"de forma destrutiva\"."},{"s":"06SH036","n":"Cripta da Renovação","f":"Nasus emergiu do sarcófago com a mente limpa e as feridas completamente curadas. Ele rabiscou umas palavras e espiou os sarcófagos acima do seu, imaginando qual seria o estado mental das aberrações que ali estavam. Só o tempo diria se essa magia seria capaz de devolver a sanidade aos Baccai. Uma magia contestada pelos outros Ascendentes. Mas eles não estavam mais lá, e Renekton e sua loucura estavam."},{"s":"04SH062T1","n":"Disco Solar Restaurado","f":"\"Hoje é o dia mais glorioso da história de Shurima. Venha e absorva a luz do nosso sol!\" – Voz dos Renascidos"},{"s":"04SH062","n":"Disco Solar Soterrado","f":"Quando Azir avistou o Disco Solar da capital shurimane, ele não enxergou meramente o que era, mas o que poderia vir a ser: a chave para restaurar a antiga glória de Shurima."},{"s":"04SH076T1","n":"Estátua de Estase","f":"\"Isso é o que eu chamo de 'capturar o momento'.\"\n\"Rá. Pode crer.\"\n– Xetsa e Zinsa, Pesquisadoras do Vazio"},{"s":"06SH035","n":"O Altar de Sangue","f":"O altar pulsava com vida mais uma vez, sacudindo a areia ao redor com uma batida lenta e constante. Cada um dos discípulos de Xolaani sentia a mesma batida no fundo do coração. Cada músculo, pensamento, momento... estava sob o controle dela."},{"s":"05SH003","n":"Obelisco do Poder","f":"Pilares faiscantes e crepitantes ergueram-se das areias, locais de poder subvertidos que reforçariam o já poderoso exército de Xerath."},{"s":"04SH003T10","n":"Palácio do General","f":"\"Contemple nosso deus-imperador! Ele conhece o poder destas terras como ninguém, e seu exército não para de crescer. Shurima se reergueu para nunca mais cair!\" – Voz dos Reerguidos"},{"s":"04SH130T1","n":"Palácio do Senhor da Guerra","f":"''Está vendo aquele edifício horrível? É lá que aquele porco mora. Vamos rendê-lo, saquear tudo e voltar a tempo do jantar.'' – Errante de Vekaura"},{"s":"04SH024","n":"Pináculo de Sal","f":"Os shurimanes que trabalham com sal aprendem rápido a reconhecer quais depósitos são bons para coleta e quais devem ser deixados em paz."},{"s":"04SH028","n":"Preparativos Ancestrais","f":"Alguns podem pensar que os autômatos se perderam no tempo, enterrados sob anos de areia acumulada. Na verdade, eles foram estrategicamente posicionados, e apenas esperam o momento do despertar."},{"s":"04SH013","n":"Preservário","f":"Zilean mostra aos que traz à torre o que, de fato, estão tentando restaurar. O Preservacionista consegue lhes mostrar tudo, mesmo que apenas por um breve momento."},{"s":"06SH046","n":"Relicário do Acólito","f":"\"Nossas mãos moldam o deserto!\" – Acólito Ruinoso"},{"s":"04SH048","n":"Sacrário Interior","f":"\"Alguns mapas levam anos para serem decifrados, algumas armadilhas levam meses para serem desmontadas, e algumas criptas levam semanas para serem exploradas. Mas, quando finalmente conseguimos, vemos que cada segundo valeu a pena.\" – Sivir"},{"s":"05SH011T2","n":"Sarcófago","f":"Mesmo sendo usada como prisão para conter Xerath, a Tumba dos Imperadores nunca perdeu sua exuberância. A beleza do lugar e da estrutura que o prendia era apenas uma forma de lembrar como ele caíra em desgraça, retido numa prisão ornamentada."},{"s":"04SH105","n":"Tumba Arenosa","f":"Enquanto eles passavam pelo desfiladeiro, a Artífice das Areias entoou as palavras mágicas. Uma rajada de vento ecoou pelo cânion e se voltou contra a trovoada de cascos galopantes."},{"s":"07SH046","n":"Vale da Imitação","f":"''E essa é minha palada favolita e a MAIS BO-NIII-TA do passeio. Tanta gente gostou do meu passeio aquele dia que constluílam um LASQUINHA GLANDÃO E PODELOSO, e ele vai fazê palte do passeio pla semple. Fala \"OI, LASQUINHAZÃO'', pessoal! O Lasquinhazão ama TODO mundo, plincipalmente quem veio no passeio dele.''\n– Aventuras com Lasquinha, parte 6"},{"s":"u4c5409b367","n":"A areia recua, e Shurima renasce.","u":1},{"s":"ud77d16290d","n":"A Planície Perene","u":1},{"s":"u5e7aeb316e","n":"Cascata Zoantha","f":"Sabe-se que o movimento das dunas do deserto pode talhar caminhos através das pedras, escorregando pelos penhascos em grandes cachoeiras de areia. Tradicionalmente, os shurimanes atiram objetos queridos nas areias como presentes para os Ascendentes. Por causa disso, essas cascatas são bons locais para caçadores de tesouros lucrarem.","u":1},{"s":"u1d4c71019c","n":"Cascata Zoantha","f":"Sabe-se que o movimento das dunas do deserto pode talhar caminhos através das pedras, escorregando pelos penhascos em grandes cachoeiras de areia. Tradicionalmente, os shurimanes atiram objetos queridos nas areias como presentes para os Ascendentes. Por causa disso, essas cascatas são bons locais para caçadores de tesouros lucrarem.","u":1},{"s":"u4b6299376f","n":"Mercado Medumarca","u":1},{"s":"ub2d2712f84","n":"O disco solar reconstruído nas ruas de Nashramae","u":1},{"s":"u08b690d2a6","n":"O povo de Shurima voltou ao seu lar ancestral.","u":1},{"s":"u07cfe2e38e","n":"O Vale da Canção","f":"O nome desta passagem remota vem dos assobios desorientadores que surgem quando o vento passa forte o suficiente pelas estruturas ocas de pedra. Muitos viajantes desavisados se viram à mercê dos saqueadores surdos que espreitam o vale durante a noite.","u":1},{"s":"ud2926be89d","n":"Shurima, renascida das areias para se banhar novamente na luz do sol","u":1},{"s":"wd2d99e5b93","n":"Shurima (arte conceitual 1)","w":1},{"s":"wf8ba4570e4","n":"Shurima (arte conceitual 10)","w":1},{"s":"w77d098218b","n":"Shurima (arte conceitual 11)","w":1},{"s":"w864775a769","n":"Shurima (arte conceitual 12)","w":1},{"s":"we0caa7b9ec","n":"Shurima (arte conceitual 13)","w":1},{"s":"wb2b0ccbaf9","n":"Shurima (arte conceitual 14)","w":1},{"s":"wc369ca79b8","n":"Shurima (arte conceitual 2)","w":1},{"s":"w298e6d8b9a","n":"Shurima (arte conceitual 3)","w":1},{"s":"w4d2501c583","n":"Shurima (arte conceitual 4)","w":1},{"s":"wf0cdcc7961","n":"Shurima (arte conceitual 5)","w":1},{"s":"w457dd35de6","n":"Shurima (arte conceitual 6)","w":1},{"s":"wac8e2316b8","n":"Shurima (arte conceitual 7)","w":1},{"s":"wceaaf3b187","n":"Shurima (arte conceitual 8)","w":1},{"s":"w2a16047cf1","n":"Shurima (arte conceitual 9)","w":1}],"creatures":[{"s":"07SH044","n":"Aurora Alucinati","f":"\"Como eu gostaria de ver uma! A maioria dos expedicionários acredita que Auroras Alucinati sejam um mito, mas um jovem jura que não. Ele me disse que a ave tem cores vivas e uma envergadura tão larga quanto a altura de um homem. Olhar nos olhos dela, ele me confidenciou uma noite, é entender que você é a presa.\" – Do diário de campo de Anura, dia 21"},{"s":"04SH137","n":"Enxame Ruidoso","f":"Acreditava-se que os escaravelhos gigantes tinham sumido junto com o império Shurimane. Mas ramos rastejantes da Névoa se infiltraram nas areias e os arrancaram de lá para servirem a Viego."},{"s":"08SH014","n":"Hordamante Cornífero","f":"Apesar do tamanho intimidante, esse hordamante raramente é violento. Quando a horda se aproxima de um assentamento shurimane, os moradores deixam oferendas de frutas frescas no deserto próximo para distrair os visitantes de plantações mais importantes."},{"s":"07SH043","n":"Parofante Grandioso","f":"Como seus residentes mais antigos, alguns dizem que parofantes guardam a memória e o coração da própria selva. Embora normalmente sejam criaturas gentis, eles não hesitarão em defender seu lar contra qualquer ameaça, grande ou pequena."},{"s":"04SH042","n":"Pedregurso Hibernado","f":"\"MEU NOME É ZAIFA, E EU GOSTO DE ESCREVER COISAS SEM GRAÇA NO MEU DIÁRIO SEM GRAÇA QUANDO ACHO QUE TODOS ESTÃO DORMINDO. ATÉ O SAMI.\"\n– Diário de Zaifa"},{"s":"07SH040","n":"Porcouriço","f":"\"Pequenos mamíferos onívoros cobertos por espinhos semelhantes a cerdas, que podem ser liberados em alta velocidade quando perturbados. A cauda é farpada e ágil, provavelmente usada como arma defensiva. De acordo com expedicionários experientes, as criaturas são notoriamente rabugentas e difíceis de lidar...\" – Do diário de campo de Anura, dia 3"},{"s":"u874325c69c","n":"Nadadores da Areia","f":"Essas criaturas gigantescas atravessam o deserto em padrões cíclicos, alimentando-se de insetos e de outras criaturas pequenas que a maior parte dos animais do deserto ignora. Catadores às vezes memorizam os caminhos previsíveis dessas criaturas e pulam em suas costas para andar nelas até onde quiserem.","u":1},{"s":"u65e3c56b81","n":"No Topo dos Dormuns","f":"Alguns shurimanes escolheram viver sua existência nômade no topo de criaturas gigantes e lentas conhecidas como dormuns. Protegidos por placas de quitina, os dormuns evoluíram para sobreviver à seca eterna e condições severas de Shurima.","u":1},{"s":"ue4a1e5b0f2","n":"Skallashi","f":"Animais de carga resistentes e comuns em toda Shurima, os skallashis são perfeitos para o ambiente severo do deserto. Eles são famosos por seu temperamento ruim, mas, ainda assim, são tratados com grande veneração e é normal que sejam pintados com símbolos sagrados de proteção e seus chifres enfeitados com totens e amuletos. Ser dono de um é visto como um sinal de prosperidade considerável.","u":1},{"s":"we441ac751a","n":"Criatura de Shurima (arte conceitual 1)","w":1},{"s":"w4234954946","n":"Criatura de Shurima (arte conceitual 2)","w":1},{"s":"w58632832bc","n":"Criatura de Shurima (arte conceitual 3)","w":1}]},"void":{"groups":[{"id":"prophets","name":"O culto e o profeta do Vazio","desc":"Mortais que ouviram o chamado do Vazio e o seguem como profecia. Malzahar, o Profeta do Vazio, guia seus fiéis; o Arauto da Colmeia fala com quem escuta.","items":[{"s":"06SH016","n":"Arauto do Enxame","f":"\"Falou comigo... como se me conhecesse. Como se quisesse me mostrar... alguma coisa...\" – Kai'Sa"},{"s":"lmalzahar","n":"Malzahar","f":"O Profeta do Vazio.\nFervoroso vidente dedicado a unificar toda a vida, Malzahar acredita piamente que o recém-emergente Vazio é o caminho para a salvação de Runeterra. Nas terras remotas de Shurima, ele seguiu as vozes que sussurravam em sua mente, até chegar à antiga Icathia. Entre as ruínas daquela terra, ele olhou para o coração sombrio do Vazio e recebeu novos poderes e um propósito.","l":1}]},{"id":"touched","name":"Tocados pelo Vazio","desc":"Mortais que carregam o Vazio na própria carne, por escolha ou azar, e quem decidiu enfrentá-lo. Kai'Sa, a Filha do Vazio, divide o corpo com uma segunda pele viva; Kassadin, o Caminhante do Vazio, caça rupturas pelo mundo; os belvethianos conhecem o enxame de perto.","items":[{"s":"06SH008","n":"Anciã Belvethiana","f":"Shalatai se espantou diante de tanto horror. Lá estava Ferai, a filha do açougueiro, esmagada. Ao lado dela estava Gorrub, o filho do pescador, ainda esticando as mãos sem vida para alcançar seu amor. Tantas memórias desfeitas. Tantas vidas perdidas. Com desgosto, Shalatai voltou-se para o mal, pronta para dar a vida para salvar o resto de seu povo."},{"s":"06SH010","n":"Detonadora do Vazio","f":"A erupção do Vazio na cidade de Belveth foi ao mesmo tempo repentina e aterrorizante. A maioria dos civis ficou apavorada com o caos que tomou conta da cidade e fugiu o mais rápido possível. A maioria, mas não Koyemi."},{"s":"06SH009T2","n":"Kai'Sa","f":"Kai'Sa trabalhou o mais rápido que pôde. Outra saraivada atingiu mais uma aberração, derrubando-a no chão. Ela tinha aprendido a combater o Vazio há muito tempo, mas essas criaturas... elas eram diferentes."},{"s":"u9ffdcb95f6","n":"O toque do Vazio","f":"Ao longo dos séculos, muitos mortais do mundo superior responderam ao chamado do Vazio ou foram arrastados para ele contra sua vontade. Alguns deles — em raríssimos casos — sobreviveram ao encontro... porém nenhum deles voltou inalterado.","u":1},{"s":"ufebfcbde99","n":"Sal na terra","f":"Uma das poucas formas de combater o Vazio é deixando-o passar fome. Sem nenhum suprimento orgânico nem mágico por perto, o crescimento material do Vazio fica mais lento - até que, finalmente, entra em um estado de dormência.","u":1},{"s":"lkassadin","n":"Kassadin","f":"O Andarilho do Vazio.\nAbrindo um rastro ardente por um dos lugares mais sombrios do mundo, Kassadin sabe que seus dias estão contados. Guia e explorador experiente de Shurima, ele escolhera criar sua família nas pacatas tribos do sul; até o dia em que sua aldeia foi consumida pelo Vazio. Ele jurou vingança, combinando vários artefatos arcanos e tecnologias proibidas para os momentos difíceis que estavam por vir.","l":1}]},{"id":"icathia","name":"Os últimos de Icathia","desc":"O reino que o Vazio devorou. Jax, o último guerreiro de Icathia, procura pelo mundo quem tenha a força de enfrentar o que destruiu sua casa.","items":[{"s":"06SI003","n":"Fireth, a Ceifadora das Areias","f":"Jax perguntou o nome de Fireth inúmeras vezes em suas primeiras semanas de viagem juntos, mas ela só rosnava: \"Eu sou a Ceifadora!\". Breshi encontrou a solução perfeita — ele tinha acabado de fazer um bolo e precisava do nome do integrante mais forte do grupo para comemorar adequadamente."},{"s":"06RU008T7","n":"Jax","f":"\"Icathia jaz adormecida há muito tempo. Mas, enquanto eu permanecer de pé, o rugido de seu povo ecoará para sempre!\" – Jax"},{"s":"06SI031T1","n":"Miragem Icathiana","f":"Talvez eles sejam uma miragem. Talvez ela e aqueles que a acompanham venham de um vilarejo distante e escondido. Ela não fala de onde veio, e Jax não questiona. Mas, quando ela se ergue das areias e se posta ao lado do guerreiro, os dois lutam em uma harmonia perfeita, silenciosa, inacreditável."}]},{"id":"voidborn","name":"Os Vastinatas","desc":"Seres construídos pelos Observadores para aprender, consumir e preparar a volta de seus mestres. Vel'Koz, o Olho do Vazio, Kha'Zix, o caçador que evolui, e Bel'Veth, a Imperatriz que devora mundos.","items":[{"s":"lbelveth","n":"Bel’Veth","f":"A Imperatriz do Vazio.\nUma imperatriz apavorante, criada a partir da matéria-prima de uma cidade inteira devorada, Bel’Veth é o fim da própria Runeterra... e o começo de uma realidade monstruosa que ela mesma criou.","l":1},{"s":"lkhazix","n":"Kha'Zix","f":"O Ceifador do Vazio.\nO Vazio cresce e o Vazio se adapta, e nenhuma de suas outras criaturas incorpora isso tão bem quanto Kha’Zix. A evolução é o que impulsiona a essência desse horror mutável, nascido para sobreviver e destruir os mais fortes. Qualquer momento de dificuldades em fazê-lo só o faz criar modos novos e mais efetivos de neutralizar e matar sua presa.","l":1},{"s":"lvelkoz","n":"Vel'Koz","f":"O Olho do Vazio.\nNão é claro se Vel’Koz foi a primeira cria do Vazio a aparecer em Runeterra, mas certamente nunca houve outra que se igualasse ao seu nível de compreensão cruel e calculista. Enquanto sua raça devora ou perverte tudo ao seu redor, ele busca, em vez disso, examinar e estudar o domínio físico, assim como os estranhos seres guerreiros que habitam nele, por quaisquer fraquezas que o Vazio possa…","l":1},{"s":"w2916961f4f","n":"Vastinatas encapuzados (arte conceitual)","w":1}]}],"places":[{"s":"u11736619d9","n":"A Ruptura","f":"Nos arredores de Icathia está localizada a Ruptura, a maior evidência da ascensão do Vazio das profundezas da terra, em uma era há muito esquecida. Embora tanto corajosos quanto curiosos tenham tentado constantemente descobrir mais a seu respeito, somente os exploradores mais teimosos se aventurariam nos espaços escuros das profundezas.","u":1},{"s":"u666bb28c54","n":"Um Poder Inatingível","f":"Na escuridão abissal, lá nas profundezas, acredita-se que agora vivem, dormentes e ocultas, as primeiras grandes criaturas do Vazio a emergirem na superfície de Runeterra. Se isso for verdade, isso significa que elas esperaram pacientemente por milênios e agora pode ser hora de elas ascenderem novamente.","u":1},{"s":"w7b910b7611","n":"Vazio (arte conceitual 1)","w":1},{"s":"wf2a53cf5b6","n":"Vazio (arte conceitual 2)","w":1},{"s":"wcc56f03750","n":"Vazio (arte conceitual 3)","w":1},{"s":"w4253198a2f","n":"Vazio (arte conceitual 4)","w":1}],"creatures":[{"s":"08SH002","n":"Bocarra-Dunesco","f":"O bocarra-dunesco está adormecido em profundezas muito maiores do que seus primos xer'sai menores. Conhecido por devorar facilmente outros predadores xer'sai, ele raramente é documentado... Provavelmente porque pode engolir dunas inteiras (juntamente com qualquer testemunha)."},{"s":"06SH007","n":"Cria do Vazio","f":"Dharna se lembrou de que tinha aberto as janelas naquela manhã e sentido o aroma de pão fresquinho. Mais à frente, pescadores já tinham começado a levar o apurado do dia para os mercados. Ela se lembrou de ter sorrido, pensando que seria um belo dia."},{"s":"04SH022","n":"Devastadunas Xer'Sai","f":"Mesmo que todos os xer'sai sejam hábeis cavadores de túneis, apenas os devastadunas têm o tamanho e o poder necessários para atravessar os leitos rochosos que serpenteiam o Grande Sai, abrindo caminhos e aumentando suas oportunidades de caça em outros locais."},{"s":"04SH068","n":"Evocador Xer'Sai","f":"Nem todos os xer'sai nascem para matar. Alguns nascem para invocar outros da espécie com chamados agudos que estremecem as areias e os sentidos de qualquer um."},{"s":"04SH074","n":"Filhote Xer'Sai","f":"Ocasionalmente, após dizimarem uma caravana, os caçadores recuam e permitem que seus filhotes pilhem os escombros. É aqui que os jovens xer'sai aprimoram seus instintos, aprendendo quais sons pertencem à paisagem desértica e quais indicam novas presas."},{"s":"06SH021","n":"Horror Camuflado","f":"Enquanto o ataque prosseguia, criaturas maiores e ainda mais ferozes jorravam da passagem crescente. A cidade de Belveth foi destruída; no entanto, como quis a crueldade do destino, o nome dela perduraria."},{"s":"04SH019","n":"Rek'Sai","f":"\"O jovem Jhuraa estava explorando uma pequena caverna oculta, como já era de costume, quando se deparou com pergaminhos antigos! Levamos os artefatos para um tradutor em Medumarca, e neles... havia textos descrevendo um terror ancestral que perseguia nossos antepassados. Uma rainha. A rainha dos xer'sai!\" – Fezhaur, ancião de Vekaura"},{"s":"04SH019T1","n":"Rek'Sai","f":"\"Conhecemos o terror que ela causa há gerações, mas para nossos antepassados também falarem sobre ela... Quantos anos será que ela tem? E quantas pessoas do nosso povo já não dizimou? Só de imaginar, já me dá calafrios.\" – Fezhaur, ancião de Vekaura"},{"s":"04SH065","n":"Xerxa'reth, o Titã Subterrâneo","f":"\"Dizem que, há centenas de anos, o grande posto avançado conhecido como Taraleek servia como ponto de troca de mercadorias nas margens do rio Khaleek. Porém, em um dia fatídico, uma criatura poderosa se ergueu do chão, aniquilando o local e todos que o chamavam de lar. Mas que tipo de monstro faria algo assim?\" – Historiador shurimane"},{"s":"u0dc0c28db2","n":"A Cria do Vazio","f":"Apesar de ter gerado muitos deles, nenhum horror do Vazio é exatamente igual a outro. Suas formas sobrenaturais são tão variadas quanto aterrorizantes; entretanto, todas são motivadas por uma fome insaciável, e a misteriosa pulsação de seus corações é o que faz com que sigam em frente implacavelmente.","u":1},{"s":"uecb54de5b3","n":"Armadura de Trevas","f":"Algumas lendas sugerem que, assim que elas emergem no ar de Runeterra, as Crias do Vazio são pálidas, fibrosas e flexíveis. À medida que envelhecem, partes de sua forma ficam mais escuras, se assemelhando a uma casca, rígida o suficiente para rebater praticamente qualquer arma.","u":1},{"s":"lchogath","n":"Cho'Gath","f":"O Terror do Vazio.\nA partir do momento em que Cho’Gath emergiu da terra para a luz do sol ofuscante de Runeterra, a besta foi motivada por pura fome insaciável. A mais perfeita expressão do desejo do Vazio de consumir toda a vida, a biologia complexa de Cho’Gath rapidamente converte matéria em crescimento corporal novo, aumentando sua massa e densidade muscular ou endurecendo sua carapaça externa como um diamante…","l":1},{"s":"lkogmaw","n":"Kog'Maw","f":"A Boca do Abismo.\nVomitado para fora de uma aparição podre do Vazio nas profundezas das terras desertas de Icathia, Kog’Maw é uma criatura inquisitiva e pútrida com uma boca cáustica gigantesca. Essa criatura do Vazio em particular precisa morder e babar em qualquer coisa que alcançar para realmente compreendê-la.","l":1},{"s":"w5cb258c65c","n":"Criatura do Vazio (arte conceitual 1)","w":1},{"s":"w5ca35c0485","n":"Criatura do Vazio (arte conceitual 2)","w":1},{"s":"w844c8ecb1f","n":"Criatura do Vazio (arte conceitual 3)","w":1},{"s":"w97e1b0289e","n":"Criatura do Vazio (arte conceitual 4)","w":1},{"s":"w00f341d7a1","n":"Guerreiro do Vazio (arte conceitual 2)","w":1}]},"nazumah":{"groups":[{"id":"ksante","name":"K'Sante, o Orgulho de Nazumah","desc":"Guerreiro-caçador de Nazumah, criado entre histórias dos antepassados que fugiram dos Ascendidos. Seu orgulho quase o separa de Tope, até ele aprender que força sozinha não derruba o baccai.","items":[{"s":"lksante","n":"K'Sante","f":"O Orgulho de Nazumah..\nCorajoso e desafiador, K'Sante enfrenta feras colossais e Ascendentes cruéis para proteger seu lar, Nazumah — um cobiçado oásis no meio das areias de Shurima. Entretanto, após uma desavença com seu antigo parceiro, K'Sante entendeu que, para se tornar um guerreiro digno de liderar a cidade, primeiro ele deve aplacar seu desejo obstinado de sucesso.","l":1},{"s":"wcb1b1b8144","n":"K'Sante (arte conceitual)","w":1},{"s":"we0d6aeefcc","n":"K'Sante e Tope: tudo o que devíamos ter dito","w":1},{"s":"wda12d1d825","n":"K'Sante, de volta para vencer seu monstro","w":1},{"s":"w874986224a","n":"K'Sante: retrato (arte conceitual)","w":1}]},{"id":"tope","name":"Tope e a caça ao baccai","desc":"Tope, de Marrowmark, caçador de longo alcance e parceiro de K'Sante. Seu diário revelou o que a dupla não via sobre o monstro cobra-leão.","items":[{"s":"w1c1c66045a","n":"O diário aberto sobre o baccai","w":1},{"s":"wb6822999b7","n":"O diário de Tope (arte conceitual)","w":1},{"s":"wb9928e4be4","n":"Tope (arte conceitual)","w":1}]}],"places":[{"s":"w571b09236b","n":"Nazumah, a cidade-estado do oásis","w":1}],"creatures":[{"s":"04SH090","n":"Pedregurso Ranzinza","f":"\"Ai, hoje foi muito legal! Quando paramos para almoçar (queijo de skallashi – ECA!), Kadira viu um ursinho de pedra dormindo na sombra. É claro que ela foi cutucar a cauda dele, e é claro que o bichinho não gostou nada disso. Espero que ele goste do queijo que deixamos por lá!\"\n– Diário de Zaifa"},{"s":"w4738cc64b3","n":"O baccai cobra-leão (arte conceitual)","w":1}]}};
